import { AnnotationFactory } from './src/core/annotation.js';
import { Dict, Name, Ref } from './src/core/primitives.js';
const xref={fetchIfRef:v=>v, fetch:v=>v, fetchAsync:async v=>v, fetchIfRefAsync:async v=>v, getNewTemporaryRef:()=>Ref.get(99,0)};
const annotationGlobals={pdfManager:{evaluatorOptions:{isOffscreenCanvasSupported:false}},catalog:{},acroForm:new Dict(),xfaDatasets:null,structTreeRoot:null,baseUrl:null,attachments:null,globalColorSpaceCache:null};
const subs=['Link','Text','Widget','Popup','FreeText','Line','Square','Circle','PolyLine','Polygon','Caret','Ink','Highlight','Underline','Squiggly','StrikeOut','Stamp','FileAttachment','RichMedia','Screen','Sound','Unknown'];
for (const subtype of subs) {
  const d=new Dict(xref); d.set('Subtype',Name.get(subtype)); d.set('Rect',[0,0,10,10]);
  if (subtype==='Widget') d.set('FT',Name.get('Tx'));
  try { const a=AnnotationFactory._create(xref,d,annotationGlobals,{createObjId:()=>1},false); console.log(subtype,'=>',a?.constructor.name); }
  catch(e) { console.log(subtype,'ERROR',e.message); }
}
for (const ft of ['Btn','Ch','Sig',null]) { const d=new Dict(xref); d.set('Subtype',Name.get('Widget')); d.set('Rect',[0,0,10,10]); if(ft)d.set('FT',Name.get(ft)); try { console.log('Widget',ft,'=>',AnnotationFactory._create(xref,d,annotationGlobals,{createObjId:()=>1},false)?.constructor.name); }catch(e){console.log('Widget',ft,'ERR',e.message)} }
NODE"}

