    pageRef: null,
  };

  return Object.assign(params, overrides);
}

function makeDict(xref, entries = {}) {
  const dict = new Dict(xref);
  for (const [key, value] of Object.entries(entries)) {
    dict.set(key, value);
  }
  return dict;
}

function makeBaseDict(xref) {
  return makeDict(xref, {
    Rect: [0, 0, 10, 20],
    Subtype: Name.get("Text"),
