describe("AnnotationBorderStyle", () => {
  it("exposes the documented defaults", () => {
    const border = new AnnotationBorderStyle();

    expect(border.width).toBe(1);
    expect(border.rawWidth).toBe(1);
    expect(border.style).toBe(AnnotationBorderStyleType.SOLID);
    expect(border.dashArray).toEqual([3]);
    expect(border.horizontalCornerRadius).toBe(0);
    expect(border.verticalCornerRadius).toBe(0);
  });

  it("validates, records, and clamps border widths", () => {
    const border = new AnnotationBorderStyle();

    border.setWidth(20, [0, 0, 10, 10]);
    expect(border.rawWidth).toBe(20);
    expect(border.width).toBe(1);

    border.setWidth(Name.get("Bogus"), [0, 0, 10, 10]);
    expect(border.width).toBe(0);

    border.setWidth("2", [0, 0, 10, 10]);
    expect(border.width).toBe(0);

    expect(() => border.setWidth(2, [0, 0, 10])).toThrow(
      "A valid `rect` parameter must be provided."
    );
  });

  it("maps PDF border-style names and handles invalid input", () => {
    const border = new AnnotationBorderStyle();

    for (const [name, expected] of [
      ["S", AnnotationBorderStyleType.SOLID],
      ["D", AnnotationBorderStyleType.DASHED],
      ["B", AnnotationBorderStyleType.BEVELED],
      ["I", AnnotationBorderStyleType.INSET],
      ["U", AnnotationBorderStyleType.UNDERLINE],
    ]) {
      border.setStyle(Name.get(name));
      expect(border.style).toBe(expected);
    }

    border.setStyle("D");
    expect(border.style).toBe(AnnotationBorderStyleType.UNDERLINE);
  });

  it("accepts valid dash arrays and rejects invalid ones", () => {
    const border = new AnnotationBorderStyle();

    border.setDashArray([4, 2], true);
    expect(border.dashArray).toEqual([4, 2]);
    expect(border.style).toBe(AnnotationBorderStyleType.DASHED);

    border.setDashArray([0, 0]);
    expect(border.width).toBe(0);

    border = new AnnotationBorderStyle();
    border.setDashArray("invalid");
    expect(border.width).toBe(0);
  });

  it("only stores integer corner radii", () => {
    const border = new AnnotationBorderStyle();

    border.setHorizontalCornerRadius(3.5);
    border.setVerticalCornerRadius(4.5);
    expect(border.horizontalCornerRadius).toBe(0);
    expect(border.verticalCornerRadius).toBe(0);

    border.setHorizontalCornerRadius(3);
    border.setVerticalCornerRadius(4);
    expect(border.horizontalCornerRadius).toBe(3);
    expect(border.verticalCornerRadius).toBe(4);
  });
});

describe("getQuadPoints", () => {
  it("normalizes one quadrilateral into the renderer's canonical order", () => {
    const xref = makeXref();
    const dict = makeDict(xref, {
      QuadPoints: [8, 9, 2, 9, 8, 1, 2, 1],
    });

    const points = getQuadPoints(dict, [0, 0, 10, 10]);

    expect(points).toBeInstanceOf(Float32Array);
    expect(Array.from(points)).toEqual([2, 9, 8, 9, 2, 1, 8, 1]);
  });

  it("normalizes every quadrilateral in a multi-quad array", () => {
    const xref = makeXref();
    const dict = makeDict(xref, {
      QuadPoints: [0, 2, 1, 2, 0, 1, 1, 1, 2, 4, 3, 4, 2, 3, 3, 3],
    });

    expect(Array.from(getQuadPoints(dict, [0, 0, 4, 5]))).toEqual([
      0, 2, 1, 2, 0, 1, 1, 1, 2, 4, 3, 4, 2, 3, 3, 3,
    ]);
  });

  it("rejects malformed, empty, and out-of-rectangle quad point data", () => {
    const xref = makeXref();

    expect(getQuadPoints(makeDict(xref, {}), [0, 0, 10, 10])).toBeNull();
    expect(
      getQuadPoints(makeDict(xref, { QuadPoints: [0, 0, 1, 1] }), null)
    ).toBeNull();
    expect(
      getQuadPoints(
        makeDict(xref, { QuadPoints: [0, 0, 1, 1, 0, 1, "x", 1] }),
        null
      )
    ).toBeNull();
    expect(
      getQuadPoints(
        makeDict(xref, { QuadPoints: [-1, 0, 1, 1, 0, 1, 1, 1] }),
        [0, 0, 2, 2]
      )
    ).toBeNull();
  });

  it("allows quad points outside the rectangle when no rectangle is supplied", () => {
    const xref = makeXref();
    const dict = makeDict(xref, {
      QuadPoints: [-5, 2, 20, 2, -5, -3, 20, -3],
    });

    expect(Array.from(getQuadPoints(dict, null))).toEqual([
      -5, 2, 20, 2, -5, -3, 20, -3,
    ]);
  });
});

describe("Annotation", () => {
