    expect(result).toEqual({
      opList: expect.any(Object),
      separateForm: false,
      separateCanvas: false,
    });
    expect(result.opList.fnArray).toEqual([]);
    expect(evaluator.getOperatorList).not.toHaveBeenCalled();
  });

  it("wraps an appearance stream with annotation and transform operators", async () => {
    const xref = makeXref();
    const appearanceDict = makeDict(xref, {
      BBox: [0, 0, 10, 5],
      Matrix: [1, 0, 0, 1, 0, 0],
    });
    const stream = new StringStream("content", appearanceDict);
    const dict = makeDict(xref, {
      Rect: [0, 0, 100, 50],
      AP: makeDict(xref, { N: stream }),
    });
    const annotation = new Annotation(makeParams(dict, xref, { id: "a1" }));
    const resetSpy = jest.spyOn(stream, "reset");
    const evaluator = {
      getOperatorList: jest.fn(async ({ operatorList }) => {
        operatorList.addOp(999, ["inner"]);
      }),
    };

    const { opList, separateCanvas } = await annotation.getOperatorList(
      evaluator,
      { task: true },
      0,
      null
    );

    expect(opList.fnArray).toEqual([
      OPS.beginAnnotation,
      999,
      OPS.endAnnotation,
    ]);
    expect(opList.argsArray[0]).toEqual([
      "a1",
      [0, 0, 100, 50],
      [10, 0, 0, 10, 0, 0],
      [1, 0, 0, 1, 0, 0],
      false,
    ]);
    expect(evaluator.getOperatorList).toHaveBeenCalledWith(
      expect.objectContaining({
        stream,
        task: { task: true },
        resources: undefined,
        operatorList: opList,
        fallbackFontDict: null,
      })
    );
    expect(resetSpy).toHaveBeenCalled();
    expect(separateCanvas).toBe(false);
  });

  it("extracts and trims text from appearance streams", async () => {
    const xref = makeXref();
    const appearanceDict = makeDict(xref, {
      BBox: [0, 0, 10, 5],
      Matrix: [1, 0, 0, 1, 0, 0],
    });
    const stream = new StringStream("content", appearanceDict);
    const dict = makeDict(xref, {
      Rect: [0, 0, 100, 50],
      AP: makeDict(xref, { N: stream }),
    });
    const annotation = new Annotation(makeParams(dict, xref));
    const evaluator = {
      getTextContent: jest.fn(async ({ sink }) => {
        sink.enqueue(
          {
            items: [
              { str: " Hello ", transform: [1, 0, 0, 1, 2, 3], hasEOL: true },
              { str: "world", transform: [1, 0, 0, 1, 4, 5], hasEOL: false },
            ],
          },
          0
        );
      }),
    };
    const viewBox = [1, 2, 3, 4];

    await annotation.extractTextContent(evaluator, {}, viewBox);

    expect(annotation.data.textContent).toEqual([" Hello", "world"]);
    expect(annotation.data.textPosition).toEqual([20, 30]);
    expect(evaluator.getTextContent).toHaveBeenCalledWith(
      expect.objectContaining({
        stream,
        includeMarkedContent: true,
        keepWhiteSpace: true,
        viewBox,
        sink: expect.any(Object),
      })
    );
  });

  it("does not call the evaluator when there is no appearance", async () => {
    const xref = makeXref();
    const annotation = new Annotation(makeParams(makeBaseDict(xref), xref));
    const evaluator = { getTextContent: jest.fn() };

    await expect(
      annotation.extractTextContent(evaluator, {}, null)
    ).resolves.toBeUndefined();
    expect(evaluator.getTextContent).not.toHaveBeenCalled();
  });
});

