    expect(Array.from(annotation.data.color)).toEqual([0, 0, 255]);
    expect(annotation.data.titleObj.str).toBe("Parent title");
    expect(annotation.data.contentsObj.str).toBe("Parent contents");
    expect(annotation.data.open).toBe(true);
    expect(annotation.data.noHTML).toBe(false);
  });

  it("normalizes an empty rectangle to null", () => {
    const xref = makeXref();
    const parent = makeDict(xref, { Rect: [0, 0, 10, 10] });
    const dict = makeDict(xref, { Rect: [0, 0, 0, 0], Parent: parent });

    const annotation = new PopupAnnotation(makeParams(dict, xref));

    expect(annotation.data.rect).toBeNull();
  });

  it("inherits viewability flags from a viewable parent when needed", () => {
    const xref = makeXref();
    const parent = makeDict(xref, {
      Rect: [0, 0, 10, 10],
      F: AnnotationFlag.PRINT,
    });
    const dict = makeDict(xref, {
      Rect: [0, 0, 10, 10],
      F: AnnotationFlag.NOVIEW,
      Parent: parent,
    });

    const annotation = new PopupAnnotation(makeParams(dict, xref));

    expect(annotation.flags).toBe(AnnotationFlag.PRINT);
    expect(annotation.viewable).toBe(true);
  });

  it("creates or updates a popup dictionary", () => {
    const xref = makeXref();
    const parent = Ref.get(3);

    const created = PopupAnnotation.createNewDict(
      { rect: [1, 2, 3, 4], parent },
      xref
    );
    expect(created.get("Type")).toEqual(Name.get("Annot"));
    expect(created.get("Subtype")).toEqual(Name.get("Popup"));
    expect(created.get("Open")).toBe(false);
    expect(created.get("Rect")).toEqual([1, 2, 3, 4]);
    expect(created.get("Parent")).toBe(parent);

    const oldAnnotation = makeDict(xref, {
      Type: Name.get("Annot"),
      Subtype: Name.get("Popup"),
      Open: true,
      Extra: "kept",
    });
    const updated = PopupAnnotation.createNewDict(
      { oldAnnotation, rect: [4, 3, 2, 1], parent: Ref.get(4) },
      xref
    );
    expect(updated).toBe(oldAnnotation);
    expect(updated.get("Open")).toBe(true);
    expect(updated.get("Extra")).toBe("kept");
    expect(updated.get("Rect")).toEqual([4, 3, 2, 1]);
  });

  it("has no appearance stream and supports the shared new-annotation flow", async () => {
    const xref = makeXref();
    await expect(
      PopupAnnotation.createNewAppearanceStream({}, xref, {})
    ).resolves.toBeNull();

    const annotation = {
      ref: null,
      rect: [1, 2, 3, 4],
      parent: Ref.get(9),
    };
    const changes = new Map();

    const result = await PopupAnnotation.createNewAnnotation(
      xref,
      annotation,
      changes
    );

    expect(annotation.ref).toBe(Ref.get(100));
    expect(result).toEqual({ ref: annotation.ref });
    expect(changes.has(annotation.ref)).toBe(true);
    expect(changes.get(annotation.ref).data.get("Subtype")).toEqual(
      Name.get("Popup")
    );
  });
});

describe("WidgetAnnotation", () => {
  it("decodes inherited field data and field flags", () => {
    const xref = makeXref();
    const parent = makeDict(xref, {
      FT: Name.get("Tx"),
      V: [Name.get("A"), "B"],
      DV: "Default",
      Ff:
        AnnotationFieldFlag.READONLY |
        AnnotationFieldFlag.REQUIRED |
        AnnotationFieldFlag.PASSWORD,
      DA: "/Helv 9 Tf 0 g",
    });
    const dict = makeDict(xref, {
      Rect: [0, 0, 10, 20],
      T: "field",
      Parent: parent,
      TU: "Alternative",
      F: AnnotationFlag.HIDDEN,
    });

    const widget = new WidgetAnnotation(makeParams(dict, xref));

    expect(widget.data.fieldName).toBe("field");
    expect(widget.data.fieldType).toBe("Tx");
    expect(widget.data.fieldValue).toEqual(["A", "B"]);
    expect(widget.data.defaultFieldValue).toBe("Default");
    expect(widget.data.alternativeText).toBe("Alternative");
    expect(widget.data.fieldFlags).toBe(
      AnnotationFieldFlag.READONLY |
        AnnotationFieldFlag.REQUIRED |
        AnnotationFieldFlag.PASSWORD
    );
    expect(widget.data.readOnly).toBe(true);
    expect(widget.data.required).toBe(true);
    expect(widget.data.password).toBe(true);
    expect(widget.data.hidden).toBe(true);
    expect(widget.data.defaultAppearanceData.fontName).toBe("Helv");
    expect(widget.data.defaultAppearanceData.fontSize).toBe(9);
  });

  it("falls back to the default value and NeedAppearances state", () => {
    const xref = makeXref();
    const dict = makeDict(xref, {
      Rect: [0, 0, 10, 20],
      T: "field",
      FT: Name.get("Tx"),
      DV: "Fallback",
      DA: "/Helv 12 Tf 0 g",
    });

    const widget = new WidgetAnnotation(
      makeParams(dict, xref, { needAppearances: true })
    );

    expect(widget.data.fieldValue).toBe("Fallback");
    expect(widget.data.hasAppearance).toBe(true);
    expect(widget.data.password).toBe(false);
    expect(widget.data.readOnly).toBe(false);
    expect(widget.data.required).toBe(false);
  });

  it("recursively decodes simple form values", () => {
    const xref = makeXref();
    const widget = new WidgetAnnotation(
      makeParams(makeBaseDict(xref), xref)
    );

    expect(widget._decodeFormValue(Name.get("Off"))).toBe("Off");
    expect(widget._decodeFormValue("Plain")).toBe("Plain");
    expect(widget._decodeFormValue([Name.get("A"), "B", null])).toEqual([
      "A",
      "B",
    ]);
    expect(widget._decodeFormValue([null, 3])).toBeNull();
    expect(widget._decodeFormValue(3)).toBeNull();
  });

  it("checks field flags and rendered visibility semantics", () => {
    const xref = makeXref();
    const dict = makeDict(xref, {
      Rect: [0, 0, 10, 20],
      F: AnnotationFlag.NOVIEW,
      Ff: AnnotationFieldFlag.RADIO,
    });
    const widget = new WidgetAnnotation(makeParams(dict, xref));

    expect(widget.hasFieldFlag(AnnotationFieldFlag.RADIO)).toBe(true);
    expect(widget.hasFieldFlag(AnnotationFieldFlag.PUSHBUTTON)).toBe(false);
    expect(widget.mustBeViewed(null, true)).toBe(true);
    expect(widget.mustBeViewed(null, false)).toBe(false);
  });

  it("computes rotation matrices from the annotation or storage", () => {
    const xref = makeXref();
    const dict = makeDict(xref, {
      Rect: [0, 0, 20, 10],
      Rotate: 90,
    });
    const widget = new WidgetAnnotation(makeParams(dict, xref));

    expect(widget.getRotationMatrix()).toEqual([0, 1, -1, 0, 20, 0]);
    expect(
      widget.getRotationMatrix(
        new Map([["annot_1", { rotation: 0 }]]),
      )
    ).toEqual([1, 0, 0, 1, 0, 0]);
  });

  it("generates border/background appearance commands and MK dictionaries", () => {
    const xref = makeXref();
    const mk = makeDict(xref, {
      BC: [1, 0, 0],
      BG: [0, 1, 0],
    });
    const dict = makeDict(xref, {
      Rect: [0, 0, 100, 50],
      MK: mk,
    });
    const widget = new WidgetAnnotation(makeParams(dict, xref));

    expect(widget.getBorderAndBackgroundAppearances()).toBe(
      "0 1 0 rg 0 0 100 50 re f 1 w 1 0 0 RG 0 0 100 50 re S "
    );
    expect(
      widget.getBorderAndBackgroundAppearances(
        new Map([["annot_1", { rotation: 90 }]]),
      )
    ).toBe("0 1 0 rg 0 0 50 100 re f 1 w 1 0 0 RG 0 0 50 100 re S ");

    const mkDict = widget._getMKDict(90);
    expect(mkDict.get("R")).toBe(90);
    expect(mkDict.get("BC")).toEqual([1, 0, 0]);
    expect(mkDict.get("BG")).toEqual([0, 1, 0]);
  });

  it("sets a value directly or through an inheritable parent", () => {
    const xref = makeXref();
    const directDict = makeDict(xref, { T: "direct" });
    const direct = new WidgetAnnotation(
      makeParams(directDict, xref, { ref: Ref.get(1) })
    );
    expect(direct.setValue(directDict, "direct value", xref, new Map())).toBe(
      null
    );
    expect(directDict.get("V")).toBe("direct value");

    const parentRef = Ref.get(2);
    const parent = makeDict(xref, { T: "parent" });
    xref.objects.set(parentRef.toString(), parent);
    const child = makeDict(xref, { Parent: parentRef });
    const widget = new WidgetAnnotation(
      makeParams(child, xref, { ref: Ref.get(3) })
    );
    const changes = new Map();
    const newParent = widget.setValue(child, "child value", xref, changes);

    expect(newParent).not.toBe(parent);
    expect(newParent.get("T")).toBe("parent");
    expect(newParent.get("V")).toBe("child value");
    expect(changes.get(parentRef).data).toBe(newParent);
  });

  it("returns a form-separated operator list in forms rendering mode", async () => {
    const xref = makeXref();
    const widget = new WidgetAnnotation(
      makeParams(makeBaseDict(xref), xref)
    );
    const evaluator = { getOperatorList: jest.fn() };

    const result = await widget.getOperatorList(
      evaluator,
      {},
      RenderingIntentFlag.DISPLAY | RenderingIntentFlag.ANNOTATIONS_FORMS,
      null
    );

    expect(result.separateForm).toBe(true);
    expect(result.separateCanvas).toBe(false);
    expect(result.opList.fnArray).toEqual([]);
    expect(evaluator.getOperatorList).not.toHaveBeenCalled();
  });
});

describe("AnnotationFactory", () => {
  it("creates annotation globals from the PDF manager", async () => {
    const acroForm = new Dict();
    const catalog = {};
    const pdfManager = {
      pdfDocument: { catalog },
      evaluatorOptions: { isOffscreenCanvasSupported: false },
      ensureCatalog: jest.fn(async key => {
        if (key === "acroForm") {
          return acroForm;
        }
        return { fromCatalog: key };
      }),
      ensureDoc: jest.fn(async key => ({ fromDoc: key })),
    };

    const globals = await AnnotationFactory.createGlobals(pdfManager);

    expect(globals).toEqual({
      pdfManager,
      catalog,
      acroForm,
      xfaDatasets: { fromDoc: "xfaDatasets" },
      structTreeRoot: { fromCatalog: "structTreeRoot" },
      baseUrl: { fromCatalog: "baseUrl" },
      attachments: { fromCatalog: "attachments" },
      globalColorSpaceCache: { fromCatalog: "globalColorSpaceCache" },
    });
    expect(pdfManager.ensureCatalog.mock.calls.map(([key]) => key)).toEqual([
      "acroForm",
      "structTreeRoot",
      "baseUrl",
      "attachments",
      "globalColorSpaceCache",
    ]);
    expect(pdfManager.ensureDoc).toHaveBeenCalledWith("xfaDatasets");
  });

  it("returns null when globals cannot be created", async () => {
    const pdfManager = {
      pdfDocument: { catalog: {} },
      ensureCatalog: jest.fn(async () => {
        throw new Error("broken catalog");
      }),
      ensureDoc: jest.fn(async () => null),
    };

    await expect(AnnotationFactory.createGlobals(pdfManager)).resolves.toBeNull();
    expect(console.warn).toHaveBeenCalledWith(
      expect.stringContaining('createGlobals: "Error: broken catalog"')
    );
  });

  it.each([
    ["Link", "LinkAnnotation"],
    ["Text", "TextAnnotation"],
    ["Popup", "PopupAnnotation"],
    ["FreeText", "FreeTextAnnotation"],
    ["Line", "LineAnnotation"],
    ["Square", "SquareAnnotation"],
    ["Circle", "CircleAnnotation"],
    ["PolyLine", "PolylineAnnotation"],
    ["Polygon", "PolygonAnnotation"],
    ["Caret", "CaretAnnotation"],
    ["Ink", "InkAnnotation"],
    ["Highlight", "HighlightAnnotation"],
    ["Underline", "UnderlineAnnotation"],
    ["Squiggly", "SquigglyAnnotation"],
    ["StrikeOut", "StrikeOutAnnotation"],
    ["Stamp", "StampAnnotation"],
    ["FileAttachment", "FileAttachmentAnnotation"],
    ["RichMedia", "RichMediaAnnotation"],
    ["Screen", "ScreenAnnotation"],
    ["Sound", "SoundAnnotation"],
  ])("dispatches /%s to %s", (subtype, expectedClass) => {
    const xref = makeXref();
    const dict = makeDict(xref, {
      Rect: [0, 0, 10, 10],
      Subtype: Name.get(subtype),
    });

    const annotation = AnnotationFactory._create(
      xref,
      dict,
      makeGlobals(),
      { createObjId: () => 1 }
    );

    expect(annotation.constructor.name).toBe(expectedClass);
    expect(annotation.data.subtype).toBe(subtype);
    expect(annotation.data.annotationType).toBe(
      AnnotationType[subtype.toUpperCase()]
    );
  });

  it.each([
    ["Tx", "TextWidgetAnnotation"],
    ["Btn", "ButtonWidgetAnnotation"],
    ["Ch", "ChoiceWidgetAnnotation"],
    ["Sig", "SignatureWidgetAnnotation"],
    [null, "WidgetAnnotation"],
  ])("dispatches Widget with /FT %s to %s", (fieldType, expectedClass) => {
    const xref = makeXref();
    const dict = makeDict(xref, {
      Rect: [0, 0, 10, 10],
      Subtype: Name.get("Widget"),
    });
    if (fieldType) {
      dict.set("FT", Name.get(fieldType));
    }

    const annotation = AnnotationFactory._create(
      xref,
      dict,
      makeGlobals(),
      { createObjId: () => 1 }
    );

    expect(annotation.constructor.name).toBe(expectedClass);
    expect(annotation.data.annotationType).toBe(AnnotationType.WIDGET);
  });

  it.each([["Unknown"], [null]])(
    "falls back to the base Annotation for subtype %s",
    subtype => {
      const xref = makeXref();
      const dict = makeDict(xref, { Rect: [0, 0, 10, 10] });
      if (subtype) {
        dict.set("Subtype", Name.get(subtype));
      }

      const annotation = AnnotationFactory._create(
        xref,
        dict,
        makeGlobals(),
        { createObjId: () => 1 }
      );

      expect(annotation.constructor).toBe(Annotation);
      expect(annotation.data.annotationType).toBeUndefined();
    }
  );

  it("returns undefined for non-dictionary input", () => {
    const xref = makeXref();

    expect(
      AnnotationFactory._create(
        xref,
        null,
        makeGlobals(),
        { createObjId: () => 1 }
      )
    ).toBeUndefined();
  });

  it("filters by collected annotation type before constructing", () => {
    const xref = makeXref();
    const square = makeDict(xref, {
      Rect: [0, 0, 10, 10],
      Subtype: Name.get("Square"),
    });
    const text = makeDict(xref, {
      Rect: [0, 0, 10, 10],
      Subtype: Name.get("Text"),
    });
    const collectByType = new Set([AnnotationType.TEXT]);

    expect(
      AnnotationFactory._create(
        xref,
        square,
        makeGlobals(),
        { createObjId: () => 1 },
        false,
        null,
        collectByType
      )
    ).toBeNull();
    expect(
      AnnotationFactory._create(
        xref,
        text,
        makeGlobals(),
        { createObjId: () => 1 },
        false,
        null,
        collectByType
      ).constructor.name
    ).toBe("TextAnnotation");
  });

  it("uses reference ids, generated ids, and orphan parent links", () => {
    const xref = makeXref();
