function makeXref(extra = {}) {
  return {
    fetch: value => value,
    fetchAsync: async value => value,
    fetchIfRef: value => value,
    fetchIfRefAsync: async value => value,
    getNewTemporaryRef: () => Ref.get(100, 0),
