  };
}

function makeDict(entries = {}, xref = makeXref()) {
  const dict = new Dict(xref);
  dict.set("Rect", [0, 0, 10, 20]);
  for (const [key, value] of Object.entries(entries)) {
    dict.set(key, value);
  }
  return dict;
}

function createAnnotation(entries = {}, overrides = {}) {
  const dict = makeDict(entries, overrides.xref);
  return new Annotation(makeParams(dict, overrides));
}

function createWidget(entries = {}, overrides = {}) {
  const dict = makeDict(entries, overrides.xref);
  return new WidgetAnnotation(makeParams(dict, { subtype: "Widget", ...overrides }));
}

describe("AnnotationBorderStyle", () => {
  it("starts with the documented defaults", () => {
    const style = new AnnotationBorderStyle();
    expect(style).toMatchObject({
      width: 1,
      rawWidth: 1,
      style: AnnotationBorderStyleType.SOLID,
      dashArray: [3],
      horizontalCornerRadius: 0,
      verticalCornerRadius: 0,
    });
  });

  it("accepts numeric widths but caps widths that overflow the rectangle", () => {
    const style = new AnnotationBorderStyle();
    style.setWidth(4, [0, 0, 20, 20]);
    expect(style.width).toBe(4);
    expect(style.rawWidth).toBe(4);

    style.setWidth(12, [0, 0, 20, 20]);
    expect(style.width).toBe(1);
    expect(style.rawWidth).toBe(12);

    style.setWidth(Name.get("Wide"), [0, 0, 20, 20]);
    expect(style.width).toBe(0);
  });

  it("maps PDF border style names and ignores unknown non-name values", () => {
    const style = new AnnotationBorderStyle();
    style.setStyle(Name.get("D"));
    expect(style.style).toBe(AnnotationBorderStyleType.DASHED);
    style.setStyle(Name.get("U"));
    expect(style.style).toBe(AnnotationBorderStyleType.UNDERLINE);
    style.setStyle("B");
    expect(style.style).toBe(AnnotationBorderStyleType.UNDERLINE);
  });

  it("validates dash arrays and can force a dashed border", () => {
    const style = new AnnotationBorderStyle();
    style.setDashArray([2, 4], true);
    expect(style.dashArray).toEqual([2, 4]);
    expect(style.style).toBe(AnnotationBorderStyleType.DASHED);

    style.setDashArray([0, 0]);
    expect(style.width).toBe(0);
  });

  it("only accepts integer corner radii", () => {
    const style = new AnnotationBorderStyle();
    style.setHorizontalCornerRadius(3.5);
    style.setVerticalCornerRadius(2);
    expect(style.horizontalCornerRadius).toBe(0);
    expect(style.verticalCornerRadius).toBe(2);
  });
});

