      getQuadPoints(makeDict({ QuadPoints: [0, 0, 1, 1, 2, "x", 3, 3] }), [0, 0, 10, 10])
    ).toBeNull();
    expect(
      getQuadPoints(makeDict({ QuadPoints: [0, 0, 11, 0, 0, 1, 11, 1] }), [0, 0, 10, 10])
    ).toBeNull();
  });

  it("permits points outside the rectangle when no rectangle is supplied", () => {
    const result = getQuadPoints(
      makeDict({ QuadPoints: [-2, -1, 2, -1, -2, 1, 2, 1] }),
      null
    );
    expect(Array.from(result)).toEqual([-2, 1, 2, 1, -2, -1, 2, -1]);
  });
});

