    const storage = new Map([["annot_1", { noView: true, noPrint: true }]]);
    expect(annotation.mustBeViewed(storage)).toBe(false);
    expect(annotation.mustBePrinted(storage)).toBe(false);

    const hidden = createAnnotation({ F: AnnotationFlag.HIDDEN | AnnotationFlag.PRINT });
    hidden.data.quadPoints ||= new Float32Array();
    expect(hidden.mustBeViewed()).toBe(false);
    expect(hidden.mustBePrinted()).toBe(false);
