      makeParams(dict, {
        ref,
        orphanFields: new Map([[ref, parentRef]]),
      })
    );
    expect(annotation.ref).toBe(ref);
    expect(dict.getRaw("Parent")).toBe(parentRef);
  });

  it("returns an empty operator list when there is no appearance", async () => {
    const annotation = createAnnotation();
    const result = await annotation.getOperatorList({}, {}, RenderingIntentFlag.DISPLAY);
    expect(result.opList.fnArray).toEqual([]);
    expect(result.separateForm).toBe(false);
    expect(result.separateCanvas).toBe(false);
  });

  it("renders an appearance stream with the computed annotation transform", async () => {
    const xref = makeXref();
    const appearanceDict = makeDict({ BBox: [0, 0, 10, 5], Matrix: [1, 0, 0, 1, 0, 0] }, xref);
    const appearance = new StringStream("appearance", appearanceDict);
    const dict = makeDict({ Rect: [0, 0, 100, 50], AP: makeDict({ N: appearance }, xref) }, xref);
    const annotation = new Annotation(makeParams(dict, { xref, id: "a1" }));
    const reset = jest.spyOn(appearance, "reset");
    const evaluator = {
      getOperatorList: jest.fn(async ({ operatorList }) => operatorList.addOp(123, ["content"])),
    };

    const result = await annotation.getOperatorList(
      evaluator,
      { task: true },
      RenderingIntentFlag.DISPLAY
    );

    expect(result.opList.fnArray).toEqual([OPS.beginAnnotation, 123, OPS.endAnnotation]);
    expect(result.opList.argsArray[0]).toEqual([
      "a1",
      [0, 0, 100, 50],
      [10, 0, 0, 10, 0, 0],
      [1, 0, 0, 1, 0, 0],
      false,
    ]);
    expect(evaluator.getOperatorList).toHaveBeenCalledWith(
      expect.objectContaining({ stream: appearance, operatorList: result.opList })
    );
    expect(reset).toHaveBeenCalled();
  });

  it("extracts text from an appearance and records its content and position", async () => {
    const xref = makeXref();
    const appearanceDict = makeDict({ BBox: [0, 0, 10, 5], Matrix: [1, 0, 0, 1, 0, 0] }, xref);
    const appearance = new StringStream("appearance", appearanceDict);
    const dict = makeDict({ Rect: [0, 0, 100, 50], AP: makeDict({ N: appearance }, xref) }, xref);
    const annotation = new Annotation(makeParams(dict, { xref }));
    const evaluator = {
      getTextContent: jest.fn(async ({ sink }) => {
        sink.enqueue({
          items: [
            { str: " Hello ", transform: [1, 0, 0, 1, 2, 3], hasEOL: true },
            { str: "world", transform: [1, 0, 0, 1, 4, 5], hasEOL: false },
          ],
        });
      }),
    };

    await annotation.extractTextContent(evaluator, {}, null);
    expect(annotation.data.textContent).toEqual([" Hello", "world"]);
    expect(annotation.data.textPosition).toEqual([20, 30]);
  });
});

