    expect(widget.getRotationMatrix()).toEqual([1, 0, 0, 1, 0, 0]);
    expect(widget.getRotationMatrix(new Map([["annot_1", { rotation: 90 }]]))).toEqual([
      0, 1, -1, 0, 10, 20,
    ]);
    expect(widget.getBorderAndBackgroundAppearances()).toBe(
      "0 1 0 rg 0 0 10 20 re f 1 w 1 0 0 RG 0 0 10 20 re S "
