    expect(
      widget.getBorderAndBackgroundAppearances(new Map([["annot_1", { rotation: 90 }]]))
    ).toBe("0 1 0 rg 0 0 20 10 re f 1 w 1 0 0 RG 0 0 20 10 re S ");
