});

describe("AnnotationFactory", () => {
  let warnSpy;

  beforeEach(() => {
    warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
  });

  afterEach(() => {
    warnSpy.mockRestore();
  });

  it("creates factory globals from the document manager", async () => {
    const acroForm = new Dict();
    const catalog = { marker: "catalog" };
    const pdfManager = {
      pdfDocument: { catalog },
      ensureCatalog: jest.fn(async key =>
        key === "acroForm" ? acroForm : `${key}-value`
      ),
      ensureDoc: jest.fn(async key => `${key}-value`),
    };

    const globals = await AnnotationFactory.createGlobals(pdfManager);
    expect(globals).toMatchObject({
      pdfManager,
      catalog,
      acroForm,
      xfaDatasets: "xfaDatasets-value",
      structTreeRoot: "structTreeRoot-value",
      baseUrl: "baseUrl-value",
      attachments: "attachments-value",
      globalColorSpaceCache: "globalColorSpaceCache-value",
    });
    expect(pdfManager.ensureCatalog.mock.calls.map(([key]) => key)).toEqual([
      "acroForm",
      "structTreeRoot",
      "baseUrl",
      "attachments",
      "globalColorSpaceCache",
    ]);
    expect(pdfManager.ensureDoc).toHaveBeenCalledWith("xfaDatasets");
  });

  it("returns null when gathering globals fails", async () => {
    const pdfManager = {
      pdfDocument: { catalog: {} },
      ensureCatalog: jest.fn(async () => {
        throw new Error("denied");
      }),
      ensureDoc: jest.fn(async () => null),
    };
    await expect(AnnotationFactory.createGlobals(pdfManager)).resolves.toBeNull();
  });

  it("dispatches every supported annotation subtype to the right class", () => {
    const xref = makeXref();
    const globals = makeGlobals();
    const cases = [
      ["Link", "LinkAnnotation"],
      ["Text", "TextAnnotation"],
      ["Widget", "TextWidgetAnnotation", { FT: Name.get("Tx") }],
      ["Popup", "PopupAnnotation"],
      ["FreeText", "FreeTextAnnotation"],
      ["Line", "LineAnnotation"],
      ["Square", "SquareAnnotation"],
      ["Circle", "CircleAnnotation"],
      ["PolyLine", "PolylineAnnotation"],
      ["Polygon", "PolygonAnnotation"],
      ["Caret", "CaretAnnotation"],
      ["Ink", "InkAnnotation"],
      ["Highlight", "HighlightAnnotation"],
      ["Underline", "UnderlineAnnotation"],
      ["Squiggly", "SquigglyAnnotation"],
      ["StrikeOut", "StrikeOutAnnotation"],
      ["Stamp", "StampAnnotation"],
      ["FileAttachment", "FileAttachmentAnnotation"],
      ["RichMedia", "RichMediaAnnotation"],
      ["Screen", "ScreenAnnotation"],
      ["Sound", "SoundAnnotation"],
    ];

    for (const [subtype, expectedClass, extra = {}] of cases) {
      const dict = makeDict({ Subtype: Name.get(subtype), ...extra }, xref);
      const annotation = AnnotationFactory._create(
        xref,
        dict,
        globals,
        { createObjId: () => 42 },
        false
      );
      expect(annotation.constructor.name).toBe(expectedClass);
      expect(annotation.data.subtype).toBe(subtype);
    }
  });

  it("dispatches widget field types, including the base fallback", () => {
    const xref = makeXref();
    const globals = makeGlobals();
    const cases = [
      ["Tx", "TextWidgetAnnotation"],
      ["Btn", "ButtonWidgetAnnotation"],
      ["Ch", "ChoiceWidgetAnnotation"],
      ["Sig", "SignatureWidgetAnnotation"],
      [null, "WidgetAnnotation"],
    ];

    for (const [fieldType, expectedClass] of cases) {
      const entries = { Subtype: Name.get("Widget") };
      if (fieldType) {
        entries.FT = Name.get(fieldType);
      }
      const annotation = AnnotationFactory._create(
        xref,
        makeDict(entries, xref),
        globals,
        { createObjId: () => 1 },
        false
      );
      expect(annotation.constructor.name).toBe(expectedClass);
    }
  });

  it("falls back to the base annotation for missing or unknown subtypes", () => {
    const xref = makeXref();
    const globals = makeGlobals();
    const unknown = AnnotationFactory._create(
      xref,
      makeDict({ Subtype: Name.get("NotAnAnnotation") }, xref),
      globals,
      { createObjId: () => 1 },
      false
    );
    const missing = AnnotationFactory._create(
      xref,
      makeDict({}, xref),
      globals,
      { createObjId: () => 1 },
      false
    );

    expect(unknown).toBeInstanceOf(Annotation);
    expect(unknown.data.annotationType).toBeUndefined();
    expect(missing).toBeInstanceOf(Annotation);
    expect(missing.data.subtype).toBeNull();
  });

  it("filters by collected type and ignores non-dictionaries", () => {
    const xref = makeXref();
    const globals = makeGlobals();
    expect(AnnotationFactory._create(xref, null, globals, { createObjId: () => 1 })).toBeUndefined();

    const square = makeDict({ Subtype: Name.get("Square") }, xref);
    expect(
      AnnotationFactory._create(
        xref,
        square,
        globals,
        { createObjId: () => 1 },
        false,
        null,
        new Set([AnnotationType.TEXT])
      )
    ).toBeNull();
    expect(
      AnnotationFactory._create(
        xref,
        square,
        globals,
        { createObjId: () => 1 },
        false,
        null,
        new Set([AnnotationType.SQUARE])
      ).constructor.name
    ).toBe("SquareAnnotation");
  });

