      fetchIfRefAsync: jest.fn(async () => makeDict({ P: Ref.get(8, 0) }, xref)),
    });
    const pdfManager = {
      evaluatorOptions: { isOffscreenCanvasSupported: false },
      ensure: jest.fn(async (obj, method, args) => obj[method](...args)),
