        expect(args).toEqual([Ref.get(8, 0)]);
        return 6;
      }),
      ensureDoc: jest.fn(),
      getPage: jest.fn(),
    };
    const globals = makeGlobals({ pdfManager });
    const dict = makeDict({ Subtype: Name.get("Text") }, xref);
    const result = await AnnotationFactory.create(
      xref,
      Ref.get(1, 0),
      globals,
      { createObjId: () => 1 },
      true
    );

    expect(result.data.pageIndex).toBe(6);
    expect(xref.fetchIfRefAsync).toHaveBeenCalledWith(Ref.get(1, 0));
  });

