    expect(
      AnnotationFactory.getPrintData({
        annotationType: AnnotationEditorType.FREETEXT,
        color: [255, 0, 0],
        fontSize: 12,
        rect: [10, 20, 110, 70],
        rotation: 90,
        value: "Hello",
      })
    ).toEqual({
      matrix: [0, 1, -1, 0, 100, 0],
      data: {
        width: 50,
        height: 100,
        text: "Hello",
        color: "#ff0000",
        fontSize: 12,
        verticalAlign: "top",
      },
    });

    expect(
      AnnotationFactory.getPrintData({
        annotationType: AnnotationEditorType.FREETEXT,
        color: null,
        fontSize: 12,
        rect: [0, 0, 10, 10],
        rotation: 0,
        value: "Hello",
      })
    ).toBeNull();
    expect(
      AnnotationFactory.getPrintData({ annotationType: AnnotationEditorType.HIGHLIGHT })
    ).toBeNull();
  });

  it("does not generate images without OffscreenCanvas support", () => {
    expect(AnnotationFactory.generateImages([], makeXref(), false)).toBeNull();
    expect(AnnotationFactory.generateImages([], makeXref(), true)).toBeUndefined();
  });
});
