    return this.bytes.length === 0;
  }

  getByte() {
    return this.pos < this.bytes.length ? this.bytes[this.pos++] : -1;
  }

  getBytes(length) {
    const end =
      length === undefined
        ? this.bytes.length
        : Math.min(this.bytes.length, this.pos + length);
    const result = this.bytes.slice(this.pos, end);
    this.pos = end;
