function makeXref(catalogDict, { objects = {}, trailer = new Dict() } = {}) {
  const lookup = ref => {
    if (typeof objects === "function") {
      return objects(ref);
    }
    if (objects instanceof Map) {
      return objects.get(ref.toString());
    }
    return objects[ref.toString()];
  };
  const resolve = value => {
    if (value instanceof Error) {
      throw value;
    }
    return value ?? null;
  };

  return {
    getCatalogObj: jest.fn(() => catalogDict),
    fetch: jest.fn(ref => resolve(lookup(ref))),
    fetchIfRef: jest.fn(value =>
      value instanceof Ref ? resolve(lookup(value)) : value
    ),
    fetchAsync: jest.fn(async value => {
      if (value instanceof Ref) {
        return resolve(lookup(value));
      }
      return value;
    }),
