class TestStream extends BaseStream {
  constructor(bytes, dict = null) {
    super();
    this.bytes = Uint8Array.from(bytes);
    this.dict = dict;
    this.pos = 0;
  }

  get length() {
    return this.bytes.length;
  }

  get isEmpty() {
    return this.bytes.length === 0;
  }

  getByte() {
    return this.pos < this.bytes.length ? this.bytes[this.pos++] : -1;
  }

  getBytes(length) {
    const end =
      length === undefined
        ? this.bytes.length
        : Math.min(this.bytes.length, this.pos + length);
    const result = this.bytes.slice(this.pos, end);
    this.pos = end;
    return result;
  }

  reset() {
    this.pos = 0;
  }
}

function makeXref(catalogDict, { objects = {}, trailer = new Dict() } = {}) {
  const lookup = ref => {
    if (typeof objects === "function") {
      return objects(ref);
    }
    if (objects instanceof Map) {
      return objects.get(ref.toString());
    }
    return objects[ref.toString()];
  };
  const resolve = value => {
    if (value instanceof Error) {
      throw value;
    }
    return value ?? null;
  };

  return {
    getCatalogObj: jest.fn(() => catalogDict),
    fetch: jest.fn(ref => resolve(lookup(ref))),
    fetchIfRef: jest.fn(value =>
      value instanceof Ref ? resolve(lookup(value)) : value
    ),
    fetchAsync: jest.fn(async value => {
      if (value instanceof Ref) {
        return resolve(lookup(value));
      }
      return value;
    }),
    trailer,
  };
}

function makeCatalog({
  entries = {},
  pages = null,
  xrefOptions = {},
  pdfManager = {},
} = {}) {
  const catDict = new Dict();
  const pagesDict = pages ?? new Dict();
  if (!pagesDict.has("Count")) {
    pagesDict.set("Count", 0);
  }
  catDict.set("Pages", pagesDict);
  for (const [key, value] of Object.entries(entries)) {
    catDict.set(key, value);
  }

  const xref = makeXref(catDict, xrefOptions);
  catDict.assignXref(xref);
  pagesDict.assignXref(xref);

  const manager = {
    docBaseUrl: "https://example.com/base/",
    evaluatorOptions: { ignoreErrors: false },
    ...pdfManager,
  };
  const catalog = new Catalog(manager, xref);

  return { catalog, catDict, pagesDict, xref, manager };
}

function makePages(xref, count, extra = {}) {
  const pages = new Dict(xref);
  pages.set("Count", count);
  for (const [key, value] of Object.entries(extra)) {
    pages.set(key, value);
  }
  return pages;
}

function makeDest(pageRef, name = "Fit") {
  return [pageRef, Name.get(name)];
}

function makeFileSpec(xref, filename, description = "") {
  const spec = new Dict(xref);
  spec.set("UF", filename);
  if (description) {
    spec.set("Desc", description);
  }
  return spec;
}

function makeEmbeddedFile(xref, bytes) {
  const stream = new TestStream(bytes, new Dict(xref));
  const ef = new Dict(xref);
  ef.set("F", stream);
  const spec = new Dict(xref);
  spec.set("UF", "attachment.bin");
  spec.set("EF", ef);
  return spec;
}

