class TestStream extends BaseStream {
  constructor(bytes, dict = null) {
    super();
    this.bytes = Uint8Array.from(bytes);
    this.dict = dict;
    this.pos = 0;
  }

  get length() {
    return this.bytes.length;
  }

  get isEmpty() {
    return this.bytes.length === 0;
  }

  getByte() {
    return this.pos < this.bytes.length ? this.bytes[this.pos++] : -1;
  }

  getBytes(length) {
    const end =
      length === undefined
        ? this.bytes.length
        : Math.min(this.bytes.length, this.pos + length);
    const result = this.bytes.slice(this.pos, end);
    this.pos = end;
    return result;
  }

  reset() {
    this.pos = 0;
  }
}

function makeXref(catalogDict, { objects = {}, trailer = new Dict() } = {}) {
  const lookup = ref => {
    if (typeof objects === "function") {
      return objects(ref);
    }
    if (objects instanceof Map) {
      return objects.get(ref.toString());
    }
    return objects[ref.toString()];
  };
  const resolve = value => {
    if (value instanceof Error) {
      throw value;
    }
    return value ?? null;
  };

  return {
    getCatalogObj: jest.fn(() => catalogDict),
    fetch: jest.fn(ref => resolve(lookup(ref))),
    fetchIfRef: jest.fn(value =>
      value instanceof Ref ? resolve(lookup(value)) : value
    ),
    fetchAsync: jest.fn(async value => {
      if (value instanceof Ref) {
        return resolve(lookup(value));
      }
      return value;
    }),
    trailer,
  };
