  test("combines NameTree and simple destination dictionaries", () => {
    const pageRef = Ref.get(70, 0);
    const nameTreeDest = makeDest(pageRef);
    const simpleDest = makeDest(pageRef, "FitH");
    const nameTree = makeNameTree(null, ["alpha", nameTreeDest]);
    const names = new Dict();
    names.set("Dests", nameTree);

    const simple = new Dict();
    simple.set("alpha", makeDest(pageRef, "FitB"));
    simple.set("gamma", simpleDest);

    const { catalog } = makeCatalog({
      entries: { Names: names, Dests: simple },
    });
    catalog.xref = catalog.xref;

    expect(catalog.destinations).toEqual(
      new Map([
        ["alpha", nameTreeDest],
        ["gamma", simpleDest],
      ])
    );
  });

  test("supports direct lookup and falls back for unsorted NameTrees", () => {
    const pageRef = Ref.get(71, 0);
    const destA = makeDest(pageRef, "Fit");
