    getPageDict: jest.fn(async index => [new Dict(), Ref.get(index + 1, 0)]),
    globalColorSpaceCache: new Map(),
    globalImageCache: new Map(),
    nonBlendModesSet: new Set(),
    numPages: 1,
    pageIndexCache: new Map(),
    pageKidsCountCache: new Map(),
    setActualNumPages: jest.fn(),
    standardFontDataCache: new Map(),
    systemFontCache: new Map(),
    ...overrides,
  };
}

describe("PDFDocument", () => {
  describe("constructor", () => {
    test("rejects an empty stream", () => {
      expect(
        () => new PDFDocument({}, new Stream(new Uint8Array(0)))
      ).toThrow(InvalidPDFException);
      expect(
        () => new PDFDocument({}, new Stream(new Uint8Array(0)))
      ).toThrow("The PDF file is empty, i.e. its size is zero bytes.");
    });

    test("requires a BaseStream instance", () => {
      expect(() => new PDFDocument({}, { length: 1 })).toThrow(
        'PDFDocument: Invalid "stream" argument.'
      );
    });

    test("stores the manager and creates an XRef", () => {
      const pdfManager = { docId: "doc-1" };
      const stream = new Stream(new Uint8Array([1]));
      const doc = new PDFDocument(pdfManager, stream);

      expect(doc.pdfManager).toBe(pdfManager);
      expect(doc.stream).toBe(stream);
      expect(doc.xref.stream).toBe(stream);
      expect(doc.xref.pdfManager).toBe(pdfManager);
    });
  });

  describe("parse", () => {
    test("parses the XRef and creates the catalog", () => {
      const pagesDict = new Dict();
      pagesDict.set("Kids", []);
      pagesDict.set("Count", 0);
      const catalogDict = new Dict();
      catalogDict.set("Pages", pagesDict);
      const xref = createXref();
      xref.parse = jest.fn();
      xref.getCatalogObj = jest.fn(() => catalogDict);
      const { doc } = createDocument({ xref });

      doc.parse(true);

      expect(xref.parse).toHaveBeenCalledWith(true);
      expect(doc.catalog).toBeDefined();
      expect(doc.catalog.numPages).toBe(0);
    });
  });

  describe("checkHeader and version", () => {
    test("reads the version from the PDF header", () => {
      const { doc, stream } = createDocument({
        bytes: "leading-junk%PDF-1.7\nrest",
      });

      doc.checkHeader();

      expect(doc.version).toBe("1.7");
      expect(stream.start).toBe("leading-junk".length);
    });

    test("ignores a malformed header version and warns", () => {
      const warn = jest.spyOn(console, "warn").mockImplementation(() => {});
      const { doc } = createDocument({ bytes: "%PDF-1.10\n" });

      doc.checkHeader();

      expect(doc.version).toBeNull();
      expect(warn).toHaveBeenCalledWith(
        expect.stringContaining("Invalid PDF header version: 1.10")
      );
      warn.mockRestore();
    });

    test("does not throw when no PDF header exists", () => {
      const { doc } = createDocument({ bytes: "plain text" });

      expect(() => doc.checkHeader()).not.toThrow();
      expect(doc.version).toBeNull();
    });

    test("the catalog version takes precedence over the header", () => {
      const { doc } = createDocument({
        bytes: "%PDF-1.7\n",
        catalog: { version: "2.0" },
      });

      doc.checkHeader();

      expect(doc.version).toBe("2.0");
    });
  });

  describe("startXRef and parseStartXRef", () => {
    test("finds the last startxref offset", () => {
      const { doc } = createDocument({
        bytes: "%PDF-1.7\n1 0 obj\n<<>>\nendobj\nstartxref\n123\n%%EOF",
      });

      expect(doc.startXRef).toBe(123);
    });

    test("searches backwards in a long file", () => {
      const padding = "x".repeat(3000);
      const { doc } = createDocument({
        bytes: `%PDF-1.5\n${padding}\nstartxref\n456\n%%EOF`,
      });

      expect(doc.startXRef).toBe(456);
    });

    test("returns 0 when startxref is missing", () => {
      const { doc } = createDocument({ bytes: "%PDF-1.7\n%%EOF" });
      expect(doc.startXRef).toBe(0);
    });

    test("returns 0 for a non-numeric startxref value", () => {
      const { doc } = createDocument({
        bytes: "%PDF-1.7\nstartxref\n%%EOF",
      });
      expect(doc.startXRef).toBe(0);
    });

    test("uses the first object end for linearized documents", () => {
      const bytes = "1 0 obj\n<<>>\nendobj\n   42 0 obj\n<<>>\nendobj";
      const { doc } = createDocument({ bytes });
      defineValue(doc, "linearization", { pageFirst: 0 });

      expect(doc.startXRef).toBe(bytes.indexOf("42 0 obj"));
    });

    test("passes the computed offset to the XRef", () => {
      const { doc } = createDocument({
        bytes: "%PDF-1.4\nstartxref\n42\n%%EOF",
        useRealXref: true,
      });

      doc.parseStartXRef();

      expect(doc.xref.startXRefQueue).toEqual([42]);
    });
  });

  describe("numPages", () => {
    test("uses the catalog page count", () => {
      const { doc } = createDocument({ catalog: { numPages: 3 } });
      expect(doc.numPages).toBe(3);
    });

    test("prefers an explicitly actual page count", () => {
      const { doc } = createDocument({
        catalog: { hasActualNumPages: true, numPages: 7 },
      });
      expect(doc.numPages).toBe(7);
    });

    test("uses the XFA factory page count when available", () => {
      const xfaFactory = { getNumPages: jest.fn(() => 5) };
      const { doc } = createDocument({
        catalog: { hasActualNumPages: false, numPages: 99 },
      });
      defineValue(doc, "xfaFactory", xfaFactory);

      expect(doc.numPages).toBe(5);
      expect(xfaFactory.getNumPages).toHaveBeenCalledTimes(1);
    });

    test("uses the linearization page count", () => {
      const { doc } = createDocument({
        catalog: { hasActualNumPages: false, numPages: 99 },
      });
      defineValue(doc, "linearization", { numPages: 4 });

      expect(doc.numPages).toBe(4);
    });

    test("is cached on the instance", () => {
      const { doc, catalog } = createDocument({ catalog: { numPages: 3 } });
      expect(doc.numPages).toBe(3);

      catalog.numPages = 10;
      expect(doc.numPages).toBe(3);
    });
  });

  describe("formInfo", () => {
    test("returns defaults without an AcroForm", () => {
      const { doc } = createDocument({ catalog: {} });

      expect(doc.formInfo).toEqual({
        hasFields: false,
        hasAcroForm: false,
        hasXfa: false,
        hasSignatures: false,
      });
    });

    test("detects fields and an AcroForm", () => {
      const field = new Dict();
      field.set("FT", Name.get("Tx"));
      const acroForm = new Dict();
      acroForm.set("Fields", [field]);
      const { doc } = createDocument({ catalog: { acroForm } });

      expect(doc.formInfo).toEqual({
        hasFields: true,
        hasAcroForm: true,
        hasXfa: false,
        hasSignatures: false,
      });
    });

    test("detects XFA data in arrays and non-empty streams", () => {
      const arrayForm = new Dict();
      arrayForm.set("XFA", ["xdp"]);
      const { doc: arrayDoc } = createDocument({
        catalog: { acroForm: arrayForm },
      });
      expect(arrayDoc.formInfo.hasXfa).toBe(true);

      const streamForm = new Dict();
      streamForm.set("XFA", new Stream(new Uint8Array([1])));
      const { doc: streamDoc } = createDocument({
        catalog: { acroForm: streamForm },
      });
      expect(streamDoc.formInfo.hasXfa).toBe(true);
    });

    test("detects signatures via /SigFlags", () => {
      const acroForm = new Dict();
      acroForm.set("Fields", []);
      acroForm.set("SigFlags", 0x1);
      const { doc } = createDocument({ catalog: { acroForm } });

      expect(doc.formInfo.hasSignatures).toBe(true);
      expect(doc.formInfo.hasFields).toBe(false);
      expect(doc.formInfo.hasAcroForm).toBe(false);
    });

    test("treats a fields list of only invisible signatures as document signatures", () => {
      const field = new Dict();
      field.set("FT", Name.get("Sig"));
      field.set("Rect", [0, 0, 0, 0]);
      const acroForm = new Dict();
      acroForm.set("Fields", [field]);
      acroForm.set("SigFlags", 0x1);
      const { doc } = createDocument({ catalog: { acroForm } });

      expect(doc.formInfo).toEqual({
        hasFields: true,
        hasAcroForm: false,
        hasXfa: false,
        hasSignatures: true,
      });
    });

    test("keeps an AcroForm when a visible signature field is present", () => {
      const field = new Dict();
      field.set("FT", Name.get("Sig"));
      field.set("Rect", [0, 0, 10, 10]);
      const acroForm = new Dict();
      acroForm.set("Fields", [field]);
      acroForm.set("SigFlags", 0x1);
      const { doc } = createDocument({ catalog: { acroForm } });

      expect(doc.formInfo.hasAcroForm).toBe(true);
      expect(doc.formInfo.hasSignatures).toBe(true);
    });

    test("checks nested Kids for document signatures", () => {
      const signature = new Dict();
      signature.set("FT", Name.get("Sig"));
      signature.set("Rect", [0, 0, 0, 0]);
      const parent = new Dict();
      parent.set("Kids", [signature]);
      const acroForm = new Dict();
      acroForm.set("Fields", [parent]);
      acroForm.set("SigFlags", 0x1);
      const { doc } = createDocument({ catalog: { acroForm } });

      expect(doc.formInfo.hasOnlyDocumentSignatures).toBeUndefined();
      expect(doc.formInfo.hasAcroForm).toBe(false);
    });

    test("stops walking too deeply nested Kids", () => {
      const warn = jest.spyOn(console, "warn").mockImplementation(() => {});
      let field = new Dict();
      field.set("FT", Name.get("Sig"));
      field.set("Rect", [0, 0, 0, 0]);
      for (let i = 0; i < 12; i++) {
        const parent = new Dict();
        parent.set("Kids", [field]);
        field = parent;
      }
      const acroForm = new Dict();
      acroForm.set("Fields", [field]);
      acroForm.set("SigFlags", 0x1);
      const { doc } = createDocument({ catalog: { acroForm } });

      expect(doc.formInfo.hasAcroForm).toBe(true);
      expect(warn).toHaveBeenCalledWith(
        expect.stringContaining("maximum recursion depth reached")
      );
      warn.mockRestore();
    });

    test("rethrows MissingDataException", () => {
      const acroForm = {
        get: jest.fn(() => {
          throw new MissingDataException(0, 10);
        }),
      };
      const { doc } = createDocument({ catalog: { acroForm } });

      expect(() => doc.formInfo).toThrow(MissingDataException);
    });
  });

  describe("documentInfo", () => {
    test("reports the basic document metadata", () => {
      const { doc } = createDocument({
