    test("copies whitelisted and custom Info entries", () => {
      const warn = jest.spyOn(console, "warn").mockImplementation(() => {});
      const info = new Dict();
      info.set("Title", "A title");
      info.set("Author", "An author");
      info.set("Trapped", Name.get("True"));
      info.set("CustomString", "value");
      info.set("CustomNumber", 12);
      info.set("CustomBoolean", false);
      info.set("CustomName", Name.get("Custom"));
      info.set("CustomDict", new Dict());
      info.set("BadTitle", 3);
      const trailer = new Dict();
      trailer.set("Info", info);
