      expect(documentInfo.Custom.get("CustomString")).toBe("value");
      expect(documentInfo.Custom.get("CustomNumber")).toBe(12);
      expect(documentInfo.Custom.get("CustomBoolean")).toBe(false);
      expect(documentInfo.Custom.get("CustomName")).toBe(Name.get("Custom"));
      expect(documentInfo.Custom.has("CustomDict")).toBe(false);
      expect(warn).toHaveBeenCalledWith(
