    });

    test("ignores a non-dictionary Info entry", () => {
      const trailer = new Dict();
      trailer.set("Info", "not-a-dict");
      const { doc } = createDocument({ xref: createXref({ trailer }) });

      expect(doc.documentInfo.PDFFormatVersion).toBeNull();
