      expect(() => doc.documentInfo).toThrow(MissingDataException);
    });
  });

  describe("fingerprints", () => {
    test("uses valid /ID values and reports a modified fingerprint", () => {
      const trailer = new Dict();
      trailer.set("ID", ["0123456789abcdef", "fedcba9876543210"]);
      const { doc } = createDocument({ xref: createXref({ trailer }) });

      expect(doc.fingerprints).toEqual([
        "30313233343536373839616263646566",
        "66656463626139383736353433323130",
      ]);
    });

    test("omits the modified fingerprint when both IDs match", () => {
      const trailer = new Dict();
      trailer.set("ID", ["0123456789abcdef", "0123456789abcdef"]);
      const { doc } = createDocument({ xref: createXref({ trailer }) });

      expect(doc.fingerprints).toEqual([
        "30313233343536373839616263646566",
        null,
      ]);
    });

    test("omits an invalid modified ID", () => {
      const trailer = new Dict();
      trailer.set("ID", ["0123456789abcdef", "too-short"]);
      const { doc } = createDocument({ xref: createXref({ trailer }) });

      expect(doc.fingerprints).toEqual([
        "30313233343536373839616263646566",
        null,
      ]);
    });

    test("computes an MD5 fingerprint when /ID is missing or invalid", () => {
      const bytes = new Uint8Array(1024);
      for (let i = 0; i < bytes.length; i++) {
        bytes[i] = i % 256;
      }
      const { doc } = createDocument({ bytes });

      expect(doc.fingerprints).toEqual([
        "b2ea9f7fcea831a4a63b213f41a8855b",
        null,
      ]);
    });
  });

  describe("getPage", () => {
    test("returns a cached Page for the page index", async () => {
      const pageDict = new Dict();
      const ref = Ref.get(10, 0);
      const catalog = createPageCatalog({
        getPageDict: jest.fn(async () => [pageDict, ref]),
      });
      const { doc } = createDocument({ catalog });

      const first = doc.getPage(0);
      const second = doc.getPage(0);
      expect(first).toBe(second);

      const page = await first;
      expect(page).toBeInstanceOf(Page);
      expect(page.pageIndex).toBe(0);
      expect(page.pageDict).toBe(pageDict);
      expect(page.ref).toBe(ref);
      expect(page.xfaFactory).toBeNull();
      expect(catalog.getPageDict).toHaveBeenCalledTimes(1);
      expect(catalog.getPageDict).toHaveBeenCalledWith(0);
    });

    test("returns an empty page for XFA documents", async () => {
      const catalog = createPageCatalog();
      const { doc } = createDocument({ catalog });
      const xfaFactory = { getNumPages: () => 1 };
      defineValue(doc, "xfaFactory", xfaFactory);

      const page = await doc.getPage(3);

      expect(page.pageIndex).toBe(3);
      expect(page.pageDict).toBe(Dict.empty);
      expect(page.ref).toBeNull();
      expect(page.xfaFactory).toBe(xfaFactory);
      expect(catalog.getPageDict).not.toHaveBeenCalled();
    });

    test("uses the linearization dictionary for the first page", async () => {
      const pageDict = new Dict();
      pageDict.set("Type", Name.get("Page"));
      const ref = Ref.get(5, 0);
      const xref = createXref({
        fetchMap: new Map([[ref.toString(), pageDict]]),
      });
      const catalog = createPageCatalog();
      const { doc } = createDocument({ catalog, xref });
      defineValue(doc, "linearization", {
        objectNumberFirst: 5,
        pageFirst: 0,
      });

      const page = await doc.getPage(0);

      expect(page.pageDict).toBe(pageDict);
      expect(page.ref).toBe(ref);
      expect(catalog.getPageDict).not.toHaveBeenCalled();
      expect(catalog.pageKidsCountCache.get(ref)).toBe(1);
      expect(catalog.pageIndexCache.get(ref)).toBe(0);
    });

    test("falls back to the catalog when the linearized object is invalid", async () => {
      const warn = jest.spyOn(console, "warn").mockImplementation(() => {});
      const invalidDict = new Dict();
      invalidDict.set("Type", Name.get("NotAPage"));
      const ref = Ref.get(5, 0);
      const fallbackDict = new Dict();
      const fallbackRef = Ref.get(9, 0);
      const xref = createXref({
        fetchMap: new Map([[ref.toString(), invalidDict]]),
