        }),
      });
      const { doc } = createDocument({ catalog });

      await expect(doc.checkLastPage()).rejects.toBeInstanceOf(
        XRefParseException
      );
      expect(catalog.cleanup).toHaveBeenCalledWith(false);
    });

    test("repairs the page tree when the page count is invalid", async () => {
      const warn = jest.spyOn(console, "warn").mockImplementation(() => {});
      const repairedDict = new Dict();
      const repairedRef = Ref.get(20, 0);
      const catalog = createPageCatalog({
        numPages: 2.5,
        getAllPageDicts: jest.fn(async () => {
          return new Map([
            [0, [repairedDict, repairedRef]],
            [1, [new Error("broken page"), null]],
          ]);
        }),
      });
      const { doc } = createDocument({ catalog });

      await doc.checkLastPage();

      expect(catalog.cleanup).toHaveBeenCalledWith(false);
      expect(catalog.getAllPageDicts).toHaveBeenCalledWith(false);
      expect(catalog.setActualNumPages).toHaveBeenLastCalledWith(2);
      const page = await doc.getPage(0);
      expect(page.pageDict).toBe(repairedDict);
      await expect(doc.getPage(1)).rejects.toThrow("broken page");
      expect(warn).toHaveBeenCalledWith(
        expect.stringContaining("checkLastPage - invalid /Pages tree /Count")
      );
      warn.mockRestore();
    });

    test("throws XRefParseException when the page tree cannot be recovered", async () => {
      const catalog = createPageCatalog({
        numPages: 2.5,
        getAllPageDicts: jest.fn(async () => {
          throw new XRefEntryException("bad tree");
