      );
    });

    test("falls back to one page when the page tree recovery fails", async () => {
      const warn = jest.spyOn(console, "warn").mockImplementation(() => {});
      const catalog = createPageCatalog({
        numPages: 2.5,
        getAllPageDicts: jest.fn(async () => {
          throw new Error("unrecoverable");
        }),
      });
      const { doc } = createDocument({ catalog });

