  describe("signatures and getSignatureData", () => {
    function createSignatureDocument({
      contents = "SIGNATURE",
      byteRange = [0, 10, 20, 10],
      streamLength = 30,
      extras = {},
      countUpdatesAfter = () => 0,
    } = {}) {
      const fieldRef = Ref.get(1, 0);
      const field = new Dict();
      field.set("FT", Name.get("Sig"));
      field.set("T", "Signature1");
      field.set("Rect", [0, 0, 0, 0]);
      const sigDict = new Dict();
      sigDict.set("ByteRange", byteRange);
      sigDict.set("Contents", contents);
      sigDict.set("SubFilter", Name.get("adbe.pkcs7.detached"));
      sigDict.set("Filter", Name.get("Adobe.PPKLite"));
      sigDict.set("Name", "Alice");
      sigDict.set("Reason", "Approved");
      sigDict.set("Location", "Somewhere");
      sigDict.set("ContactInfo", "alice@example.test");
      sigDict.set("M", "D:20240101000000Z");
      for (const [key, value] of Object.entries(extras)) {
        sigDict.set(key, value);
      }
      field.set("V", sigDict);

      const acroForm = new Dict();
      acroForm.set("Fields", [fieldRef]);
      acroForm.set("SigFlags", 0x1);
      const xref = createXref({
        fetchMap: new Map([[fieldRef.toString(), field]]),
        countUpdatesAfter,
      });
      const { doc, stream } = createDocument({
        bytes: new Uint8Array(streamLength),
        catalog: { acroForm },
        xref,
      });
      return { doc, fieldRef, field, sigDict, stream, xref };
    }

    test("returns null when the document has no signatures", async () => {
      const { doc } = createDocument({ catalog: {} });
      await expect(doc.signatures).resolves.toBeNull();
      await expect(doc.getSignatureData("1R:0-0-0-0")).resolves.toBeNull();
    });

    test("collects the signature metadata", async () => {
      const { doc, fieldRef, xref } = createSignatureDocument();

      const signatures = await doc.signatures;

      expect(signatures).toHaveLength(1);
      expect(signatures[0]).toMatchObject({
        id: `${fieldRef}:0-10-20-10`,
        fieldName: "Signature1",
        signerName: "Alice",
        reason: "Approved",
        location: "Somewhere",
        contactInfo: "alice@example.test",
        signingTime: "D:20240101000000Z",
        filter: "Adobe.PPKLite",
        subFilter: "adbe.pkcs7.detached",
        signatureType: 0,
        byteRange: [0, 10, 20, 10],
        revisionIndex: 0,
        parentId: null,
        modificationsAfterSignature: 0,
        coversWholeDocument: true,
      });
      expect(signatures[0]).not.toHaveProperty("pkcs7");
      expect(xref.countUpdatesAfter).toHaveBeenCalledWith(30);
    });

    test("exposes the signed bytes through getSignatureData", async () => {
      const { doc, fieldRef } = createSignatureDocument({
        contents: "ABCD",
        byteRange: [0, 4, 10, 4],
        streamLength: 14,
      });
      await doc.signatures;

      const signatureData = await doc.getSignatureData(
        `${fieldRef}:0-4-10-4`
      );

      expect(signatureData).not.toBeNull();
      expect(signatureData.data).toHaveLength(2);
      expect(signatureData.data[0]).toEqual(new Uint8Array([0, 0, 0, 0]));
      expect(signatureData.data[1]).toEqual(new Uint8Array([0, 0, 0, 0]));
      expect(signatureData.pkcs7).toEqual(
        new Uint8Array([0x41, 0x42, 0x43, 0x44])
      );
    });

    test("detects modifications after the signed range", async () => {
      const { doc } = createSignatureDocument({
        streamLength: 35,
        countUpdatesAfter: () => 2,
      });

      const [signature] = await doc.signatures;

      expect(signature.modificationsAfterSignature).toBe(2);
      expect(signature.coversWholeDocument).toBe(false);
    });

    test("detects trailing non-whitespace after the signed range", async () => {
      const bytes = new Uint8Array(35);
      bytes.set(new TextEncoder().encode("abcde"), 30);
      const fieldRef = Ref.get(2, 0);
      const field = new Dict();
      field.set("FT", Name.get("Sig"));
      const sigDict = new Dict();
      sigDict.set("ByteRange", [0, 10, 20, 10]);
      sigDict.set("Contents", "X");
      field.set("V", sigDict);
      const acroForm = new Dict();
      acroForm.set("Fields", [fieldRef]);
      acroForm.set("SigFlags", 0x1);
      const xref = createXref({
        fetchMap: new Map([[fieldRef.toString(), field]]),
      });
      const { doc } = createDocument({ bytes, catalog: { acroForm }, xref });

      const [signature] = await doc.signatures;

      expect(signature.coversWholeDocument).toBe(false);
    });

    test("ignores structurally invalid byte ranges", async () => {
      const { doc } = createSignatureDocument({
        byteRange: [1, 10, 20, 10],
      });

      await expect(doc.signatures).resolves.toBeNull();
    });

    test("groups signatures by byte-range containment", async () => {
      const outerRef = Ref.get(1, 0);
      const innerRef = Ref.get(2, 0);
      const makeField = (ref, byteRange, contents) => {
        const field = new Dict();
        field.set("FT", Name.get("Sig"));
        field.set("T", ref.toString());
        field.set("Rect", [0, 0, 0, 0]);
        const sigDict = new Dict();
        sigDict.set("ByteRange", byteRange);
        sigDict.set("Contents", contents);
        field.set("V", sigDict);
        return field;
      };
      const outerField = makeField(outerRef, [0, 10, 40, 10], "OUTER");
      const innerField = makeField(innerRef, [0, 10, 20, 10], "INNER");
      const acroForm = new Dict();
      acroForm.set("Fields", [innerRef, outerRef]);
      acroForm.set("SigFlags", 0x1);
      const xref = createXref({
        fetchMap: new Map([
          [outerRef.toString(), outerField],
          [innerRef.toString(), innerField],
        ]),
      });
      const { doc } = createDocument({
        bytes: new Uint8Array(60).fill(0x20),
        catalog: { acroForm },
        xref,
      });

      const signatures = await doc.signatures;

      expect(signatures.map(signature => signature.id)).toEqual([
        `${outerRef}:0-10-40-10`,
        `${innerRef}:0-10-20-10`,
      ]);
      expect(signatures[0].revisionIndex).toBe(0);
      expect(signatures[0].parentId).toBeNull();
      expect(signatures[1].revisionIndex).toBe(1);
      expect(signatures[1].parentId).toBe(signatures[0].id);
    });
  });

