      const trailer = new Dict();
      trailer.set("Producer", "pdf.js");
      const { doc } = createDocument({ xref: createXref({ trailer }) });

      await expect(doc.toJSObject(null)).resolves.toEqual({
        Producer: "pdf.js",
      });
    });

    test("resolves references on the first call and describes them otherwise", async () => {
      const ref = Ref.get(7, 0);
      const target = new Dict();
      target.set("Type", Name.get("Page"));
      target.set("Value", 1);
      const xref = createXref({ fetchMap: new Map([[ref.toString(), target]]) });
      const { doc } = createDocument({ xref });

      await expect(doc.toJSObject(ref)).resolves.toEqual({
        Type: Name.get("Page"),
        Value: 1,
      });
      await expect(doc.toJSObject(ref, false)).resolves.toEqual({
        gen: 0,
        num: 7,
      });
    });

    test("converts streams to their bytes", async () => {
      const { doc } = createDocument();
      const stream = new StringStream("stream contents");

      await expect(doc.toJSObject(stream, false)).resolves.toEqual({
        bytes: "stream contents",
        dict: null,
      });
    });
  });
});
