  cff.charset = new CFFCharset(true,0,ISOAdobeCharset);
  cff.charStrings = new CFFIndex();
  for (const g of charStrings) cff.charStrings.add(new Uint8Array(g));
  cff.encoding = null;
  return cff;
}
