{"command": "cd /testbed; cat > test/core/cff_parser.test.js <<'EOF'
import { jest } from "@jest/globals";

import {
  CFF,
  CFFCharset,
  CFFCompiler,
  CFFFDSelect,
  CFFHeader,
  CFFIndex,
  CFFParser,
  CFFPrivateDict,
  CFFStandardStrings,
  CFFStrings,
  CFFTopDict,
} from "../../src/core/cff_parser.js";
import {
  ExpertCharset,
  ExpertSubsetCharset,
  ISOAdobeCharset,
} from "../../src/core/charsets.js";

const compiler = new CFFCompiler({});

function makeParser(bytes, { properties = {}, seacAnalysisEnabled = false } = {}) {
  return new CFFParser(
    { getBytes: () => bytes },
    properties,
    seacAnalysisEnabled
  );
}

function bytesWithOffset(offset, bytes) {
  const out = new Uint8Array(offset + bytes.length);
  out.set(bytes, offset);
  return out;
}

function u16(value) {
  return [(value >> 8) & 0xff, value & 0xff];
}

function makePrivateDict(values = {}) {
  const dict = new CFFPrivateDict(new CFFStrings());
  for (const [name, value] of Object.entries(values)) {
    dict.setByName(name, value);
  }
  return dict;
}

function makePrivateDictWithSubrs(defaultWidthX, nominalWidthX) {
  const dict = makePrivateDict({ defaultWidthX, nominalWidthX });
  const subrs = new CFFIndex();
  subrs.add(new Uint8Array([139, 11]));
  dict.subrsIndex = subrs;
  return dict;
}

function privateDictBytes(fields) {
  const out = [];
  for (const [opcode, values] of fields) {
    for (const value of values) {
      out.push(...compiler.encodeNumber(value));
    }
    if (Array.isArray(opcode)) {
      out.push(...opcode);
    } else {
      out.push(opcode);
    }
  }
  return new Uint8Array(out);
}

function createCharState(overrides = {}) {
  return {
    callDepth: 0,
    stackSize: 0,
    stack: [],
    hints: 0,
    firstStackClearing: true,
    seac: null,
    width: null,
    hasVStems: false,
    ...overrides,
  };
}

function createCFF({
  names = ["TestFont"],
  customStrings = [],
  charStrings = [[0x8b, 0x0e]],
  privateValues = {},
  subrs = null,
  globalSubrIndex = new CFFIndex(),
  charset = new CFFCharset(true, 0, ISOAdobeCharset),
  topDictValues = {},
} = {}) {
  const cff = new CFF(0);
  cff.header = new CFFHeader(1, 0, 4, 4);
  cff.names = [...names];
  cff.strings = new CFFStrings();
  for (const value of customStrings) {
    cff.strings.add(value);
  }
  cff.globalSubrIndex = globalSubrIndex;
  cff.topDict = new CFFTopDict(cff.strings);
  cff.topDict.setByKey(17, [0]); // CharStrings

  const privateDict = makePrivateDict(privateValues);
  if (subrs) {
    privateDict.setByName("Subrs", 0);
    privateDict.subrsIndex = subrs;
  }
  cff.topDict.setByKey(18, [0, 0]); // Private
  cff.topDict.privateDict = privateDict;

  for (const [name, value] of Object.entries(topDictValues)) {
    cff.topDict.setByName(name, value);
  }

  cff.charset = charset;
  cff.charStrings = new CFFIndex();
  for (const glyph of charStrings) {
    cff.charStrings.add(new Uint8Array(glyph));
  }
  cff.encoding = null;
  return cff;
}

function createCIDCFF({
  charStrings = [
    [139, 14],
    [140, 14],
    [141, 14],
  ],
  fdCount = 2,
  fdSelect = [0, 0, 1],
  fdSelectFormat = 3,
  fdPrivateValues = [],
  topFontMatrix = null,
} = {}) {
  const cff = new CFF(0);
  cff.header = new CFFHeader(1, 0, 4, 4);
  cff.names = ["CIDFont"];
  cff.strings = new CFFStrings();
  cff.globalSubrIndex = new CFFIndex();
  cff.topDict = new CFFTopDict(cff.strings);
  cff.topDict.setByKey(3102, [0, 1, 0]); // ROS
  cff.topDict.setByKey(17, [0]); // CharStrings
  cff.topDict.setByKey(3108, [0]); // FDArray
  cff.topDict.setByKey(3109, [0]); // FDSelect
  if (topFontMatrix) {
    cff.topDict.setByName("FontMatrix", topFontMatrix);
  }
  cff.topDict.setByKey(18, [0, 0]);
  cff.topDict.privateDict = new CFFPrivateDict(cff.strings);

  cff.charset = new CFFCharset(
    true,
    0,
    charStrings.map((_, index) => index)
  );
  cff.charStrings = new CFFIndex();
  for (const glyph of charStrings) {
    cff.charStrings.add(new Uint8Array(glyph));
  }

  cff.fdArray = [];
  for (let index = 0; index < fdCount; index++) {
    const fontDict = new CFFTopDict(cff.strings);
    const privateDict = makePrivateDict(fdPrivateValues[index]);
    fontDict.setByKey(18, [0, 0]);
    fontDict.privateDict = privateDict;
    cff.fdArray.push(fontDict);
  }
  cff.fdSelect = new CFFFDSelect(fdSelectFormat, fdSelect);
  cff.isCIDFont = true;
  return cff;
}

function compileAndParse(cff, parserOptions = {}) {
  const bytes = new CFFCompiler(cff).compile();
  const parser = makeParser(bytes, parserOptions);
  return { bytes, parsed: parser.parse(), parser };
}

function decodeNumber(encoded) {
  const parser = makeParser(new Uint8Array(0));
  const data = new Uint8Array([...encoded, 0]);
  return parser.parseDict(data)[0][1][0];
}

let warnSpy;

beforeEach(() => {
  warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
});

afterEach(() => {
  warnSpy.mockRestore();
});

describe("CFFStandardStrings", () => {
  test("contains the 391 standard CFF strings", () => {
    expect(CFFStandardStrings).toHaveLength(391);
    expect(CFFStandardStrings[0]).toBe(".notdef");
    expect(CFFStandardStrings[1]).toBe("space");
    expect(CFFStandardStrings[34]).toBe("A");
    expect(CFFStandardStrings[390]).toBe("Semibold");
  });
});

describe("CFFStrings", () => {
  test("resolves standard SIDs and falls back for unknown indexes", () => {
    const strings = new CFFStrings();

    expect(strings.count).toBe(0);
    expect(strings.get(0)).toBe(".notdef");
    expect(strings.get(1)).toBe("space");
    expect(strings.get(390)).toBe("Semibold");
    expect(strings.get(392)).toBe(".notdef");
  });

  test("stores custom strings and maps them to SIDs", () => {
    const strings = new CFFStrings();
    strings.add("CustomA");
    strings.add("CustomB");

    expect(strings.count).toBe(2);
    expect(strings.get(391)).toBe("CustomA");
    expect(strings.get(392)).toBe("CustomB");
    expect(strings.getSID(".notdef")).toBe(0);
    expect(strings.getSID("space")).toBe(1);
    expect(strings.getSID("CustomA")).toBe(391);
    expect(strings.getSID("CustomB")).toBe(392);
    expect(strings.getSID("Missing")).toBe(-1);
  });
});

describe("CFFIndex, CFFHeader, CFFCharset and CFFFDSelect", () => {
  test("CFFIndex tracks total length through add and set", () => {
    const index = new CFFIndex();
    index.add(new Uint8Array([1, 2]));
    expect(index.length).toBe(2);
    expect(index.count).toBe(1);

    index.add(new Uint8Array([3]));
    expect(index.length).toBe(3);
    expect(index.count).toBe(2);

    index.set(0, new Uint8Array([4, 5, 6, 7]));
    expect(index.length).toBe(5);
    expect(Array.from(index.get(0))).toEqual([4, 5, 6, 7]);
    expect(Array.from(index.get(1))).toEqual([3]);
    expect(index.get(99)).toBeUndefined();
  });

  test("CFFHeader exposes all constructor fields", () => {
    const header = new CFFHeader(2, 1, 4, 3);
    expect(header).toMatchObject({
      major: 2,
      minor: 1,
      hdrSize: 4,
      offSize: 3,
    });
  });

  test("CFFCharset stores the charset description", () => {
    const charset = new CFFCharset(false, 1, ["a", "b"]);
    expect(charset.predefined).toBe(false);
    expect(charset.format).toBe(1);
    expect(charset.charset).toEqual(["a", "b"]);
  });

  test("CFFFDSelect bounds-checks glyph lookups", () => {
    const fdSelect = new CFFFDSelect(0, [0, 1, 2]);
    expect(fdSelect.format).toBe(0);
    expect(fdSelect.getFDIndex(-1)).toBe(-1);
    expect(fdSelect.getFDIndex(0)).toBe(0);
    expect(fdSelect.getFDIndex(2)).toBe(2);
    expect(fdSelect.getFDIndex(3)).toBe(-1);
  });
});

describe("CFFDict through CFFTopDict and CFFPrivateDict", () => {
  test("returns layout defaults for absent entries", () => {
    const dict = new CFFTopDict(new CFFStrings());

    expect(dict.hasName("FontBBox")).toBe(false);
    expect(dict.getByName("FontBBox")).toEqual([0, 0, 0, 0]);
    expect(dict.getByName("FontMatrix")).toEqual([0.001, 0, 0, 0.001, 0, 0]);
    expect(dict.getByName("CharstringType")).toBe(2);
    expect(dict.getByName("ItalicAngle")).toBe(0);
    expect(dict.getByName("CIDCount")).toBe(8720);
    expect(dict.getByName("charset")).toBe(0);
  });

  test("sets scalar values by key and by name", () => {
    const dict = new CFFTopDict(new CFFStrings());

    expect(dict.setByKey(17, [123])).toBe(true); // CharStrings (offset)
    expect(dict.hasName("CharStrings")).toBe(true);
    expect(dict.getByName("CharStrings")).toBe(123);

    dict.setByName("ItalicAngle", -12);
    expect(dict.hasName("ItalicAngle")).toBe(true);
    expect(dict.getByName("ItalicAngle")).toBe(-12);
  });

  test("keeps array and delta typed values as arrays", () => {
    const topDict = new CFFTopDict(new CFFStrings());
    topDict.setByKey(14, [1, 2, 3]); // XUID
    expect(topDict.getByName("XUID")).toEqual([1, 2, 3]);

    const privateDict = new CFFPrivateDict(new CFFStrings());
    privateDict.setByKey(6, [10, 20, 30]); // BlueValues
    expect(privateDict.getByName("BlueValues")).toEqual([10, 20, 30]);
  });

  test("ignores unknown keys, empty values and invalid numbers", () => {
    const dict = new CFFTopDict(new CFFStrings());

    expect(dict.setByKey(9999, [1])).toBe(false);
    expect(dict.hasName("CharStrings")).toBe(false);

    expect(dict.setByKey(17, [])).toBe(true);
    expect(dict.hasName("CharStrings")).toBe(false);

    expect(dict.setByKey(17, [NaN])).toBe(true);
    expect(dict.hasName("CharStrings")).toBe(false);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Invalid CFFDict value")
    );
  });

  test("throws on unknown dictionary names", () => {
    const dict = new CFFTopDict(new CFFStrings());

    expect(() => dict.setByName("Bogus", 1)).toThrow(
      /Invalid dictionary name "Bogus"/
    );
    expect(() => dict.getByName("Bogus")).toThrow(/Invalid dictionary name/);
  });

  test("removeByName makes getByName fall back to the default", () => {
    const dict = new CFFTopDict(new CFFStrings());
    dict.setByName("ItalicAngle", 5);
    expect(dict.hasName("ItalicAngle")).toBe(true);

    dict.removeByName("ItalicAngle");
    expect(dict.hasName("ItalicAngle")).toBe(false);
    expect(dict.getByName("ItalicAngle")).toBe(0);
  });

  test("exposes the static table layouts", () => {
    const topTables = CFFTopDict.tables;
    expect(topTables.nameToKeyMap.get("ROS")).toBe(3102);
    expect(topTables.keyToNameMap.get(3102)).toBe("ROS");
    expect(topTables.opcodes.get(3102)).toEqual([12, 30]);
    expect(topTables.opcodes.get(5)).toEqual([5]);
    expect(topTables.types.get(5)).toEqual(["num", "num", "num", "num"]);
    expect(topTables.order[0]).toBe(3102);

    const privateTables = CFFPrivateDict.tables;
    expect(privateTables.nameToKeyMap.get("BlueScale")).toBe(3081);
    expect(privateTables.types.get(6)).toBe("delta");
    expect(privateTables.defaults.get(3081)).toBeCloseTo(0.039625);
    expect(privateTables.defaults.get(20)).toBe(0); // defaultWidthX
    expect(privateTables.defaults.get(21)).toBe(0); // nominalWidthX
  });
});

describe("CFFParser header and INDEX parsing", () => {
  test("parses a regular CFF header", () => {
    const parser = makeParser(new Uint8Array([1, 0, 4, 3]));
    const { obj, endPos } = parser.parseHeader();

    expect(obj.major).toBe(1);
    expect(obj.minor).toBe(0);
    expect(obj.hdrSize).toBe(4);
    expect(obj.offSize).toBe(3);
    expect(endPos).toBe(4);
  });

  test("skips leading bytes before a shifted header", () => {
    const parser = makeParser(new Uint8Array([9, 9, 1, 0, 5, 3]));
    const { obj, endPos } = parser.parseHeader();

    expect(obj.hdrSize).toBe(5);
    expect(endPos).toBe(5);
    expect(parser.bytes).toHaveLength(4);
    expect(parser.bytes[0]).toBe(1);
  });

  test("throws for data without a CFF header marker", () => {
    const parser = makeParser(new Uint8Array([2, 3, 4, 5]));
    expect(() => parser.parseHeader()).toThrow(/Invalid CFF header/);
  });

  test("parses an empty INDEX", () => {
    const parser = makeParser(new Uint8Array([0, 0]));
    const { obj, endPos } = parser.parseIndex(0);

    expect(obj.count).toBe(0);
    expect(endPos).toBe(2);
  });

  test("parses a one-object INDEX and reports its end", () => {
    const parser = makeParser(new Uint8Array([0, 1, 1, 1, 3, 0xaa, 0xbb]));
    const { obj, endPos } = parser.parseIndex(0);

    expect(obj.count).toBe(1);
    expect(Array.from(obj.get(0))).toEqual([0xaa, 0xbb]);
    expect(endPos).toBe(7);
  });

  test("parses a multi-object INDEX", () => {
    const parser = makeParser(
      new Uint8Array([0, 2, 1, 1, 2, 4, 0xaa, 0xbb, 0xcc])
    );
    const { obj, endPos } = parser.parseIndex(0);

    expect(obj.count).toBe(2);
    expect(Array.from(obj.get(0))).toEqual([0xaa]);
    expect(Array.from(obj.get(1))).toEqual([0xbb, 0xcc]);
    expect(endPos).toBe(9);
  });

  test("rejects invalid INDEX offset sizes", () => {
    expect(() => makeParser(new Uint8Array([0, 1, 0])).parseIndex(0)).toThrow(
      /Invalid CFF INDEX offset size: 0/
    );
    expect(() => makeParser(new Uint8Array([0, 1, 5])).parseIndex(0)).toThrow(
      /Invalid CFF INDEX offset size: 5/
    );
  });

  test("decodes name and string INDEX contents", () => {
    const nameBytes = compiler.compileNameIndex(["Font One"]);
    const nameParser = makeParser(nameBytes);
    const nameIndex = nameParser.parseIndex(0).obj;
    expect(nameParser.parseNameIndex(nameIndex)).toEqual(["Font_One"]);

    const stringBytes = compiler.compileStringIndex(["CustomA", "CustomB"]);
    const stringParser = makeParser(stringBytes);
    const stringIndex = stringParser.parseIndex(0).obj;
    const strings = stringParser.parseStringIndex(stringIndex);

    expect(strings.count).toBe(2);
    expect(strings.get(391)).toBe("CustomA");
    expect(strings.get(392)).toBe("CustomB");
  });
});

describe("CFFParser.parseDict", () => {
  test("decodes all integer operand encodings", () => {
    const parser = makeParser(new Uint8Array(0));
    const data = new Uint8Array([
      139, // 0
      247, 0, // 108
      250, 255, // 1131
      251, 0, // -108
      254, 255, // -1131
      28, 0x12, 0x34, // shortint 4660
      29, 0, 0, 0x12, 0x34, // longint 4660
      0, // operator
    ]);

    const entries = parser.parseDict(data);
    expect(entries).toHaveLength(1);
    expect(entries[0][0]).toBe(0);
    expect(entries[0][1]).toEqual([0, 108, 1131, -108, -1131, 4660, 4660]);
  });

  test("decodes real-number operands", () => {
    const parser = makeParser(new Uint8Array(0));

    const positive = parser.parseDict(new Uint8Array([30, 0x1a, 0x5f, 0]));
    expect(positive[0][1]).toEqual([1.5]);

    const negative = parser.parseDict(
      new Uint8Array([30, 0x1e, 0xe1, 0xa5, 0xff, 0])
    );
    expect(negative[0][1]).toEqual([-1.5]);
  });

  test("combines the two-byte escaped operator", () => {
    const parser = makeParser(new Uint8Array(0));
    const entries = parser.parseDict(new Uint8Array([12, 30]));

    expect(entries).toEqual([[3102, []]]);
  });

  test("groups operands per operator", () => {
    const parser = makeParser(new Uint8Array(0));
    const entries = parser.parseDict(new Uint8Array([139, 140, 0, 139, 1]));

    expect(entries).toEqual([
      [0, [0, 1]],
      [1, [0]],
    ]);
  });

  test("treats reserved operand bytes as NaN", () => {
    const parser = makeParser(new Uint8Array(0));
    const entries = parser.parseDict(new Uint8Array([255, 0]));

    expect(entries).toHaveLength(1);
    expect(Number.isNaN(entries[0][1][0])).toBe(true);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("is a reserved command")
    );
  });
});

describe("CFFParser.parseCharsets", () => {
  test("returns predefined charsets for offsets 0, 1 and 2", () => {
    const parser = makeParser(new Uint8Array(0));
    const strings = new CFFStrings();

    const iso = parser.parseCharsets(0, 3, strings, false);
    expect(iso.predefined).toBe(true);
    expect(iso.format).toBe(0);
    expect(iso.charset).toBe(ISOAdobeCharset);

    const expert = parser.parseCharsets(1, 3, strings, false);
    expect(expert.predefined).toBe(true);
    expect(expert.format).toBe(1);
    expect(expert.charset).toBe(ExpertCharset);

    const expertSubset = parser.parseCharsets(2, 3, strings, false);
    expect(expertSubset.predefined).toBe(true);
    expect(expertSubset.format).toBe(2);
    expect(expertSubset.charset).toBe(ExpertSubsetCharset);
  });

  test("parses a format 0 charset and resolves string SIDs", () => {
    const strings = new CFFStrings();
    strings.add("CustomA");
    const bytes = bytesWithOffset(
      3,
      new Uint8Array([0, ...u16(0), ...u16(391)])
    );
    const parser = makeParser(bytes);

    const charset = parser.parseCharsets(3, 3, strings, false);
    expect(charset.predefined).toBe(false);
    expect(charset.format).toBe(0);
    expect(charset.charset).toEqual([".notdef", ".notdef", "CustomA"]);
  });

  test("keeps numeric ids for a CID format 0 charset", () => {
    const strings = new CFFStrings();
    const bytes = bytesWithOffset(
      3,
      new Uint8Array([0, ...u16(0), ...u16(391)])
    );
    const parser = makeParser(bytes);

    const charset = parser.parseCharsets(3, 3, strings, true);
    expect(charset.charset).toEqual([0, 0, 391]);
  });

  test("expands format 1 and format 2 charset ranges", () => {
    const strings = new CFFStrings();
    strings.add("CustomA");
    strings.add("CustomB");

    const format1 = makeParser(
      bytesWithOffset(3, new Uint8Array([1, ...u16(391), 1]))
    ).parseCharsets(3, 3, strings, false);
    expect(format1.format).toBe(1);
    expect(format1.charset).toEqual([".notdef", "CustomA", "CustomB"]);

    const format2 = makeParser(
      bytesWithOffset(3, new Uint8Array([2, ...u16(391), ...u16(1)]))
    ).parseCharsets(3, 3, strings, true);
    expect(format2.format).toBe(2);
    expect(format2.charset).toEqual([0, 391, 392]);
  });

  test("rejects unknown charset formats", () => {
    const parser = makeParser(bytesWithOffset(3, new Uint8Array([5, 0])));
    expect(() => parser.parseCharsets(3, 1, new CFFStrings(), false)).toThrow(
      /Unknown charset format/
    );
  });
});

describe("CFFParser.parseEncoding", () => {
  test("builds StandardEncoding mappings for a predefined encoding", () => {
    const parser = makeParser(new Uint8Array([0]));
    const encoding = parser.parseEncoding(
      0,
      {},
      new CFFStrings(),
      [".notdef", "A", "B"]
    );

    expect(encoding.predefined).toBe(true);
    expect(encoding.format).toBe(0);
    expect(encoding.raw).toBeNull();
    expect(encoding.encoding).toEqual({ 65: 0, 66: 1 });
  });

  test("builds ExpertEncoding mappings for a predefined encoding", () => {
    const parser = makeParser(new Uint8Array([1]));
    const encoding = parser.parseEncoding(
      1,
      {},
      new CFFStrings(),
      ["space", "A"]
    );

    expect(encoding.predefined).toBe(true);
    expect(encoding.format).toBe(1);
    expect(encoding.raw).toBeNull();
    expect(encoding.encoding).toEqual({ 32: 0 });
  });

  test("parses a custom format 0 encoding", () => {
    const parser = makeParser(
      bytesWithOffset(3, new Uint8Array([0, 2, 65, 66]))
    );
    const encoding = parser.parseEncoding(
      3,
      {},
      new CFFStrings(),
      [".notdef", "A", "B"]
    );

    expect(encoding.predefined).toBe(false);
    expect(encoding.format).toBe(0);
    expect(encoding.encoding).toEqual({ 65: 1, 66: 2 });
    expect(Array.from(encoding.raw)).toEqual([0, 2, 65, 66]);
  });

  test("parses a custom format 1 encoding with ranges", () => {
    const parser = makeParser(
      bytesWithOffset(3, new Uint8Array([1, 2, 65, 1, 67, 1]))
    );
    const encoding = parser.parseEncoding(3, {}, new CFFStrings(), []);

    expect(encoding.format).toBe(1);
    expect(encoding.encoding).toEqual({ 65: 1, 66: 2, 67: 3, 68: 4 });
    expect(Array.from(encoding.raw)).toEqual([1, 2, 65, 1, 67, 1]);
  });

  test("reads and normalizes an encoding supplement", () => {
    const parser = makeParser(
      bytesWithOffset(3, new Uint8Array([0x80, 1, 65, 1, 66, 0, 1]))
    );
    const encoding = parser.parseEncoding(
      3,
      {},
      new CFFStrings(),
      ["space", "A"]
    );

    expect(encoding.format).toBe(0);
    expect(encoding.encoding).toEqual({ 65: 1, 66: 0 });
    expect(Array.from(encoding.raw)).toEqual([0, 1, 65]);
    expect(parser.bytes[3]).toBe(0); // high bit cleared
  });

  test("rejects unknown encoding formats", () => {
    const parser = makeParser(bytesWithOffset(3, new Uint8Array([2])));
    expect(() =>
      parser.parseEncoding(3, {}, new CFFStrings(), [])
    ).toThrow(/Unknown encoding format: 2/);
  });
});

describe("CFFParser.parseFDSelect", () => {
  test("parses format 0 FDSelect data", () => {
    const parser = makeParser(
      bytesWithOffset(3, new Uint8Array([0, 0, 1, 2]))
    );
    const fdSelect = parser.parseFDSelect(3, 3);

    expect(fdSelect.format).toBe(0);
    expect(fdSelect.fdSelect).toEqual([0, 1, 2]);
    expect(fdSelect.getFDIndex(-1)).toBe(-1);
    expect(fdSelect.getFDIndex(3)).toBe(-1);
  });

  test("parses format 3 FDSelect ranges", () => {
    const parser = makeParser(
      bytesWithOffset(
        3,
        new Uint8Array([3, 0, 2, 0, 0, 0, 0, 2, 1, 0, 3])
      )
    );
    const fdSelect = parser.parseFDSelect(3, 3);

    expect(fdSelect.format).toBe(3);
    expect(fdSelect.fdSelect).toEqual([0, 0, 1]);
  });

  test("recovers when the first format 3 range does not start at 0", () => {
    const parser = makeParser(
      bytesWithOffset(3, new Uint8Array([3, 0, 1, 0, 1, 0, 0, 3]))
    );
    const fdSelect = parser.parseFDSelect(3, 3);

    expect(fdSelect.fdSelect).toEqual([0, 0, 0]);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("first range must have a first GID of 0")
    );
  });

  test("rejects format 3 ranges that exceed the glyph count", () => {
    const parser = makeParser(
      bytesWithOffset(3, new Uint8Array([3, 0, 1, 0, 0, 0, 0, 10]))
    );
    expect(() => parser.parseFDSelect(3, 3)).toThrow(
      /parseFDSelect: Invalid font data/
    );
  });

  test("rejects unknown FDSelect formats", () => {
    const parser = makeParser(bytesWithOffset(3, new Uint8Array([9, 0])));
    expect(() => parser.parseFDSelect(3, 1)).toThrow(
      /Unknown format "9"/
    );
  });

  test("rejects format 3 data whose ranges do not cover all glyphs", () => {
    const parser = makeParser(
      bytesWithOffset(3, new Uint8Array([3, 0, 1, 0, 0, 0, 0, 2]))
    );
    expect(() => parser.parseFDSelect(3, 3)).toThrow(
      /parseFDSelect: Invalid font data/
    );
  });
});

describe("CFFParser.parsePrivateDict", () => {
  test("creates an empty private dictionary when Private is absent", () => {
    const parser = makeParser(new Uint8Array(0));
    const parent = new CFFTopDict(new CFFStrings());

    parser.parsePrivateDict(parent);

    expect(parent.hasName("Private")).toBe(true);
    expect(parent.getByName("Private")).toEqual([0, 0]);
    expect(parent.privateDict.getByName("defaultWidthX")).toBe(0);
    expect(parent.privateDict.getByName("nominalWidthX")).toBe(0);
  });

  test("parses width defaults from a private dictionary", () => {
    const privateBytes = privateDictBytes([
      [20, [500]], // defaultWidthX
      [21, [100]], // nominalWidthX
    ]);
    const parser = makeParser(bytesWithOffset(10, privateBytes));
    const parent = new CFFTopDict(new CFFStrings());
    parent.setByKey(18, [privateBytes.length, 10]);

    parser.parsePrivateDict(parent);

    expect(parent.privateDict.getByName("defaultWidthX")).toBe(500);
    expect(parent.privateDict.getByName("nominalWidthX")).toBe(100);
    expect(parent.privateDict.getByName("BlueScale")).toBeCloseTo(0.039625);
    expect(parent.privateDict.getByName("ExpansionFactor")).toBeCloseTo(0.06);
  });

  test("restores blue-zone defaults when Ghostscript wrote explicit zeros", () => {
    const privateBytes = privateDictBytes([
      [[12, 9], [0]], // BlueScale
      [[12, 10], [0]], // BlueShift
      [[12, 11], [0]], // BlueFuzz
      [[12, 18], [0]], // ExpansionFactor
    ]);
    const parser = makeParser(bytesWithOffset(5, privateBytes));
    const parent = new CFFTopDict(new CFFStrings());
    parent.setByKey(18, [privateBytes.length, 5]);

    parser.parsePrivateDict(parent);

    expect(parent.privateDict.getByName("BlueScale")).toBeCloseTo(0.039625);
    expect(parent.privateDict.getByName("BlueShift")).toBe(7);
    expect(parent.privateDict.getByName("BlueFuzz")).toBe(1);
    expect(parent.privateDict.getByName("ExpansionFactor")).toBeCloseTo(0.06);
  });

  test("clamps BlueScale using the maximum blue-zone height", () => {
    const privateBytes = privateDictBytes([
      [[12, 9], [1]], // BlueScale, too large
      [6, [0, 20]], // BlueValues: one 20-unit zone
    ]);
    const parser = makeParser(bytesWithOffset(5, privateBytes));
    const parent = new CFFTopDict(new CFFStrings());
    parent.setByKey(18, [privateBytes.length, 5]);

    parser.parsePrivateDict(parent);

    expect(parent.privateDict.getByName("BlueValues")).toEqual([0, 20]);
    expect(parent.privateDict.getByName("BlueScale")).toBeCloseTo(0.05);
  });

  test("parses the Subrs INDEX relative to the private dictionary", () => {
    const privateBytes = privateDictBytes([[19, [2]]]); // Subrs offset
    const subrsBytes = new Uint8Array([0, 1, 1, 1, 4, 139, 140, 141]);
    const all = new Uint8Array(3 + privateBytes.length + subrsBytes.length);
    all.set(privateBytes, 3);
    all.set(subrsBytes, 3 + privateBytes.length);

    const parser = makeParser(all);
    const parent = new CFFTopDict(new CFFStrings());
    parent.setByKey(18, [privateBytes.length, 3]);

    parser.parsePrivateDict(parent);

    expect(parent.privateDict.subrsIndex.count).toBe(1);
    expect(Array.from(parent.privateDict.subrsIndex.get(0))).toEqual([
      139, 140, 141,
    ]);
  });

  test("rejects private dictionaries that extend past the font data", () => {
    const parser = makeParser(new Uint8Array(10));
    const parent = new CFFTopDict(new CFFStrings());
    parent.setByKey(18, [20, 0]);

    expect(() => parser.parsePrivateDict(parent)).toThrow(
      /Private DICT extends past end of font/
    );
  });

  test("replaces zero-size and out-of-range private dictionaries", () => {
    const parser = makeParser(new Uint8Array(10));

    const zeroSize = new CFFTopDict(new CFFStrings());
    zeroSize.setByKey(18, [0, 5]);
    parser.parsePrivateDict(zeroSize);
    expect(zeroSize.getByName("Private")).toEqual([0, 0]);
    expect(zeroSize.privateDict.getByName("defaultWidthX")).toBe(0);

    const badOffset = new CFFTopDict(new CFFStrings());
    badOffset.setByKey(18, [5, 999]);
    parser.parsePrivateDict(badOffset);
    expect(badOffset.getByName("Private")).toEqual([0, 0]);
    expect(badOffset.privateDict.getByName("nominalWidthX")).toBe(0);
  });

  test("removes malformed Private entries", () => {
    const parser = makeParser(new Uint8Array(10));
    const parent = new CFFTopDict(new CFFStrings());
    parent.setByKey(18, [5]);

    parser.parsePrivateDict(parent);

    expect(parent.hasName("Private")).toBe(false);
    expect(parent.privateDict).toBeNull();
  });
});

describe("CFFParser.parseCharString", () => {
  const parser = makeParser(new Uint8Array(0));

  test("rejects missing data and excessive subroutine nesting", () => {
    expect(parser.parseCharString(createCharState(), null, null, null)).toBe(
      false
    );
    expect(
      parser.parseCharString(
        createCharState({ callDepth: 11 }),
        new Uint8Array([14]),
        null,
        null
      )
    ).toBe(false);
  });

  test("decodes the different Type2 number encodings", () => {
    const state = createCharState();
    const data = new Uint8Array([
      28, 0, 5, // shortint
      247, 0, // +108
      251, 0, // -108
      255, 0, 0, 1, 0, // 16.16 fixed
    ]);

    expect(parser.parseCharString(state, data, null, null)).toBe(true);
    expect(state.stackSize).toBe(4);
    expect(state.stack.slice(0, 4)).toEqual([
      5, 108, -108, 0.00390625,
    ]);
  });

  test("applies arithmetic stack operators", () => {
    const state = createCharState();
    const data = new Uint8Array([140, 141, 12, 10]); // 1 2 add

    expect(parser.parseCharString(state, data, null, null)).toBe(true);
    expect(state.stackSize).toBe(1);
    expect(state.stack[0]).toBe(3);
  });

  test("extracts width from the first stack-clearing command", () => {
    const state = createCharState();
    const data = new Uint8Array([139, 140, 141, 142, 14]); // 0 1 2 3 endchar

    expect(parser.parseCharString(state, data, null, null)).toBe(true);
    expect(state.width).toBe(3);
    expect(state.stackSize).toBe(0);
  });

  test("detects seac-like endchar sequences when enabled", () => {
    const seacParser = makeParser(new Uint8Array(0), {
      seacAnalysisEnabled: true,
    });
    const state = createCharState();
    const data = new Uint8Array([139, 140, 141, 142, 14]);

    expect(seacParser.parseCharString(state, data, null, null)).toBe(false);
    expect(state.seac).toEqual([0, 1, 2, 3]);
  });

  test("fails on missing and out-of-bounds subroutines", () => {
    expect(
      parser.parseCharString(createCharState(), new Uint8Array([10]), null, null)
    ).toBe(false);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Missing subrsIndex")
    );

    const localSubrs = new CFFIndex();
    localSubrs.add(new Uint8Array([139, 11]));
    expect(
      parser.parseCharString(
        createCharState(),
        new Uint8Array([139, 10]),
        localSubrs,
        null
      )
    ).toBe(false);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Out of bounds subrIndex")
    );
  });

  test("executes local and global subroutines", () => {
    const localSubrs = new CFFIndex();
    localSubrs.add(new Uint8Array([139, 11]));

    const localState = createCharState();
    expect(
      parser.parseCharString(localState, new Uint8Array([32, 10]), localSubrs, null)
    ).toBe(true);
    expect(localState.stackSize).toBe(1);
    expect(localState.stack[0]).toBe(0);

    const globalState = createCharState();
    expect(
      parser.parseCharString(globalState, new Uint8Array([32, 29]), null, localSubrs)
    ).toBe(true);
    expect(globalState.stackSize).toBe(1);
    expect(globalState.stack[0]).toBe(0);
  });

  test("repairs dotsection, invalid operator 9 and a trailing zero", () => {
    const dotsection = new Uint8Array([12, 0]);
    expect(parser.parseCharString(createCharState(), dotsection, null, null)).toBe(
      true
    );
