});

describe("CFFDict through CFFTopDict and CFFPrivateDict", () => {
  test("returns layout defaults and reports absent names", () => {
    const dict = new CFFTopDict(new CFFStrings());
    expect(dict.hasName("FontBBox")).toBe(false);
    expect(dict.getByName("FontBBox")).toEqual([0, 0, 0, 0]);
    expect(dict.getByName("FontMatrix")).toEqual([0.001, 0, 0, 0.001, 0, 0]);
    expect(dict.getByName("CharstringType")).toBe(2);
    expect(dict.getByName("CIDCount")).toBe(8720);
    expect(dict.getByName("ItalicAngle")).toBe(0);
  });

  test("sets simple values by key and by name", () => {
    const dict = new CFFTopDict(new CFFStrings());
    expect(dict.setByKey(17, [123])).toBe(true);
    expect(dict.hasName("CharStrings")).toBe(true);
    expect(dict.getByName("CharStrings")).toBe(123);

    dict.setByName("ItalicAngle", -12);
    expect(dict.hasName("ItalicAngle")).toBe(true);
    expect(dict.getByName("ItalicAngle")).toBe(-12);
  });

  test("keeps array and delta typed values intact", () => {
    const topDict = new CFFTopDict(new CFFStrings());
    topDict.setByKey(14, [1, 2, 3]);
    expect(topDict.getByName("XUID")).toEqual([1, 2, 3]);

