describe("CFFParser name and string indices", () => {
  test("decodes names and collects custom strings", () => {
    const nameBytes = compiler.compileNameIndex(["Font One"]);
    const nameParser = makeParser(nameBytes);
    expect(nameParser.parseNameIndex(nameParser.parseIndex(0).obj)).toEqual([
      "Font_One",
    ]);

    const stringBytes = compiler.compileStringIndex(["CustomA", "CustomB"]);
    const stringParser = makeParser(stringBytes);
    const strings = stringParser.parseStringIndex(stringParser.parseIndex(0).obj);
    expect(strings.count).toBe(2);
    expect(strings.get(391)).toBe("CustomA");
    expect(strings.get(392)).toBe("CustomB");
  });
});

describe("CFFParser.parseDict", () => {
  test("decodes all integer operand encodings", () => {
    const data = new Uint8Array([
      139, // 0
      247, 0, // 108
      250, 255, // 1131
      251, 0, // -108
      254, 255, // -1131
      28, 0x12, 0x34, // shortint 4660
      29, 0, 0, 0x12, 0x34, // longint 4660
      0, // operator
    ]);
    expect(plainParser.parseDict(data)).toEqual([
      [0, [0, 108, 1131, -108, -1131, 4660, 4660]],
    ]);
  });

  test("decodes real-number operands", () => {
    expect(plainParser.parseDict(new Uint8Array([30, 0x1a, 0x5f, 0]))).toEqual([
      [0, [1.5]],
    ]);
    expect(
      plainParser.parseDict(new Uint8Array([30, 0x1e, 0xe1, 0xa5, 0xff, 0]))
    ).toEqual([[0, [-1.5]]]);
  });

  test("decodes escaped two-byte commands", () => {
    expect(plainParser.parseDict(new Uint8Array([12, 30]))).toEqual([[3102, []]]);
  });

  test("reports reserved operand commands as NaN", () => {
    const entries = plainParser.parseDict(new Uint8Array([255, 0]));
    expect(entries).toHaveLength(1);
    expect(Number.isNaN(entries[0][1][0])).toBe(true);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining('"255" is a reserved command')
    );
  });

  test("groups operands by following command", () => {
    expect(
      plainParser.parseDict(new Uint8Array([139, 140, 0, 139, 1]))
    ).toEqual([
      [0, [0, 1]],
      [1, [0]],
    ]);
  });
});

describe("CFFParser.parseCharsets", () => {
  const strings = new CFFStrings();
  strings.add("CustomA");
  strings.add("CustomB");

  test("returns the predefined charsets for offsets 0, 1 and 2", () => {
    expect(plainParser.parseCharsets(0, 3, strings, false)).toMatchObject({
      predefined: true,
      format: 0,
      charset: ISOAdobeCharset,
    });
    expect(plainParser.parseCharsets(1, 3, strings, false)).toMatchObject({
      predefined: true,
      format: 1,
      charset: ExpertCharset,
    });
    expect(plainParser.parseCharsets(2, 3, strings, false)).toMatchObject({
      predefined: true,
      format: 2,
      charset: ExpertSubsetCharset,
    });
  });

  test("parses format 0 charset SIDs", () => {
    const bytes = bytesWithOffset(3, [0, ...u16(0), ...u16(391)]);
    const parsed = makeParser(bytes).parseCharsets(3, 3, strings, false);
    expect(parsed.predefined).toBe(false);
    expect(parsed.format).toBe(0);
    expect(parsed.charset).toEqual([".notdef", ".notdef", "CustomA"]);
  });

  test("keeps numeric CIDs for CID fonts in format 0", () => {
    const bytes = bytesWithOffset(3, [0, ...u16(0), ...u16(391)]);
    const parsed = makeParser(bytes).parseCharsets(3, 3, strings, true);
    expect(parsed.charset).toEqual([0, 0, 391]);
  });

  test("parses format 1 and format 2 range charsets", () => {
    const format1 = makeParser(
      bytesWithOffset(3, [1, ...u16(391), 1])
    ).parseCharsets(3, 3, strings, false);
    expect(format1.format).toBe(1);
    expect(format1.charset).toEqual([".notdef", "CustomA", "CustomB"]);

    const format2 = makeParser(
      bytesWithOffset(3, [2, ...u16(391), ...u16(1)])
    ).parseCharsets(3, 3, strings, true);
    expect(format2.format).toBe(2);
    expect(format2.charset).toEqual([0, 391, 392]);
