describe("CFFParser.parsePrivateDict", () => {
  function parsePrivate(bytes, fields, offset) {
    const data = privateDictBytes(fields);
    const all = bytesWithOffset(offset, data);
    const parent = new CFFTopDict(new CFFStrings());
    parent.setByKey(18, [data.length, offset]);
    makeParser(all).parsePrivateDict(parent);
    return parent.privateDict;
  }

  test("creates an empty private dictionary when none is present", () => {
    const parent = new CFFTopDict(new CFFStrings());
    makeParser(new Uint8Array(0)).parsePrivateDict(parent);
    expect(parent.hasName("Private")).toBe(true);
    expect(parent.getByName("Private")).toEqual([0, 0]);
    expect(parent.privateDict.getByName("defaultWidthX")).toBe(0);
  });

  test("parses private metrics and applies defaults", () => {
    const privateDict = parsePrivate(
      null,
      [
        [20, [500]],
        [21, [100]],
      ],
      10
    );
    expect(privateDict.getByName("defaultWidthX")).toBe(500);
    expect(privateDict.getByName("nominalWidthX")).toBe(100);
    expect(privateDict.getByName("BlueScale")).toBeCloseTo(0.039625);
    expect(privateDict.getByName("ExpansionFactor")).toBeCloseTo(0.06);
  });

  test("repairs omitted Ghostscript blue-zone values", () => {
    const privateDict = parsePrivate(
      null,
      [
        [[12, 9], [0]],
        [[12, 10], [0]],
        [[12, 11], [0]],
        [[12, 18], [0]],
      ],
      5
    );
    expect(privateDict.getByName("BlueScale")).toBeCloseTo(0.039625);
    expect(privateDict.getByName("BlueShift")).toBe(7);
    expect(privateDict.getByName("BlueFuzz")).toBe(1);
    expect(privateDict.getByName("ExpansionFactor")).toBeCloseTo(0.06);
  });

  test("clamps BlueScale using the largest blue-zone height", () => {
    const privateDict = parsePrivate(
      null,
      [
        [[12, 9], [1]],
        [6, [0, 20]],
      ],
      5
    );
    expect(privateDict.getByName("BlueScale")).toBeCloseTo(0.05);
    expect(privateDict.getByName("BlueValues")).toEqual([0, 20]);
  });

  test("parses a relative Subrs INDEX", () => {
    const privateBytes = privateDictBytes([[19, [2]]]);
    const subrsBytes = new Uint8Array([0, 1, 1, 1, 4, 139, 140, 141]);
    const all = new Uint8Array(3 + privateBytes.length + subrsBytes.length);
    all.set(privateBytes, 3);
    all.set(subrsBytes, 3 + privateBytes.length);

    const parent = new CFFTopDict(new CFFStrings());
    parent.setByKey(18, [privateBytes.length, 3]);
    makeParser(all).parsePrivateDict(parent);

    expect(parent.privateDict.subrsIndex.count).toBe(1);
    expect(Array.from(parent.privateDict.subrsIndex.get(0))).toEqual([
      139, 140, 141,
    ]);
  });

  test("empties the private dictionary for zero sizes or invalid offsets", () => {
    const zeroSize = new CFFTopDict(new CFFStrings());
    zeroSize.setByKey(18, [0, 5]);
    makeParser(new Uint8Array(10)).parsePrivateDict(zeroSize);
    expect(zeroSize.getByName("Private")).toEqual([0, 0]);
    expect(zeroSize.privateDict.getByName("defaultWidthX")).toBe(0);

    const badOffset = new CFFTopDict(new CFFStrings());
    badOffset.setByKey(18, [5, 999]);
    makeParser(new Uint8Array(10)).parsePrivateDict(badOffset);
    expect(badOffset.getByName("Private")).toEqual([0, 0]);
  });

  test("removes malformed Private entries", () => {
    const parent = new CFFTopDict(new CFFStrings());
    parent.setByKey(18, [5]);
    makeParser(new Uint8Array(10)).parsePrivateDict(parent);
    expect(parent.hasName("Private")).toBe(false);
    expect(parent.privateDict).toBeNull();
  });

  test("throws when a private DICT extends past the font data", () => {
    const parent = new CFFTopDict(new CFFStrings());
    parent.setByKey(18, [20, 0]);
    expect(() =>
      makeParser(new Uint8Array(10)).parsePrivateDict(parent)
    ).toThrow(/CFF Private DICT extends past end of font/);
  });
});

describe("CFFParser.parseCharString", () => {
  test("rejects missing data and excessive subroutine nesting", () => {
    expect(
      plainParser.parseCharString(createCharStringState(), null, null, null)
    ).toBe(false);
    expect(
      plainParser.parseCharString(
        createCharStringState({ callDepth: 11 }),
        new Uint8Array([14]),
        null,
        null
      )
    ).toBe(false);
  });

  test("decodes charstring number encodings", () => {
    const state = createCharStringState();
    const data = new Uint8Array([
      28, 0, 5, // shortint
      247, 0, // positive 108
      251, 0, // negative -108
      255, 0, 0, 1, 0, // fixed 1/256
    ]);
    expect(plainParser.parseCharString(state, data, null, null)).toBe(true);
    expect(state.stackSize).toBe(4);
    expect(state.stack.slice(0, 4)).toEqual([5, 108, -108, 0.00390625]);
  });

  test("applies arithmetic operator stack functions", () => {
    const state = createCharStringState();
    const data = new Uint8Array([140, 141, 12, 10]); // 1 2 add
    expect(plainParser.parseCharString(state, data, null, null)).toBe(true);
    expect(state.stackSize).toBe(1);
    expect(state.stack[0]).toBe(3);
  });

  test("extracts the first-stack-clearing width", () => {
    const state = createCharStringState();
    const data = new Uint8Array([139, 140, 141, 142, 14]);
    expect(plainParser.parseCharString(state, data, null, null)).toBe(true);
    expect(state.width).toBe(3);
    expect(state.stackSize).toBe(0);
  });

  test("records seac components when seac analysis is enabled", () => {
    const parser = makeParser(new Uint8Array(0), { seacAnalysisEnabled: true });
    const state = createCharStringState();
    const data = new Uint8Array([139, 140, 141, 142, 14]);
    expect(parser.parseCharString(state, data, null, null)).toBe(false);
    expect(state.seac).toEqual([0, 1, 2, 3]);
  });

  test("fails when required subroutines are missing", () => {
    expect(
      plainParser.parseCharString(
        createCharStringState(),
        new Uint8Array([10]),
        null,
        null
      )
    ).toBe(false);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Missing subrsIndex for callsubr")
    );
  });

  test("fails on out-of-bounds subroutine indexes", () => {
    const localSubrs = new CFFIndex();
    localSubrs.add(new Uint8Array([139, 11]));
    expect(
      plainParser.parseCharString(
        createCharStringState(),
        new Uint8Array([139, 10]),
        localSubrs,
        null
      )
    ).toBe(false);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Out of bounds subrIndex for callsubr")
    );
  });

  test("executes local and global subroutines", () => {
    const localSubrs = new CFFIndex();
    localSubrs.add(new Uint8Array([139, 11]));
    const localState = createCharStringState();
    expect(
      plainParser.parseCharString(
        localState,
        new Uint8Array([32, 10]),
        localSubrs,
        null
      )
    ).toBe(true);
    expect(localState.stackSize).toBe(1);
    expect(localState.stack[0]).toBe(0);

    const globalSubrs = new CFFIndex();
    globalSubrs.add(new Uint8Array([139, 11]));
    const globalState = createCharStringState();
    expect(
      plainParser.parseCharString(
        globalState,
        new Uint8Array([32, 29]),
        null,
        globalSubrs
      )
    ).toBe(true);
    expect(globalState.stackSize).toBe(1);
  });

  test("repairs or rejects malformed charstring operators", () => {
    const dotsection = new Uint8Array([12, 0]);
    expect(
      plainParser.parseCharString(
        createCharStringState(),
        dotsection,
        null,
        null
      )
    ).toBe(true);
    expect(Array.from(dotsection)).toEqual([139, 22]);

    const invalidNine = new Uint8Array([9]);
    expect(
      plainParser.parseCharString(
        createCharStringState(),
        invalidNine,
        null,
        null
      )
    ).toBe(true);
    expect(Array.from(invalidNine)).toEqual([14]);

    const trailingZero = new Uint8Array([0]);
    expect(
      plainParser.parseCharString(
        createCharStringState(),
        trailingZero,
        null,
        null
      )
    ).toBe(true);
    expect(Array.from(trailingZero)).toEqual([14]);

    const hintmaskWithoutHints = new Uint8Array([19]);
    expect(
      plainParser.parseCharString(
        createCharStringState(),
        hintmaskWithoutHints,
        null,
        null
      )
    ).toBe(true);
    expect(Array.from(hintmaskWithoutHints)).toEqual([14]);

    const wrongStemOrder = new Uint8Array([139, 139, 3, 139, 139, 1]);
    expect(
      plainParser.parseCharString(
        createCharStringState(),
        wrongStemOrder,
        null,
        null
      )
    ).toBe(true);
    expect(Array.from(wrongStemOrder)).toEqual([139, 139, 3, 139, 139, 3]);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("CFF stem hints are in wrong order")
    );
  });

  test("repairs empty-stack arity errors but rejects non-empty ones", () => {
    const emptyStack = new Uint8Array([5]);
    expect(
      plainParser.parseCharString(
        createCharStringState(),
        emptyStack,
        null,
        null
      )
    ).toBe(true);
    expect(Array.from(emptyStack)).toEqual([14]);

    const oneOperand = new Uint8Array([139, 5]);
    expect(
      plainParser.parseCharString(
        createCharStringState(),
        oneOperand,
        null,
        null
      )
    ).toBe(false);
  });
});

describe("CFFParser.parseCharStrings", () => {
  test("computes widths and replaces invalid glyphs", () => {
    const charStrings = new CFFIndex();
    for (const glyph of [[14], [189, 14], [10]]) {
      charStrings.add(new Uint8Array(glyph));
    }
    const result = plainParser.parseCharStrings({
      charStrings,
      localSubrIndex: null,
      globalSubrIndex: null,
      fdSelect: null,
      fdArray: [],
      privateDict: makePrivateDict({ defaultWidthX: 7, nominalWidthX: 100 }),
    });

    expect(result.widths).toEqual([7, 150, 7]);
    expect(Array.from(charStrings.get(0))).toEqual([14]);
    expect(Array.from(charStrings.get(1))).toEqual([189, 14]);
    expect(Array.from(charStrings.get(2))).toEqual([14]);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Missing subrsIndex for callsubr")
    );
  });

  test("extracts seacs and replaces their glyphs", () => {
    const parser = makeParser(new Uint8Array(0), { seacAnalysisEnabled: true });
    const charStrings = new CFFIndex();
    charStrings.add(new Uint8Array([139, 140, 141, 142, 14]));

    const result = parser.parseCharStrings({
      charStrings,
      localSubrIndex: null,
      globalSubrIndex: null,
      fdSelect: null,
      fdArray: [],
      privateDict: makePrivateDict({ defaultWidthX: 7 }),
    });

    expect([...result.seacs.entries()]).toEqual([[0, [0, 1, 2, 3]]]);
    expect(Array.from(charStrings.get(0))).toEqual([14]);
    expect(result.widths).toEqual([7]);
  });

  test("selects the private dict and local subrs via FDSelect", () => {
    const subrs0 = new CFFIndex();
    subrs0.add(new Uint8Array([139, 11]));
    const subrs1 = new CFFIndex();
    subrs1.add(new Uint8Array([139, 11]));

    const fd0 = new CFFTopDict(new CFFStrings());
    fd0.privateDict = makePrivateDict(
      { defaultWidthX: 5, nominalWidthX: 100 },
      subrs0
    );
    const fd1 = new CFFTopDict(new CFFStrings());
    fd1.privateDict = makePrivateDict(
      { defaultWidthX: 9, nominalWidthX: 200 },
      subrs1
    );

    const charStrings = new CFFIndex();
    charStrings.add(new Uint8Array([32, 10, 14]));
    charStrings.add(new Uint8Array([32, 10, 14]));

    const result = plainParser.parseCharStrings({
      charStrings,
      localSubrIndex: null,
      globalSubrIndex: null,
      fdSelect: new CFFFDSelect(0, [0, 1]),
      fdArray: [fd0, fd1],
