describe("CFFParser.parseCharsets", () => {
  const strings = new CFFStrings();
  strings.add("CustomA");
  strings.add("CustomB");

  test("returns the predefined charsets for offsets 0, 1 and 2", () => {
    expect(plainParser.parseCharsets(0, 3, strings, false)).toMatchObject({
      predefined: true,
      format: 0,
      charset: ISOAdobeCharset,
    });
    expect(plainParser.parseCharsets(1, 3, strings, false)).toMatchObject({
      predefined: true,
      format: 1,
      charset: ExpertCharset,
    });
    expect(plainParser.parseCharsets(2, 3, strings, false)).toMatchObject({
      predefined: true,
      format: 2,
      charset: ExpertSubsetCharset,
    });
  });

  test("parses format 0 charset SIDs", () => {
    const bytes = bytesWithOffset(3, [0, ...u16(0), ...u16(391)]);
    const parsed = makeParser(bytes).parseCharsets(3, 3, strings, false);
    expect(parsed.predefined).toBe(false);
    expect(parsed.format).toBe(0);
    expect(parsed.charset).toEqual([".notdef", ".notdef", "CustomA"]);
  });

  test("keeps numeric CIDs for CID fonts in format 0", () => {
    const bytes = bytesWithOffset(3, [0, ...u16(0), ...u16(391)]);
    const parsed = makeParser(bytes).parseCharsets(3, 3, strings, true);
    expect(parsed.charset).toEqual([0, 0, 391]);
  });

  test("parses format 1 and format 2 range charsets", () => {
    const format1 = makeParser(
      bytesWithOffset(3, [1, ...u16(391), 1])
    ).parseCharsets(3, 3, strings, false);
    expect(format1.format).toBe(1);
    expect(format1.charset).toEqual([".notdef", "CustomA", "CustomB"]);

    const format2 = makeParser(
      bytesWithOffset(3, [2, ...u16(391), ...u16(1)])
    ).parseCharsets(3, 3, strings, true);
    expect(format2.format).toBe(2);
    expect(format2.charset).toEqual([0, 391, 392]);
  });

  test("throws on an unknown charset format", () => {
    const parser = makeParser(bytesWithOffset(3, [5, 0]));
    expect(() => parser.parseCharsets(3, 1, strings, false)).toThrow(
      /Unknown charset format/
    );
  });
});

describe("CFFParser.parseEncoding", () => {
  test("maps a charset through StandardEncoding", () => {
