    );
    expect(encoding.predefined).toBe(true);
    expect(encoding.format).toBe(0);
    expect(encoding.raw).toBeNull();
    expect(encoding.encoding).toEqual({ 65: 0, 66: 1 });
  });

  test("maps a charset through ExpertEncoding", () => {
    const encoding = plainParser.parseEncoding(
      1,
      {},
      new CFFStrings(),
      ["space", "A"]
    );
    expect(encoding.predefined).toBe(true);
    expect(encoding.format).toBe(1);
    expect(encoding.raw).toBeNull();
    expect(encoding.encoding).toEqual({ 32: 0 });
  });

  test("parses custom format 0 encodings", () => {
    const parser = makeParser(bytesWithOffset(3, [0, 2, 65, 66]));
    const encoding = parser.parseEncoding(
      3,
      {},
      new CFFStrings(),
      [".notdef", "A", "B"]
    );
    expect(encoding.predefined).toBe(false);
    expect(encoding.format).toBe(0);
    expect(encoding.encoding).toEqual({ 65: 1, 66: 2 });
    expect(Array.from(encoding.raw)).toEqual([0, 2, 65, 66]);
  });

  test("parses custom format 1 range encodings", () => {
    const parser = makeParser(bytesWithOffset(3, [1, 2, 65, 1, 67, 1]));
    const encoding = parser.parseEncoding(3, {}, new CFFStrings(), []);
    expect(encoding.format).toBe(1);
    expect(encoding.encoding).toEqual({ 65: 1, 66: 2, 67: 3, 68: 4 });
    expect(Array.from(encoding.raw)).toEqual([1, 2, 65, 1, 67, 1]);
  });

  test("reads supplements and clears the supplement flag bit", () => {
    const parser = makeParser(
      bytesWithOffset(3, [0x80, 1, 65, 1, 66, 0, 1])
    );
    const encoding = parser.parseEncoding(
      3,
      {},
