    expect(parser.bytes[3]).toBe(0);
  });

  test("throws on an unknown encoding format", () => {
    const parser = makeParser(bytesWithOffset(3, [2]));
    expect(() => parser.parseEncoding(3, {}, new CFFStrings(), [])).toThrow(
      /Unknown encoding format: 2/
    );
  });
});

