    });

    expect([...result.seacs.entries()]).toEqual([[0, [0, 1, 2, 3]]]);
    expect(Array.from(charStrings.get(0))).toEqual([14]);
    expect(result.widths).toEqual([7]);
  });

  test("selects the private dict and local subrs via FDSelect", () => {
    const subrs0 = new CFFIndex();
    subrs0.add(new Uint8Array([139, 11]));
    const subrs1 = new CFFIndex();
    subrs1.add(new Uint8Array([139, 11]));

    const fd0 = new CFFTopDict(new CFFStrings());
    fd0.privateDict = makePrivateDict(
      { defaultWidthX: 5, nominalWidthX: 100 },
      subrs0
    );
    const fd1 = new CFFTopDict(new CFFStrings());
