      fdArray: [fd0],
      privateDict: makePrivateDict({ defaultWidthX: 42 }),
    });

    expect(result.widths).toEqual([7, 42]);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Glyph index is not in fd select")
    );

    const invalidIndex = plainParser.parseCharStrings({
      charStrings: (() => {
        const cs = new CFFIndex();
        cs.add(new Uint8Array([14]));
        cs.add(new Uint8Array([14]));
        return cs;
      })(),
      localSubrIndex: null,
      globalSubrIndex: null,
      fdSelect: new CFFFDSelect(0, [0, 2]),
      fdArray: [fd0],
      privateDict: makePrivateDict({ defaultWidthX: 42 }),
    });
    expect(invalidIndex.widths).toEqual([7, 42]);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Invalid fd index for glyph index")
    );
  });
});

describe("CFF", () => {
  test("duplicateFirstGlyph appends a copy for simple fonts", () => {
    const cff = new CFF(100);
    expect(cff.rawFileLength).toBe(100);
    cff.charStrings = new CFFIndex();
    cff.charStrings.add(new Uint8Array([1, 2]));
    cff.duplicateFirstGlyph();

    expect(cff.charStrings.count).toBe(2);
    expect(Array.from(cff.charStrings.get(0))).toEqual([1, 2]);
    expect(Array.from(cff.charStrings.get(1))).toEqual([1, 2]);
  });

  test("duplicateFirstGlyph also duplicates the FDSelect entry for CID fonts", () => {
    const cff = new CFF();
    cff.isCIDFont = true;
    cff.charStrings = new CFFIndex();
    cff.charStrings.add(new Uint8Array([9]));
    cff.fdSelect = new CFFFDSelect(0, [0, 1]);
    cff.duplicateFirstGlyph();

    expect(cff.charStrings.count).toBe(2);
    expect(cff.fdSelect.fdSelect).toEqual([0, 1, 0]);
  });

  test("duplicateFirstGlyph refuses when the glyph limit is reached", () => {
    const cff = new CFF();
    const index = new CFFIndex();
    index.objects = new Array(65535);
    cff.charStrings = index;
    cff.duplicateFirstGlyph();
    expect(index.count).toBe(65535);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Not enough space in charstrings")
    );
  });

  test("hasGlyphId checks bounds and empty outlines", () => {
    const cff = new CFF();
    cff.charStrings = new CFFIndex();
    cff.charStrings.add(new Uint8Array(0));
    cff.charStrings.add(new Uint8Array([1]));
    expect(cff.hasGlyphId(-1)).toBe(false);
    expect(cff.hasGlyphId(0)).toBe(false);
    expect(cff.hasGlyphId(1)).toBe(true);
    expect(cff.hasGlyphId(2)).toBe(false);
  });
});

describe("CFFCompiler primitive encoders", () => {
  test.each([
    [-107, [32]],
    [107, [246]],
    [108, [247, 0]],
    [1131, [250, 255]],
    [-108, [251, 0]],
    [-1131, [254, 255]],
    [-32768, [0x1c, 0x80, 0]],
    [32767, [0x1c, 0x7f, 0xff]],
    [32768, [0x1d, 0, 0, 0x80, 0]],
    [-32769, [0x1d, 0xff, 0xff, 0x7f, 0xff]],
  ])("encodeInteger(%i) uses the expected CFF encoding", (value, expected) => {
    expect(compiler.encodeInteger(value)).toEqual(expected);
  });

  test("encodeNumber dispatches to integer and float encoders", () => {
    expect(compiler.encodeNumber(42)).toEqual(compiler.encodeInteger(42));
    expect(compiler.encodeNumber(1.5)).toEqual(compiler.encodeFloat(1.5));
    expect(compiler.encodeNumber(1.5)[0]).toBe(30);
  });

  function decodeNumber(encoded) {
    return plainParser.parseDict(new Uint8Array([...encoded, 0]))[0][1][0];
  }

  test.each([1.5, -1.5, 0.1, 3.14159, -2.71828, 1e-7, 1e21])(
    "encodeFloat round-trips %p",
    value => {
      expect(decodeNumber(compiler.encodeFloat(value))).toBe(value);
    }
  );

  test("encodeFloat rounds floating-point representation noise", () => {
    expect(decodeNumber(compiler.encodeFloat(0.1 + 0.2))).toBe(0.3);
  });

  test("compileHeader always writes a header size of 4", () => {
    expect(compiler.compileHeader(new CFFHeader(2, 1, 9, 7))).toEqual([
      2, 1, 4, 7,
    ]);
  });
});

describe("CFFCompiler index, charset and FDSelect encoders", () => {
  function readIndex(bytes) {
    const parser = makeParser(bytes);
    return parser.parseIndex(0).obj;
  }

  test("compileNameIndex sanitizes, truncates and substitutes names", () => {
    const sanitized = compiler.compileNameIndex(["Fo nt[b]"]);
    const sanitizedParser = makeParser(sanitized);
    expect(
      sanitizedParser.parseNameIndex(sanitizedParser.parseIndex(0).obj)
    ).toEqual(["Fo_nt_b_"]);

    const empty = compiler.compileNameIndex([""]);
    const emptyParser = makeParser(empty);
    expect(emptyParser.parseNameIndex(emptyParser.parseIndex(0).obj)).toEqual([
      "Bad_Font_Name",
    ]);

    const long = compiler.compileNameIndex(["A".repeat(200) + "!"]);
    const longParser = makeParser(long);
    const [name] = longParser.parseNameIndex(longParser.parseIndex(0).obj);
    expect(name).toHaveLength(127);
    expect(name.endsWith("!")).toBe(false);
  });

  test("compileIndex emits an empty index and preserves object boundaries", () => {
    expect(Array.from(compiler.compileIndex(new CFFIndex()))).toEqual([0, 0]);

    const index = new CFFIndex();
    index.add(new Uint8Array([1, 2]));
    index.add(new Uint8Array([3]));
    const out = compiler.compileIndex(index);
    expect(Array.from(out)).toEqual([0, 2, 1, 1, 3, 4, 1, 2, 3]);

    const parsed = readIndex(out);
    expect(parsed.count).toBe(2);
    expect(Array.from(parsed.get(0))).toEqual([1, 2]);
    expect(Array.from(parsed.get(1))).toEqual([3]);
  });

  test.each([
    [300, 2],
    [65536, 3],
  ])("compileIndex chooses offset size %i -> %i", (objectLength, expected) => {
    const index = new CFFIndex();
    index.add(new Uint8Array(objectLength));
    const out = compiler.compileIndex(index);
    expect(out[2]).toBe(expected);
    expect(readIndex(out).get(0)).toHaveLength(objectLength);
  });

  test("compileStringIndex round-trips custom strings", () => {
    const out = compiler.compileStringIndex(["CustomA", "CustomB"]);
    const parser = makeParser(out);
    const strings = parser.parseStringIndex(parser.parseIndex(0).obj);
    expect(strings.count).toBe(2);
    expect(strings.get(391)).toBe("CustomA");
    expect(strings.get(392)).toBe("CustomB");
  });

  test("compileCharStrings replaces empty glyphs with .notdef", () => {
    const charStrings = new CFFIndex();
    charStrings.add(new Uint8Array(0));
    charStrings.add(new Uint8Array([1, 2, 3]));
    const out = compiler.compileCharStrings(charStrings);
    const parsed = readIndex(out);
    expect(parsed.count).toBe(2);
    expect(Array.from(parsed.get(0))).toEqual([139, 14]);
    expect(Array.from(parsed.get(1))).toEqual([1, 2, 3]);
  });

  test("compileCharset maps names to SIDs and substitutes unknown names", () => {
    const charset = new CFFCharset(false, 0, ["A", "B"]);
    expect(
      Array.from(compiler.compileCharset(charset, 3, new CFFStrings(), false))
    ).toEqual([0, 0, 34, 0, 35]);

    const withUnknown = new CFFCharset(false, 0, ["A", "Bogus"]);
    expect(
      Array.from(
        compiler.compileCharset(withUnknown, 3, new CFFStrings(), false)
      )
    ).toEqual([0, 0, 34, 0, 0]);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Couldn't find Bogus in CFF strings")
    );
  });

  test("compileCharset emits an identity CID mapping", () => {
    expect(
      Array.from(
        compiler.compileCharset(new CFFCharset(false, 0, []), 3, new CFFStrings(), true)
      )
    ).toEqual([2, 0, 1, 0, 1]);
  });

  test("compileEncoding returns the stored raw encoding", () => {
    const raw = new Uint8Array([1, 2, 3]);
    expect(compiler.compileEncoding({ raw })).toBe(raw);
  });

  test("compileFDSelect round-trips format 0 and format 3", () => {
    const format0 = compiler.compileFDSelect(new CFFFDSelect(0, [0, 1, 1, 2]));
    expect(Array.from(format0)).toEqual([0, 0, 1, 1, 2]);
    expect(makeParser(format0).parseFDSelect(0, 4).fdSelect).toEqual([
      0, 1, 1, 2,
    ]);

    const format3 = compiler.compileFDSelect(
      new CFFFDSelect(3, [0, 0, 1, 1, 1, 2])
    );
    expect(Array.from(format3)).toEqual([
      3, 0, 3, 0, 0, 0, 0, 2, 1, 0, 5, 2, 0, 6,
    ]);
    expect(makeParser(format3).parseFDSelect(0, 6).fdSelect).toEqual([
      0, 0, 1, 1, 1, 2,
    ]);
  });
});

describe("CFFCompiler compile validation and XUID handling", () => {
  test("throws when CharStrings has not been tracked", () => {
    const cff = createCFF();
    cff.topDict.removeByName("CharStrings");
    expect(() => new CFFCompiler(cff).compile()).toThrow(
      /Not tracking location of CharStrings/
    );
  });

  test("throws when no private dictionary exists", () => {
    const cff = createCFF();
    cff.topDict.privateDict = null;
    expect(() => new CFFCompiler(cff).compile()).toThrow(
      /There must be a private dictionary/
    );
  });

  test("keeps XUID arrays of at most 16 entries", () => {
    const cff = createCFF();
    const values = Array.from({ length: 16 }, (_, i) => i + 1);
    cff.topDict.setByKey(14, values);
    const { parsed } = compileAndParse(cff);
    expect(parsed.topDict.getByName("XUID")).toEqual(values);
  });

  test("removes XUID arrays longer than 16 entries", () => {
    const cff = createCFF();
    cff.topDict.setByKey(14, Array.from({ length: 17 }, (_, i) => i + 1));
    const { parsed } = compileAndParse(cff);
    expect(cff.topDict.hasName("XUID")).toBe(false);
    expect(parsed.topDict.getByName("XUID")).toBeNull();
  });
});

describe("CFFParser.parse integration", () => {
  test("parses a compiled simple font end-to-end", () => {
    const cff = createCFF({
      customStrings: ["CustomA"],
      charStrings: [
        [0x8b, 0x0e],
        [0x0e],
        [189, 0x0e],
      ],
      privateValues: { defaultWidthX: 7, nominalWidthX: 100 },
    });
    const properties = {};
    const { parsed } = compileAndParse(cff, { properties });

    expect(parsed.header).toMatchObject({
      major: 1,
      minor: 0,
      hdrSize: 4,
      offSize: 4,
    });
    expect(parsed.names).toEqual(["TestFont"]);
    expect(parsed.strings.count).toBe(1);
    expect(parsed.strings.get(391)).toBe("CustomA");
    expect(parsed.isCIDFont).toBe(false);
    expect(parsed.encoding.predefined).toBe(true);
    expect(parsed.encoding.format).toBe(0);
    expect(parsed.charset.predefined).toBe(false);
    expect(parsed.charset.format).toBe(0);
    expect(parsed.charset.charset).toHaveLength(3);
    expect(parsed.charStringCount).toBe(3);
    expect(parsed.charStrings.count).toBe(3);
    expect(parsed.widths).toEqual([100, 7, 150]);
    expect(parsed.seacs.size).toBe(0);
    expect(parsed.topDict.getByName("CharStrings")).toBeGreaterThan(0);
    expect(parsed.topDict.getByName("Private")).toEqual([
      expect.any(Number),
      expect.any(Number),
    ]);
    expect(properties.fontMatrix).toEqual([0.001, 0, 0, 0.001, 0, 0]);
  });

  test("parses a compiled custom encoding", () => {
    const cff = createCFF();
    const encodingParser = makeParser(
      bytesWithOffset(3, [0, 2, 65, 66])
    );
    cff.encoding = encodingParser.parseEncoding(
      3,
      {},
      cff.strings,
      [".notdef", "A", "B"]
    );
    cff.topDict.setByKey(16, [0]);

    const { parsed } = compileAndParse(cff);
    expect(parsed.encoding.predefined).toBe(false);
    expect(parsed.encoding.format).toBe(0);
    expect(parsed.encoding.encoding).toEqual({ 65: 1, 66: 2 });
    expect(Array.from(parsed.encoding.raw)).toEqual([0, 2, 65, 66]);
  });

  test("parses private and global subroutine indexes", () => {
    const localSubrs = new CFFIndex();
    localSubrs.add(new Uint8Array([139, 11]));
    const localCff = createCFF({
      charStrings: [[32, 10, 14]],
      privateValues: { defaultWidthX: 7, nominalWidthX: 100 },
      subrs: localSubrs,
    });
    const local = compileAndParse(localCff).parsed;
    expect(local.topDict.privateDict.subrsIndex.count).toBe(1);
    expect(Array.from(local.charStrings.get(0))).toEqual([32, 10, 14]);
    expect(local.widths).toEqual([100]);

    const globalSubrs = new CFFIndex();
    globalSubrs.add(new Uint8Array([139, 11]));
    const globalCff = createCFF({
      charStrings: [[32, 29, 14]],
      privateValues: { defaultWidthX: 7, nominalWidthX: 100 },
      globalSubrIndex: globalSubrs,
    });
    const global = compileAndParse(globalCff).parsed;
    expect(global.globalSubrIndex.count).toBe(1);
    expect(global.widths).toEqual([100]);
  });

  test("extracts seac data during a full parse", () => {
    const cff = createCFF({
      charStrings: [[139, 140, 141, 142, 14]],
      privateValues: { defaultWidthX: 7 },
    });
    const { parsed } = compileAndParse(cff, { seacAnalysisEnabled: true });
    expect([...parsed.seacs.entries()]).toEqual([[0, [0, 1, 2, 3]]]);
    expect(Array.from(parsed.charStrings.get(0))).toEqual([14]);
    expect(parsed.widths).toEqual([7]);
  });

  test("falls back to the descriptor bbox when FontBBox is empty", () => {
    const cff = createCFF();
    const properties = { bbox: [-10, -20, 30, 40] };
    const { parsed } = compileAndParse(cff, { properties });

    expect(Array.from(parsed.topDict.getByName("FontBBox"))).toEqual([
      -10, -20, 30, 40,
    ]);
    expect(properties.ascent).toBe(40);
    expect(properties.descent).toBe(-20);
    expect(properties.ascentScaled).toBe(true);
  });

  test("recovers unsigned 16-bit negative lower-left coordinates", () => {
    const cff = createCFF();
    cff.topDict.setByName("FontBBox", [65436, 65336, 500, 600]);
    const properties = {};
    const { parsed } = compileAndParse(cff, { properties });

    expect(Array.from(parsed.topDict.getByName("FontBBox"))).toEqual([
      -100, -200, 500, 600,
    ]);
    expect(properties.ascent).toBe(600);
    expect(properties.descent).toBe(-200);
  });

  test("uses a corroborating descriptor to repair all bbox coordinates", () => {
    const cff = createCFF();
    cff.topDict.setByName("FontBBox", [65436, 65336, 500, 600]);
    const properties = { bbox: [-100, -200, 500, 600] };
    const { parsed } = compileAndParse(cff, { properties });

    expect(Array.from(parsed.topDict.getByName("FontBBox"))).toEqual([
      -100, -200, 500, 600,
    ]);
    expect(properties.ascent).toBe(600);
    expect(properties.descent).toBe(-200);
  });

  test("preserves unsigned upper-right bbox coordinates without corroboration", () => {
    const cff = createCFF();
    cff.topDict.setByName("FontBBox", [0, 0, 65436, 600]);
    const { parsed } = compileAndParse(cff);

    expect(Array.from(parsed.topDict.getByName("FontBBox"))).toEqual([
      0, 0, 65436, 600,
    ]);
  });

  test("throws for a font without a CFF header", () => {
    const parser = makeParser(new Uint8Array([2, 3, 4]));
    expect(() => parser.parse()).toThrow(/Invalid CFF header/);
  });

  test("parses a CID font with format 3 FDSelect", () => {
    const { parsed } = compileAndParse(createCIDCFF());

    expect(parsed.isCIDFont).toBe(true);
    expect(parsed.encoding).toBeNull();
    expect(parsed.names).toEqual(["CIDFont"]);
    expect(parsed.topDict.hasName("ROS")).toBe(true);
    expect(parsed.fdArray).toHaveLength(2);
    expect(parsed.fdSelect.format).toBe(3);
    expect(parsed.fdSelect.fdSelect).toEqual([0, 0, 1]);
    expect(parsed.charStringCount).toBe(3);
    expect(parsed.widths).toEqual([100, 101, 202]);
    expect(parsed.charset.predefined).toBe(false);
    expect(parsed.charset.format).toBe(2);
    expect(parsed.charset.charset).toEqual([0, 1, 2]);
    expect(
      parsed.fdArray.map(fd => fd.privateDict.getByName("defaultWidthX"))
    ).toEqual([11, 22]);
  });

  test("parses a CID font with format 0 FDSelect", () => {
    const { parsed } = compileAndParse(
      createCIDCFF({ fdSelectFormat: 0, fdSelect: [1, 1, 0] })
    );
    expect(parsed.fdSelect.format).toBe(0);
    expect(parsed.fdSelect.fdSelect).toEqual([1, 1, 0]);
    expect(parsed.widths).toEqual([201, 201, 100]);
  });

  test("moves a top-level CID FontMatrix into each FDArray entry", () => {
    const cff = createCIDCFF({
      topFontMatrix: [0.002, 0, 0, 0.002, 0, 0],
    });
    const { parsed } = compileAndParse(cff);

    expect(cff.topDict.hasName("FontMatrix")).toBe(false);
    expect(parsed.topDict.hasName("FontMatrix")).toBe(false);
    expect(parsed.fdArray[0].getByName("FontMatrix")).toEqual([
      0.002, 0, 0, 0.002, 0, 0,
    ]);
  });

  test("limits CID FDArray parsing to 256 entries", () => {
    const cff = createCIDCFF({
      charStrings: [[14]],
      fdCount: 257,
      fdSelect: [0],
      fdSelectFormat: 0,
    });
    const { parsed } = compileAndParse(cff);

    expect(parsed.fdArray).toHaveLength(256);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("too many FDArray entries (257)")
    );
  });
});
