import {
  afterEach,
  describe,
  expect,
  it,
  jest,
} from "@jest/globals";
import {
  EvaluatorPreprocessor,
  PartialEvaluator,
} from "../../src/core/evaluator.js";
import { OperatorList } from "../../src/core/operator_list.js";
import { Dict, Name, Ref, RefSet } from "../../src/core/primitives.js";
import { Stream } from "../../src/core/stream.js";
import {
  DrawOPS,
  F32_BBOX_INIT,
  FormatError,
  getVerbosityLevel,
  OPS,
  setVerbosityLevel,
  stringToBytes,
  TextRenderingMode,
  VerbosityLevel,
} from "../../src/shared/util.js";

afterEach(() => {
  setVerbosityLevel(getVerbosityLevel());
  jest.restoreAllMocks();
  setVerbosityLevel(VerbosityLevel.WARNINGS);
});

function makeEvaluator(overrides = {}) {
  return new PartialEvaluator({
    xref: {
      fetch: value => value,
      fetchIfRef: value => value,
    },
    handler: {
      send: jest.fn(),
      sendWithPromise: jest.fn(),
    },
    pageIndex: 0,
    pageProxyId: 1,
    idFactory: {
      createObjId: jest.fn(() => 1),
      getDocId: jest.fn(() => "doc"),
    },
    fontCache: new Map(),
    builtInCMapCache: new Map(),
    standardFontDataCache: new Map(),
    globalColorSpaceCache: null,
    globalImageCache: null,
    systemFontCache: new Map(),
    options: null,
    ...overrides,
  });
}

function makeStream(content) {
  const bytes = stringToBytes(content);
  return new Stream(bytes, 0, bytes.length);
}

function makePreprocessor(content) {
  return new EvaluatorPreprocessor(makeStream(content), null);
}

function readAll(preprocessor) {
  const operations = [];
  const operation = { args: null };
  while (preprocessor.read(operation)) {
    operations.push({ fn: operation.fn, args: operation.args });
    operation.args = null;
  }
  return operations;
}

function makePathState() {
  return {
    currentPointX: 0,
    currentPointY: 0,
    pathBuffer: [],
    pathMinMax: new Float32Array(F32_BBOX_INIT),
  };
}

describe("EvaluatorPreprocessor command reading", () => {
  it("reads numeric operands and the command id, then reports EOF", () => {
    const preprocessor = makePreprocessor("10 20 m");
    const operation = { args: null };

    expect(preprocessor.read(operation)).toBe(true);
    expect(operation.fn).toBe(OPS.moveTo);
    expect(operation.args).toEqual([10, 20]);
    expect(preprocessor.read(operation)).toBe(false);
  });

  it("leaves args null for a zero-argument command when no array is supplied", () => {
    const preprocessor = makePreprocessor("q");
    const operation = { args: null };

    expect(preprocessor.read(operation)).toBe(true);
    expect(operation.fn).toBe(OPS.save);
    expect(operation.args).toBeNull();
  });

  it("reuses a caller-provided arguments array", () => {
    const preprocessor = makePreprocessor("1 2 l");
    const args = [];
    const operation = { args };

    expect(preprocessor.read(operation)).toBe(true);
    expect(operation.args).toBe(args);
    expect(args).toEqual([1, 2]);
  });

  it("warns about an unknown command and continues with the next command", () => {
    const warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
    const preprocessor = makePreprocessor("XYZ 0 0 m");
    const operation = { args: null };

    expect(preprocessor.read(operation)).toBe(true);
    expect(warnSpy).toHaveBeenCalledWith('Warning: Unknown command "XYZ".');
    expect(operation.fn).toBe(OPS.moveTo);
    expect(operation.args).toEqual([0, 0]);
  });

  it("warns about and skips a command with too few arguments", () => {
    const warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
    const preprocessor = makePreprocessor("1 m 0 0 m");
    const operation = { args: null };

    expect(preprocessor.read(operation)).toBe(true);
    expect(warnSpy).toHaveBeenCalledWith(
      "Warning: Skipping command m: expected 2 args, but received 1 args."
    );
    expect(operation.fn).toBe(OPS.moveTo);
    expect(operation.args).toEqual([0, 0]);
  });

  it("allows ten invalid path operators but throws on the eleventh", () => {
    const warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
    const validPreprocessor = makePreprocessor(
      `${"1 m ".repeat(EvaluatorPreprocessor.MAX_INVALID_PATH_OPS)}0 0 m`
    );
    const operation = { args: null };

    expect(validPreprocessor.read(operation)).toBe(true);
    expect(operation.args).toEqual([0, 0]);
    expect(warnSpy).toHaveBeenCalledTimes(
      EvaluatorPreprocessor.MAX_INVALID_PATH_OPS
    );

    const invalidPreprocessor = makePreprocessor(
      "1 m ".repeat(EvaluatorPreprocessor.MAX_INVALID_PATH_OPS + 1)
    );
    expect(() => invalidPreprocessor.read({ args: null })).toThrow(FormatError);
    expect(() => invalidPreprocessor.read({ args: null })).toThrow(
      /Invalid command m: expected 2 args, but received 1 args\./
    );
  });

  it("throws when more than 33 operands have accumulated", () => {
    const preprocessor = makePreprocessor(`${"1 ".repeat(34)}w`);

    expect(() => preprocessor.read({ args: null })).toThrow(FormatError);
    expect(() => preprocessor.read({ args: null })).toThrow(
      "Too many arguments"
    );
  });

  it("accepts extra operands for variable-argument commands and logs an info message", () => {
    setVerbosityLevel(VerbosityLevel.INFOS);
    const infoSpy = jest.spyOn(console, "info").mockImplementation(() => {});
    const preprocessor = makePreprocessor("1 2 3 4 5 SC");
    const operation = { args: null };

    expect(preprocessor.read(operation)).toBe(true);
    expect(operation.fn).toBe(OPS.setStrokeColor);
    expect(operation.args).toEqual([1, 2, 3, 4, 5]);
    expect(infoSpy).toHaveBeenCalledWith(
      "Info: Command SC: expected [0, 4] args, but received 5 args."
    );
  });

  it("tracks nested save/restore state depth without going negative", () => {
    const preprocessor = makePreprocessor("q q Q Q Q");
    const operation = { args: null };
    const depths = [];

    while (preprocessor.read(operation)) {
      depths.push(preprocessor.savedStatesDepth);
      operation.args = null;
    }

    expect(depths).toEqual([1, 2, 1, 0, 0]);
    expect(preprocessor.savedStatesDepth).toBe(0);
  });

  it("accumulates transformation matrices from the cm operator", () => {
    const preprocessor = makePreprocessor(
      "2 0 0 2 10 20 cm 1 0 0 1 5 5 cm"
    );
    readAll(preprocessor);

    expect(Array.from(preprocessor.stateManager.state.ctm)).toEqual([
      2, 0, 0, 2, 20, 30,
    ]);
  });

  it("restores the transformation matrix when a saved state is restored", () => {
    const preprocessor = makePreprocessor("q 5 0 0 5 0 0 cm Q");
    readAll(preprocessor);

    expect(Array.from(preprocessor.stateManager.state.ctm)).toEqual([
      1, 0, 0, 1, 0, 0,
    ]);
  });

  it("exposes command specifications for the operators it understands", () => {
    expect(EvaluatorPreprocessor.opMap.q).toEqual({
      id: OPS.save,
      numArgs: 0,
      variableArgs: false,
    });
    expect(EvaluatorPreprocessor.opMap.cm).toEqual({
      id: OPS.transform,
      numArgs: 6,
      variableArgs: false,
    });
    expect(EvaluatorPreprocessor.opMap.sc).toEqual({
      id: OPS.setFillColor,
      numArgs: 4,
      variableArgs: true,
    });
    expect(EvaluatorPreprocessor.opMap["f*"].id).toBe(OPS.eoFill);
    expect(EvaluatorPreprocessor.MAX_INVALID_PATH_OPS).toBe(10);
  });
});

describe("PartialEvaluator configuration", () => {
  it("uses the documented default options", () => {
    const evaluator = makeEvaluator();

    expect(evaluator.options).toEqual({
      maxImageSize: -1,
      disableFontFace: false,
      ignoreErrors: false,
      isOffscreenCanvasSupported: false,
      isImageDecoderSupported: false,
      canvasMaxAreaInBytes: -1,
      fontExtraProperties: false,
      useSystemFonts: true,
      useWasm: true,
      useWorkerFetch: true,
      cMapUrl: null,
      cMapPacked: true,
      iccUrl: null,
      standardFontDataUrl: null,
      wasmUrl: null,
      hasGPU: false,
    });
    expect(Object.isFrozen(evaluator.options)).toBe(true);
  });

  it("uses supplied options as-is until cloned", () => {
    const options = { ignoreErrors: true, maxImageSize: 100 };
    const evaluator = makeEvaluator({ options });

    expect(evaluator.options).toBe(options);
  });

  it("clones with an independent merged options object", () => {
    const evaluator = makeEvaluator({
      options: { ignoreErrors: true, maxImageSize: 10 },
    });

    const clone = evaluator.clone({ maxImageSize: 20, useSystemFonts: false });

    expect(clone).not.toBe(evaluator);
    expect(clone).toBeInstanceOf(PartialEvaluator);
    expect(clone.options).not.toBe(evaluator.options);
    expect(clone.options).toEqual({
      ignoreErrors: true,
      maxImageSize: 20,
      useSystemFonts: false,
    });
    expect(evaluator.options).toEqual({
      ignoreErrors: true,
      maxImageSize: 10,
    });
    expect(clone.xref).toBe(evaluator.xref);
  });

  it("reports whether it is parsing a Type3 font", () => {
    const evaluator = makeEvaluator();
    expect(evaluator.parsingType3Font).toBe(false);

    evaluator.type3FontRefs = new RefSet();
    expect(evaluator.parsingType3Font).toBe(true);

    evaluator.type3FontRefs = null;
    expect(evaluator.parsingType3Font).toBe(false);
  });
});

describe("PartialEvaluator.hasBlendModes", () => {
  it("returns false for non-dictionary resources", () => {
    const evaluator = makeEvaluator();

    expect(evaluator.hasBlendModes(null, new RefSet())).toBe(false);
    expect(evaluator.hasBlendModes([], new RefSet())).toBe(false);
    expect(evaluator.hasBlendModes({}, new RefSet())).toBe(false);
  });

  it("returns false when every blend mode is Normal", () => {
    const resources = new Dict();
    const extGState = new Dict();
    const normalState = new Dict();
    normalState.set("BM", Name.get("Normal"));
    extGState.set("GS0", normalState);
    resources.set("ExtGState", extGState);

    expect(makeEvaluator().hasBlendModes(resources, new RefSet())).toBe(false);
  });

  it("detects a non-Normal blend mode", () => {
    const resources = new Dict();
    const extGState = new Dict();
    const multiply = new Dict();
    multiply.set("BM", Name.get("Multiply"));
    extGState.set("GS0", multiply);
    resources.set("ExtGState", extGState);

    expect(makeEvaluator().hasBlendModes(resources, new RefSet())).toBe(true);
  });

  it("detects a supported blend mode inside an array", () => {
    const resources = new Dict();
    const extGState = new Dict();
    const state = new Dict();
    state.set("BM", [Name.get("Normal"), Name.get("Screen")]);
    extGState.set("GS0", state);
    resources.set("ExtGState", extGState);

    expect(makeEvaluator().hasBlendModes(resources, new RefSet())).toBe(true);
  });

  it("finds blend modes in nested XObject resources", () => {
    const childResources = new Dict();
    const childExtGState = new Dict();
    const childState = new Dict();
    childState.set("BM", Name.get("Overlay"));
    childExtGState.set("GS0", childState);
    childResources.set("ExtGState", childExtGState);

    const xObjectDict = new Dict();
    xObjectDict.set("Resources", childResources);
    const xObject = new Stream(new Uint8Array(0), 0, 0, xObjectDict);
    const xObjects = new Dict();
    xObjects.set("Fm0", xObject);
    const resources = new Dict();
    resources.set("XObject", xObjects);

    expect(makeEvaluator().hasBlendModes(resources, new RefSet())).toBe(true);
  });

  it("resolves referenced ExtGStates through the xref", () => {
    const fetch = jest.fn(() => {
      const state = new Dict();
      state.set("BM", Name.get("Darken"));
      return state;
    });
    const evaluator = makeEvaluator({ xref: { fetch, fetchIfRef: value => value } });
    const resources = new Dict();
    const extGState = new Dict();
    const ref = Ref.get(1, 0);
    extGState.set("GS0", ref);
    resources.set("ExtGState", extGState);

    expect(evaluator.hasBlendModes(resources, new RefSet())).toBe(true);
    expect(fetch).toHaveBeenCalledWith(ref);
  });

  it("ignores an ExtGState that cannot be fetched", () => {
    const evaluator = makeEvaluator({
      xref: {
        fetch: () => {
          throw new Error("unreadable");
        },
        fetchIfRef: value => value,
      },
    });
    const resources = new Dict();
    const extGState = new Dict();
    extGState.set("GS0", Ref.get(2, 0));
    resources.set("ExtGState", extGState);

    expect(evaluator.hasBlendModes(resources, new RefSet())).toBe(false);
  });

  it("remembers resources that contain no blend modes", () => {
    const evaluator = makeEvaluator();
    const resources = new Dict();
    resources.objId = Ref.get(7, 0);
    const nonBlendModesSet = new RefSet();

    expect(evaluator.hasBlendModes(resources, nonBlendModesSet)).toBe(false);
    expect(nonBlendModesSet.has(Ref.get(7, 0))).toBe(true);

    const extGState = new Dict();
    const state = new Dict();
    state.set("BM", Name.get("Multiply"));
    extGState.set("GS0", state);
    resources.set("ExtGState", extGState);

    expect(evaluator.hasBlendModes(resources, nonBlendModesSet)).toBe(false);
  });
});

describe("PartialEvaluator.buildPath", () => {
  it("builds a complete rectangle and updates its bounding box", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();

    evaluator.buildPath(OPS.rectangle, [10, 20, 30, 40], state);

    expect(state.pathBuffer).toEqual([
      DrawOPS.moveTo,
      10,
      20,
      DrawOPS.lineTo,
      40,
      20,
      DrawOPS.lineTo,
      40,
      60,
      DrawOPS.lineTo,
      10,
      60,
      DrawOPS.closePath,
    ]);
    expect(Array.from(state.pathMinMax)).toEqual([10, 20, 40, 60]);
    expect(state.currentPointX).toBe(10);
    expect(state.currentPointY).toBe(20);
  });

  it("degenerates a rectangle with a zero dimension into a line", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();

    evaluator.buildPath(OPS.rectangle, [5, 5, 0, 10], state);

    expect(state.pathBuffer).toEqual([
      DrawOPS.moveTo,
      5,
      5,
      DrawOPS.lineTo,
      5,
      15,
      DrawOPS.closePath,
    ]);
    expect(Array.from(state.pathMinMax)).toEqual([5, 5, 5, 15]);
  });

  it("handles a rectangle with negative width and height", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();

    evaluator.buildPath(OPS.rectangle, [10, 20, -5, -10], state);

    expect(Array.from(state.pathMinMax)).toEqual([5, 10, 10, 20]);
    expect(state.pathBuffer).toEqual([
      DrawOPS.moveTo,
      10,
      20,
      DrawOPS.lineTo,
      5,
      20,
      DrawOPS.lineTo,
      5,
      10,
      DrawOPS.lineTo,
      10,
      10,
      DrawOPS.closePath,
    ]);
  });

  it("tracks line segments and the current point", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();

    evaluator.buildPath(OPS.moveTo, [3, 4], state);
    evaluator.buildPath(OPS.lineTo, [-2, 8], state);

    expect(state.pathBuffer).toEqual([
      DrawOPS.moveTo, 3, 4, DrawOPS.lineTo, -2, 8,
    ]);
    expect(Array.from(state.pathMinMax)).toEqual([-2, 4, 3, 8]);
    expect(state.currentPointX).toBe(-2);
    expect(state.currentPointY).toBe(8);
  });

  it("converts a curveTo into a cubic curve and bounds it", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();

    evaluator.buildPath(OPS.curveTo, [10, 10, 20, 10, 30, 30], state);

    expect(state.pathBuffer).toEqual([
      DrawOPS.curveTo,
      10,
      10,
      20,
      10,
      30,
      30,
    ]);
    expect(Array.from(state.pathMinMax)).toEqual([0, 0, 30, 30]);
    expect(state.currentPointX).toBe(30);
    expect(state.currentPointY).toBe(30);
  });

  it("converts curveTo2 using the current point as the first control point", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();
    state.currentPointX = 5;
    state.currentPointY = 6;
    state.pathMinMax = new Float32Array([5, 6, 5, 6]);

    evaluator.buildPath(OPS.curveTo2, [10, 6, 30, 6], state);

    expect(state.pathBuffer).toEqual([
      DrawOPS.curveTo,
      5,
      6,
      10,
      6,
      30,
      6,
    ]);
    expect(Array.from(state.pathMinMax)).toEqual([5, 6, 30, 6]);
    expect(state.currentPointX).toBe(30);
    expect(state.currentPointY).toBe(6);
  });

  it("converts curveTo3 duplicating the endpoint as the final control point", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();
    state.currentPointX = 5;
    state.currentPointY = 6;
    state.pathMinMax = new Float32Array([5, 6, 5, 6]);

    evaluator.buildPath(OPS.curveTo3, [10, 6, 30, 6], state);

    expect(state.pathBuffer).toEqual([
      DrawOPS.curveTo,
      10,
      6,
      30,
      6,
      30,
      6,
    ]);
    expect(Array.from(state.pathMinMax)).toEqual([5, 6, 30, 6]);
    expect(state.currentPointX).toBe(30);
    expect(state.currentPointY).toBe(6);
  });

  it("appends a closePath operation without changing the current point", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();
    state.currentPointX = 4;
    state.currentPointY = 9;

    evaluator.buildPath(OPS.closePath, [], state);

    expect(state.pathBuffer).toEqual([DrawOPS.closePath]);
    expect(state.currentPointX).toBe(4);
    expect(state.currentPointY).toBe(9);
  });

  it("ignores non-path operators", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();
    state.currentPointX = 4;
    state.currentPointY = 9;

    evaluator.buildPath(OPS.fill, [1, 2, 3], state);

    expect(state.pathBuffer).toEqual([]);
    expect(Array.from(state.pathMinMax)).toEqual([
      Infinity,
      Infinity,
      -Infinity,
      -Infinity,
    ]);
    expect(state.currentPointX).toBe(4);
    expect(state.currentPointY).toBe(9);
  });
});

describe("PartialEvaluator text handling", () => {
  it("returns the glyphs produced by the current font", () => {
    const glyphs = [{ fontChar: "A" }];
    const font = {
      charsToGlyphs: jest.fn(() => glyphs),
      data: null,
    };
    const handler = { send: jest.fn(), sendWithPromise: jest.fn() };
    const evaluator = makeEvaluator({ handler });
    const state = {
      font,
      textRenderingMode: TextRenderingMode.FILL,
      fillColorSpace: { name: "DeviceGray" },
      strokeColorSpace: { name: "DeviceGray" },
    };

    expect(evaluator.handleText("text", state)).toBe(glyphs);
    expect(font.charsToGlyphs).toHaveBeenCalledWith("text");
    expect(handler.send).not.toHaveBeenCalled();
  });

  it("builds font paths when font faces are disabled", () => {
    const glyphs = [
      { fontChar: "A", accent: { fontChar: "B" } },
      { fontChar: "C" },
    ];
    const font = {
      loadedName: "F1",
      data: {},
      disableFontFace: true,
      renderer: {
        getPath: jest.fn(fontChar => ({ fontChar })),
      },
      charsToGlyphs: jest.fn(() => glyphs),
    };
    const handler = { send: jest.fn(), sendWithPromise: jest.fn() };
    const evaluator = makeEvaluator({ handler });
    const state = {
      font,
      textRenderingMode: TextRenderingMode.FILL,
      fillColorSpace: { name: "DeviceGray" },
      strokeColorSpace: { name: "DeviceGray" },
    };

    expect(evaluator.handleText("x", state)).toBe(glyphs);
    expect(handler.send.mock.calls.map(call => call[1][0])).toEqual([
      "F1_path_A",
      "F1_path_B",
      "F1_path_C",
    ]);
    expect(handler.send).toHaveBeenNthCalledWith(
      1,
      "commonobj",
      ["F1_path_A", "FontPath", { fontChar: "A" }],
      [{ fontChar: "A" }]
    );
  });

  it("does nothing from ensureStateFont when a font is already selected", () => {
    const evaluator = makeEvaluator();
    const state = { font: { name: "F1" } };

    expect(() => evaluator.ensureStateFont(state)).not.toThrow();
  });

  it("throws a FormatError when no font has been selected", () => {
    const evaluator = makeEvaluator();

    expect(() => evaluator.ensureStateFont({ font: null })).toThrow(FormatError);
    expect(() => evaluator.ensureStateFont({ font: null })).toThrow(
      "Missing setFont (Tf) operator before text rendering operator."
    );
  });

  it("only warns about a missing font when errors are ignored", () => {
    const warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
    const evaluator = makeEvaluator({ options: { ignoreErrors: true } });

    expect(() => evaluator.ensureStateFont({ font: null })).not.toThrow();
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("ensureStateFont")
    );
  });
});

describe("PartialEvaluator font metrics helpers", () => {
  it("identifies serif fonts by name and fallback convention", () => {
    const evaluator = makeEvaluator();

    expect(evaluator.isSerifFont("Times-Roman")).toBe(true);
    expect(evaluator.isSerifFont("SomeSerifFace")).toBe(true);
    expect(evaluator.isSerifFont("Helvetica")).toBe(false);
    expect(evaluator.isSerifFont("Courier-Bold")).toBe(false);
  });

  it("returns monospaced metrics for Courier", () => {
    const metrics = makeEvaluator().getBaseFontMetrics("Courier");

    expect(metrics.defaultWidth).toBe(600);
    expect(metrics.monospace).toBe(true);
    expect(Object.keys(metrics.widths)).toHaveLength(0);
  });

  it("returns glyph widths for a proportional standard font", () => {
    const metrics = makeEvaluator().getBaseFontMetrics("Helvetica");

    expect(metrics.monospace).toBe(false);
    expect(metrics.defaultWidth).toBe(0);
    expect(metrics.widths.space).toBe(278);
  });

  it("falls back to Times-Roman for unknown serif fonts and Helvetica otherwise", () => {
    const evaluator = makeEvaluator();
    const times = evaluator.getBaseFontMetrics("Times-Roman");
    const helvetica = evaluator.getBaseFontMetrics("Helvetica");
    const unknownSerif = evaluator.getBaseFontMetrics("CustomSerifText");
    const unknownSans = evaluator.getBaseFontMetrics("CustomText");

    expect(unknownSerif.widths.space).toBe(times.widths.space);
    expect(unknownSans.widths.space).toBe(helvetica.widths.space);
  });

  it("prefers differences over the default encoding when building widths", () => {
    const widths = makeEvaluator().buildCharCodeToWidth(
      { A: 500, B: 600 },
      {
        differences: new Map([
          [65, "B"],
          [66, "A"],
          [67, "Missing"],
        ]),
        defaultEncoding: {
          65: "A",
          66: "B",
          67: "B",
        },
      }
    );

    expect(widths[65]).toBe(600);
    expect(widths[66]).toBe(500);
    expect(widths[67]).toBe(600);
    expect(widths[68]).toBeUndefined();
  });

  it("reads a CID-to-GID map while skipping unmapped zero glyphs", () => {
    const toUnicode = new Map([[0, "zero"]]);
    const map = makeEvaluator().readCidToGidMap(
      new Uint8Array([
        0, 0, // code 0 -> glyph 0 (kept because ToUnicode has it)
        0, 5, // code 1 -> glyph 5
        1, 0, // code 2 -> glyph 256
        0, 0, // code 3 -> glyph 0 (skipped, no ToUnicode entry)
      ]),
      toUnicode
    );

    expect(map.size).toBe(3);
    expect(map.get(0)).toBe(0);
    expect(map.get(1)).toBe(5);
    expect(map.get(2)).toBe(256);
    expect(map.has(3)).toBe(false);
  });
});

describe("PartialEvaluator.preEvaluateFont", () => {
  it("applies defaults for a simple font", () => {
    const evaluator = makeEvaluator();
    const dict = new Dict();
    dict.set("Subtype", Name.get("Type1"));

    const result = evaluator.preEvaluateFont(dict);

    expect(result.dict).toBe(dict);
    expect(result.baseDict).toBe(dict);
    expect(result.type).toBe("Type1");
    expect(result.composite).toBe(false);
    expect(result.firstChar).toBe(0);
    expect(result.lastChar).toBe(255);
    expect(result.descriptor).toBeUndefined();
    expect(result.toUnicode).toBeUndefined();
    expect(result.hash).toBe("");
  });

  it("rejects a missing or non-Name font subtype", () => {
    const evaluator = makeEvaluator();
    const missing = new Dict();
    const stringSubtype = new Dict();
    stringSubtype.set("Subtype", "Type1");

    expect(() => evaluator.preEvaluateFont(missing)).toThrow(FormatError);
    expect(() => evaluator.preEvaluateFont(missing)).toThrow(
      "invalid font Subtype"
    );
    expect(() => evaluator.preEvaluateFont(stringSubtype)).toThrow(
      "invalid font Subtype"
    );
  });

  it("rejects a composite font without a valid descendant font", () => {
    const evaluator = makeEvaluator();
    const noDescendants = new Dict();
    noDescendants.set("Subtype", Name.get("Type0"));
    const nonDictionaryDescendant = new Dict();
    nonDictionaryDescendant.set("Subtype", Name.get("Type0"));
    nonDictionaryDescendant.set("DescendantFonts", [42]);

    expect(() => evaluator.preEvaluateFont(noDescendants)).toThrow(
      "Descendant fonts are not specified"
    );
    expect(() => evaluator.preEvaluateFont(nonDictionaryDescendant)).toThrow(
      "Descendant font is not a dictionary."
    );
  });

  it("resolves a Type0 descendant font through the xref", () => {
    const descendant = new Dict();
    descendant.set("Subtype", Name.get("CIDFontType2"));
    const baseDict = new Dict();
    baseDict.set("Subtype", Name.get("Type0"));
    baseDict.set("DescendantFonts", [descendant]);
    const fetchIfRef = jest.fn(value => value);
    const evaluator = makeEvaluator({
      xref: { fetch: value => value, fetchIfRef },
    });

    const result = evaluator.preEvaluateFont(baseDict);

    expect(fetchIfRef).toHaveBeenCalledWith(descendant);
    expect(result.dict).toBe(descendant);
    expect(result.baseDict).toBe(baseDict);
    expect(result.composite).toBe(true);
    expect(result.type).toBe("CIDFontType2");
    expect(result.firstChar).toBe(0);
    expect(result.lastChar).toBe(0xffff);
  });

  it("produces stable hashes for equivalent fonts and a different hash for changed metrics", () => {
    const evaluator = makeEvaluator();
    const makeFont = firstChar => {
      const dict = new Dict();
      dict.set("Subtype", Name.get("Type1"));
      dict.set("FontDescriptor", new Dict());
      dict.set("FirstChar", firstChar);
      dict.set("LastChar", 10);
      return dict;
    };

    const first = evaluator.preEvaluateFont(makeFont(1));
    const equivalent = evaluator.preEvaluateFont(makeFont(1));
    const changed = evaluator.preEvaluateFont(makeFont(2));

    expect(first.hash).toMatch(/^[0-9a-f]{16}$/);
    expect(first.hash).toBe(equivalent.hash);
    expect(first.hash).not.toBe(changed.hash);
  });
});

describe("PartialEvaluator external data fetching", () => {
  it("returns a cached built-in CMap without sending a request", async () => {
    const cached = { cMapData: new Uint8Array([1]), isCompressed: true };
    const handler = { send: jest.fn(), sendWithPromise: jest.fn() };
    const evaluator = makeEvaluator({
      handler,
      builtInCMapCache: new Map([["Foo", cached]]),
    });

    await expect(evaluator.fetchBuiltInCMap("Foo")).resolves.toBe(cached);
    expect(handler.sendWithPromise).not.toHaveBeenCalled();
  });

  it.each([
    {
      cMapPacked: true,
      filename: "Foo.bcmap",
      isCompressed: true,
    },
    {
      cMapPacked: false,
      filename: "Foo",
      isCompressed: false,
    },
  ])(
    "fetches a built-in CMap with cMapPacked=$cMapPacked and caches it",
    async ({ cMapPacked, filename, isCompressed }) => {
      const bytes = new Uint8Array([1, 2]);
      const handler = {
        send: jest.fn(),
        sendWithPromise: jest.fn().mockResolvedValue(bytes),
      };
      const cache = new Map();
      const evaluator = makeEvaluator({
        handler,
        builtInCMapCache: cache,
        options: { useWorkerFetch: false, cMapPacked },
      });

      const result = await evaluator.fetchBuiltInCMap("Foo");

      expect(result).toEqual({ cMapData: bytes, isCompressed });
      expect(cache.get("Foo")).toBe(result);
      expect(handler.sendWithPromise).toHaveBeenCalledWith("FetchBinaryData", {
        kind: "cMapUrl",
        filename,
      });
    }
  );

  it("returns cached standard font data as a stream", async () => {
    const bytes = new Uint8Array([1, 2, 3]);
    const handler = { send: jest.fn(), sendWithPromise: jest.fn() };
    const evaluator = makeEvaluator({
      handler,
      standardFontDataCache: new Map([["Helvetica", bytes]]),
    });

    const stream = await evaluator.fetchStandardFontData("Helvetica");

    expect(stream).toBeInstanceOf(Stream);
    expect(Array.from(stream.bytes)).toEqual([1, 2, 3]);
    expect(stream.length).toBe(3);
    expect(handler.sendWithPromise).not.toHaveBeenCalled();
  });

  it("does not fetch standard data for non-symbol system fonts", async () => {
    const handler = { send: jest.fn(), sendWithPromise: jest.fn() };
    const evaluator = makeEvaluator({
      handler,
      options: { useSystemFonts: true, useWorkerFetch: false },
    });

    await expect(
      evaluator.fetchStandardFontData("Helvetica")
    ).resolves.toBeNull();
    expect(handler.sendWithPromise).not.toHaveBeenCalled();
  });

  it("fetches and caches standard font data for symbol fonts", async () => {
    const bytes = new Uint8Array([4, 5]);
    const handler = {
      send: jest.fn(),
      sendWithPromise: jest.fn().mockResolvedValue(bytes),
    };
    const cache = new Map();
    const evaluator = makeEvaluator({
      handler,
      standardFontDataCache: cache,
      options: { useSystemFonts: true, useWorkerFetch: false },
    });

    const stream = await evaluator.fetchStandardFontData("Symbol");

    expect(stream).toBeInstanceOf(Stream);
    expect(Array.from(stream.bytes)).toEqual([4, 5]);
    expect(cache.get("Symbol")).toBe(bytes);
    expect(handler.sendWithPromise).toHaveBeenCalledWith("FetchBinaryData", {
      kind: "standardFontDataUrl",
      filename: expect.any(String),
    });
  });

  it("returns null and warns when standard font data cannot be fetched", async () => {
    const warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
    const handler = {
      send: jest.fn(),
      sendWithPromise: jest.fn().mockRejectedValue(new Error("offline")),
    };
    const cache = new Map();
    const evaluator = makeEvaluator({
      handler,
      standardFontDataCache: cache,
      options: { useSystemFonts: true, useWorkerFetch: false },
    });

    await expect(evaluator.fetchStandardFontData("Symbol")).resolves.toBeNull();
    expect(cache.has("Symbol")).toBe(false);
    expect(warnSpy).toHaveBeenCalledWith("Warning: Error: offline");
  });
});

describe("PartialEvaluator.getOperatorList", () => {
  function makeTask() {
    return {
      ensureNotTerminated: jest.fn(),
      name: "test-task",
    };
  }

  it("rejects when the operator list is missing", async () => {
    const evaluator = makeEvaluator();

    await expect(
      evaluator.getOperatorList({
        stream: makeStream("0 0 m"),
        task: makeTask(),
        resources: Dict.empty,
      })
    ).rejects.toThrow('getOperatorList: missing "operatorList" parameter');
  });

  it("processes paths and fill colors into operator-list entries", async () => {
    const evaluator = makeEvaluator();
    const task = makeTask();
    const operatorList = new OperatorList();

    await evaluator.getOperatorList({
      stream: makeStream("10 20 m 30 40 l 0 0 0 rg S"),
      task,
      resources: Dict.empty,
      operatorList,
    });

    expect(task.ensureNotTerminated).toHaveBeenCalled();
    expect(operatorList.fnArray).toEqual([
      OPS.setFillRGBColor,
      OPS.constructPath,
    ]);
    expect(operatorList.argsArray[0]).toEqual(["#000000"]);

    const [pathFn, [pathBuffer], minMax] = operatorList.argsArray[1];
    expect(pathFn).toBe(OPS.stroke);
    expect(Array.from(pathBuffer)).toEqual([
      DrawOPS.moveTo,
      10,
      20,
      DrawOPS.lineTo,
      30,
      40,
    ]);
    expect(Array.from(minMax)).toEqual([10, 20, 30, 40]);
  });

  it("emits an empty constructPath entry for a pathless paint operator", async () => {
    const evaluator = makeEvaluator();
    const operatorList = new OperatorList();

    await evaluator.getOperatorList({
      stream: makeStream("S"),
      task: makeTask(),
      resources: Dict.empty,
      operatorList,
    });

    expect(operatorList.fnArray).toEqual([OPS.constructPath]);
    expect(operatorList.argsArray[0]).toEqual([OPS.stroke, [null], null]);
  });

  it("closes the subpath for the close-stroke operator", async () => {
    const evaluator = makeEvaluator();
    const operatorList = new OperatorList();

    await evaluator.getOperatorList({
      stream: makeStream("0 0 m 1 1 l s"),
      task: makeTask(),
      resources: Dict.empty,
      operatorList,
    });

    const [pathFn, [pathBuffer], minMax] = operatorList.argsArray[0];
    expect(pathFn).toBe(OPS.closeStroke);
    expect(Array.from(pathBuffer)).toEqual([
      DrawOPS.moveTo,
      0,
      0,
      DrawOPS.lineTo,
      1,
      1,
      DrawOPS.closePath,
    ]);
    expect(Array.from(minMax)).toEqual([0, 0, 1, 1]);
  });

  it("restores graphics states left open by the content stream", async () => {
    const evaluator = makeEvaluator();
    const operatorList = new OperatorList();

    await evaluator.getOperatorList({
      stream: makeStream("q 0 0 m 1 1 l"),
      task: makeTask(),
      resources: Dict.empty,
      operatorList,
    });

    expect(operatorList.fnArray).toEqual([
      OPS.save,
      OPS.constructPath,
      OPS.restore,
    ]);
  });

  it("rejects invalid XObject references unless errors are ignored", async () => {
    const invalidStream = () => makeStream("/F1 Do");

    await expect(
      makeEvaluator().getOperatorList({
        stream: invalidStream(),
        task: makeTask(),
        resources: Dict.empty,
        operatorList: new OperatorList(),
      })
    ).rejects.toThrow("XObject should be a stream");

    const warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
    const tolerantOperatorList = new OperatorList();
    await expect(
      makeEvaluator({ options: { ignoreErrors: true } }).getOperatorList({
        stream: invalidStream(),
        task: makeTask(),
        resources: Dict.empty,
        operatorList: tolerantOperatorList,
      })
    ).resolves.toBeUndefined();
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("getOperatorList - ignoring errors")
    );
    expect(tolerantOperatorList.length).toBe(0);
  });
});
