    expect(evaluator.hasBlendModes(resources, nonBlendModesSet)).toBe(false);
    expect(nonBlendModesSet.has(Ref.get(7, 0))).toBe(true);

    const extGState = new Dict();
    const state = new Dict();
    state.set("BM", Name.get("Multiply"));
    extGState.set("GS0", state);
    resources.set("ExtGState", extGState);

    expect(evaluator.hasBlendModes(resources, nonBlendModesSet)).toBe(false);
  });
});

describe("PartialEvaluator.buildPath", () => {
  it("builds a complete rectangle and updates its bounding box", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();

    evaluator.buildPath(OPS.rectangle, [10, 20, 30, 40], state);

    expect(state.pathBuffer).toEqual([
      DrawOPS.moveTo,
      10,
      20,
      DrawOPS.lineTo,
      40,
      20,
      DrawOPS.lineTo,
      40,
      60,
      DrawOPS.lineTo,
      10,
      60,
      DrawOPS.closePath,
    ]);
    expect(Array.from(state.pathMinMax)).toEqual([10, 20, 40, 60]);
    expect(state.currentPointX).toBe(10);
    expect(state.currentPointY).toBe(20);
  });

  it("degenerates a rectangle with a zero dimension into a line", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();

    evaluator.buildPath(OPS.rectangle, [5, 5, 0, 10], state);

    expect(state.pathBuffer).toEqual([
      DrawOPS.moveTo,
      5,
      5,
      DrawOPS.lineTo,
      5,
      15,
      DrawOPS.closePath,
    ]);
    expect(Array.from(state.pathMinMax)).toEqual([5, 5, 5, 15]);
  });

  it("handles a rectangle with negative width and height", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();

    evaluator.buildPath(OPS.rectangle, [10, 20, -5, -10], state);

    expect(Array.from(state.pathMinMax)).toEqual([5, 10, 10, 20]);
    expect(state.pathBuffer).toEqual([
      DrawOPS.moveTo,
      10,
      20,
      DrawOPS.lineTo,
      5,
      20,
      DrawOPS.lineTo,
      5,
      10,
      DrawOPS.lineTo,
      10,
      10,
      DrawOPS.closePath,
    ]);
  });

  it("tracks line segments and the current point", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();

    evaluator.buildPath(OPS.moveTo, [3, 4], state);
    evaluator.buildPath(OPS.lineTo, [-2, 8], state);

    expect(state.pathBuffer).toEqual([
      DrawOPS.moveTo, 3, 4, DrawOPS.lineTo, -2, 8,
    ]);
    expect(Array.from(state.pathMinMax)).toEqual([-2, 4, 3, 8]);
    expect(state.currentPointX).toBe(-2);
    expect(state.currentPointY).toBe(8);
  });

  it("converts a curveTo into a cubic curve and bounds it", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();

    evaluator.buildPath(OPS.curveTo, [10, 10, 20, 10, 30, 30], state);

    expect(state.pathBuffer).toEqual([
      DrawOPS.curveTo,
      10,
      10,
      20,
      10,
      30,
      30,
    ]);
    expect(Array.from(state.pathMinMax)).toEqual([0, 0, 30, 30]);
    expect(state.currentPointX).toBe(30);
    expect(state.currentPointY).toBe(30);
  });

  it("converts curveTo2 using the current point as the first control point", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();
    state.currentPointX = 5;
    state.currentPointY = 6;
    state.pathMinMax = new Float32Array([5, 6, 5, 6]);

    evaluator.buildPath(OPS.curveTo2, [10, 6, 30, 6], state);

    expect(state.pathBuffer).toEqual([
      DrawOPS.curveTo,
      5,
      6,
      10,
      6,
      30,
      6,
    ]);
    expect(Array.from(state.pathMinMax)).toEqual([5, 6, 30, 6]);
    expect(state.currentPointX).toBe(30);
    expect(state.currentPointY).toBe(6);
  });

  it("converts curveTo3 duplicating the endpoint as the final control point", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();
    state.currentPointX = 5;
    state.currentPointY = 6;
    state.pathMinMax = new Float32Array([5, 6, 5, 6]);

    evaluator.buildPath(OPS.curveTo3, [10, 6, 30, 6], state);

    expect(state.pathBuffer).toEqual([
      DrawOPS.curveTo,
      10,
      6,
      30,
      6,
      30,
      6,
    ]);
    expect(Array.from(state.pathMinMax)).toEqual([5, 6, 30, 6]);
    expect(state.currentPointX).toBe(30);
    expect(state.currentPointY).toBe(6);
  });

  it("appends a closePath operation without changing the current point", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();
    state.currentPointX = 4;
    state.currentPointY = 9;

    evaluator.buildPath(OPS.closePath, [], state);

    expect(state.pathBuffer).toEqual([DrawOPS.closePath]);
    expect(state.currentPointX).toBe(4);
    expect(state.currentPointY).toBe(9);
  });

  it("ignores non-path operators", () => {
    const evaluator = makeEvaluator();
    const state = makePathState();
    state.currentPointX = 4;
    state.currentPointY = 9;

    evaluator.buildPath(OPS.fill, [1, 2, 3], state);

    expect(state.pathBuffer).toEqual([]);
    expect(Array.from(state.pathMinMax)).toEqual([
      Infinity,
      Infinity,
      -Infinity,
      -Infinity,
    ]);
    expect(state.currentPointX).toBe(4);
    expect(state.currentPointY).toBe(9);
  });
});

