describe("Font with a Type 3 font", () => {
  function createType3Font(overrides = {}) {
    const defaultEncoding = [];
    defaultEncoding[65] = "alpha";
    defaultEncoding[66] = "beta";
    return createFont(
      "Type3Font",
      null,
      {
        type: "Type3",
        isType3Font: true,
        differences: new Map([[65, "gamma"]]),
        defaultEncoding,
        ...overrides,
      },
      { fontExtraProperties: true }
    );
  }

  it("builds toFontChar for every char code from Differences/Encoding", () => {
    const font = createType3Font();

    expect(font.toFontChar).toBeInstanceOf(Map);
    expect(font.toFontChar.size).toBe(256);
    // `Differences` takes precedence over the font `Encoding`.
    expect(font.toFontChar.get(65)).toBe("gamma");
    expect(font.toFontChar.get(66)).toBe("beta");
    expect(font.toFontChar.get(0)).toBeUndefined();
  });

  it("does not attempt to load or repair a font file", () => {
    const font = createType3Font();

    expect(font.missingFile).toBe(false);
    expect(font.data).toBeUndefined();
    // Type 3 fonts return early, before the CID/vertical properties are set.
    expect(font.cidEncoding).toBeUndefined();
    expect(font.vertical).toBeUndefined();
  });

  it("uses the glyph name as the operator list id", () => {
    const font = createType3Font();

    const glyph = font._charToGlyph(65);
    expect(glyph.operatorListId).toBe("gamma");
    // Glyph names are not valid code points, hence no `fontChar` is produced.
    expect(glyph.fontChar).toBe("");
    expect(glyph.unicode).toBe("A");
    expect(glyph.isInFont).toBe(true);
  });
});

describe("Font with a non-embedded font file", () => {
  it("derives name, metrics and flags for a standard font", () => {
    const font = createFont("Helvetica", null, {
      widths: { 65: 667 },
      ascent: NaN,
      descent: NaN,
      capHeight: NaN,
    });

    expect(font.missingFile).toBe(true);
    expect(font.loadedName).toBe("Helvetica");
    // The basic metrics of the standard font are used for missing values.
    expect(font.ascent).toBeCloseTo(0.718, 6);
    expect(font.descent).toBeCloseTo(-0.207, 6);
    expect(font.capHeight).toBeCloseTo(0.718, 6);
    expect(font.bold).toBe(false);
    expect(font.italic).toBe(false);
    expect(font.black).toBe(false);
    expect(font.fallbackName).toBe("sans-serif");
    expect(font.isSerifFont).toBe(false);
    // At least one width is present, but it is a standard font.
    expect(font.remeasure).toBe(false);
  });

  it("detects bold/italic/black variants through the standard font name", () => {
    const bold = createFont("Arial-BoldMT", null, { widths: { 1: 100 } });
    expect(bold.loadedName).toBe("Helvetica");
    expect(bold.bold).toBe(true);
    expect(bold.italic).toBe(false);

    const italic = createFont("Helvetica-Oblique", null);
    expect(italic.italic).toBe(true);

    const black = createFont("ArialBlack", null);
    expect(black.black).toBe(true);
  });

  it("infers a serif fallback from the font name", () => {
    const times = createFont("Times-Roman", null);
    expect(times.isSerifFont).toBe(true);
    expect(times.fallbackName).toBe("serif");

    // Simulated flags disable the name based serif detection.
    const simulated = createFont("Times-Roman", null, { isSimulatedFlags: true });
    expect(simulated.isSerifFont).toBe(false);
    expect(simulated.fallbackName).toBe("sans-serif");
  });

  it("maps the font flags onto the fallback name", () => {
    const symbolic = createFont("SomeFont", null, { flags: 4 });
    expect(symbolic.isSymbolicFont).toBe(true);
    expect(symbolic.fallbackName).toBe("sans-serif");

    const monospace = createFont("SomeFont", null, { flags: 1 });
    expect(monospace.isMonospace).toBe(true);
    expect(monospace.fallbackName).toBe("monospace");
  });

  it("recognizes invalid PDF.js font names", () => {
    const font = createFont("InvalidPDFjsFont_MyCustomFont_12345", null);

    expect(font.isInvalidPDFjsFont).toBe(true);
    expect(font.fallbackName).toBe("MyCustomFont");
  });

  it("appends the guessed fallback to a system font info", () => {
    const systemFontInfo = { css: "local(Test)", guessFallback: true };
    const font = createFont("Courier", null, { systemFontInfo });

    expect(font.systemFontInfo).toBe(systemFontInfo);
    expect(systemFontInfo.guessFallback).toBe(false);
    expect(systemFontInfo.css).toBe("local(Test),monospace");
  });

  it("remeasures non-standard and narrow fonts with widths", () => {
    const custom = createFont("MyCustomFont", null, { widths: { 1: 100 } });
    expect(custom.remeasure).toBe(true);

    const withoutWidths = createFont("MyCustomFont", null);
    expect(withoutWidths.remeasure).toBe(false);

    const narrow = createFont("ArialNarrow", null, { widths: { 1: 100 } });
    expect(narrow.loadedName).toBe("Helvetica");
    expect(narrow.remeasure).toBe(true);
  });

  it("builds toFontChar from the standard encoding and /Differences", () => {
    const font = createFont("Helvetica", null, {
      differences: new Map([
        [0x41, "bullet"],
        [0x100, "Euro"],
      ]),
    });

    expect(font.toFontChar.size).toBeGreaterThan(100);
    expect(font.toFontChar.get(0x20)).toBe(0x20); // space
    expect(font.toFontChar.get(0x42)).toBe(0x42); // B
    // /Differences override the encoding for a given char code...
    expect(font.toFontChar.get(0x41)).toBe(0x2022); // bullet
    // ... and may introduce char codes outside of the encoding.
    expect(font.toFontChar.get(0x100)).toBe(0x20ac); // Euro
  });

  it("builds toFontChar from the Symbol encoding", () => {
    const font = createFont("Symbol", null);
    const alpha = getGlyphsUnicode().Alpha;

    expect(font.toFontChar.get(65)).toBe(alpha);
    expect(font.toFontChar.get(65)).toBe(913);
  });

  it("builds toFontChar from the ZapfDingbats encoding", () => {
    const font = createFont("ZapfDingbats", null);
    const dingbats = getDingbatsGlyphsUnicode();

    expect(dingbats.a10).toEqual(expect.any(Number));
    expect(font.toFontChar.get(65)).toBe(dingbats.a10);
  });

  it("builds toFontChar from the ToUnicode data of unknown fonts", () => {
    const font = createFont("MyCustomFont", null, {
      defaultEncoding: [],
      differences: new Map([[1, "A"]]),
      toUnicode: createToUnicodeMap([
        [2, "B"],
        [3, "C"],
      ]),
    });

    // Only the /ToUnicode entries are used for unknown fonts.
    expect([...font.toFontChar.keys()]).toEqual([2, 3]);
    expect(font.toFontChar.get(2)).toBe(0x42);
    expect(font.toFontChar.get(3)).toBe(0x43);
  });

  it("maps standard glyph ids for CIDFontType2 fonts with Identity encoding", () => {
    const cidToGidMap = new CharCodeMap();
    cidToGidMap.set(65, 999);

    const font = createFont("Helvetica", null, {
      type: "CIDFontType2",
      subtype: "CIDFontType2",
      composite: true,
      cidEncoding: "Identity-H",
      cidToGidMap,
      toUnicode: new IdentityToUnicodeMap(0, 0xffff),
      widths: { 36: 400 },
    });

    expect(font.toFontChar.size).toBeGreaterThan(100);
    // 36 => 65 in the standard font glyph map, remapped through /CIDToGIDMap.
    expect(font.toFontChar.get(36)).toBe(999);
    expect(font.toFontChar.get(37)).toBe(66);
    // The ToUnicode map is replaced by the glyph id based mapping.
    expect(font.toUnicode).toBeInstanceOf(ToUnicodeMap);
    expect(font.toUnicode.get(36)).toBe(999);

    const glyph = font._charToGlyph(36);
    expect(glyph.fontChar).toBe(String.fromCodePoint(999));
    expect(glyph.unicode).toBe(String.fromCodePoint(999));
    expect(glyph.isInFont).toBe(true);
    // Char codes missing from the map fall back to the char code itself.
    expect(font._charToGlyph(1).isInFont).toBe(false);
  });
});

describe("Font with embedded font data", () => {
