describe("Font.encodeString", () => {
  it("encodes characters found in the ToUnicode map", () => {
    const font = createFont("MyCustomFont", null, {
      toUnicode: createToUnicodeMap([
        [1, "A"],
        [2, "B"],
      ]),
    });

    expect(font.encodeString("AB")).toEqual(["\u0001\u0002"]);
  });

  it("keeps encoded and non-encoded parts in separate buffers", () => {
    const font = createFont("MyCustomFont", null, {
      toUnicode: createToUnicodeMap([
        [1, "A"],
        [2, "B"],
      ]),
    });

    // Even positions contain encoded strings, odd positions plain text.
    expect(font.encodeString("A\u{1f600}B")).toEqual(["\u0001", "\u{1f600}", "\u0002"]);
  });

  it("uses the CMap char code length for the encoded bytes", () => {
    const cMap = createTwoByteCMap([
      [1, 5],
      [0x20, 7],
    ]);
    const font = createFont("MyCustomFont", null, {
      composite: true,
      cMap,
      toUnicode: createToUnicodeMap([
        [1, "A"],
        [2, "B"],
        [0x20, " "],
      ]),
    });

    expect(font.encodeString("AB ")).toEqual(["\u0000\u0001\u0000\u0002 "]);
  });

  it("encodes unicode values through an IdentityToUnicodeMap", () => {
    const font = createFont("Helvetica", null, {
      toUnicode: new IdentityToUnicodeMap(0, 0xffff),
    });

    expect(font.encodeString("AB")).toEqual(["AB"]);
    // Code points outside of the identity range cannot be encoded.
    expect(font.encodeString("A\u{1f600}")).toEqual(["A", "\u{1f600}"]);
  });

  it("does not encode anything without a ToUnicode map", () => {
    const font = createFont("Helvetica", null, { toUnicode: undefined });

    expect(font.encodeString("abc")).toEqual(["", "abc"]);
  });
});

describe("Font.exportData", () => {
