import { FONT_INFO } from "../../src/shared/obj_bin_transform_utils.js";

const EVALUATOR_OPTIONS = {
  disableFontFace: false,
  fontExtraProperties: false,
};

/**
 * Build a `ToUnicodeMap` from an array of `[charCode, unicodeString]` pairs.
 */
function createToUnicodeMap(entries = []) {
  const map = new CharCodeMap();
  for (const [charCode, unicode] of entries) {
    map.set(charCode, unicode);
  }
  return new ToUnicodeMap(map);
}

/**
 * Build a complete-enough `properties` object for the `Font` constructor.
 */
function createFontProperties(overrides = {}) {
  return {
    loadedName: "g_font_1",
    isType3Font: false,
    cssFontInfo: undefined,
    flags: 0,
    type: "TrueType",
    subtype: "TrueType",
    systemFontInfo: undefined,
    differences: new Map(),
    widths: {},
    defaultWidth: 0,
    composite: false,
    cMap: undefined,
    capHeight: 700,
    ascent: 800,
    descent: -200,
    fontMatrix: [0.001, 0, 0, 0.001, 0, 0],
    bbox: [0, 0, 1000, 1000],
    defaultEncoding: StandardEncoding,
    toUnicode: createToUnicodeMap(),
    ...overrides,
  };
}

function createFont(name, file, overrides = {}, options = {}) {
  return new Font(
    name,
    file,
    createFontProperties(overrides),
    { ...EVALUATOR_OPTIONS, ...options }
  );
}

function createTwoByteCMap(pairs) {
  const cMap = new CMap();
  cMap.addCodespaceRange(1, 0x20, 0x20);
  cMap.addCodespaceRange(2, 0x0000, 0xffff);
  for (const [charCode, cid] of pairs) {
    cMap.mapOne(charCode, cid);
  }
  return cMap;
}

function readExportedStrings(buffer) {
  const view = new DataView(buffer);
  const decoder = new TextDecoder();
  let offset = FONT_INFO.OFFSET_STRINGS;
  offset += 4; // Total length of the encoded strings.
  const strings = Object.create(null);
  for (const name of FONT_INFO.strings) {
    const length = view.getUint32(offset);
    offset += 4;
    strings[name] = decoder.decode(new Uint8Array(buffer, offset, length));
    offset += length;
  }
  return strings;
}

function readExportedBools(buffer) {
  const bytes = new Uint8Array(buffer);
  const bools = Object.create(null);
  FONT_INFO.bools.forEach((name, i) => {
    // Each boolean is stored in two bits: 0b00 === undefined, 0b01 === false
    // and 0b10 === true.
    const value =
      (bytes[Math.floor((2 * i) / 8)] >> ((2 * i) % 8)) & /* mask = */ 0b11;
    if (value !== 0) {
      bools[name] = value === 0b10;
    }
  });
  return bools;
}

