    expect(data.extra).toBeDefined();
    expect(data.extra.widths).toEqual({ 65: 667 });
    expect(data.extra.composite).toBe(true);
    expect(data.extra.defaultWidth).toBe(0);
    expect(data.extra.toFontChar).toBeInstanceOf(Map);
    expect(data.extra).not.toHaveProperty("data");
    expect(data.extra).not.toHaveProperty("bbox");
  });
});
