  fetchAsync: async value => value,
  fetchIfRef: value => value,
};

function makeDict(entries = {}) {
  const dict = new Dict(xref);
  for (const [key, value] of Object.entries(entries)) {
    dict.set(key, value);
  }
  return dict;
}

function makeStream({
  entries = {},
  bytes = [],
  width,
  height,
  numComps = 1,
  bitsPerComponent = 8,
  dict,
} = {}) {
  const streamDict = dict || makeDict(entries);
  const stream = new Stream(Uint8Array.from(bytes), 0, bytes.length, streamDict);
  stream.width = width;
  stream.height = height;
  stream.numComps = numComps;
  stream.bitsPerComponent = bitsPerComponent;
  return stream;
}

function makePDFImage(stream, overrides = {}) {
  return new PDFImage({
    xref,
    res: null,
    image: stream,
    pdfFunctionFactory: null,
    globalColorSpaceCache: new GlobalColorSpaceCache(),
    localColorSpaceCache: new LocalColorSpaceCache(),
    ...overrides,
  });
}

class TestDecodeStream extends DecodeStream {
