import { PDFImage } from "../../src/core/image.js";
import { Dict, Name } from "../../src/core/primitives.js";
import { Stream } from "../../src/core/stream.js";
import { DecodeStream } from "../../src/core/decode_stream.js";
import {
  GlobalColorSpaceCache,
  LocalColorSpaceCache,
} from "../../src/core/image_utils.js";
import { FormatError, ImageKind } from "../../src/shared/util.js";

const xref = {
  fetch: value => value,
  fetchAsync: async value => value,
  fetchIfRef: value => value,
};

function makeDict(entries = {}) {
  const dict = new Dict(xref);
  for (const [key, value] of Object.entries(entries)) {
    dict.set(key, value);
  }
  return dict;
}

function makeStream({
  entries = {},
  bytes = [],
  width,
  height,
  numComps = 1,
  bitsPerComponent = 8,
  dict,
} = {}) {
  const streamDict = dict || makeDict(entries);
  const stream = new Stream(Uint8Array.from(bytes), 0, bytes.length, streamDict);
  stream.width = width;
  stream.height = height;
  stream.numComps = numComps;
  stream.bitsPerComponent = bitsPerComponent;
  return stream;
}

function makePDFImage(stream, overrides = {}) {
  return new PDFImage({
    xref,
    res: null,
    image: stream,
    pdfFunctionFactory: null,
    globalColorSpaceCache: new GlobalColorSpaceCache(),
    localColorSpaceCache: new LocalColorSpaceCache(),
    ...overrides,
  });
}

class TestDecodeStream extends DecodeStream {
  constructor(bytes, dict) {
    super();
    this.buffer = Uint8Array.from(bytes);
    this.bufferLength = this.buffer.length;
    this.eof = true;
    this.dict = dict;
  }

  readBlock() {}
}

class MockImageData {
  constructor(dataOrWidth, widthOrHeight, maybeHeight) {
    if (typeof dataOrWidth === "number") {
      this.width = dataOrWidth;
      this.height = widthOrHeight;
      this.data = new Uint8ClampedArray(this.width * this.height * 4);
    } else {
      this.data = dataOrWidth;
      this.width = widthOrHeight;
      this.height = maybeHeight;
    }
  }
}

class MockOffscreenCanvas {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this.putImageDataCalls = [];
    this.ctx = {
      createImageData: (w, h) => new MockImageData(w, h),
      putImageData: (imageData, x, y) => {
        this.putImageDataCalls.push({ imageData, x, y });
      },
    };
  }

  getContext(type) {
    return type === "2d" ? this.ctx : null;
  }

  transferToImageBitmap() {
    const source = this.putImageDataCalls.at(-1)?.imageData;
    const data = source?.data ? new Uint8ClampedArray(source.data) : null;
    return {
      displayWidth: this.width,
      displayHeight: this.height,
      data,
    };
  }
}

const originalOffscreenCanvas = globalThis.OffscreenCanvas;
const originalImageData = globalThis.ImageData;

function installCanvasGlobals() {
  globalThis.OffscreenCanvas = MockOffscreenCanvas;
  globalThis.ImageData = MockImageData;
}

afterEach(() => {
  if (originalOffscreenCanvas === undefined) {
    delete globalThis.OffscreenCanvas;
  } else {
    globalThis.OffscreenCanvas = originalOffscreenCanvas;
  }
  if (originalImageData === undefined) {
    delete globalThis.ImageData;
  } else {
    globalThis.ImageData = originalImageData;
  }
});

