    });

    const result = await PDFImage.createMask({ image: stream });

    expect(Array.from(result.data)).toEqual([0xf0, 0xff]);
  });

  it("transfers decoded bytes from a DecodeStream without a Uint8Array copy", async () => {
    const dict = makeDict({ Width: 10, Height: 1 });
    const stream = new TestDecodeStream([0x12], dict);

    const result = await PDFImage.createMask({ image: stream });

    expect(result.data).toBeInstanceOf(Uint8Array);
