describe("PDFImage component decoding", () => {
  it("returns 8-bit input unchanged from getComponents", () => {
    const stream = makeStream({
      entries: { Width: 1, Height: 1 },
      bytes: [7],
      width: 1,
      height: 1,
      numComps: 1,
    });
    const image = makePDFImage(stream);
    const buffer = new Uint8Array([7]);

    expect(image.getComponents(buffer)).toBe(buffer);
  });

  it("unpacks 1-bit components row by row", () => {
    const stream = makeStream({
      entries: { Width: 3, Height: 2 },
      bytes: [0b10100000, 0b01000000],
      width: 3,
      height: 2,
      numComps: 1,
      bitsPerComponent: 1,
    });
    const image = makePDFImage(stream);

    expect(Array.from(image.getComponents(new Uint8Array([0b10100000, 0b01000000])))).toEqual([
      1, 0, 1, 0, 1, 0,
    ]);
  });

  it("unpacks 2-bit components", () => {
    const stream = makeStream({
      entries: { Width: 2, Height: 2 },
      bytes: [0b00011000, 0b11100100],
      width: 2,
      height: 2,
      numComps: 1,
      bitsPerComponent: 2,
    });
    const image = makePDFImage(stream);

    expect(Array.from(image.getComponents(new Uint8Array([0b00011000, 0b11100100])))).toEqual([
      0, 1, 3, 2,
    ]);
  });

  it("unpacks 16-bit components and clamps to the component maximum", () => {
    const stream = makeStream({
      entries: { Width: 2, Height: 1 },
      bytes: [0x12, 0x34, 0xab, 0xcd],
      width: 2,
      height: 1,
      numComps: 1,
      bitsPerComponent: 16,
    });
    const image = makePDFImage(stream);

    expect(
      Array.from(
        image.getComponents(new Uint8Array([0x12, 0x34, 0xab, 0xcd]))
      )
    ).toEqual([0x1234, 0xabcd]);
  });

  it("inverts every byte when decoding a 1-bit buffer", () => {
    const stream = makeStream({
      entries: { Width: 4, Height: 1 },
      bytes: [0x00],
      width: 4,
      height: 1,
      numComps: 1,
      bitsPerComponent: 1,
    });
    const image = makePDFImage(stream);
    const buffer = new Uint8Array([0x00, 0xaa, 0xff]);

    image.decodeBuffer(buffer);

    expect(Array.from(buffer)).toEqual([0xff, 0x55, 0x00]);
  });

  it("applies and clamps a reverse 4-bit decode map", () => {
    const stream = makeStream({
      entries: { Width: 3, Height: 1, Decode: [15, 0] },
      bytes: [0x12, 0x30],
      width: 3,
      height: 1,
      numComps: 1,
      bitsPerComponent: 4,
    });
    const image = makePDFImage(stream);
    const buffer = new Uint8Array([0, 1, 15]);

    expect(image.needsDecode).toBe(true);
    image.decodeBuffer(buffer);

    expect(Array.from(buffer)).toEqual([225, 210, 0]);
  });
});

