describe("PDFImage.fillGrayBuffer", () => {
  it("rejects color images", async () => {
    const stream = makeStream({
      entries: { Width: 1, Height: 1 },
      bytes: [0, 0, 0],
      width: 1,
      height: 1,
      numComps: 3,
    });
    const image = makePDFImage(stream);

    await expect(image.fillGrayBuffer(new Uint8ClampedArray(1))).rejects.toThrow(
      "Reading gray scale from a color image: 3"
    );
  });

  it("copies 8-bit grayscale samples without resampling", async () => {
    const stream = makeStream({
      entries: { Width: 2, Height: 2 },
      bytes: [0, 64, 128, 255],
      width: 2,
      height: 2,
      numComps: 1,
    });
    const image = makePDFImage(stream);
    const buffer = new Uint8ClampedArray(4);

    await image.fillGrayBuffer(buffer);

    expect(Array.from(buffer)).toEqual([0, 64, 128, 255]);
  });

  it("honors maxRows, offset, stride, and invertOutput", async () => {
    const stream = makeStream({
      entries: { Width: 2, Height: 2 },
      bytes: [0, 64, 128, 255],
      width: 2,
      height: 2,
      numComps: 1,
    });
    const image = makePDFImage(stream);
    const buffer = new Uint8ClampedArray(8).fill(99);

    await image.fillGrayBuffer(buffer, {
      invertOutput: true,
      maxRows: 1,
      offset: 1,
      stride: 2,
    });

    expect(Array.from(buffer)).toEqual([99, 255, 99, 191, 99, 99, 99, 99]);
  });

  it("scales 1-bit samples to black and white", async () => {
    const stream = makeStream({
      entries: { Width: 4, Height: 1 },
      bytes: [0b10100000],
      width: 4,
      height: 1,
      numComps: 1,
      bitsPerComponent: 1,
    });
    const image = makePDFImage(stream);
    const buffer = new Uint8ClampedArray(4);

    await image.fillGrayBuffer(buffer);

    expect(Array.from(buffer)).toEqual([255, 0, 255, 0]);
  });

  it("inverts 1-bit samples when a reverse decode map is present", async () => {
    const stream = makeStream({
      entries: { Width: 4, Height: 1, Decode: [1, 0] },
      bytes: [0b10100000],
      width: 4,
      height: 1,
      numComps: 1,
      bitsPerComponent: 1,
    });
    const image = makePDFImage(stream);
    const buffer = new Uint8ClampedArray(4);

    await image.fillGrayBuffer(buffer);

    expect(Array.from(buffer)).toEqual([0, 255, 0, 255]);
  });

  it("uses nearest-neighbour resampling to the requested dimensions", async () => {
    const stream = makeStream({
      entries: { Width: 2, Height: 2 },
      bytes: [10, 20, 30, 40],
      width: 2,
      height: 2,
      numComps: 1,
    });
    const image = makePDFImage(stream);
    const buffer = new Uint8ClampedArray(9);

    await image.fillGrayBuffer(buffer, { destWidth: 3, destHeight: 3 });

    expect(Array.from(buffer)).toEqual([10, 10, 20, 10, 10, 20, 30, 30, 40]);
  });
});

describe("PDFImage.createImageData", () => {
  it("returns compact RGB data for an uncomplicated 8-bit RGB image", async () => {
    const stream = makeStream({
      entries: { Width: 2, Height: 1 },
      bytes: [255, 0, 0, 0, 255, 0],
      width: 2,
      height: 1,
      numComps: 3,
    });
    const image = makePDFImage(stream);

    const result = await image.createImageData();

    expect(result).toMatchObject({ width: 2, height: 1, kind: ImageKind.RGB_24BPP });
    expect(Array.from(result.data)).toEqual([255, 0, 0, 0, 255, 0]);
  });

  it("returns compact grayscale data for an uncomplicated 1-bit image", async () => {
    const stream = makeStream({
      entries: { Width: 3, Height: 1 },
      bytes: [0b10100000],
      width: 3,
      height: 1,
      numComps: 1,
      bitsPerComponent: 1,
    });
    const image = makePDFImage(stream);

    const result = await image.createImageData();

    expect(result.kind).toBe(ImageKind.GRAYSCALE_1BPP);
    expect(Array.from(result.data)).toEqual([0xa0]);
  });

  it("inverts compact grayscale data when decoding is required", async () => {
    const stream = makeStream({
      entries: { Width: 3, Height: 1, Decode: [1, 0] },
      bytes: [0b10100000],
      width: 3,
      height: 1,
      numComps: 1,
      bitsPerComponent: 1,
    });
    const image = makePDFImage(stream);

    const result = await image.createImageData();

    expect(result.kind).toBe(ImageKind.GRAYSCALE_1BPP);
    expect(Array.from(result.data)).toEqual([0x5f]);
  });

  it("expands grayscale to RGB when forceRGBA is false and compact output is unavailable", async () => {
    const stream = makeStream({
      entries: { Width: 2, Height: 1 },
      bytes: [0, 255],
      width: 2,
      height: 1,
      numComps: 1,
    });
    const image = makePDFImage(stream);

    const result = await image.createImageData();

    expect(result.kind).toBe(ImageKind.RGB_24BPP);
    expect(Array.from(result.data)).toEqual([0, 0, 0, 255, 255, 255]);
  });

  it("forceRGBA expands grayscale and fills opaque alpha channels", async () => {
    const stream = makeStream({
      entries: { Width: 2, Height: 1 },
      bytes: [0, 255],
      width: 2,
      height: 1,
      numComps: 1,
    });
    const image = makePDFImage(stream);

    const result = await image.createImageData(true);

    expect(result.kind).toBe(ImageKind.RGBA_32BPP);
    expect(Array.from(result.data)).toEqual([
      0, 0, 0, 255, 255, 255, 255, 255,
    ]);
  });

  it("applies a color-key mask before producing RGBA data", async () => {
    const stream = makeStream({
      entries: {
        Width: 1,
        Height: 1,
        Mask: [0, 255, 0, 255, 0, 255],
      },
      bytes: [255, 0, 0],
      width: 1,
      height: 1,
      numComps: 3,
    });
    const image = makePDFImage(stream);

    const result = await image.createImageData();

    expect(result.kind).toBe(ImageKind.RGBA_32BPP);
    expect(Array.from(result.data)).toEqual([255, 0, 0, 0]);
  });

  it("combines RGB data with a soft mask alpha channel", async () => {
    const smask = makeStream({
      entries: { Width: 1, Height: 1 },
      bytes: [128],
      width: 1,
      height: 1,
      numComps: 1,
    });
    const stream = makeStream({
      entries: { Width: 1, Height: 1 },
      bytes: [255, 0, 0],
      width: 1,
      height: 1,
      numComps: 3,
    });
    const image = makePDFImage(stream, { smask });

    const result = await image.createImageData();

    expect(result.kind).toBe(ImageKind.RGBA_32BPP);
    expect(Array.from(result.data)).toEqual([255, 0, 0, 128]);
  });

  it("passes through DeviceRGBA data without expansion", async () => {
    const stream = makeStream({
      entries: { Width: 1, Height: 1, ColorSpace: Name.get("DeviceRGBA") },
      bytes: [1, 2, 3, 4],
      width: 1,
      height: 1,
      numComps: 4,
    });
    const image = makePDFImage(stream);

    const result = await image.createImageData();

    expect(result.kind).toBe(ImageKind.RGBA_32BPP);
    expect(Array.from(result.data)).toEqual([1, 2, 3, 4]);
  });

  it("produces an ImageBitmap when offscreen canvas support is available", async () => {
    installCanvasGlobals();
    const stream = makeStream({
      entries: { Width: 2, Height: 1, Interpolate: true },
      bytes: [0, 255],
      width: 2,
      height: 1,
      numComps: 1,
    });
    const image = makePDFImage(stream);

    const result = await image.createImageData(true, true);

    expect(result.data).toBeNull();
    expect(result.width).toBe(2);
    expect(result.height).toBe(1);
    expect(result.interpolate).toBe(true);
    expect(result.bitmap.displayWidth).toBe(2);
    expect(Array.from(result.bitmap.data)).toEqual([
      0, 0, 0, 255, 255, 255, 255, 255,
    ]);
  });
});

describe("PDFImage.createBitmap", () => {
