describe("PDFImage.getImageBytes", () => {
  it("resets and configures the source stream before reading", async () => {
    const calls = [];
    const stream = makeStream({
      entries: { Width: 3, Height: 2 },
      bytes: [1, 2, 3],
      width: 3,
      height: 2,
      numComps: 1,
    });
    stream.getImageData = async (length, options) => {
      calls.push({ length, options });
      return new Uint8Array([9]);
    };
    let resets = 0;
    stream.reset = () => {
      resets++;
    };
    const image = makePDFImage(stream);

    await image.getImageBytes(5, {
      drawWidth: 7,
      drawHeight: 8,
      forceRGBA: true,
      forceRGB: true,
      internal: true,
    });

    expect(resets).toBe(1);
    expect(stream.drawWidth).toBe(7);
    expect(stream.drawHeight).toBe(8);
    expect(stream.forceRGBA).toBe(true);
    expect(stream.forceRGB).toBe(true);
    expect(calls).toEqual([{ length: 5, options: undefined }]);
  });

  it("returns a fresh Uint8Array for externally visible stream data", async () => {
    const stream = makeStream({
      entries: { Width: 3, Height: 1 },
      bytes: [1, 2, 3],
      width: 3,
      height: 1,
      numComps: 1,
    });
    const image = makePDFImage(stream);

    const result = await image.getImageBytes(3);

    expect(result).toBeInstanceOf(Uint8Array);
    expect(Array.from(result)).toEqual([1, 2, 3]);
    expect(result.buffer).not.toBe(stream.buffer.buffer);
  });

  it("returns the source view directly for internal callers", async () => {
    const stream = makeStream({
      entries: { Width: 3, Height: 1 },
      bytes: [1, 2, 3],
      width: 3,
      height: 1,
      numComps: 1,
    });
    const image = makePDFImage(stream);

    const result = await image.getImageBytes(3, { internal: true });

    expect(Array.from(result)).toEqual([1, 2, 3]);
    expect(result.buffer).toBe(stream.buffer.buffer);
  });
});

describe("PDFImage._fillDownscaledRgba", () => {
  it("averages opaque grayscale blocks", async () => {
    const stream = makeStream({
      entries: { Width: 4, Height: 4 },
      bytes: [
        0, 0, 100, 100,
        0, 0, 100, 100,
        200, 200, 255, 255,
        200, 200, 255, 255,
      ],
      width: 4,
      height: 4,
      numComps: 1,
    });
    const image = makePDFImage(stream);
    const dest = new Uint8ClampedArray(16);

    await image._fillDownscaledRgba(dest, 2, 2);

    expect(Array.from(dest)).toEqual([
      0, 0, 0, 255,
      100, 100, 100, 255,
      200, 200, 200, 255,
      255, 255, 255, 255,
    ]);
  });

  it("averages opaque RGB blocks", async () => {
    const stream = makeStream({
      entries: { Width: 2, Height: 2 },
      bytes: [
        255, 0, 0,
        0, 255, 0,
        0, 0, 255,
        255, 255, 255,
      ],
      width: 2,
      height: 2,
      numComps: 3,
    });
    const image = makePDFImage(stream);
    const dest = new Uint8ClampedArray(4);

    await image._fillDownscaledRgba(dest, 1, 1);

    expect(Array.from(dest)).toEqual([128, 128, 128, 255]);
  });
});
