import { GlyfTable, pruneCompositeGlyphCycles } from "../../src/core/glyf.js";

// The two helpers below are newer ECMAScript additions which are used by the
// production code, but which are not available in every supported runtime.
// Defining them here keeps the tests runnable without touching production code.
if (typeof Math.sumPrecise !== "function") {
  Object.defineProperty(Math, "sumPrecise", {
    configurable: true,
    writable: true,
    value(values) {
      let sum = 0;
      for (const value of values) {
        sum += value;
      }
      return sum;
    },
  });
}
if (typeof Map.prototype.getOrInsertComputed !== "function") {
  Object.defineProperty(Map.prototype, "getOrInsertComputed", {
    configurable: true,
    writable: true,
    value(key, insert) {
      if (!this.has(key)) {
        this.set(key, insert(key));
      }
      return this.get(key);
    },
  });
}

// TrueType glyph flags. Re-declared here so the expectations are independent
// from the constants contained in the production implementation.
const ON_CURVE_POINT = 1 << 0;
const X_SHORT_VECTOR = 1 << 1;
const Y_SHORT_VECTOR = 1 << 2;
const REPEAT_FLAG = 1 << 3;
const X_IS_SAME_OR_POSITIVE_X_SHORT_VECTOR = 1 << 4;
const Y_IS_SAME_OR_POSITIVE_Y_SHORT_VECTOR = 1 << 5;
const OVERLAP_SIMPLE = 1 << 6;

const ARG_1_AND_2_ARE_WORDS = 1 << 0;
const ARGS_ARE_XY_VALUES = 1 << 1;
const WE_HAVE_A_SCALE = 1 << 3;
const MORE_COMPONENTS = 1 << 5;
const WE_HAVE_AN_X_AND_Y_SCALE = 1 << 6;
const WE_HAVE_A_TWO_BY_TWO = 1 << 7;
const WE_HAVE_INSTRUCTIONS = 1 << 8;

function viewOf(bytes) {
  return new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
}

function concatBytes(...chunks) {
  const length = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
  const result = new Uint8Array(length);
  let pos = 0;
  for (const chunk of chunks) {
    result.set(chunk, pos);
    pos += chunk.length;
  }
  return result;
}

function makeGlyphHeader(
  numberOfContours,
  { xMin = 0, yMin = 0, xMax = 0, yMax = 0 } = {}
) {
  const bytes = new Uint8Array(10);
  const view = viewOf(bytes);
  view.setInt16(0, numberOfContours);
  view.setInt16(2, xMin);
  view.setInt16(4, yMin);
  view.setInt16(6, xMax);
  view.setInt16(8, yMax);
  return bytes;
}

function makeSimpleGlyph({
  numberOfContours = 2,
  bbox,
  endPoints,
  instructions = [],
  flags,
  xBytes = [],
  yBytes = [],
}) {
  const length =
    10 +
    endPoints.length * 2 +
    2 +
    instructions.length +
    flags.length +
    xBytes.length +
    yBytes.length;
  const bytes = new Uint8Array(length);
  const view = viewOf(bytes);
  bytes.set(makeGlyphHeader(numberOfContours, bbox), 0);

  let pos = 10;
  for (const endPoint of endPoints) {
    view.setUint16(pos, endPoint);
    pos += 2;
  }
  view.setUint16(pos, instructions.length);
  pos += 2;
  bytes.set(instructions, pos);
  pos += instructions.length;
  bytes.set(flags, pos);
  pos += flags.length;
  bytes.set(xBytes, pos);
  pos += xBytes.length;
  bytes.set(yBytes, pos);

  return bytes;
}

// (0, 0), (100, 0), (100, -100), then (10, 10), (20, 20).
const TWO_CONTOUR_END_POINTS = [2, 4];
const TWO_CONTOUR_FLAGS = [
  ON_CURVE_POINT | X_IS_SAME_OR_POSITIVE_X_SHORT_VECTOR |
    Y_IS_SAME_OR_POSITIVE_Y_SHORT_VECTOR,
  ON_CURVE_POINT | X_SHORT_VECTOR | X_IS_SAME_OR_POSITIVE_X_SHORT_VECTOR |
    Y_IS_SAME_OR_POSITIVE_Y_SHORT_VECTOR,
  X_IS_SAME_OR_POSITIVE_X_SHORT_VECTOR | Y_SHORT_VECTOR,
  ON_CURVE_POINT | X_SHORT_VECTOR | Y_SHORT_VECTOR |
    Y_IS_SAME_OR_POSITIVE_Y_SHORT_VECTOR,
  OVERLAP_SIMPLE | X_SHORT_VECTOR | X_IS_SAME_OR_POSITIVE_X_SHORT_VECTOR |
    Y_SHORT_VECTOR | Y_IS_SAME_OR_POSITIVE_Y_SHORT_VECTOR,
];
const TWO_CONTOUR_X_BYTES = [100, 90, 10];
const TWO_CONTOUR_Y_BYTES = [100, 110, 10];

function makeTwoContourGlyph(instructions = []) {
  return makeSimpleGlyph({
    numberOfContours: 2,
    bbox: { xMin: 0, yMin: -100, xMax: 100, yMax: 20 },
    endPoints: TWO_CONTOUR_END_POINTS,
    instructions,
    flags: TWO_CONTOUR_FLAGS,
    xBytes: TWO_CONTOUR_X_BYTES,
    yBytes: TWO_CONTOUR_Y_BYTES,
  });
}

function makeRepeatedFlagGlyph(pointCount = 4) {
  // One flag byte, followed by a repeat count, describes `pointCount` points.
  return makeSimpleGlyph({
    numberOfContours: 1,
    endPoints: [pointCount - 1],
    flags: [
      ON_CURVE_POINT | X_IS_SAME_OR_POSITIVE_X_SHORT_VECTOR |
        Y_IS_SAME_OR_POSITIVE_Y_SHORT_VECTOR | REPEAT_FLAG,
      pointCount - 1,
    ],
  });
}

function makeCompositeRecord({
  flags,
  glyphIndex,
  argument1 = 0,
  argument2 = 0,
  transform = [],
  instructions = null,
}) {
  const useWords = (flags & ARG_1_AND_2_ARE_WORDS) !== 0;
  const length =
    4 +
    (useWords ? 4 : 2) +
    transform.length * 2 +
    (instructions === null ? 0 : 2 + instructions.length);
  const bytes = new Uint8Array(length);
  const view = viewOf(bytes);
  view.setUint16(0, flags);
  view.setUint16(2, glyphIndex);

  let pos = 4;
  if (useWords) {
    if (flags & ARGS_ARE_XY_VALUES) {
      view.setInt16(pos, argument1);
      view.setInt16(pos + 2, argument2);
    } else {
      view.setUint16(pos, argument1);
      view.setUint16(pos + 2, argument2);
    }
    pos += 4;
  } else if (flags & ARGS_ARE_XY_VALUES) {
    view.setInt8(pos++, argument1);
    view.setInt8(pos++, argument2);
  } else {
    view.setUint8(pos++, argument1);
    view.setUint8(pos++, argument2);
  }

  for (const value of transform) {
    view.setUint16(pos, value);
    pos += 2;
  }
  if (instructions !== null) {
    view.setUint16(pos, instructions.length);
    pos += 2;
    bytes.set(instructions, pos);
  }
  return bytes;
}

function makeCompositeGlyph(records, bbox = {}) {
  return concatBytes(
    makeGlyphHeader(-1, bbox),
    ...records.map(record => makeCompositeRecord(record))
  );
}

function makeLoca(offsets, isLong) {
  const bytes = new Uint8Array(offsets.length * (isLong ? 4 : 2));
  const view = viewOf(bytes);
  offsets.forEach((offset, index) => {
    if (isLong) {
      view.setUint32(index * 4, offset);
    } else {
      if (offset % 2 !== 0) {
        throw new Error(`Short loca requires an even offset, got ${offset}`);
      }
      view.setUint16(index * 2, offset >> 1);
    }
  });
  return bytes;
}

function readLoca(loca, isLong) {
  const view = viewOf(loca);
  const size = isLong ? 4 : 2;
  const result = [];
  for (let i = 0; i < loca.length; i += size) {
    result.push(isLong ? view.getUint32(i) : 2 * view.getUint16(i));
  }
  return result;
}

/**
 * Builds a GlyfTable from a list of glyph byte arrays. Passing an empty
 * Uint8Array models a missing/empty glyph. Each glyph is padded to a multiple
 * of four bytes, matching the input produced by real fonts.
 */
function makeTable(glyphs, { isLong = false } = {}) {
  const chunks = [];
  const offsets = [0];
  let offset = 0;
  for (const glyph of glyphs) {
    const paddedLength = (glyph.length + 3) & ~3;
    const padded = new Uint8Array(paddedLength);
    padded.set(glyph);
    chunks.push(padded);
    offset += paddedLength;
    offsets.push(offset);
  }
  const glyf = concatBytes(...chunks);
  const loca = makeLoca(offsets, isLong);
  return new GlyfTable({
    glyfTable: glyf,
    isGlyphLocationsLong: isLong,
    locaTable: loca,
    numGlyphs: glyphs.length,
  });
}

