      glyphIndex: 3,
      argument1: 5,
      argument2: -6,
      transform: [0x1234],
    }),
  ]);
}

/** Build a real GlyfTable, padding each stored glyph to `pad` bytes. */
function makeTable(glyphBytesList, { isLong = false, pad = 4 } = {}) {
  const chunks = [];
  const offsets = [];
  let pos = 0;
  for (const glyphBytes of glyphBytesList) {
    offsets.push(pos);
    chunks.push(glyphBytes);
    const paddedLength = pad ? (glyphBytes.length + pad - 1) & ~(pad - 1) : glyphBytes.length;
    const padding = paddedLength - glyphBytes.length;
    if (padding > 0) {
      chunks.push(new Uint8Array(padding));
    }
    pos += paddedLength;
  }
  offsets.push(pos);

  const glyfTable = concatBytes(...chunks);
  const entrySize = isLong ? 4 : 2;
  const locaData = new DataView(new ArrayBuffer((glyphBytesList.length + 1) * entrySize));
  offsets.forEach((offset, index) => {
    if (isLong) {
      locaData.setUint32(index * 4, offset);
    } else {
      expect(offset % 2).toBe(0);
      locaData.setUint16(index * 2, offset >> 1);
    }
  });
  const table = new GlyfTable({
    glyfTable,
    isGlyphLocationsLong: isLong,
    locaTable: new Uint8Array(locaData.buffer),
    numGlyphs: glyphBytesList.length,
  });
  return { table, offsets };
}

function parseWritten(result, numGlyphs) {
  return new GlyfTable({
    glyfTable: result.glyf,
    isGlyphLocationsLong: result.isLocationLong,
    locaTable: result.loca,
    numGlyphs,
  });
}

function writeUint32Loca(offsets) {
  const data = new DataView(new ArrayBuffer(offsets.length * 4));
  offsets.forEach((offset, index) => data.setUint32(index * 4, offset));
  return new Uint8Array(data.buffer);
}

