if (typeof Math.sumPrecise !== "function") {
  Math.sumPrecise = values => {
    let sum = 0;
    for (const value of values) {
      sum += value;
    }
    return sum;
  };
}
if (typeof Map.prototype.getOrInsertComputed !== "function") {
  Map.prototype.getOrInsertComputed = function (key, compute) {
    if (!this.has(key)) {
      this.set(key, compute(key));
    }
    return this.get(key);
  };
}

import { GlyfTable, pruneCompositeGlyphCycles } from "../../src/core/glyf.js";

const ON_CURVE_POINT = 1;
const X_SHORT_VECTOR = 1 << 1;
const Y_SHORT_VECTOR = 1 << 2;
const REPEAT_FLAG = 1 << 3;
const X_SAME_OR_POSITIVE = 1 << 4;
const Y_SAME_OR_POSITIVE = 1 << 5;
const OVERLAP_SIMPLE = 1 << 6;

const ARG_1_AND_2_ARE_WORDS = 1 << 0;
const ARGS_ARE_XY_VALUES = 1 << 1;
const WE_HAVE_A_SCALE = 1 << 3;
const MORE_COMPONENTS = 1 << 5;
const WE_HAVE_AN_X_AND_Y_SCALE = 1 << 6;
const WE_HAVE_A_TWO_BY_TWO = 1 << 7;
const WE_HAVE_INSTRUCTIONS = 1 << 8;

const GLYPH_HEADER_SIZE = 10;

function concatBytes(...chunks) {
  const length = chunks.reduce((total, chunk) => total + chunk.length, 0);
  const result = new Uint8Array(length);
  let pos = 0;
  for (const chunk of chunks) {
    result.set(chunk, pos);
    pos += chunk.length;
  }
  return result;
}

function header({
  numberOfContours,
  xMin = 0,
  yMin = 0,
  xMax = 0,
  yMax = 0,
}) {
  const bytes = new Uint8Array(GLYPH_HEADER_SIZE);
  const view = new DataView(bytes.buffer);
  view.setInt16(0, numberOfContours);
  view.setInt16(2, xMin);
  view.setInt16(4, yMin);
  view.setInt16(6, xMax);
  view.setInt16(8, yMax);
  return bytes;
}

/**
 * A two contour glyph.  Every coordinate encoding is used at least once:
 * same-as-previous, positive short, negative short and word deltas.
 */
function simpleGlyphBytes({ instructions = null } = {}) {
  const instructionBytes = instructions ? Uint8Array.from(instructions) : new Uint8Array(0);
  const bytes = new Uint8Array(27 + instructionBytes.length + (instructions ? 0 : 0));
  const view = new DataView(bytes.buffer);
  view.setInt16(0, 2);
  view.setInt16(2, 0);
  view.setInt16(4, -100);
  view.setInt16(6, 100);
  view.setInt16(8, 20);
  // End points of the two contours: (0,1,2) and (3,4).
  view.setUint16(10, 2);
  view.setUint16(12, 4);
  view.setUint16(14, instructionBytes.length);
  let pos = 16;
  if (instructionBytes.length) {
    bytes.set(instructionBytes, pos);
    pos += instructionBytes.length;
  }
  const flags = [
    ON_CURVE_POINT | X_SAME_OR_POSITIVE | Y_SAME_OR_POSITIVE, // (0, 0)
    ON_CURVE_POINT | X_SHORT_VECTOR | X_SAME_OR_POSITIVE | Y_SAME_OR_POSITIVE, // (100, 0)
    X_SAME_OR_POSITIVE | Y_SHORT_VECTOR, // (100, -100), off curve
    ON_CURVE_POINT | X_SHORT_VECTOR | Y_SHORT_VECTOR | Y_SAME_OR_POSITIVE, // (10, 10)
    OVERLAP_SIMPLE | X_SHORT_VECTOR | X_SAME_OR_POSITIVE | Y_SHORT_VECTOR | Y_SAME_OR_POSITIVE, // (20, 20)
  ];
  bytes.set(flags, pos);
  pos += flags.length;
  // x deltas: 100, -90, +10 (the other points reuse the previous x).
  bytes.set([100, 90, 10], pos);
  pos += 3;
  // y deltas: -100, +110, +10.
  bytes.set([100, 110, 10], pos);
  return bytes;
}

/** A single four point contour, encoded using the REPEAT_FLAG. */
function repeatedFlagGlyphBytes() {
  const bytes = new Uint8Array(16);
  const view = new DataView(bytes.buffer);
  view.setInt16(0, 1);
  view.setUint16(10, 3); // end point of the only contour
  view.setUint16(12, 0); // no instructions
  // ON_CURVE | X_SAME | Y_SAME, repeated three times (four points total).
  const flag = ON_CURVE_POINT | X_SAME_OR_POSITIVE | Y_SAME_OR_POSITIVE;
  bytes[14] = flag | REPEAT_FLAG;
  bytes[15] = 3;
  return bytes;
}

function componentBytes({
  flags,
  glyphIndex,
  argument1 = 0,
  argument2 = 0,
  transform = [],
  instructions = null,
}) {
  const argsAreWords = flags & ARG_1_AND_2_ARE_WORDS;
  const argsAreSigned = flags & ARGS_ARE_XY_VALUES;
  const argsSize = argsAreWords ? 4 : 2;
  const instructionsSize = instructions ? 2 + instructions.length : 0;
  const size = 4 + argsSize + transform.length * 2 + instructionsSize;
  const bytes = new Uint8Array(size);
  const view = new DataView(bytes.buffer);
  view.setUint16(0, flags);
  view.setUint16(2, glyphIndex);
  let pos = 4;
  if (argsAreWords) {
    if (argsAreSigned) {
      view.setInt16(pos, argument1);
      view.setInt16(pos + 2, argument2);
    } else {
      view.setUint16(pos, argument1);
      view.setUint16(pos + 2, argument2);
    }
    pos += 4;
  } else {
    bytes[pos++] = argument1 & 0xff;
    bytes[pos++] = argument2 & 0xff;
  }
  for (const value of transform) {
    view.setUint16(pos, value);
    pos += 2;
  }
  if (instructions) {
    view.setUint16(pos, instructions.length);
    pos += 2;
    bytes.set(instructions, pos);
  }
  return bytes;
}

function compositeGlyphBytes(components) {
  return concatBytes(header({ numberOfContours: -1, xMin: -10, yMin: -20, xMax: 30, yMax: 40 }), ...components);
}

/** Composite without transform records; safe to write back with this module. */
function plainCompositeGlyphBytes() {
  return compositeGlyphBytes([
    componentBytes({
      flags: ARGS_ARE_XY_VALUES | MORE_COMPONENTS,
      glyphIndex: 1,
      argument1: -5,
      argument2: 7,
    }),
    componentBytes({
      flags: ARGS_ARE_XY_VALUES | WE_HAVE_INSTRUCTIONS,
      glyphIndex: 2,
      argument1: -3,
      argument2: 4,
      instructions: [0x11, 0x22],
    }),
  ]);
}

/** Composite exercising all three transform records. */
function transformedCompositeGlyphBytes() {
  return compositeGlyphBytes([
    componentBytes({
      flags: ARGS_ARE_XY_VALUES | WE_HAVE_AN_X_AND_Y_SCALE | MORE_COMPONENTS,
      glyphIndex: 1,
      argument1: -1,
      argument2: 2,
      transform: [0x4000, 0x2000],
    }),
    componentBytes({
      flags: WE_HAVE_A_TWO_BY_TWO | MORE_COMPONENTS,
      glyphIndex: 2,
      argument1: 3,
      argument2: 4,
      transform: [1000, 2000, 3000, 4000],
    }),
    componentBytes({
      flags: ARGS_ARE_XY_VALUES | WE_HAVE_A_SCALE,
      glyphIndex: 3,
      argument1: 5,
      argument2: -6,
      transform: [0x1234],
    }),
  ]);
}

/** Build a real GlyfTable, padding each stored glyph to `pad` bytes. */
function makeTable(glyphBytesList, { isLong = false, pad = 4 } = {}) {
  const chunks = [];
  const offsets = [];
  let pos = 0;
  for (const glyphBytes of glyphBytesList) {
    offsets.push(pos);
    chunks.push(glyphBytes);
    const paddedLength = pad ? (glyphBytes.length + pad - 1) & ~(pad - 1) : glyphBytes.length;
    const padding = paddedLength - glyphBytes.length;
    if (padding > 0) {
      chunks.push(new Uint8Array(padding));
    }
    pos += paddedLength;
  }
  offsets.push(pos);

  const glyfTable = concatBytes(...chunks);
  const entrySize = isLong ? 4 : 2;
  const locaData = new DataView(new ArrayBuffer((glyphBytesList.length + 1) * entrySize));
  offsets.forEach((offset, index) => {
    if (isLong) {
      locaData.setUint32(index * 4, offset);
    } else {
      expect(offset % 2).toBe(0);
      locaData.setUint16(index * 2, offset >> 1);
    }
  });
  const table = new GlyfTable({
    glyfTable,
    isGlyphLocationsLong: isLong,
    locaTable: new Uint8Array(locaData.buffer),
    numGlyphs: glyphBytesList.length,
  });
  return { table, offsets };
}

function parseWritten(result, numGlyphs) {
  return new GlyfTable({
    glyfTable: result.glyf,
    isGlyphLocationsLong: result.isLocationLong,
    locaTable: result.loca,
    numGlyphs,
  });
}

function writeUint32Loca(offsets) {
  const data = new DataView(new ArrayBuffer(offsets.length * 4));
  offsets.forEach((offset, index) => data.setUint32(index * 4, offset));
  return new Uint8Array(data.buffer);
}

describe("GlyfTable parsing", () => {
  test("parses a simple glyph header, contours, coordinates and boundary flags", () => {
    const { table } = makeTable([simpleGlyphBytes()]);
    expect(table.glyphs).toHaveLength(1);

    const glyph = table.glyphs[0];
    expect(glyph.header).toMatchObject({
      numberOfContours: 2,
      xMin: 0,
      yMin: -100,
      xMax: 100,
      yMax: 20,
    });
    expect(glyph.simple.contours).toHaveLength(2);
    expect(glyph.composites).toBeNull();

    expect(glyph.simple.contours[0]).toMatchObject({
      xCoordinates: [0, 100, 100],
      yCoordinates: [0, 0, -100],
      flags: [ON_CURVE_POINT, ON_CURVE_POINT, 0],
    });
    expect(glyph.simple.contours[1]).toMatchObject({
      xCoordinates: [10, 20],
      yCoordinates: [10, 20],
      flags: [ON_CURVE_POINT, OVERLAP_SIMPLE],
    });
  });

  test("honours the instruction length while locating the point data", () => {
    const { table } = makeTable([
      simpleGlyphBytes({ instructions: [0xde, 0xad, 0xbe, 0xef] }),
    ]);
    const glyph = table.glyphs[0];
    expect(glyph.simple.contours[0].xCoordinates).toEqual([0, 100, 100]);
    expect(glyph.simple.contours[1].xCoordinates).toEqual([10, 20]);
    expect(glyph.simple.contours[1].yCoordinates).toEqual([10, 20]);
  });

  test("expands repeated point flags into one flag per point", () => {
    const { table } = makeTable([repeatedFlagGlyphBytes()]);
    const contour = table.glyphs[0].simple.contours[0];
    expect(contour.flags).toHaveLength(4);
    expect(contour.flags).toEqual([ON_CURVE_POINT, ON_CURVE_POINT, ON_CURVE_POINT, ON_CURVE_POINT]);
    expect(contour.xCoordinates).toEqual([0, 0, 0, 0]);
    expect(contour.yCoordinates).toEqual([0, 0, 0, 0]);
  });

  test("parses empty glyph entries as header-less glyphs", () => {
    const { table } = makeTable([new Uint8Array(0), simpleGlyphBytes()]);
    expect(table.glyphs).toHaveLength(2);
    expect(table.glyphs[0].header).toBeNull();
    expect(table.glyphs[0].simple).toBeNull();
    expect(table.glyphs[0].composites).toBeNull();
    expect(table.glyphs[0].getSize()).toBe(0);
    expect(table.glyphs[1].header.numberOfContours).toBe(2);
  });

  test("parses a composite glyph with signed short arguments and instructions", () => {
    const { table } = makeTable([plainCompositeGlyphBytes()]);
    const glyph = table.glyphs[0];
    expect(glyph.header.numberOfContours).toBe(-1);
    expect(glyph.simple).toBeNull();
    expect(glyph.composites).toHaveLength(2);

    expect(glyph.composites[0]).toMatchObject({
      flags: ARGS_ARE_XY_VALUES | MORE_COMPONENTS,
      glyphIndex: 1,
      argument1: -5,
      argument2: 7,
      transf: [],
      instructions: null,
    });
    expect(glyph.composites[1]).toMatchObject({
      flags: ARGS_ARE_XY_VALUES | WE_HAVE_INSTRUCTIONS,
      glyphIndex: 2,
      argument1: -3,
      argument2: 4,
      transf: [],
    });
    // Composite hint instructions are not retained by the parser.
    expect(glyph.composites[1].instructions).toHaveLength(0);
    expect(glyph.getSize()).toBe(24);
  });

  test("parses all composite transform variants and includes them in the size", () => {
    const { table } = makeTable([transformedCompositeGlyphBytes()]);
    const glyph = table.glyphs[0];
    expect(glyph.composites.map(c => c.glyphIndex)).toEqual([1, 2, 3]);
    expect(glyph.composites.map(c => c.transf)).toEqual([
      [0x4000, 0x2000],
      [1000, 2000, 3000, 4000],
      [0x1234],
    ]);
    expect(glyph.composites.map(c => [c.argument1, c.argument2])).toEqual([
      [-1, 2],
      [3, 4],
      [5, -6],
    ]);
    expect(glyph.getSize()).toBe(42);
  });

  test("reads long loca offsets beyond the 16 bit range", () => {
    const glyph = plainCompositeGlyphBytes();
    const glyfTable = new Uint8Array(0x10000 + glyph.length);
    glyfTable.set(glyph, 0x10000);
    const offsets = [0x10000, 0x10000 + glyph.length];
    const table = new GlyfTable({
      glyfTable,
      isGlyphLocationsLong: true,
      locaTable: writeUint32Loca(offsets),
      numGlyphs: 1,
    });
    expect(table.glyphs[0].header.numberOfContours).toBe(-1);
    expect(table.glyphs[0].composites.map(c => c.glyphIndex)).toEqual([1, 2]);
  });
});

describe("Glyph sizing and writing", () => {
  test("reports the exact and table-rounded sizes for a simple glyph", () => {
    const { table } = makeTable([simpleGlyphBytes()]);
    expect(table.glyphs[0].getSize()).toBe(27);
    expect(table.getSize()).toBe(28); // rounded up to a multiple of four
  });

  test("writes a simple glyph back into a compact glyf/loca pair", () => {
    const { table } = makeTable([simpleGlyphBytes()]);
    const result = table.write();
    expect(result.isLocationLong).toBe(false);
    expect(result.glyf).toHaveLength(28);
    expect([...result.loca]).toEqual([0, 0, 0, 14]); // offsets: 0, 28

    const reparsed = parseWritten(result, 1);
    const glyph = reparsed.glyphs[0];
    expect(glyph.header).toMatchObject({ xMin: 0, yMin: -100, xMax: 100, yMax: 20 });
    expect(glyph.simple.contours.map(c => c.xCoordinates)).toEqual([
      [0, 100, 100],
      [10, 20],
    ]);
    expect(glyph.simple.contours.map(c => c.yCoordinates)).toEqual([
      [0, 0, -100],
      [10, 20],
    ]);
    expect(glyph.simple.contours.map(c => c.flags)).toEqual([
      [1, 1, 0],
      [1, OVERLAP_SIMPLE],
    ]);
  });

  test("writes a repeated-flag glyph without losing points", () => {
    const { table } = makeTable([repeatedFlagGlyphBytes()]);
    expect(table.glyphs[0].getSize()).toBe(18);
    expect(table.getSize()).toBe(20);

    const result = table.write();
    expect(result.glyf).toHaveLength(20);
    expect([...result.loca]).toEqual([0, 0, 0, 10]);

    const glyph = parseWritten(result, 1).glyphs[0];
    expect(glyph.simple.contours[0].flags).toEqual([1, 1, 1, 1]);
    expect(glyph.simple.contours[0].xCoordinates).toEqual([0, 0, 0, 0]);
    expect(glyph.simple.contours[0].yCoordinates).toEqual([0, 0, 0, 0]);
  });

  test("preserves empty glyph entries when writing a mixed table", () => {
    const { table } = makeTable([
      simpleGlyphBytes(),
      new Uint8Array(0),
      plainCompositeGlyphBytes(),
    ]);
    expect(table.glyphs.map(g => g.getSize())).toEqual([27, 0, 24]);
    expect(table.getSize()).toBe(52);

    const result = table.write();
    expect(result.isLocationLong).toBe(false);
    expect(result.glyf).toHaveLength(52);
    expect([...result.loca]).toEqual([0, 0, 0, 14, 0, 14, 0, 26]);

    const reparsed = parseWritten(result, 3);
    expect(reparsed.glyphs).toHaveLength(3);
    expect(reparsed.glyphs[0].simple.contours[0].xCoordinates).toEqual([0, 100, 100]);
    expect(reparsed.glyphs[1].header).toBeNull();
    expect(reparsed.glyphs[1].getSize()).toBe(0);
    expect(reparsed.glyphs[2].composites.map(c => c.glyphIndex)).toEqual([1, 2]);
  });

  test("writes a plain composite glyph and round-trips its arguments", () => {
    const { table } = makeTable([plainCompositeGlyphBytes()]);
    const result = table.write();
    expect(result.glyf).toHaveLength(24);
    expect([...result.loca]).toEqual([0, 0, 0, 12]);

    const composites = parseWritten(result, 1).glyphs[0].composites;
    expect(composites.map(c => c.glyphIndex)).toEqual([1, 2]);
    expect(composites.map(c => [c.argument1, c.argument2])).toEqual([
      [-5, 7],
      [-3, 4],
    ]);
    expect(composites.map(c => c.flags)).toEqual([
      ARGS_ARE_XY_VALUES | MORE_COMPONENTS,
      ARGS_ARE_XY_VALUES | WE_HAVE_INSTRUCTIONS,
    ]);
  });

  test.each([
    ["signed bytes that fit", ARGS_ARE_XY_VALUES, -128, 127, 18],
    ["signed bytes that overflow", ARGS_ARE_XY_VALUES, -129, 127, 20],
    ["unsigned bytes that fit", 0, 200, 255, 18],
    ["unsigned bytes that overflow", 0, 256, 100, 20],
    ["word arguments read as signed", ARG_1_AND_2_ARE_WORDS | ARGS_ARE_XY_VALUES, -200, 300, 18],
    ["word arguments read as unsigned", ARG_1_AND_2_ARE_WORDS, 300, 400, 18],
  ])("chooses the right argument width for %s", (_name, flags, arg1, arg2, expectedSize) => {
    const glyphBytes = compositeGlyphBytes([
      componentBytes({ flags, glyphIndex: 7, argument1: arg1, argument2: arg2 }),
    ]);
    const { table } = makeTable([glyphBytes]);
    expect(table.glyphs[0].getSize()).toBe(expectedSize);

    const result = table.write();
    const reparsed = parseWritten(result, 1).glyphs[0];
    expect(reparsed.composites).toHaveLength(1);
    expect(reparsed.composites[0].glyphIndex).toBe(7);
    expect(reparsed.composites[0].argument1).toBe(arg1);
    expect(reparsed.composites[0].argument2).toBe(arg2);
    // The internal flag is normalized and re-derived when writing.
    expect(reparsed.composites[0].flags & ARG_1_AND_2_ARE_WORDS).toBe(0);
  });

  test("writes short loca entries for a large but still short glyph", () => {
    const { table } = makeTable([bigGlyphBytes(65536)], { pad: 2 });
    expect(table.glyphs[0].getSize()).toBe(65550);
    const result = table.write();
    expect(result.isLocationLong).toBe(false);
    expect(result.glyf).toHaveLength(65552);
    expect(result.loca).toHaveLength(4);
    const loca = new DataView(result.loca.buffer, result.loca.byteOffset, result.loca.byteLength);
    expect(loca.getUint16(0)).toBe(0);
    expect(loca.getUint16(2)).toBe(65552 >> 1);
    expect(parseWritten(result, 1).glyphs[0].simple.contours[0].flags).toHaveLength(65536);
  });

  test("switches to long loca entries when the glyf table is larger than 0x1fffe", () => {
    const glyph = bigGlyphBytes(65536);
    const { table } = makeTable([glyph, glyph, glyph], { isLong: true });
    expect(table.getSize()).toBe(196656);

    const result = table.write();
    expect(result.isLocationLong).toBe(true);
    expect(result.glyf).toHaveLength(196656);
    expect(result.loca).toHaveLength(16);
    const loca = new DataView(result.loca.buffer, result.loca.byteOffset, result.loca.byteLength);
    expect([0, 1, 2, 3].map(i => loca.getUint32(i * 4))).toEqual([
      0, 65552, 131104, 196656,
    ]);
    expect(parseWritten(result, 3).glyphs.map(g => g.simple.contours[0].flags.length)).toEqual([
      65536, 65536, 65536,
    ]);
  });
});

describe("Glyph scaling", () => {
  test("scales simple glyph x coordinates and horizontal bounds around the x middle", () => {
    const { table } = makeTable([simpleGlyphBytes()]);
    table.scale([0.5]);
    const glyph = table.glyphs[0];
    expect(glyph.header).toMatchObject({ xMin: 25, xMax: 75, yMin: -100, yMax: 20 });
    expect(glyph.simple.contours[0].xCoordinates).toEqual([25, 75, 75]);
    expect(glyph.simple.contours[1].xCoordinates).toEqual([30, 35]);
    // Vertical coordinates are deliberately left untouched.
    expect(glyph.simple.contours[0].yCoordinates).toEqual([0, 0, -100]);
    expect(glyph.simple.contours[1].yCoordinates).toEqual([10, 20]);
  });

  test("rounds scaled coordinates and applies one factor per glyph", () => {
    const { table } = makeTable([simpleGlyphBytes(), new Uint8Array(0)]);
    table.scale([3, 2]);
    const glyph = table.glyphs[0];
    expect(glyph.header).toMatchObject({ xMin: -100, xMax: 200 });
    expect(glyph.simple.contours[0].xCoordinates).toEqual([-100, 200, 200]);
    expect(glyph.simple.contours[1].xCoordinates).toEqual([-70, -40]);
    expect(table.glyphs[1].header).toBeNull();
  });

  test("scales a composite header without changing component records", () => {
    const { table } = makeTable([plainCompositeGlyphBytes()]);
    const before = table.glyphs[0].composites.map(c => ({
      glyphIndex: c.glyphIndex,
      argument1: c.argument1,
      argument2: c.argument2,
      transf: [...c.transf],
    }));
    table.scale([2]);
    const glyph = table.glyphs[0];
    expect(glyph.header).toMatchObject({ xMin: -30, xMax: 50, yMin: -20, yMax: 40 });
    expect(glyph.composites.map(c => ({
      glyphIndex: c.glyphIndex,
      argument1: c.argument1,
      argument2: c.argument2,
      transf: [...c.transf],
    }))).toEqual(before);
  });
});

function bigGlyphBytes(points) {
  const flags = [];
  let remaining = points;
  while (remaining > 0) {
    const count = Math.min(remaining, 256);
    if (count === 1) {
      flags.push(ON_CURVE_POINT | X_SAME_OR_POSITIVE | Y_SAME_OR_POSITIVE);
    } else {
      flags.push(
        ON_CURVE_POINT | X_SAME_OR_POSITIVE | Y_SAME_OR_POSITIVE | REPEAT_FLAG,
        count - 1
      );
    }
    remaining -= count;
  }
  const bytes = new Uint8Array(14 + flags.length);
  const view = new DataView(bytes.buffer);
  view.setInt16(0, 1);
  view.setUint16(10, points - 1);
  view.setUint16(12, 0);
  bytes.set(flags, 14);
  return bytes;
}

function pruneFixture(glyphBytesList) {
  const offsets = [];
  let pos = 0;
  for (const glyphBytes of glyphBytesList) {
    offsets.push(pos);
    pos += glyphBytes.length;
  }
  offsets.push(pos);
  const glyfTable = concatBytes(...glyphBytesList);
  const locaEntries = glyphBytesList.map((_, index) => ({
    offset: offsets[index],
    endOffset: offsets[index + 1],
  }));
  return { glyfTable, offsets, locaEntries };
}

function parsePrunedTable(glyfTable, offsets, numGlyphs) {
  return new GlyfTable({
    glyfTable,
    isGlyphLocationsLong: true,
    locaTable: writeUint32Loca(offsets),
    numGlyphs,
  });
}

describe("pruneCompositeGlyphCycles", () => {
  test("drops a glyph whose only component is itself", () => {
    const selfCycle = compositeGlyphBytes([
      componentBytes({ flags: 0, glyphIndex: 0 }),
    ]);
    const { glyfTable, locaEntries } = pruneFixture([selfCycle]);
    const original = glyfTable.slice();
    const dropped = pruneCompositeGlyphCycles(glyfTable, locaEntries, 1);
    expect([...dropped]).toEqual([0]);
    // A dropped glyph is not rewritten; the caller omits it via loca.
    expect(glyfTable).toEqual(original);
  });

  test("reports the closing glyph of a multi-glyph cycle", () => {
    const glyph0 = compositeGlyphBytes([
      componentBytes({ flags: MORE_COMPONENTS, glyphIndex: 1 }),
    ]);
    const glyph1 = compositeGlyphBytes([
      componentBytes({ flags: MORE_COMPONENTS, glyphIndex: 2 }),
    ]);
    const glyph2 = compositeGlyphBytes([
      componentBytes({ flags: 0, glyphIndex: 0 }),
    ]);
    const { glyfTable, locaEntries } = pruneFixture([glyph0, glyph1, glyph2]);
    const dropped = pruneCompositeGlyphCycles(glyfTable, locaEntries, 3);
    expect([...dropped]).toEqual([2]);
  });

  test("leaves an acyclic composite graph untouched", () => {
    const glyph0 = compositeGlyphBytes([
      componentBytes({ flags: MORE_COMPONENTS, glyphIndex: 1 }),
    ]);
    const glyph1 = compositeGlyphBytes([
      componentBytes({ flags: 0, glyphIndex: 2 }),
    ]);
    const glyph2 = concatBytes(header({ numberOfContours: 1 }), new Uint8Array(6));
