import { GlyfTable, pruneCompositeGlyphCycles } from "../../src/core/glyf.js";

const ON_CURVE_POINT = 1;
const X_SHORT_VECTOR = 1 << 1;
const Y_SHORT_VECTOR = 1 << 2;
const REPEAT_FLAG = 1 << 3;
const X_SAME_OR_POSITIVE = 1 << 4;
const Y_SAME_OR_POSITIVE = 1 << 5;
const OVERLAP_SIMPLE = 1 << 6;

const ARG_1_AND_2_ARE_WORDS = 1 << 0;
const ARGS_ARE_XY_VALUES = 1 << 1;
const WE_HAVE_A_SCALE = 1 << 3;
const MORE_COMPONENTS = 1 << 5;
const WE_HAVE_AN_X_AND_Y_SCALE = 1 << 6;
const WE_HAVE_A_TWO_BY_TWO = 1 << 7;
const WE_HAVE_INSTRUCTIONS = 1 << 8;

const GLYPH_HEADER_SIZE = 10;

function concatBytes(...chunks) {
  const length = chunks.reduce((total, chunk) => total + chunk.length, 0);
  const result = new Uint8Array(length);
  let pos = 0;
  for (const chunk of chunks) {
    result.set(chunk, pos);
    pos += chunk.length;
  }
  return result;
}

function header({
  numberOfContours,
  xMin = 0,
  yMin = 0,
  xMax = 0,
  yMax = 0,
}) {
  const bytes = new Uint8Array(GLYPH_HEADER_SIZE);
  const view = new DataView(bytes.buffer);
  view.setInt16(0, numberOfContours);
  view.setInt16(2, xMin);
  view.setInt16(4, yMin);
  view.setInt16(6, xMax);
  view.setInt16(8, yMax);
  return bytes;
}

/**
 * A two contour glyph.  Every coordinate encoding is used at least once:
 * same-as-previous, positive short, negative short and word deltas.
 */
function simpleGlyphBytes({ instructions = null } = {}) {
  const instructionBytes = instructions ? Uint8Array.from(instructions) : new Uint8Array(0);
  const bytes = new Uint8Array(27 + instructionBytes.length + (instructions ? 0 : 0));
  const view = new DataView(bytes.buffer);
  view.setInt16(0, 2);
  view.setInt16(2, 0);
  view.setInt16(4, -100);
  view.setInt16(6, 100);
  view.setInt16(8, 20);
  // End points of the two contours: (0,1,2) and (3,4).
  view.setUint16(10, 2);
  view.setUint16(12, 4);
  view.setUint16(14, instructionBytes.length);
  let pos = 16;
  if (instructionBytes.length) {
    bytes.set(instructionBytes, pos);
    pos += instructionBytes.length;
  }
  const flags = [
    ON_CURVE_POINT | X_SAME_OR_POSITIVE | Y_SAME_OR_POSITIVE, // (0, 0)
    ON_CURVE_POINT | X_SHORT_VECTOR | X_SAME_OR_POSITIVE | Y_SAME_OR_POSITIVE, // (100, 0)
    X_SAME_OR_POSITIVE | Y_SHORT_VECTOR, // (100, -100), off curve
    ON_CURVE_POINT | X_SHORT_VECTOR | Y_SHORT_VECTOR | Y_SAME_OR_POSITIVE, // (10, 10)
    OVERLAP_SIMPLE | X_SHORT_VECTOR | X_SAME_OR_POSITIVE | Y_SHORT_VECTOR | Y_SAME_OR_POSITIVE, // (20, 20)
  ];
  bytes.set(flags, pos);
  pos += flags.length;
  // x deltas: 100, -90, +10 (the other points reuse the previous x).
  bytes.set([100, 90, 10], pos);
  pos += 3;
  // y deltas: -100, +110, +10.
  bytes.set([100, 110, 10], pos);
  return bytes;
}

/** A single four point contour, encoded using the REPEAT_FLAG. */
function repeatedFlagGlyphBytes() {
  const bytes = new Uint8Array(16);
  const view = new DataView(bytes.buffer);
  view.setInt16(0, 1);
  view.setUint16(10, 3); // end point of the only contour
  view.setUint16(12, 0); // no instructions
  // ON_CURVE | X_SAME | Y_SAME, repeated three times (four points total).
  const flag = ON_CURVE_POINT | X_SAME_OR_POSITIVE | Y_SAME_OR_POSITIVE;
  bytes[14] = flag | REPEAT_FLAG;
  bytes[15] = 3;
  return bytes;
}

function componentBytes({
  flags,
  glyphIndex,
  argument1 = 0,
  argument2 = 0,
  transform = [],
  instructions = null,
}) {
  const argsAreWords = flags & ARG_1_AND_2_ARE_WORDS;
  const argsAreSigned = flags & ARGS_ARE_XY_VALUES;
  const argsSize = argsAreWords ? 4 : 2;
  const instructionsSize = instructions ? 2 + instructions.length : 0;
  const size = 4 + argsSize + transform.length * 2 + instructionsSize;
  const bytes = new Uint8Array(size);
  const view = new DataView(bytes.buffer);
  view.setUint16(0, flags);
  view.setUint16(2, glyphIndex);
  let pos = 4;
  if (argsAreWords) {
    if (argsAreSigned) {
      view.setInt16(pos, argument1);
      view.setInt16(pos + 2, argument2);
    } else {
      view.setUint16(pos, argument1);
      view.setUint16(pos + 2, argument2);
    }
    pos += 4;
  } else {
    bytes[pos++] = argument1 & 0xff;
    bytes[pos++] = argument2 & 0xff;
  }
  for (const value of transform) {
    view.setUint16(pos, value);
    pos += 2;
  }
  if (instructions) {
    view.setUint16(pos, instructions.length);
    pos += 2;
    bytes.set(instructions, pos);
  }
  return bytes;
}

function compositeGlyphBytes(components) {
  return concatBytes(header({ numberOfContours: -1, xMin: -10, yMin: -20, xMax: 30, yMax: 40 }), ...components);
}

/** Composite without transform records; safe to write back with this module. */
function plainCompositeGlyphBytes() {
  return compositeGlyphBytes([
    componentBytes({
      flags: ARGS_ARE_XY_VALUES | MORE_COMPONENTS,
      glyphIndex: 1,
      argument1: -5,
      argument2: 7,
    }),
    componentBytes({
      flags: ARGS_ARE_XY_VALUES | WE_HAVE_INSTRUCTIONS,
      glyphIndex: 2,
      argument1: -3,
      argument2: 4,
      instructions: [0x11, 0x22],
    }),
  ]);
}

/** Composite exercising all three transform records. */
function transformedCompositeGlyphBytes() {
  return compositeGlyphBytes([
    componentBytes({
      flags: ARGS_ARE_XY_VALUES | WE_HAVE_AN_X_AND_Y_SCALE | MORE_COMPONENTS,
      glyphIndex: 1,
      argument1: -1,
      argument2: 2,
      transform: [0x4000, 0x2000],
    }),
    componentBytes({
      flags: WE_HAVE_A_TWO_BY_TWO | MORE_COMPONENTS,
      glyphIndex: 2,
      argument1: 3,
      argument2: 4,
      transform: [1000, 2000, 3000, 4000],
    }),
    componentBytes({
      flags: ARGS_ARE_XY_VALUES | WE_HAVE_A_SCALE,
      glyphIndex: 3,
      argument1: 5,
      argument2: -6,
      transform: [0x1234],
    }),
  ]);
