function bigGlyphBytes(points) {
  const flags = [];
  let remaining = points;
  while (remaining > 0) {
    const count = Math.min(remaining, 256);
    if (count === 1) {
      flags.push(ON_CURVE_POINT | X_SAME_OR_POSITIVE | Y_SAME_OR_POSITIVE);
    } else {
      flags.push(
        ON_CURVE_POINT | X_SAME_OR_POSITIVE | Y_SAME_OR_POSITIVE | REPEAT_FLAG,
        count - 1
      );
    }
    remaining -= count;
  }
  const bytes = new Uint8Array(14 + flags.length);
  const view = new DataView(bytes.buffer);
  view.setInt16(0, 1);
  view.setUint16(10, points - 1);
  view.setUint16(12, 0);
  bytes.set(flags, 14);
  return bytes;
}

function pruneFixture(glyphBytesList) {
  const offsets = [];
  let pos = 0;
  for (const glyphBytes of glyphBytesList) {
    offsets.push(pos);
    pos += glyphBytes.length;
  }
  offsets.push(pos);
  const glyfTable = concatBytes(...glyphBytesList);
  const locaEntries = glyphBytesList.map((_, index) => ({
    offset: offsets[index],
    endOffset: offsets[index + 1],
  }));
  return { glyfTable, offsets, locaEntries };
}

function parsePrunedTable(glyfTable, offsets, numGlyphs) {
  return new GlyfTable({
    glyfTable,
    isGlyphLocationsLong: true,
    locaTable: writeUint32Loca(offsets),
    numGlyphs,
  });
}

describe("pruneCompositeGlyphCycles", () => {
  test("drops a glyph whose only component is itself", () => {
    const selfCycle = compositeGlyphBytes([
      componentBytes({ flags: 0, glyphIndex: 0 }),
    ]);
    const { glyfTable, locaEntries } = pruneFixture([selfCycle]);
    const original = glyfTable.slice();
    const dropped = pruneCompositeGlyphCycles(glyfTable, locaEntries, 1);
    expect([...dropped]).toEqual([0]);
    // A dropped glyph is not rewritten; the caller omits it via loca.
    expect(glyfTable).toEqual(original);
  });

  test("reports the closing glyph of a multi-glyph cycle", () => {
    const glyph0 = compositeGlyphBytes([
      componentBytes({ flags: MORE_COMPONENTS, glyphIndex: 1 }),
    ]);
    const glyph1 = compositeGlyphBytes([
      componentBytes({ flags: MORE_COMPONENTS, glyphIndex: 2 }),
    ]);
    const glyph2 = compositeGlyphBytes([
      componentBytes({ flags: 0, glyphIndex: 0 }),
    ]);
    const { glyfTable, locaEntries } = pruneFixture([glyph0, glyph1, glyph2]);
    const dropped = pruneCompositeGlyphCycles(glyfTable, locaEntries, 3);
    expect([...dropped]).toEqual([2]);
  });

  test("leaves an acyclic composite graph untouched", () => {
    const glyph0 = compositeGlyphBytes([
      componentBytes({ flags: MORE_COMPONENTS, glyphIndex: 1 }),
    ]);
    const glyph1 = compositeGlyphBytes([
      componentBytes({ flags: 0, glyphIndex: 2 }),
    ]);
    const glyph2 = concatBytes(header({ numberOfContours: 1 }), new Uint8Array(6));
    const { glyfTable, locaEntries, offsets } = pruneFixture([glyph0, glyph1, glyph2]);
    const original = glyfTable.slice();
    const dropped = pruneCompositeGlyphCycles(glyfTable, locaEntries, 3);
    expect(dropped.size).toBe(0);
    expect(glyfTable).toEqual(original);
    expect(parsePrunedTable(glyfTable, offsets, 3).glyphs[2].header.numberOfContours).toBe(1);
  });

  test("removes a cyclic component, compacts the rest and clears trailing bytes", () => {
    const componentA = componentBytes({
      flags: MORE_COMPONENTS,
      glyphIndex: 1,
      argument1: 1,
      argument2: 2,
    });
    const componentB = componentBytes({
      flags: MORE_COMPONENTS,
      glyphIndex: 0,
      argument1: 3,
      argument2: 4,
    });
    const componentC = componentBytes({
      flags: WE_HAVE_INSTRUCTIONS,
      glyphIndex: 2,
      argument1: 5,
      argument2: 6,
      instructions: [0xab, 0xcd],
    });
    const { glyfTable, locaEntries, offsets } = pruneFixture([
      compositeGlyphBytes([componentA, componentB, componentC]),
    ]);
    const originalC = glyfTable.slice(22, 32);

    const dropped = pruneCompositeGlyphCycles(glyfTable, locaEntries, 1);
    expect(dropped.size).toBe(0);

    const view = new DataView(glyfTable.buffer, glyfTable.byteOffset, glyfTable.byteLength);
    // First remaining component keeps its MORE_COMPONENTS flag.
    expect(view.getUint16(10)).toBe(MORE_COMPONENTS);
    expect(view.getUint16(12)).toBe(1);
    // Second (now last) component has the cycle removed and instructions stripped.
    expect(view.getUint16(16)).toBe(0);
    expect(view.getUint16(18)).toBe(2);
    expect([...glyfTable.slice(18, 26)]).toEqual([...originalC.slice(2)]);
    expect([...glyfTable.slice(26, 32)]).toEqual([0, 0, 0, 0, 0, 0]);

    const composites = parsePrunedTable(glyfTable, offsets, 1).glyphs[0].composites;
    expect(composites.map(c => c.glyphIndex)).toEqual([1, 2]);
    expect(composites.map(c => c.flags)).toEqual([MORE_COMPONENTS, 0]);
    expect(composites.map(c => [c.argument1, c.argument2])).toEqual([
      [1, 2],
      [5, 6],
    ]);
  });

  test("clears MORE_COMPONENTS when the removed edge was the last component", () => {
    const componentA = componentBytes({
      flags: MORE_COMPONENTS,
      glyphIndex: 1,
      argument1: 1,
      argument2: 2,
    });
    const componentB = componentBytes({ flags: 0, glyphIndex: 0 });
    const { glyfTable, locaEntries, offsets } = pruneFixture([
      compositeGlyphBytes([componentA, componentB]),
    ]);

    expect(pruneCompositeGlyphCycles(glyfTable, locaEntries, 1).size).toBe(0);
    const view = new DataView(glyfTable.buffer, glyfTable.byteOffset, glyfTable.byteLength);
    expect(view.getUint16(10)).toBe(0); // MORE_COMPONENTS cleared
    expect(view.getUint16(12)).toBe(1);
    expect([...glyfTable.slice(16)]).toEqual([0, 0, 0, 0, 0, 0]);

    const composites = parsePrunedTable(glyfTable, offsets, 1).glyphs[0].composites;
    expect(composites).toHaveLength(1);
    expect(composites[0]).toMatchObject({ flags: 0, glyphIndex: 1, argument1: 1, argument2: 2 });
  });

  test("accounts for transform records while scanning components", () => {
    const componentA = componentBytes({
      flags: ARGS_ARE_XY_VALUES | WE_HAVE_A_SCALE | MORE_COMPONENTS,
      glyphIndex: 1,
      argument1: 1,
      argument2: 2,
      transform: [0x4000],
    });
    const componentB = componentBytes({ flags: 0, glyphIndex: 0, argument1: 3, argument2: 4 });
    const { glyfTable, locaEntries, offsets } = pruneFixture([
      compositeGlyphBytes([componentA, componentB]),
    ]);

    expect(pruneCompositeGlyphCycles(glyfTable, locaEntries, 1).size).toBe(0);
    const composites = parsePrunedTable(glyfTable, offsets, 1).glyphs[0].composites;
    expect(composites).toHaveLength(1);
    expect(composites[0]).toMatchObject({
      flags: ARGS_ARE_XY_VALUES | WE_HAVE_A_SCALE,
      glyphIndex: 1,
      argument1: 1,
      argument2: 2,
    });
    expect(composites[0].transf).toEqual([0x4000]);
  });

  test("drops several independent self-referencing glyphs and skips non-composites", () => {
    const self0 = compositeGlyphBytes([componentBytes({ flags: 0, glyphIndex: 0 })]);
    const self1 = compositeGlyphBytes([componentBytes({ flags: 0, glyphIndex: 1 })]);
    const simple = header({ numberOfContours: 1 });
    const { glyfTable, locaEntries } = pruneFixture([self0, self1, simple]);
    const dropped = pruneCompositeGlyphCycles(glyfTable, locaEntries, 3);
    expect([...dropped].sort((a, b) => a - b)).toEqual([0, 1]);
  });

  test("ignores component glyph ids outside the numGlyphs range", () => {
    const glyph0 = compositeGlyphBytes([
      componentBytes({ flags: MORE_COMPONENTS, glyphIndex: 99 }),
    ]);
    const glyph1 = compositeGlyphBytes([
      componentBytes({ flags: 0, glyphIndex: 42 }),
    ]);
    const { glyfTable, locaEntries } = pruneFixture([glyph0, glyph1]);
    const original = glyfTable.slice();
    const dropped = pruneCompositeGlyphCycles(glyfTable, locaEntries, 2);
    expect(dropped.size).toBe(0);
    expect(glyfTable).toEqual(original);
  });
});
