// The fixtures are embedded as base64 so that the tests stay self-contained and
// deterministic. They are tiny (8x8 pixels) JPEG images generated with a
// standard baseline/progressive encoder.
const GRAY_JPEG =
  "/9j/4AAQSkZJRgABAQAAAQABAAD/2wBDAAMCAgICAgMCAgIDAwMDBAYEBAQEBAgGBgUGCQgKCgkICQkKDA8MCgsOCwkJDRENDg8QEBEQCgwSExIQEw8QEBD/wAALCAAIAAgBAREA/8QAFAABAAAAAAAAAAAAAAAAAAAAAv/EABkQAAEFAAAAAAAAAAAAAAAAAAABGVaj4f/aAAgBAQAAPwAtZrHasP/Z";
const RGB_JPEG =
  "";
const CMYK_JPEG =
  "";
const PROGRESSIVE_JPEG =
  "";

const decodeBase64 = base64 => new Uint8Array(Buffer.from(base64, "base64"));

const grayJpeg = () => decodeBase64(GRAY_JPEG);
const rgbJpeg = () => decodeBase64(RGB_JPEG);
const cmykJpeg = () => decodeBase64(CMYK_JPEG);
const progressiveJpeg = () => decodeBase64(PROGRESSIVE_JPEG);

const readUint16 = (data, offset) => (data[offset] << 8) | data[offset + 1];

const writeUint16 = (data, offset, value) => {
  data[offset] = (value >> 8) & 0xff;
  data[offset + 1] = value & 0xff;
};

function concatBytes(...arrays) {
  const length = arrays.reduce((sum, array) => sum + array.length, 0);
  const result = new Uint8Array(length);
  let offset = 0;
  for (const array of arrays) {
    result.set(array, offset);
    offset += array.length;
  }
  return result;
}

function getSegments(data) {
  const segments = [];
  let offset = 2; // Skip the SOI marker.
  while (offset + 3 < data.length) {
    const marker = readUint16(data, offset);
    if (marker === 0xffd9) {
      break;
    }
    const length = readUint16(data, offset + 2);
    const end = offset + 2 + length;
    segments.push({ marker, start: offset, end, length });
    if (marker === 0xffda) {
      break;
    }
    offset = end;
  }
  return segments;
}

function findSegment(data, marker) {
  const segment = getSegments(data).find(({ marker: m }) => m === marker);
  if (!segment) {
    throw new Error(`JPEG fixture has no segment 0x${marker.toString(16)}`);
  }
  return segment;
}

function parseJpeg(data, options) {
  const image = new JpegImage(options);
  image.parse(data);
  return image;
}

function getGrayPixels() {
  return Array.from(parseJpeg(grayJpeg()).getData({ width: 8, height: 8 }));
}

function makeImage(samples, { indices = [], adobe = null, colorTransform = -1 } = {}) {
  const image = new JpegImage({ colorTransform });
  image.width = 1;
  image.height = 1;
  image.numComponents = samples.length;
  image.adobe = adobe;
  image.components = samples.map((sample, i) => {
    const output = new Int16Array(64);
    output.fill(sample);
    return {
      index: indices[i] ?? i + 1,
      scaleX: 1,
      scaleY: 1,
      blocksPerLine: 1,
      output,
    };
  });
  return image;
}

