  return Array.from(parseJpeg(grayJpeg()).getData({ width: 8, height: 8 }));
}

function makeImage(samples, { indices = [], adobe = null, colorTransform = -1 } = {}) {
  const image = new JpegImage({ colorTransform });
  image.width = 1;
  image.height = 1;
  image.numComponents = samples.length;
  image.adobe = adobe;
  image.components = samples.map((sample, i) => {
    const output = new Int16Array(64);
    output.fill(sample);
    return {
      index: indices[i] ?? i + 1,
      scaleX: 1,
      scaleY: 1,
      blocksPerLine: 1,
      output,
    };
  });
  return image;
}

