    return this.findDefaultInlineStreamEnd(stream);
  }
  this.inlineStreamSkipEI(stream);
  return length;
}

/**
 * Find the EOD (end-of-data) marker '~>' (i.e. TILDE + GT) of the stream.
 * @returns {number} The inline stream length.
