    case 0x3e: // '>'
      ch = this.nextChar();
      if (ch === 0x3e) {
        this.nextChar();
        return Cmd.get(">>");
      }
      return Cmd.get(">");
    case 0x7b: // '{'
      this.nextChar();
      return Cmd.get("{");
    case 0x7d: // '}'
