import { deflateSync } from "node:zlib";

import { Ascii85Stream } from "../../src/core/ascii_85_stream.js";
import { AsciiHexStream } from "../../src/core/ascii_hex_stream.js";
import { ParserEOFException } from "../../src/core/core_utils.js";
import { FlateStream } from "../../src/core/flate_stream.js";
import { JpegStream } from "../../src/core/jpeg_stream.js";
import { Lexer, Linearization, Parser } from "../../src/core/parser.js";
import {
  Cmd,
  Dict,
  EOF,
  isCmd,
  isName,
  Name,
  Ref,
} from "../../src/core/primitives.js";
import { NullStream, Stream } from "../../src/core/stream.js";
import {
  bytesToString,
  FormatError,
  stringToBytes,
} from "../../src/shared/util.js";

const INLINE_IMAGE_COMMANDS = {
  BI: { numArgs: 0 },
  Q: { numArgs: 0 },
};

function concatBytes(...parts) {
  const result = [];
  for (const part of parts) {
    if (typeof part === "string") {
      for (let i = 0, ii = part.length; i < ii; i++) {
        result.push(part.charCodeAt(i) & 0xff);
      }
    } else {
      result.push(...part);
    }
  }
  return Uint8Array.from(result);
}

function makeStream(input) {
  const bytes = typeof input === "string" ? stringToBytes(input) : input;
  return new Stream(bytes);
}

function makeLexer(input, knownCommands = null) {
  return new Lexer(makeStream(input), knownCommands);
}

function makeParser(input = "", { knownCommands = null, ...options } = {}) {
  return new Parser({
    lexer: makeLexer(input, knownCommands),
    xref: null,
    ...options,
  });
}

function makeDict(entries = []) {
  const dict = new Dict(null);
  for (const [key, value] of entries) {
    dict.set(key, value);
  }
  return dict;
}

function readAll(stream) {
  return bytesToString(stream.getBytes());
}

describe("Lexer", () => {
  let infoSpy;
  let warnSpy;

  beforeEach(() => {
    infoSpy = jest.spyOn(console, "info").mockImplementation(() => {});
    warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it.each([
    ["42", 42],
    ["-7", -7],
    ["+7", 7],
    ["--7", 7],
    [".5", 0.5],
    ["-.5", -0.5],
    ["3.14", 3.14],
    ["-12.5", -12.5],
  ])("parses the PDF number %s", (input, expected) => {
    const lexer = makeLexer(input);

    expect(lexer.getObj()).toBe(expected);
  });

  it("stops a number at a second decimal point", () => {
    const lexer = makeLexer("1.2.3");

    expect(lexer.getObj()).toBe(1.2);
    expect(lexer.getObj()).toBe(0.3);
  });

  it("ignores line breaks immediately after a number sign", () => {
    const lexer = makeLexer("-\r\n3");

    expect(lexer.getObj()).toBe(-3);
  });

  it("ignores a minus sign in the middle of a number", () => {
    const lexer = makeLexer("12-3");

    expect(lexer.getObj()).toBe(123);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Badly formatted number")
    );
  });

  it.each([" ", "(", "<", ""])(
    "treats the Adobe-compatible invalid number %j as zero",
    input => {
      const lexer = makeLexer(input);

      expect(lexer.getNumber()).toBe(0);
      expect(infoSpy).toHaveBeenCalledWith(
        expect.stringContaining("Invalid number")
      );
    }
  );

  it("throws a FormatError for a non-delimiter invalid number", () => {
    const lexer = makeLexer("x");

    expect(() => lexer.getNumber()).toThrow(FormatError);
    expect(() => makeLexer("x").getNumber()).toThrow("Invalid number: x");
  });

  it("decodes nested parentheses and escape sequences in strings", () => {
    expect(makeLexer("(a(b)c)").getObj()).toBe("a(b)c");
    expect(
      makeLexer("(line\\nbreak \\t tab \\(paren\\) \\\\ slash)").getObj()
    ).toBe("line\nbreak \t tab (paren) \\ slash");
    expect(makeLexer("(\\101\\102\\103)").getObj()).toBe("ABC");
    expect(makeLexer("(a\\qb)").getObj()).toBe("aqb");
  });

  it("handles escaped line endings inside strings", () => {
    expect(makeLexer("(a\\\r\nb)").getObj()).toBe("ab");
    expect(makeLexer("(a\\\nb)").getObj()).toBe("ab");
  });

  it("warns and returns partial data for an unterminated string", () => {
    const lexer = makeLexer("(abc");

    expect(lexer.getObj()).toBe("abc");
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Unterminated string")
    );
  });

  it("decodes hexadecimal escapes in names", () => {
    const first = makeLexer("/A#42C").getObj();
    const second = makeLexer("/#41#42").getObj();

    expect(isName(first, "ABC")).toBe(true);
    expect(isName(second, "AB")).toBe(true);
  });

  it("warns about malformed hexadecimal escapes in names", () => {
    expect(isName(makeLexer("/A# ").getObj(), "A#")).toBe(true);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("NUMBER SIGN (#)")
    );

    warnSpy.mockClear();
    expect(isName(makeLexer("/A#4Z").getObj(), "A#4Z")).toBe(true);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Illegal digit")
    );
  });

  it("warns when a name exceeds the spec length limit", () => {
    const name = "a".repeat(128);
    const result = makeLexer(`/${name}`).getObj();

    expect(isName(result, name)).toBe(true);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Name token is longer than allowed")
    );
  });

  it("decodes hexadecimal strings and ignores white space", () => {
    expect(makeLexer("<48 65 6C 6C 6F>").getObj()).toBe("Hello");
    expect(makeLexer("<>").getObj()).toBe("");
  });

  it("pads an odd number of hexadecimal digits with zero", () => {
    expect(makeLexer("<414>").getObj()).toBe("A@");
  });

  it("ignores invalid hexadecimal string characters", () => {
    expect(makeLexer("<4G8>").getObj()).toBe("H");
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("ignoring invalid character")
    );
  });

  it("warns and returns partial data for an unterminated hex string", () => {
    expect(makeLexer("<4865").getObj()).toBe("He");
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Unterminated hex string")
    );
  });

  it("skips comments and white space before objects", () => {
    const lexer = makeLexer("% a comment\r\n  % another\n42");

    expect(lexer.getObj()).toBe(42);
  });

  it("returns booleans, null, and commands", () => {
    const lexer = makeLexer("true false null q Q");

    expect(lexer.getObj()).toBe(true);
    expect(lexer.getObj()).toBe(false);
    expect(lexer.getObj()).toBeNull();
    expect(isCmd(lexer.getObj(), "q")).toBe(true);
    expect(isCmd(lexer.getObj(), "Q")).toBe(true);
    expect(lexer.getObj()).toBe(EOF);
  });

  it("returns punctuation as command objects", () => {
    const lexer = makeLexer("[] <<>> {} >");

    for (const expected of ["[", "]", "<<", ">>", "{", "}", ">"]) {
      expect(isCmd(lexer.getObj(), expected)).toBe(true);
    }
  });

  it("throws for an illegal close parenthesis and consumes it", () => {
    const lexer = makeLexer(") 42");

    expect(() => lexer.getObj()).toThrow(FormatError);
    expect(lexer.getObj()).toBe(42);
  });

  it("uses known commands to split glued tokens", () => {
    const lexer = makeLexer("q1", { q: { numArgs: 0 } });

    expect(isCmd(lexer.getObj(), "q")).toBe(true);
    expect(lexer.getObj()).toBe(1);
  });

  it("keeps an unknown glued token as a single command", () => {
    const lexer = makeLexer("q1");

    expect(isCmd(lexer.getObj(), "q1")).toBe(true);
  });

  it("returns a one-character command for a non-visible byte followed by ASCII", () => {
    const lexer = makeLexer(Uint8Array.from([0x01, 0x71]));

    expect(isCmd(lexer.getObj(), "\x01")).toBe(true);
    expect(isCmd(lexer.getObj(), "q")).toBe(true);
  });

  it("throws when a command token is too long", () => {
    const lexer = makeLexer("a".repeat(129));

    expect(() => lexer.getObj()).toThrow(FormatError);
    expect(() => makeLexer("a".repeat(129)).getObj()).toThrow(
      "Command token too long"
    );
  });

  it("records the inline-image dictionary start position for BI", () => {
    const lexer = makeLexer("BI /W 1");

    expect(isCmd(lexer.getObj(), "BI")).toBe(true);
    expect(lexer.beginInlineImagePos).toBe(3);
  });

  it.each(["a\r\nb", "a\nb", "a\rb"])(
    "skipToNextLine advances to the character after the line ending",
    input => {
      const lexer = makeLexer(input);

      lexer.skipToNextLine();

      expect(lexer.currentChar).toBe(0x62);
    }
  );
});

describe("Parser object parsing", () => {
  let infoSpy;
  let warnSpy;

  beforeEach(() => {
    infoSpy = jest.spyOn(console, "info").mockImplementation(() => {});
    warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it("reads primitive values and indirect references", () => {
    const parser = makeParser("42 /Name (text) true false null 7 2 R");

    expect(parser.getObj()).toBe(42);
    expect(isName(parser.getObj(), "Name")).toBe(true);
    expect(parser.getObj()).toBe("text");
    expect(parser.getObj()).toBe(true);
    expect(parser.getObj()).toBe(false);
    expect(parser.getObj()).toBeNull();
    expect(parser.getObj()).toBe(Ref.get(7, 2));
    expect(parser.getObj()).toBe(EOF);
  });

  it("builds nested arrays and dictionaries", () => {
    const parser = makeParser("[1 (two) /Three [4 5] << /A true >>]");

    const array = parser.getObj();

    expect(array).toHaveLength(4);
    expect(array[0]).toBe(1);
    expect(array[1]).toBe("two");
    expect(isName(array[2], "Three")).toBe(true);
    expect(array[3]).toEqual([4, 5]);
    expect(array[4].get("A")).toBe(true);
  });

  it("returns a partially parsed array in recovery mode at EOF", () => {
    expect(makeParser("[1 2", { recoveryMode: true }).getObj()).toEqual([
      1, 2,
    ]);
    expect(() => makeParser("[1 2").getObj()).toThrow(ParserEOFException);
    expect(() => makeParser("[1 2").getObj()).toThrow(
      "End of file inside array."
    );
  });

  it("returns a partially parsed dictionary in recovery mode at EOF", () => {
    const dict = makeParser("<< /A 1", { recoveryMode: true }).getObj();

    expect(dict).toBeInstanceOf(Dict);
    expect(dict.get("A")).toBe(1);
    expect(() => makeParser("<< /A 1").getObj()).toThrow(ParserEOFException);
    expect(() => makeParser("<< /A 1").getObj()).toThrow(
      "End of file inside dictionary."
    );
  });

  it("skips malformed dictionary keys", () => {
    const dict = makeParser("<< 1 2 /A 3 >>").getObj();

    expect(dict).toBeInstanceOf(Dict);
    expect(dict.get("A")).toBe(3);
    expect(infoSpy).toHaveBeenCalledWith(
      "Malformed dictionary: key must be a name object"
    );
  });

  it("decrypts strings through the supplied cipher transform", () => {
    const cipherTransform = {
      decryptString: jest.fn(value => value.toUpperCase()),
    };
    const parser = makeParser("(a) [(b)] << /K (c) >>");

    expect(parser.getObj(cipherTransform)).toBe("A");
    expect(parser.getObj(cipherTransform)).toEqual(["B"]);
    expect(parser.getObj(cipherTransform).get("K")).toBe("C");
    expect(cipherTransform.decryptString.mock.calls).toEqual([["a"], ["b"], ["c"]]);
  });

  it("maintains the two-token lookahead with shift and refill", () => {
    const parser = makeParser("1 2 3");

    expect(parser.buf1).toBe(1);
    expect(parser.buf2).toBe(2);

    parser.shift();

    expect(parser.buf1).toBe(2);
    expect(parser.buf2).toBe(3);

    parser.refill();

    expect(parser.buf1).toBe(EOF);
    expect(parser.buf2).toBe(EOF);
  });

  it("leaves a stream token for a later getObj when streams are disabled", () => {
    const parser = makeParser("<< /Length 3 >> stream\nabc\nendstream");

    const dict = parser.getObj();

    expect(dict).toBeInstanceOf(Dict);
    expect(isCmd(parser.getObj(), "stream")).toBe(true);
    expect(isCmd(parser.getObj(), "abc")).toBe(true);
    expect(isCmd(parser.getObj(), "endstream")).toBe(true);
  });

  it("returns a stream object when streams are enabled", () => {
    const parser = makeParser("<< /Length 3 >> stream\nabc\nendstream", {
      allowStreams: true,
