    warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it("parses an inline image with the default EI scanning logic", () => {
    const parser = makeParser(
      concatBytes("BI /W 1 /H 1 /BPC 8 /CS /G ID ", [0x00], " EI Q"),
      { knownCommands: INLINE_IMAGE_COMMANDS }
    );

    const image = parser.getObj();

    expect(image).toBeInstanceOf(Stream);
    expect(image.dict.get("W")).toBe(1);
    expect(image.dict.get("H")).toBe(1);
    expect(image.dict.get("BPC")).toBe(8);
    expect(isName(image.dict.get("CS"), "G")).toBe(true);
    expect(Array.from(image.getBytes())).toEqual([0x00]);
    expect(image.cacheKey).toBe("inline_img_1");
    expect(isCmd(parser.getObj(), "EI")).toBe(true);
    expect(isCmd(parser.getObj(), "Q")).toBe(true);
  });

  it("decodes an inline image with an ASCIIHexDecode filter", () => {
    const parser = makeParser(
      "BI /W 1 /H 1 /Filter /ASCIIHexDecode ID 48656C6C6F> EI Q",
