        [0x00],
        " EI ",
        imageData,
        [0x00],
        " EI Q"
      ),
      { knownCommands: INLINE_IMAGE_COMMANDS }
    );

    const firstImage = parser.getObj();

    expect(firstImage.cacheKey).toBe("inline_img_1");
    expect(Array.from(firstImage.getBytes())).toEqual([0x00]);
    expect(isCmd(parser.getObj(), "EI")).toBe(true);

    const secondImage = parser.getObj();

    expect(secondImage).toBe(firstImage);
