import { deflateSync } from "node:zlib";

import { Ascii85Stream } from "../../src/core/ascii_85_stream.js";
import { AsciiHexStream } from "../../src/core/ascii_hex_stream.js";
import { ParserEOFException } from "../../src/core/core_utils.js";
import { FlateStream } from "../../src/core/flate_stream.js";
import { JpegStream } from "../../src/core/jpeg_stream.js";
import { Lexer, Linearization, Parser } from "../../src/core/parser.js";
import {
  Cmd,
  Dict,
  EOF,
  isCmd,
  isName,
  Name,
  Ref,
} from "../../src/core/primitives.js";
import { NullStream, Stream } from "../../src/core/stream.js";
import {
  bytesToString,
  FormatError,
  stringToBytes,
} from "../../src/shared/util.js";

const INLINE_IMAGE_COMMANDS = {
  BI: { numArgs: 0 },
  Q: { numArgs: 0 },
};

function concatBytes(...parts) {
  const result = [];
  for (const part of parts) {
    if (typeof part === "string") {
      for (let i = 0, ii = part.length; i < ii; i++) {
        result.push(part.charCodeAt(i) & 0xff);
      }
    } else {
      result.push(...part);
    }
  }
  return Uint8Array.from(result);
}

function makeStream(input) {
  const bytes = typeof input === "string" ? stringToBytes(input) : input;
  return new Stream(bytes);
}

function makeLexer(input, knownCommands = null) {
  return new Lexer(makeStream(input), knownCommands);
}

function makeParser(input = "", { knownCommands = null, ...options } = {}) {
  return new Parser({
    lexer: makeLexer(input, knownCommands),
    xref: null,
    ...options,
  });
}

function makeDict(entries = []) {
  const dict = new Dict(null);
  for (const [key, value] of entries) {
    dict.set(key, value);
  }
  return dict;
}

function readAll(stream) {
  return bytesToString(stream.getBytes());
}

describe("Lexer", () => {
  let infoSpy;
  let warnSpy;

  beforeEach(() => {
    infoSpy = jest.spyOn(console, "info").mockImplementation(() => {});
