    expect(makeLexer("<48 65 6C 6C 6F>").getObj()).toBe("Hello");
    expect(makeLexer("<>").getObj()).toBe("");
  });

  it("pads an odd number of hexadecimal digits with zero", () => {
    expect(makeLexer("<414>").getObj()).toBe("A@");
  });

  it("ignores invalid hexadecimal string characters", () => {
    expect(makeLexer("<4G8>").getObj()).toBe("H");
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("ignoring invalid character")
    );
  });

  it("warns and returns partial data for an unterminated hex string", () => {
    expect(makeLexer("<4865").getObj()).toBe("He");
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("Unterminated hex string")
    );
  });

  it("skips comments and white space before objects", () => {
    const lexer = makeLexer("% a comment\r\n  % another\n42");

    expect(lexer.getObj()).toBe(42);
  });

  it("returns booleans, null, and commands", () => {
    const lexer = makeLexer("true false null q Q");

    expect(lexer.getObj()).toBe(true);
    expect(lexer.getObj()).toBe(false);
    expect(lexer.getObj()).toBeNull();
    expect(isCmd(lexer.getObj(), "q")).toBe(true);
    expect(isCmd(lexer.getObj(), "Q")).toBe(true);
    expect(lexer.getObj()).toBe(EOF);
  });

  it("returns punctuation as command objects", () => {
    const lexer = makeLexer("[] <<>> {} >");

    for (const expected of ["[", "]", "<<", ">>", "{", "}", ">"]) {
