describe("Parser object parsing", () => {
  let infoSpy;
  let warnSpy;

  beforeEach(() => {
    infoSpy = jest.spyOn(console, "info").mockImplementation(() => {});
    warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it("reads primitive values and indirect references", () => {
    const parser = makeParser("42 /Name (text) true false null 7 2 R");

    expect(parser.getObj()).toBe(42);
    expect(isName(parser.getObj(), "Name")).toBe(true);
    expect(parser.getObj()).toBe("text");
    expect(parser.getObj()).toBe(true);
    expect(parser.getObj()).toBe(false);
    expect(parser.getObj()).toBeNull();
    expect(parser.getObj()).toBe(Ref.get(7, 2));
    expect(parser.getObj()).toBe(EOF);
  });

  it("builds nested arrays and dictionaries", () => {
    const parser = makeParser("[1 (two) /Three [4 5] << /A true >>]");

    const array = parser.getObj();

    expect(array).toHaveLength(4);
    expect(array[0]).toBe(1);
    expect(array[1]).toBe("two");
    expect(isName(array[2], "Three")).toBe(true);
    expect(array[3]).toEqual([4, 5]);
    expect(array[4].get("A")).toBe(true);
  });

  it("returns a partially parsed array in recovery mode at EOF", () => {
    expect(makeParser("[1 2", { recoveryMode: true }).getObj()).toEqual([
      1, 2,
    ]);
    expect(() => makeParser("[1 2").getObj()).toThrow(ParserEOFException);
    expect(() => makeParser("[1 2").getObj()).toThrow(
      "End of file inside array."
    );
  });

  it("returns a partially parsed dictionary in recovery mode at EOF", () => {
    const dict = makeParser("<< /A 1", { recoveryMode: true }).getObj();

    expect(dict).toBeInstanceOf(Dict);
    expect(dict.get("A")).toBe(1);
    expect(() => makeParser("<< /A 1").getObj()).toThrow(ParserEOFException);
    expect(() => makeParser("<< /A 1").getObj()).toThrow(
      "End of file inside dictionary."
    );
  });

  it("skips malformed dictionary keys", () => {
    const dict = makeParser("<< 1 2 /A 3 >>").getObj();

    expect(dict).toBeInstanceOf(Dict);
    expect(dict.get("A")).toBe(3);
    expect(infoSpy).toHaveBeenCalledWith(
      "Malformed dictionary: key must be a name object"
    );
  });

  it("decrypts strings through the supplied cipher transform", () => {
    const cipherTransform = {
      decryptString: jest.fn(value => value.toUpperCase()),
    };
    const parser = makeParser("(a) [(b)] << /K (c) >>");

    expect(parser.getObj(cipherTransform)).toBe("A");
    expect(parser.getObj(cipherTransform)).toEqual(["B"]);
    expect(parser.getObj(cipherTransform).get("K")).toBe("C");
    expect(cipherTransform.decryptString.mock.calls).toEqual([["a"], ["b"], ["c"]]);
  });

  it("maintains the two-token lookahead with shift and refill", () => {
    const parser = makeParser("1 2 3");

    expect(parser.buf1).toBe(1);
    expect(parser.buf2).toBe(2);

    parser.shift();

    expect(parser.buf1).toBe(2);
    expect(parser.buf2).toBe(3);

    parser.refill();

    expect(parser.buf1).toBe(EOF);
    expect(parser.buf2).toBe(EOF);
  });

  it("leaves a stream token for a later getObj when streams are disabled", () => {
    const parser = makeParser("<< /Length 3 >> stream\nabc\nendstream");

    const dict = parser.getObj();

    expect(dict).toBeInstanceOf(Dict);
    expect(isCmd(parser.getObj(), "stream")).toBe(true);
    expect(isCmd(parser.getObj(), "abc")).toBe(true);
    expect(isCmd(parser.getObj(), "endstream")).toBe(true);
  });

  it("returns a stream object when streams are enabled", () => {
    const parser = makeParser("<< /Length 3 >> stream\nabc\nendstream", {
      allowStreams: true,
    });

    const stream = parser.getObj();

    expect(stream).toBeInstanceOf(Stream);
    expect(stream.dict.get("Length")).toBe(3);
    expect(readAll(stream)).toBe("abc");
  });

  it("scans for endstream when the declared stream length is wrong", () => {
    const parser = makeParser(
      "<< /Length 999 >>\nstream\nHello\nendstream\n",
      { allowStreams: true }
    );

    const stream = parser.getObj();

    expect(stream).toBeInstanceOf(Stream);
    expect(readAll(stream)).toBe("Hello\n");
  });

  it("throws when an unterminated stream has no endstream command", () => {
    const parser = makeParser("<< /Length 5 >>\nstream\nHello", {
      allowStreams: true,
    });

    expect(() => parser.getObj()).toThrow(FormatError);
    expect(() => parser.getObj()).toThrow("Missing endstream command.");
  });

  it("applies a stream filter while making a stream", () => {
    const parser = makeParser(
      "<< /Length 11 /Filter /ASCIIHexDecode >>\nstream\n48656C6C6F>\nendstream\n",
      { allowStreams: true }
    );

    const stream = parser.getObj();

    expect(stream).toBeInstanceOf(AsciiHexStream);
    expect(readAll(stream)).toBe("Hello");
  });

  it("applies a Flate filter while making a stream", () => {
    const compressed = new Uint8Array(deflateSync(Buffer.from("compressed")));
    const parser = makeParser(
      concatBytes(
        `<< /Length ${compressed.length} /Filter /FlateDecode >>\nstream\n`,
        compressed,
        "\nendstream\n"
      ),
      { allowStreams: true }
    );

    const stream = parser.getObj();

    expect(stream).toBeInstanceOf(FlateStream);
    expect(readAll(stream)).toBe("compressed");
  });

  it("passes non-Crypt streams through the cipher transform before filtering", () => {
    const createStream = jest.fn((stream, length) => stream);
    const cipherTransform = { createStream };
    const parser = makeParser("<< /Length 5 >>\nstream\nHello\nendstream\n", {
      allowStreams: true,
    });

    const stream = parser.getObj(cipherTransform);

    expect(createStream).toHaveBeenCalledTimes(1);
    expect(createStream).toHaveBeenCalledWith(expect.any(Stream), 5);
    expect(readAll(stream)).toBe("Hello");
  });

  it("lets the Crypt filter create the cipher stream with its crypt name", () => {
    const createStream = jest.fn((stream, length, name) => stream);
    const cipherTransform = { createStream };
    const parser = makeParser(
      "<< /Length 5 /Filter /Crypt /DecodeParms << /Name /Identity >> >>\n" +
        "stream\nHello\nendstream\n",
      { allowStreams: true }
    );

    const stream = parser.getObj(cipherTransform);

    expect(createStream).toHaveBeenCalledTimes(1);
    const [baseStream, length, cryptName] = createStream.mock.calls[0];
    expect(baseStream).toBeInstanceOf(Stream);
    expect(length).toBe(5);
    expect(isName(cryptName, "Identity")).toBe(true);
    expect(readAll(stream)).toBe("Hello");
  });
});

describe("Parser inline images", () => {
