  });

  it("parses an inline image with the default EI scanning logic", () => {
    const parser = makeParser(
      concatBytes("BI /W 1 /H 1 /BPC 8 /CS /G ID ", [0x00], " EI Q"),
      { knownCommands: INLINE_IMAGE_COMMANDS }
    );

    const image = parser.getObj();

    expect(image).toBeInstanceOf(Stream);
    expect(image.dict.get("W")).toBe(1);
    expect(image.dict.get("H")).toBe(1);
    expect(image.dict.get("BPC")).toBe(8);
    expect(isName(image.dict.get("CS"), "G")).toBe(true);
    expect(Array.from(image.getBytes())).toEqual([0x00]);
    expect(image.cacheKey).toBe("inline_img_1");
    expect(isCmd(parser.getObj(), "EI")).toBe(true);
    expect(isCmd(parser.getObj(), "Q")).toBe(true);
  });

  it("decodes an inline image with an ASCIIHexDecode filter", () => {
    const parser = makeParser(
      "BI /W 1 /H 1 /Filter /ASCIIHexDecode ID 48656C6C6F> EI Q",
      { knownCommands: INLINE_IMAGE_COMMANDS }
    );

    const image = parser.getObj();

    expect(image).toBeInstanceOf(AsciiHexStream);
    expect(readAll(image)).toBe("Hello");
  });

  it("returns a JPEG stream for a DCTDecode inline image", () => {
    const parser = makeParser(
      concatBytes(
        "BI /W 1 /H 1 /Filter /DCTDecode ID ",
        [0xff, 0xd8, 0xff, 0xd9],
        " EI Q"
      ),
      { knownCommands: INLINE_IMAGE_COMMANDS }
    );

    const image = parser.getObj();

    expect(image).toBeInstanceOf(JpegStream);
    expect(isName(image.dict.get("Filter"), "DCTDecode")).toBe(true);
  });

  it("reuses the cached stream for an identical inline image", () => {
    const imageData = "BI /W 1 /H 1 ID ";
    const parser = makeParser(
      concatBytes(
        imageData,
        [0x00],
        " EI ",
        imageData,
        [0x00],
        " EI Q"
      ),
      { knownCommands: INLINE_IMAGE_COMMANDS }
    );

    const firstImage = parser.getObj();

    expect(firstImage.cacheKey).toBe("inline_img_1");
    expect(Array.from(firstImage.getBytes())).toEqual([0x00]);
    expect(isCmd(parser.getObj(), "EI")).toBe(true);

    const secondImage = parser.getObj();

    expect(secondImage).toBe(firstImage);
    expect(secondImage.cacheKey).toBe("inline_img_1");
    expect(Array.from(secondImage.getBytes())).toEqual([0x00]);
  });

  it("throws for an inline image dictionary with a non-name key", () => {
    const parser = makeParser(concatBytes("BI 1 ID ", [0x00], " EI Q"), {
      knownCommands: INLINE_IMAGE_COMMANDS,
    });

    expect(() => parser.getObj()).toThrow(FormatError);
    expect(() => parser.getObj()).toThrow("Dictionary key must be a name object");
  });

  it("falls back to the last EI marker when no valid command follows", () => {
    const parser = makeParser(
      concatBytes("BI /W 1 /H 1 ID ", [0x00], " EI "),
      { knownCommands: { BI: { numArgs: 0 } } }
