    expect(image).toBeInstanceOf(Stream);
    expect(Array.from(image.getBytes())).toEqual([0x00]);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining('trying to recover by using the last "EI"')
    );
  });
});

describe("Parser stream filters", () => {
  let infoSpy;
  let warnSpy;
  let parser;

  beforeEach(() => {
    infoSpy = jest.spyOn(console, "info").mockImplementation(() => {});
    warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
    parser = makeParser();
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it("returns the original stream when there is no filter", () => {
    const stream = makeStream("plain");

    const result = parser.filter(stream, makeDict(), stream.length);

    expect(result).toBe(stream);
  });

  it.each([
    ["ASCIIHexDecode", "48 65 6C 6C 6F>", AsciiHexStream, "Hello"],
    [
      "ASCII85Decode",
      '87cURD]i,"Ebo80~>',
      Ascii85Stream,
      "Hello World!",
    ],
    [
      "RunLengthDecode",
      Uint8Array.from([4, 0x48, 0x65, 0x6c, 0x6c, 0x6f, 128]),
      null,
      "Hello",
    ],
  ])("decodes the %s filter", (name, data, streamType, expected) => {
    const stream = makeStream(data);
    const dict = makeDict([["Filter", Name.get(name)]]);

    const result = parser.filter(stream, dict, stream.length);

    if (streamType) {
      expect(result).toBeInstanceOf(streamType);
    }
    expect(readAll(result)).toBe(expected);
  });

  it("decodes a Flate stream", () => {
    const compressed = new Uint8Array(deflateSync(Buffer.from("flate data")));
    const stream = new Stream(compressed);
    const dict = makeDict([["Filter", Name.get("FlateDecode")]]);

    const result = parser.filter(stream, dict, compressed.length);

    expect(result).toBeInstanceOf(FlateStream);
    expect(readAll(result)).toBe("flate data");
  });

  it("applies a filter chain with the intermediate length unset", () => {
    const compressed = deflateSync(Buffer.from("Chain works"));
    const hex = compressed.toString("hex") + ">";
    const stream = makeStream(hex);
    const dict = makeDict([
      ["Filter", [Name.get("ASCIIHexDecode"), Name.get("FlateDecode")]],
    ]);

    const result = parser.filter(stream, dict, hex.length);

    expect(result).toBeInstanceOf(FlateStream);
    expect(readAll(result)).toBe("Chain works");
  });

  it("applies a Predictor when DecodeParms is present", () => {
    const compressed = new Uint8Array(
      deflateSync(Buffer.from([0, 1, 2, 3, 4]))
    );
    const stream = new Stream(compressed);
    const params = makeDict([
      ["Predictor", 12],
      ["Colors", 1],
      ["BPC", 8],
      ["Columns", 4],
    ]);
    const dict = makeDict([
      ["Filter", Name.get("FlateDecode")],
      ["DecodeParms", params],
    ]);

    const result = parser.filter(stream, dict, compressed.length);

    expect(Array.from(result.getBytes())).toEqual([1, 2, 3, 4]);
  });

  it("returns the stream unchanged for an unsupported filter", () => {
    const stream = makeStream("data");
    const dict = makeDict([["Filter", Name.get("BogusFilter")]]);

    const result = parser.filter(stream, dict, stream.length);

    expect(result).toBe(stream);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining('Filter "BogusFilter" is not supported.')
    );
  });

  it("returns a NullStream for an empty stream", () => {
    const stream = makeStream("");
    const dict = makeDict([["Filter", Name.get("FlateDecode")]]);

    const result = parser.filter(stream, dict, 0);

    expect(result).toBeInstanceOf(NullStream);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining('Empty "FlateDecode" stream.')
    );
  });

  it("returns a NullStream when a filter cannot decode the data", () => {
    const stream = makeStream([1, 2, 3, 4, 5]);
    const dict = makeDict([["Filter", Name.get("FlateDecode")]]);

    const result = parser.filter(stream, dict, stream.length);

    expect(result).toBeInstanceOf(NullStream);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining('Invalid stream:')
    );
  });

  it("throws a FormatError for a non-name entry in a filter array", () => {
    const stream = makeStream("data");
    const dict = makeDict([["Filter", [42]]]);

    expect(() => parser.filter(stream, dict, stream.length)).toThrow(
      FormatError
    );
    expect(() => parser.filter(stream, dict, stream.length)).toThrow(
      'Bad filter name "42"'
    );
  });

  it("returns the original stream for Crypt without a cipher transform", () => {
    const stream = makeStream("data");
    const dict = makeDict([["Filter", Name.get("Crypt")]]);

    const result = parser.filter(stream, dict, stream.length);

    expect(result).toBe(stream);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining('Filter "Crypt" is missing a cipher transform.')
    );
  });

  it("resolves filter references through the xref", () => {
    const ref = Ref.get(12, 0);
    const fetchIfRef = jest.fn(value =>
      value === ref ? Name.get("ASCIIHexDecode") : null
    );
    const xrefParser = new Parser({
      lexer: makeLexer(""),
      xref: { fetchIfRef },
    });
    const stream = makeStream("48 65 6C 6C 6F>");
    const dict = makeDict([["Filter", [ref]]]);

    const result = xrefParser.filter(stream, dict, stream.length);

    expect(fetchIfRef).toHaveBeenCalledWith(ref);
    expect(result).toBeInstanceOf(AsciiHexStream);
    expect(readAll(result)).toBe("Hello");
  });
});

describe("Linearization", () => {
  function makeLinearizedStream(dictBody) {
    let length = 0;
    let text = "";
    for (let i = 0; i < 10; i++) {
      text = `1 0 obj\n<< /Linearized 1 /L ${length} ${dictBody} >>\nendobj\n`;
      if (text.length === length) {
        break;
      }
      length = text.length;
    }
    return makeStream(text);
  }

  it("creates the linearization data for a valid dictionary", () => {
    const stream = makeLinearizedStream(
      "/H [10 20] /O 5 /E 100 /N 2 /T 50"
    );

    const result = Linearization.create(stream);

    expect(result).toEqual({
      length: stream.length,
      hints: [10, 20],
      objectNumberFirst: 5,
      endFirst: 100,
      numPages: 2,
      mainXRefEntriesOffset: 50,
      pageFirst: 0,
    });
  });

  it("accepts four hints and a zero first-page offset", () => {
    const stream = makeLinearizedStream(
      "/H [10 20 30 40] /O 5 /E 100 /N 2 /T 50 /P 0"
    );

    const result = Linearization.create(stream);

    expect(result.hints).toEqual([10, 20, 30, 40]);
    expect(result.pageFirst).toBe(0);
  });

  it("returns null for a document without a linearization dictionary", () => {
    const stream = makeStream(
      "1 0 obj\n<< /Type /Catalog /Linearized 0 >>\nendobj\n"
    );

    expect(Linearization.create(stream)).toBeNull();
  });

  it("throws when the L value does not match the stream length", () => {
    const text =
      '1 0 obj\n<< /Linearized 1 /L 999 /H [10 20] /O 5 /E 100 /N 2 /T 50 >>\nendobj\n';
    const stream = makeStream(text);

    expect(() => Linearization.create(stream)).toThrow(
      'The "L" parameter in the linearization dictionary does not equal the stream length.'
    );
  });

  it("throws when a required positive integer parameter is invalid", () => {
    const stream = makeLinearizedStream(
      "/H [10 20] /O 0 /E 100 /N 2 /T 50"
    );

    expect(() => Linearization.create(stream)).toThrow(
      'The "O" parameter in the linearization dictionary is invalid.'
    );
  });

  it("throws for an invalid hint array shape", () => {
    const stream = makeLinearizedStream("/H [10] /O 5 /E 100 /N 2 /T 50");

    expect(() => Linearization.create(stream)).toThrow(
      "Hint array in the linearization dictionary is invalid."
    );
  });

  it("throws for a non-positive hint value", () => {
    const stream = makeLinearizedStream(
      "/H [10 -20] /O 5 /E 100 /N 2 /T 50"
    );

    expect(() => Linearization.create(stream)).toThrow(
      "Hint (1) in the linearization dictionary is invalid."
    );
  });

  it("throws for a negative P value", () => {
    const stream = makeLinearizedStream(
      "/H [10 20] /O 5 /E 100 /N 2 /T 50 /P -1"
    );

    expect(() => Linearization.create(stream)).toThrow(
      'The "P" parameter in the linearization dictionary is invalid.'
    );
  });
});
