class Rec extends XMLParserBase {
  constructor(){ super(); this.events=[]; this.errors=[]; }
  onResolveEntity(n){ this.events.push(['resolve',n]); return `[${n}]`; }
  onText(t){ this.events.push(['text',t]); }
  onCdata(t){ this.events.push(['cdata',t]); }
  onComment(t){ this.events.push(['comment',t]); }
  onDoctype(t){ this.events.push(['doctype',t]); }
  onPi(n,v){ this.events.push(['pi',n,v]); }
  onBeginElement(n,a,e){ this.events.push(['begin',n,a,e]); }
  onEndElement(n){ this.events.push(['end',n]); }
  onError(c){ this.events.push(['error',c]); this.errors.push(c); }
}
const r = new Rec();
