import {
  SimpleDOMNode,
  SimpleXMLParser,
  XMLParserBase,
  XMLParserErrorCode,
} from "../../src/core/xml_parser.js";

function makePath(...components) {
  return components.map(([name, pos = 0]) => ({ name, pos }));
}

function parseDocument(xml, options = { hasAttributes: true }) {
  const parser = new SimpleXMLParser(options);
  const result = parser.parseFromString(xml);
  expect(result).toBeDefined();
  return result.documentElement;
}

class RecordingParser extends XMLParserBase {
  constructor() {
    super();
    this.events = [];
  }

  onResolveEntity(name) {
    this.events.push({ type: "entity", name });
    return `{{${name}}}`;
  }

  onText(text) {
    this.events.push({ type: "text", text });
  }

  onCdata(text) {
    this.events.push({ type: "cdata", text });
  }

  onComment(text) {
    this.events.push({ type: "comment", text });
  }

  onDoctype(content) {
    this.events.push({ type: "doctype", content });
  }

  onPi(name, value) {
    this.events.push({ type: "pi", name, value });
  }

  onBeginElement(name, attributes, isEmpty) {
    this.events.push({ type: "begin", name, attributes, isEmpty });
  }

  onEndElement(name) {
    this.events.push({ type: "end", name });
  }

  onError(code) {
    this.events.push({ type: "error", code });
  }
}

describe("XMLParserErrorCode", () => {
  it("exposes the documented error codes", () => {
    expect(XMLParserErrorCode).toEqual({
      NoError: 0,
      EndOfDocument: -1,
      UnterminatedCdata: -2,
      UnterminatedXmlDeclaration: -3,
      UnterminatedDoctypeDeclaration: -4,
      UnterminatedComment: -5,
      MalformedElement: -6,
      OutOfMemory: -7,
      UnterminatedAttributeValue: -8,
      UnterminatedElement: -9,
      ElementNeverBegun: -10,
    });
  });
});

describe("XMLParserBase.parseXml", () => {
  it("emits callbacks in document order for markup and text", () => {
    const parser = new RecordingParser();

    parser.parseXml(
      '<?xml version="1.0"?><!DOCTYPE html><!-- hi -->' +
        "<root a=\"x&amp;y\" b='q'>" +
        "<![CDATA[cd&ata]]>txt &foo; <empty/></root>"
    );

    expect(parser.events).toEqual([
      { type: "pi", name: "xml", value: 'version="1.0"' },
      { type: "doctype", content: " html" },
      { type: "comment", text: " hi " },
      {
        type: "begin",
        name: "root",
        attributes: [
          { name: "a", value: "x&y" },
          { name: "b", value: "q" },
        ],
        isEmpty: false,
      },
      { type: "cdata", text: "cd&ata" },
      { type: "entity", name: "foo" },
      { type: "text", text: "txt {{foo}} " },
      { type: "begin", name: "empty", attributes: [], isEmpty: true },
      { type: "end", name: "root" },
    ]);
  });

  it("distinguishes self-closing elements from open elements", () => {
    const parser = new RecordingParser();

    parser.parseXml("<root><empty/><child></child></root>");

    expect(parser.events).toEqual([
      { type: "begin", name: "root", attributes: [], isEmpty: false },
      { type: "begin", name: "empty", attributes: [], isEmpty: true },
      { type: "begin", name: "child", attributes: [], isEmpty: false },
      { type: "end", name: "child" },
      { type: "end", name: "root" },
    ]);
  });

  it("handles complex DOCTYPE declarations with an internal subset", () => {
    const parser = new RecordingParser();

