    ["unterminated element", "<root", -9],
    ["unterminated end tag", "<root></root", -9],
  ])("reports %s with the expected error code", (_label, xml, code) => {
    const parser = new RecordingParser();

    parser.parseXml(xml);

    expect(parser.events.at(-1)).toEqual({ type: "error", code });
  });
});

describe("SimpleXMLParser.parseFromString", () => {
  it("builds a tree with attributes, children, and parent links", () => {
    const root = parseDocument(
      '<root id="r"><child name="c">hello</child><empty/></root>'
    );

    expect(root.nodeName).toBe("root");
    expect(root.nodeValue).toBeUndefined();
    expect(root.attributes).toEqual([{ name: "id", value: "r" }]);
    expect(root.children.map(child => child.nodeName)).toEqual([
      "child",
      "empty",
    ]);
    expect(root.firstChild).toBe(root.children[0]);
    expect(root.children[0].attributes).toEqual([{ name: "name", value: "c" }]);
    expect(root.children[0].parentNode).toBe(root);
    expect(root.children[1].parentNode).toBe(root);
    expect(root.textContent).toBe("hello");
    expect(root.children[1].hasChildNodes()).toBe(false);
    expect(root.children[1].children).toEqual([]);
  });

  it("does not expose attributes unless hasAttributes is enabled", () => {
    const root = parseDocument(
      '<root id="r"><child name="c"/></root>',
