    expect(root.attributes).toEqual([{ name: "Attr", value: "1" }]);
    expect(root.children.map(child => child.nodeName)).toEqual(["child"]);
  });

  it("ignores whitespace-only text but preserves meaningful whitespace", () => {
    const root = parseDocument("<root>\n  <a>  x  </a>\n</root>");

