import {
  SimpleDOMNode,
  SimpleXMLParser,
  XMLParserBase,
  XMLParserErrorCode,
} from "../../src/core/xml_parser.js";

function makePath(...components) {
  return components.map(([name, pos = 0]) => ({ name, pos }));
}

function parseDocument(xml, options = { hasAttributes: true }) {
  const parser = new SimpleXMLParser(options);
  const result = parser.parseFromString(xml);
  expect(result).toBeDefined();
  return result.documentElement;
}

class RecordingParser extends XMLParserBase {
  constructor() {
    super();
    this.events = [];
  }

  onResolveEntity(name) {
    this.events.push({ type: "entity", name });
    return `{{${name}}}`;
  }

  onText(text) {
    this.events.push({ type: "text", text });
  }

  onCdata(text) {
    this.events.push({ type: "cdata", text });
  }

  onComment(text) {
    this.events.push({ type: "comment", text });
  }

  onDoctype(content) {
    this.events.push({ type: "doctype", content });
  }

  onPi(name, value) {
    this.events.push({ type: "pi", name, value });
  }

  onBeginElement(name, attributes, isEmpty) {
    this.events.push({ type: "begin", name, attributes, isEmpty });
  }

  onEndElement(name) {
    this.events.push({ type: "end", name });
  }

  onError(code) {
    this.events.push({ type: "error", code });
  }
}

describe("XMLParserErrorCode", () => {
  it("exposes the documented error codes", () => {
