describe("SimpleDOMNode", () => {
  it("provides textContent across nested children", () => {
    const root = parseDocument("<root>a<child>b</child>c</root>");

    expect(root.textContent).toBe("abc");
    expect(root.children[1].textContent).toBe("b");
  });

  it("exposes text nodes as children and reports their capabilities", () => {
    const root = parseDocument("<root>alpha<child/>omega</root>");
    const text = root.firstChild;

    expect(root.children.map(child => child.nodeName)).toEqual([
      "#text",
      "child",
      "#text",
    ]);
    expect(text.nodeName).toBe("#text");
    expect(text.nodeValue).toBe("alpha");
    expect(text.parentNode).toBe(root);
    expect(text.children).toEqual([]);
    expect(text.hasChildNodes()).toBe(false);
    expect(text.textContent).toBe("alpha");
  });

  it("finds the next sibling and returns undefined for the last child", () => {
    const root = parseDocument("<root>alpha<child/>omega</root>");
    const [alpha, child, omega] = root.children;

    expect(alpha.nextSibling).toBe(child);
    expect(child.nextSibling).toBe(omega);
    expect(omega.nextSibling).toBeUndefined();
  });

  it("uses defaults for a detached node", () => {
    const node = new SimpleDOMNode("label", "value");

    expect(node.nodeName).toBe("label");
    expect(node.nodeValue).toBe("value");
    expect(node.parentNode).toBeNull();
    expect(node.firstChild).toBeUndefined();
    expect(node.children).toEqual([]);
    expect(node.hasChildNodes()).toBe(false);
    expect(node.textContent).toBe("value");
  });

  it("returns an empty string for a childless element without a value", () => {
    const node = new SimpleDOMNode("empty");

    expect(node.textContent).toBe("");
  });
});

