function encryptBytes(plain, key, discard = 4) {
  const prefixed = new Uint8Array(discard + plain.length);
  prefixed.set(plain, discard);
  let r = key | 0;
  const encrypted = new Uint8Array(prefixed.length);
  for (let i = 0, ii = prefixed.length; i < ii; i++) {
