  const subrMapOffset = cidMapOffset + (cidCount + 1) * entrySize;
  const subrMapSize = subrCount > 0 ? (subrCount + 1) * sdBytes : 0;
  const dataOffset = subrMapOffset + subrMapSize;

  const glyphOffsets = [];
  let offset = dataOffset;
  for (let cid = 0; cid < cidCount; cid++) {
    glyphOffsets.push(offset);
    offset += glyphs[cid].length;
  }
  glyphOffsets.push(offset); // End of the last glyph interval.

  const subrOffsets = [];
  if (subrCount > 0) {
    let subrOffset = offset;
