  b.ascii(`/GDBytes ${gdBytes} def\n`);
  b.ascii(`/SubrMapOffset ${subrMapOffset} def\n`);
  b.ascii(`/SDBytes ${sdBytes} def\n`);
  b.ascii(`/SubrCount ${subrCount} def\n`);
