function parseCidFont(source) {
  const parser = new Type1Parser(streamOf(source), false, false);
  const properties = {};
  const program = parser.extractCidKeyedFontProgram(properties);
  return { program, properties };
}

const NOTDEF_CHARSTRING = [0x8b, 0x8b, 13, 14]; // 0 0 hsbw endchar

describe("Type1Parser tokenizer", () => {
  it("skips whitespace and comments, and splits special characters", () => {
    const parser = new Type1Parser(
      streamOf("% a comment\n  /Name 12 [ 3 ] {x}\n(hi)\n"),
      false,
      false
    );
    expect(parser.getToken()).toEqual("/");
    expect(parser.getToken()).toEqual("Name");
    expect(parser.getToken()).toEqual("12");
    expect(parser.getToken()).toEqual("[");
    expect(parser.getToken()).toEqual("3");
    expect(parser.getToken()).toEqual("]");
    expect(parser.getToken()).toEqual("{");
    expect(parser.getToken()).toEqual("x");
    expect(parser.getToken()).toEqual("}");
    expect(parser.getToken()).toEqual("(");
    expect(parser.getToken()).toEqual("hi");
    expect(parser.getToken()).toEqual(")");
    expect(parser.getToken()).toBeNull();
    expect(parser.getToken()).toBeNull();
  });

  it("reads numbers with readNumber, readInt and readBoolean", () => {
    const parser = new Type1Parser(
      streamOf("1.75 -3.5 7.9 42 true false True"),
      false,
      false
    );
    expect(parser.readNumber()).toBeCloseTo(1.75, 10);
    expect(parser.readNumber()).toBeCloseTo(-3.5, 10);
    expect(parser.readInt()).toBe(7); // truncated to an int
    expect(parser.readInt()).toBe(42);
    expect(parser.readBoolean()).toBe(1);
    expect(parser.readBoolean()).toBe(0);
    expect(parser.readBoolean()).toBe(0);
  });

  it("stops a number array at a closing bracket", () => {
    const parser = new Type1Parser(streamOf("[12 34]"), false, false);
    expect(parser.readNumberArray()).toEqual([12, 34]);
  });

  it("reads number arrays delimited by braces as well", () => {
    const parser = new Type1Parser(
      streamOf("{ 0.5 -1 2 } [ 3 ]"),
      false,
      false
    );
    expect(parser.readNumberArray()).toEqual([0.5, -1, 2]);
    expect(parser.readNumberArray()).toEqual([3]);
  });

  it("returns an empty array when the stream ends early", () => {
    const parser = new Type1Parser(streamOf("[ 1 2"), false, false);
    expect(parser.readNumberArray()).toEqual([1, 2]);
  });

  it("supports prevChar moving one token back", () => {
    const parser = new Type1Parser(streamOf("ab cd"), false, false);
    expect(parser.getToken()).toEqual("ab");
    parser.prevChar();
    expect(parser.getToken()).toEqual("ab");
  });

  it("readCharStrings returns the input untouched when lenIV is -1", () => {
    const parser = new Type1Parser(streamOf("x"), false, false);
    const bytes = new Uint8Array([1, 2, 3, 4, 5, 6]);
    expect(parser.readCharStrings(bytes, -1)).toBe(bytes);
  });

  it("readCharStrings discards lenIV bytes when decrypting", () => {
    const parser = new Type1Parser(streamOf("x"), false, false);
    const plain = new Uint8Array([9, 8, 7]);
    const encrypted = encryptBytes(plain, CHAR_STRS_ENCRYPT_KEY, 4);
    expect([...parser.readCharStrings(encrypted, 4)]).toEqual([9, 8, 7]);
    expect(parser.readCharStrings(encrypted, 4).length).toEqual(3);
  });
});
