  it("inlines called subroutines", () => {
    const bytes = buildFontProgram({
      glyphs: [{ name: "A", data: charString(0, 0, "hsbw", 0, "callsubr", "endchar") }],
      subrs: [[...charString(50, 60, "rlineto"), ...charString("return")]],
    });
    const { program } = parseFontProgram(bytes);
    expect(program.subrs).toHaveLength(1);
    expect(program.charstrings[0].charstring).toEqual([
      ...type2Int(0),
      ...type2Int(0),
      22,
      ...type2Int(50),
      ...type2Int(60),
      5,
      14,
    ]);
  });

  it("reports an error when calling a missing subroutine", () => {
    const bytes = buildFontProgram({
      glyphs: [{ name: "A", data: charString(0, 0, "hsbw", 7, "callsubr", "endchar") }],
      subrs: [[...charString("return")]],
    });
    const { program } = parseFontProgram(bytes);
    expect(program.charstrings[0].charstring).toEqual([14]);
  });

  it("ignores a second CharStrings and Subrs block", () => {
    const second = new ByteBuilder()
      .ascii("/CharStrings 1 dict dup begin\n/zzz 4 RD ")
      .raw(NOTDEF_CHARSTRING)
      .ascii("\nND\nend\n/Subrs 1 array\ndup 0 1 RD ")
      .raw([11])
      .ascii("\nNP\nend\n")
      .build();
    const first = buildFontProgram({
      glyphs: [{ name: "A", data: charString(0, 0, "hsbw", "endchar") }],
    });
    const bytes = new Uint8Array(first.length + second.length);
    bytes.set(first, 0);
    bytes.set(second, first.length);
    const { program } = parseFontProgram(bytes);
    expect(program.charstrings.map(g => g.glyphName)).toEqual(["A"]);
  });
});
