describe("Type1Parser.extractCidKeyedFontProgram", () => {
  function cidGlyphs() {
    return [
      Uint8Array.from(charString(0, 0, "hsbw", "endchar")),
      Uint8Array.from(charString(0, 500, "hsbw", "endchar")),
      Uint8Array.from(charString(0, 250, "hsbw", "endchar")),
    ];
  }

  function validCidFont({ dataType = "Binary", declaredLength } = {}) {
    const glyphs = cidGlyphs();
    const subrs = [Uint8Array.from(charString("return"))];
    const { binary, subrMapOffset } = buildCidBinary({
      cidCount: 3,
      glyphs,
      subrs,
    });
    const source = cidFontSource({
      binary:
        dataType === "Hex"
          ? toBytes(toHex(binary))
          : binary,
      cidCount: 3,
      subrMapOffset,
      subrCount: 1,
      dataType,
      declaredLength: declaredLength ?? binary.length,
    });
    return source;
  }

  it("extracts charstrings, subrs and font properties", () => {
    const { program, properties } = parseCidFont(validCidFont());
    expect(program.charstrings.map(g => g.glyphName)).toEqual([
      ".notdef",
      "cid1",
      "cid2",
    ]);
    expect(program.charstrings.map(g => g.width)).toEqual([0, 500, 250]);
    expect(program.charstrings[1].charstring).toEqual([
      ...type2Int(500),
      ...type2Int(0),
      22,
      14,
    ]);
    expect(program.subrs).toHaveLength(1);
    expect(program.properties.privateData.get("lenIV")).toEqual(-1);
    expect(properties.fontMatrix).toEqual([0.001, 0, 0, 0.001, 0, 0]);
    expect(properties.ascent).toEqual(800);
    expect(properties.descent).toEqual(-200);
    expect(properties.ascentScaled).toBe(true);
  });

  it("extracts a hex encoded CID data section", () => {
    const { program } = parseCidFont(validCidFont({ dataType: "Hex" }));
    expect(program.charstrings.map(g => g.glyphName)).toEqual([
      ".notdef",
      "cid1",
      "cid2",
    ]);
    expect(program.charstrings.map(g => g.width)).toEqual([0, 500, 250]);
  });

  it("caps an oversized binary length to the remaining bytes", () => {
    const { program } = parseCidFont(validCidFont({ declaredLength: 500 }));
    expect(program.charstrings.map(g => g.glyphName)).toEqual([
      ".notdef",
      "cid1",
      "cid2",
    ]);
  });

  it("reuses the .notdef charstring for empty CID intervals", () => {
    const glyphs = cidGlyphs();
    glyphs[1] = new Uint8Array(0);
    const { binary, subrMapOffset } = buildCidBinary({
      cidCount: 3,
      glyphs,
      subrs: [Uint8Array.from(charString("return"))],
    });
    const { program } = parseCidFont(
      cidFontSource({ binary, cidCount: 3, subrMapOffset, subrCount: 1 })
    );
    expect(program.charstrings.map(g => g.glyphName)).toEqual([
      ".notdef",
      "cid1",
      "cid2",
    ]);
    expect(program.charstrings[1].charstring).toEqual(
      program.charstrings[0].charstring
    );
    expect(program.charstrings[1].width).toEqual(0);
    expect(program.charstrings[2].width).toEqual(250);
  });

  it("inlines subroutines called from CID charstrings", () => {
    const glyphs = [
      Uint8Array.from(charString(0, 0, "hsbw", "endchar")),
      Uint8Array.from(charString(0, 0, "hsbw", 0, "callsubr", "endchar")),
      Uint8Array.from(charString(0, 0, "hsbw", "endchar")),
    ];
    const { binary, subrMapOffset } = buildCidBinary({
      cidCount: 3,
      glyphs,
      subrs: [Uint8Array.from(charString(60, 70, "rlineto", "return"))],
    });
    const { program } = parseCidFont(
      cidFontSource({ binary, cidCount: 3, subrMapOffset, subrCount: 1 })
    );
    expect(program.charstrings[1].charstring).toEqual([
      ...type2Int(0),
      ...type2Int(0),
      22,
      ...type2Int(60),
      ...type2Int(70),
      5,
      14,
    ]);
  });

  it("emits empty subroutines for out of range subr offsets", () => {
    const glyphs = cidGlyphs();
    const { binary, subrMapOffset } = buildCidBinary({
      cidCount: 3,
      glyphs,
      subrs: [Uint8Array.from(charString("return"))],
    });
    // Point the end of the single subr interval past the binary section.
    const patched = Uint8Array.from(binary);
    patched[subrMapOffset + 2] = 0xff;
    patched[subrMapOffset + 3] = 0xff;
    const { program } = parseCidFont(
      cidFontSource({
        binary: patched,
        cidCount: 3,
        subrMapOffset,
        subrCount: 1,
      })
    );
    expect(program.subrs).toHaveLength(1);
    expect(program.subrs[0]).toHaveLength(0);
    expect(program.charstrings.map(g => g.glyphName)).toEqual([
      ".notdef",
      "cid1",
      "cid2",
    ]);
  });

  it("returns null without a StartData marker", () => {
    const source = toBytes(
      "/CIDCount 3 def /CIDMapOffset 0 def /GDBytes 2 def\n"
    );
    expect(parseCidFont(source).program).toBeNull();
  });

  it("returns null when StartData has no valid marker arguments", () => {
    expect(parseCidFont(toBytes("StartData\n\u008b\u008b\r\u000e")).program)
      .toBeNull();
    expect(
      parseCidFont(toBytes("( Ascii ) 10 StartData\n\u008b\u008b\r\u000e"))
        .program
    ).toBeNull();
    expect(
      parseCidFont(toBytes("( Binary ) zero StartData\n\u008b\u008b\r\u000e"))
        .program
    ).toBeNull();
  });

  it("returns null for a zero StartData length", () => {
    const glyphs = cidGlyphs();
    const { binary, subrMapOffset } = buildCidBinary({
      cidCount: 3,
      glyphs,
      subrs: [Uint8Array.from(charString("return"))],
    });
    const { program } = parseCidFont(
      cidFontSource({
        binary,
        cidCount: 3,
        subrMapOffset,
        subrCount: 1,
        declaredLength: 0,
      })
    );
    expect(program).toBeNull();
  });

  it("returns null without a CIDCount", () => {
    const glyphs = cidGlyphs();
    const { binary, subrMapOffset } = buildCidBinary({
      cidCount: 3,
      glyphs,
      subrs: [Uint8Array.from(charString("return"))],
    });
    const { program } = parseCidFont(
      cidFontSource({
        binary,
        cidCount: 0,
        subrMapOffset,
        subrCount: 1,
      })
    );
    expect(program).toBeNull();
  });

  it("returns null for an invalid GDBytes value", () => {
    const { binary, subrMapOffset } = buildCidBinary({
      cidCount: 3,
      glyphs: cidGlyphs(),
      gdBytes: 2,
      subrs: [Uint8Array.from(charString("return"))],
    });
    const { program } = parseCidFont(
      cidFontSource({
        binary,
        cidCount: 3,
        gdBytes: 0,
        subrMapOffset,
        subrCount: 1,
      })
    );
    expect(program).toBeNull();
  });

  it("returns null when the CIDMap does not fit in the data section", () => {
    const { binary } = buildCidBinary({
      cidCount: 3,
      glyphs: cidGlyphs(),
    });
    const truncated = binary.subarray(0, 6);
    const { program } = parseCidFont(
      cidFontSource({
        binary: truncated,
        cidCount: 3,
        subrCount: 0,
        declaredLength: truncated.length,
      })
    );
    expect(program).toBeNull();
  });

  it("returns null when a Subrs map is declared but missing", () => {
    const { binary } = buildCidBinary({
      cidCount: 3,
      glyphs: cidGlyphs(),
      subrs: [Uint8Array.from(charString("return"))],
    });
    const { program } = parseCidFont(
      cidFontSource({
        binary,
        cidCount: 3,
        subrMapOffset: -1,
        subrCount: 1,
      })
    );
    expect(program).toBeNull();
  });

  it("returns null for fonts selecting multiple font dictionaries", () => {
    const { binary, subrMapOffset } = buildCidBinary({
      cidCount: 3,
      glyphs: cidGlyphs(),
      subrs: [Uint8Array.from(charString("return"))],
      fdValues: [0, 1, 0],
    });
    const { program } = parseCidFont(
      cidFontSource({
        binary,
        cidCount: 3,
        subrMapOffset,
        subrCount: 1,
      })
    );
    expect(program).toBeNull();
  });

  it("returns null when the hex data section is incomplete", () => {
    const { binary, subrMapOffset } = buildCidBinary({
      cidCount: 3,
      glyphs: cidGlyphs(),
      subrs: [Uint8Array.from(charString("return"))],
    });
    const { program } = parseCidFont(
      cidFontSource({
        binary: toBytes(toHex(binary)),
        cidCount: 3,
        subrMapOffset,
        subrCount: 1,
        dataType: "Hex",
        declaredLength: binary.length * 2,
      })
    );
    expect(program).toBeNull();
  });
});
