  const plainProgram = buildFontProgram({
    glyphs: [{ name: "A", data: charString(0, 250, "hsbw", "endchar") }],
  });

  it("decrypts a binary eexec block", () => {
    const encrypted = encryptBytes(plainProgram, EEXEC_ENCRYPT_KEY, 4);
    // Make sure the payload really is auto-detected as binary data.
    expect(
      "0123456789abcdefABCDEF".includes(String.fromCharCode(encrypted[0]))
    ).toBe(false);
    const { program } = parseFontProgram(encrypted, { encrypted: true });
    expect(program.charstrings.map(g => g.glyphName)).toEqual(["A"]);
    expect(program.charstrings[0].width).toEqual(250);
  });

  it("decrypts a hex encoded eexec block", () => {
    const encrypted = encryptBytes(plainProgram, EEXEC_ENCRYPT_KEY, 4);
    let hex = toHex(encrypted);
    // Line breaks and other non hex characters must be tolerated.
    hex = hex.replace(/(.{32})/g, "$1\n");
    const { program } = parseFontProgram(toBytes(hex), { encrypted: true });
    expect(program.charstrings.map(g => g.glyphName)).toEqual(["A"]);
    expect(program.charstrings[0].width).toEqual(250);
  });

