describe("Type1Parser.extractFontProgram: robustness", () => {
  it("recovers when the ND token is missing before the next glyph", () => {
    const bytes = new ByteBuilder()
      .ascii("/lenIV -1 def\n/CharStrings 2 dict dup begin\n/A 4 RD ")
      .raw(NOTDEF_CHARSTRING)
      .ascii("/B 4 RD ")
      .raw(charString(0, 9, "hsbw", "endchar"))
      .ascii("\nND\nend\n")
      .build();
    const { program } = parseFontProgram(bytes);
    expect(program.charstrings.map(g => g.glyphName)).toEqual(["A", "B"]);
    expect(program.charstrings[1].width).toEqual(9);
    expect(program.charstrings[1].charstring).toEqual([
      ...type2Int(9),
      ...type2Int(0),
      22,
      14,
    ]);
  });

  it("warns about but ignores unknown charstring commands", () => {
    const warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
    try {
      const bytes = buildFontProgram({
        glyphs: [
          {
            name: "A",
            data: [...charString(0, 0, "hsbw"), 27, ...charString("endchar")],
          },
        ],
      });
      const { program } = parseFontProgram(bytes);
      expect(program.charstrings[0].charstring).toEqual([
        ...type2Int(0),
        ...type2Int(0),
        22,
        14,
      ]);
      expect(warnSpy).toHaveBeenCalledWith(
        expect.stringContaining('Unknown type 1 charstring command of "27"')
      );
    } finally {
      warnSpy.mockRestore();
    }
  });

  it("exposes the parsed subroutines on the returned program", () => {
    // `extractFontProgram` is documented to return a "Subrs array and a
    // CharStrings array", and `extractCidKeyedFontProgram` does fill in
    // `program.subrs`; the regular Type 1 path collects the subroutines but
    // never assigns them to the returned program. This assertion exposes
    // that defect and is expected to fail until the source is fixed.
    const bytes = buildFontProgram({
      glyphs: [{ name: "A", data: charString(0, 0, "hsbw", "endchar") }],
      subrs: [[...charString("return")]],
    });
    const { program } = parseFontProgram(bytes);
    expect(program.subrs).toHaveLength(1);
    expect([...program.subrs[0]]).toEqual([11]);
  });
});
