describe("PDFDataRangeTransport", () => {
  test("stores constructor data and applies documented defaults", () => {
    const data = new Uint8Array([1, 2, 3]);
    const transport = new PDFDataRangeTransport(100, data);

    expect(transport.length).toBe(100);
    expect(transport.initialData).toBe(data);
    expect(transport.progressiveDone).toBe(false);
    expect(transport.contentDispositionFilename).toBeNull();
  });

  test("forwards range, progressive-read, and progressive-done events", async () => {
    const transport = new PDFDataRangeTransport(10, null, true, "file.pdf");
    const listener = jest.fn();
    const chunk = new Uint8Array([7]);

    transport.transportReady(listener);
    transport.onDataRange(2, chunk);
    transport.onDataProgressiveRead(chunk);
    transport.onDataProgressiveDone();
    await Promise.resolve();

    expect(listener.mock.calls.map(([event]) => event)).toEqual([
      { type: "range", begin: 2, chunk },
      { type: "progressiveRead", chunk },
      { type: "progressiveDone" },
    ]);
  });

  test("queues progressive events until the transport is ready", async () => {
    const transport = new PDFDataRangeTransport(10, null);
    const listener = jest.fn();
    const chunk = new Uint8Array([9]);

    transport.onDataProgressiveRead(chunk);
    transport.onDataProgressiveDone();
    await Promise.resolve();
    expect(listener).not.toHaveBeenCalled();

    transport.transportReady(listener);
    await Promise.resolve();

    expect(listener).toHaveBeenNthCalledWith(1, {
      type: "progressiveRead",
      chunk,
    });
    expect(listener).toHaveBeenNthCalledWith(2, { type: "progressiveDone" });
  });

  test("requires subclasses to implement requestDataRange", () => {
    const transport = new PDFDataRangeTransport(10, null);

    expect(() => transport.requestDataRange(0, 5)).toThrow(
      "Abstract method PDFDataRangeTransport.requestDataRange"
    );
    expect(() => transport.abort()).not.toThrow();
  });
});

describe("PDFDocumentLoadingTask", () => {
  test("has unique ids and documented initial state", () => {
    const first = new PDFDocumentLoadingTask();
    const second = new PDFDocumentLoadingTask();

    expect(first.docId).toMatch(/^d\d+$/);
    expect(second.docId).toMatch(/^d\d+$/);
    expect(second.docId).not.toBe(first.docId);
    expect(first.destroyed).toBe(false);
    expect(first.onPassword).toBeNull();
    expect(first.onProgress).toBeNull();
    expect(first.promise).toBeInstanceOf(Promise);
  });

  test("getData delegates to the active transport", async () => {
    const task = new PDFDocumentLoadingTask();
    const data = new Uint8Array([1, 2]);
    task._transport = { getData: jest.fn().mockResolvedValue(data) };

    await expect(task.getData()).resolves.toBe(data);
    expect(task._transport.getData).toHaveBeenCalledTimes(1);
  });

  test("destroy marks the worker synchronously, then tears everything down", async () => {
    const task = new PDFDocumentLoadingTask();
    const transport = { destroy: jest.fn().mockResolvedValue() };
    const worker = { destroy: jest.fn(), port: {} };
    const rendererWorker = { destroy: jest.fn() };
    task._transport = transport;
    task._worker = worker;
    task._rendererWorker = rendererWorker;

    const destroyPromise = task.destroy();

    expect(task.destroyed).toBe(true);
    expect(worker._pendingDestroy).toBe(true);

    task._setupCapability.resolve();
    await destroyPromise;

    expect(transport.destroy).toHaveBeenCalledTimes(1);
    expect(worker.destroy).toHaveBeenCalledTimes(1);
    expect(rendererWorker.destroy).toHaveBeenCalledTimes(1);
    expect(task._transport).toBeNull();
    expect(task._worker).toBeNull();
    expect(task._rendererWorker).toBeNull();
  });

  test("destroy restores the pending-destroy marker when transport cleanup fails", async () => {
    const task = new PDFDocumentLoadingTask();
    const error = new Error("cleanup failed");
    const transport = { destroy: jest.fn().mockRejectedValue(error) };
    const worker = { destroy: jest.fn(), port: {} };
    const rendererWorker = { destroy: jest.fn() };
    task._transport = transport;
    task._worker = worker;
    task._rendererWorker = rendererWorker;
    task._setupCapability.resolve();

    await expect(task.destroy()).rejects.toBe(error);

    expect(worker._pendingDestroy).toBeUndefined();
    expect(worker.destroy).not.toHaveBeenCalled();
    expect(rendererWorker.destroy).not.toHaveBeenCalled();
    expect(task._transport).toBe(transport);
    expect(task._worker).toBe(worker);
  });
});

