describe("RenderTask", () => {
  function makeRenderTask(overrides = {}) {
    const capability = Promise.withResolvers();
    const internalRenderTask = {
      capability,
      annotationCanvasMap: null,
      cancel: jest.fn(),
      imageCoordinates: undefined,
      isWorkerRendering: false,
      operatorList: {
        argsArray: [],
        fnArray: [],
        lastChunk: false,
        separateAnnots: null,
      },
      ...overrides,
    };
    return { internalRenderTask, task: new RenderTask(internalRenderTask) };
  }

  test("exposes the internal completion promise and operator list", async () => {
    const { internalRenderTask, task } = makeRenderTask();
    internalRenderTask.capability.resolve("rendered");

    expect(task.promise).toBe(internalRenderTask.capability.promise);
    await expect(task.promise).resolves.toBe("rendered");
    expect(task.getOperatorList()).toBe(internalRenderTask.operatorList);
    expect(task.isWorkerRendering).toBe(false);
  });

