    const { internalRenderTask, task } = makeRenderTask();

    task.cancel();
    task.cancel(40);

    expect(internalRenderTask.cancel.mock.calls).toEqual([
      [null, 0],
      [null, 40],
    ]);
  });

  test("derives separateAnnots from form and canvas annotation state", () => {
