  test("initializes from a supplied port and configures the worker", async () => {
    const { port, worker } = await createWorker(3);

    expect(worker.port).toBe(port);
    expect(worker.messageHandler).not.toBeNull();
    expect(worker.destroyed).toBe(false);
    expect(port.messages).toContainEqual(
      expect.objectContaining({
        action: "configure",
        data: { verbosity: 3 },
        sourceName: "main",
        targetName: "worker",
      })
    );

    worker.destroy();
  });

  test("caches one worker per port and rejects port reuse", async () => {
    const { port, worker } = await createWorker(1);

    expect(PDFWorker.create({ port })).toBe(worker);
    expect(() => new PDFWorker({ port })).toThrow(
      "Cannot use more than one PDFWorker per port."
    );

    worker.destroy();
  });

  test("rejects creation from a port whose worker is being destroyed", async () => {
    const { port, worker } = await createWorker(1);
    worker._pendingDestroy = true;

    expect(() => PDFWorker.create({ port })).toThrow("being destroyed");

    worker.destroy();
  });

  test("destroy releases the port and allows a replacement worker", async () => {
    const { port, worker } = await createWorker(1);

    worker.destroy();

    expect(worker.destroyed).toBe(true);
    expect(worker.port).toBeNull();
    expect(worker.messageHandler).toBeNull();

    const replacement = PDFWorker.create({ port });
    expect(replacement).not.toBe(worker);
    await replacement.promise;
    replacement.destroy();
  });

  test("workerSrc requires and returns the global worker source", () => {
    const previous = GlobalWorkerOptions.workerSrc;
    try {
      GlobalWorkerOptions.workerSrc = "";
      expect(() => PDFWorker.workerSrc).toThrow(
        'No "GlobalWorkerOptions.workerSrc" specified.'
      );

      GlobalWorkerOptions.workerSrc = "/assets/pdf.worker.mjs";
      expect(PDFWorker.workerSrc).toBe("/assets/pdf.worker.mjs");
    } finally {
      GlobalWorkerOptions.workerSrc = previous;
    }
  });
});

