import { describe, expect, jest, test } from "@jest/globals";

// The production code targets a runtime with the Map upsert proposal. The
// Jest-supported Node runtime may not expose it yet.
if (typeof Map.prototype.getOrInsertComputed !== "function") {
  Object.defineProperty(Map.prototype, "getOrInsertComputed", {
    configurable: true,
    value(key, callback) {
      if (!this.has(key)) {
        this.set(key, callback(key));
      }
      return this.get(key);
    },
  });
}

// The source is normally bundled with build-time constants. Keep the test
// deterministic, and make the testing-only branches available.
globalThis.PDFJSDev = {
  test(expr) {
    const flags = new Set(["GENERIC", "TESTING"]);
    return expr
      .split("||")
      .map(value => value.trim())
      .some(flag => flags.has(flag));
  },
  eval(name) {
    return `test-${name}`;
  },
};

const {
  build,
