  await import("../../src/display/worker_options.js");

class FakePort {
  messages = [];

  listeners = new Map();

  addEventListener(type, listener) {
    this.listeners.set(listener, type);
  }

  removeEventListener(type, listener) {
    this.listeners.delete(listener);
  }

  postMessage(message) {
    this.messages.push(message);
  }
}

async function createWorker(verbosity) {
  const port = new FakePort();
  const worker = new PDFWorker({ port, verbosity });
  await worker.promise;
  return { port, worker };
