function built(lines,{w=100,h=100,scale=1,rotation=0,thickness=0,innerMargin=0}={}) {
 const x = new InkDrawOutline(); x.build(lines,w,h,scale,rotation,thickness,innerMargin); return x;
}
const ob = built([elem12]);
show('built box', Array.from(ob.box));
show('built vb', ob.viewBox);
