show('line box after', Array.from(oline.box));
show('line path after', oline.toSVGPath());
show('line defaultsvg', oline.defaultSVGProperties);
const orot=built([elem12],{rotation:0});
for(const r of [0,90,180,270]) show('updateRotation '+r, orot.updateRotation(r));
