{"command": "node --input-type=module <<'EOF'
import { InkDrawOutline, InkDrawOutliner } from './src/display/editor/drawers/inkdraw.js';
const show = (label, v) => console.log(label, JSON.stringify(v, (_k, x) => typeof x === 'number' && Number.isNaN(x) ? 'NaN' : x));
const line12 = new Float32Array([NaN,NaN,NaN,NaN,0.2,0.1, NaN,NaN,NaN,NaN,0.4,0.5]);
const elem12={line:line12, points:new Float32Array([0.2,0.1,0.4,0.5])};
function built(lines,{w=100,h=100,scale=1,rotation=0,thickness=0,innerMargin=0}={}) { const x = new InkDrawOutline(); x.build(lines,w,h,scale,rotation,thickness,innerMargin); return x; }
for(const rotation of [0,90,180,270]) {
  const x=built([elem12],{rotation});
  const ser=x.serialize([10,20,200,100],false);
  const back=InkDrawOutline.deserialize(10,20,200,100,0,{paths:ser,rotation,thickness:0});
  show('roundtrip '+rotation+' box', Array.from(back.box));
  show('roundtrip '+rotation+' path', back.toSVGPath());
  show('roundtrip '+rotation+' origpath', x.toSVGPath());
  show('roundtrip '+rotation+' thickness', back.thickness);
}
const p2=InkDrawOutline.deserialize(0,0,100,100,0,{paths:{points:[[50,50]]},rotation:0,thickness:0});
show('des p2 box', Array.from(p2.box));
show('des p2 path', p2.toSVGPath());
const p4=InkDrawOutline.deserialize(0,0,100,100,0,{paths:{points:[[20,10,40,50]]},rotation:0,thickness:0});
show('des p4 box', Array.from(p4.box));
show('des p4 path', p4.toSVGPath());
const p6=InkDrawOutline.deserialize(0,0,100,100,0,{paths:{points:[[0,0,25,0,50,0]]},rotation:0,thickness:0});
show('des p6 box', Array.from(p6.box));
show('des p6 path', p6.toSVGPath());
show('des p6 def', p6.defaultSVGProperties);
const empty=InkDrawOutline.deserialize(0,0,100,100,0,{paths:{lines:[],points:[]},rotation:0,thickness:3});
show('des empty box', Array.from(empty.box));
show('des empty path', empty.toSVGPath());
show('des empty vb', empty.viewBox);
show('des empty prop', empty.defaultProperties);

const o = new InkDrawOutliner(10,10,100,100,0,4);
o.add(40,40); o.end();
const finished=o.getOutlines(100,100,1,0);
show('finished path', finished.toSVGPath());
show('finished box', Array.from(finished.box));
const saved = {line:new Float32Array([NaN,NaN,NaN,NaN,.6,.6,NaN,NaN,NaN,NaN,.8,.8]), points:new Float32Array([.6,.6,.8,.8])};
show('outliner set after getoutline', o.setLastElement(saved));
show('finished path after set', finished.toSVGPath());
show('outliner remove after getoutline', o.removeLastElement());
show('finished path after remove', finished.toSVGPath());

const oo = new InkDrawOutliner(10,10,100,100,0,4);
const elem=oo.getLastElement();
show('setLast same', oo.setLastElement({line:new Float32Array(elem.line), points:new Float32Array(elem.points)}));
show('path after set same', oo.toSVGPath());
show('last el line type', oo.getLastElement().line.constructor.name);
show('last el points type', oo.getLastElement().points.constructor.name);

const ostart = new InkDrawOutliner(10,10,100,100,0,4);
const first=ostart.getLastElement();
ostart.add(20,10);
show('startNew result', ostart.startNew(30,30,200,100,90));
show('first after snapshot types', [first.line.constructor.name, first.points.constructor.name]);
show('first line after snapshot', Array.from(first.line));
const last=ostart.getLastElement();
show('new start normalized', Array.from(last.line));
show('new points normalized', Array.from(last.points));

const oup = new InkDrawOutliner(10,10,100,100,0,4);
show('update prop irrelevant', oup.updateProperty('foo',10));
oup.updateProperty('stroke-width',10);
const upOut=oup.getOutlines(100,100,1,0);
show('thickness after update', upOut.thickness);
show('box after update', Array.from(upOut.box));
EOF"}

