import { InkDrawOutline, InkDrawOutliner } from "../../../../src/display/editor/drawers/inkdraw.js";

function expectCloseArray(actual, expected, precision = 5) {
  expect(actual).toHaveLength(expected.length);
  for (let i = 0; i < expected.length; i++) {
    expect(actual[i]).toBeCloseTo(expected[i], precision);
  }
}

function dotElement(x, y) {
  return {
    line: new Float32Array([NaN, NaN, NaN, NaN, x, y]),
    points: new Float32Array([x, y]),
  };
}

function segmentElement(x1, y1, x2, y2) {
  return {
    line: new Float32Array([
      NaN,
      NaN,
      NaN,
      NaN,
      x1,
      y1,
      NaN,
      NaN,
      NaN,
      NaN,
      x2,
      y2,
    ]),
    points: new Float32Array([x1, y1, x2, y2]),
  };
}

function curveElement(x1, y1, c1x, c1y, c2x, c2y, x2, y2) {
  return {
    line: new Float32Array([
      NaN,
      NaN,
      NaN,
      NaN,
      x1,
      y1,
      c1x,
      c1y,
      c2x,
      c2y,
      x2,
      y2,
    ]),
    points: new Float32Array([x1, y1, x2, y2]),
  };
}

function buildOutline(
  lines,
  {
    parentWidth = 100,
    parentHeight = 100,
    parentScale = 1,
    rotation = 0,
    thickness = 0,
    innerMargin = 0,
  } = {}
) {
  const outline = new InkDrawOutline();
  outline.build(
    lines,
    parentWidth,
    parentHeight,
    parentScale,
    rotation,
    thickness,
    innerMargin
  );
  return outline;
}

describe("InkDrawOutliner", () => {
  it("starts with one normalized point and exposes its default SVG contract", () => {
    const outliner = new InkDrawOutliner(10, 20, 100, 200, 0, 4);

    expect(outliner.isEmpty()).toBe(false);
    expect(outliner.isCancellable()).toBe(true);
    expect(outliner.getLastElement().points).toEqual(
      new Float32Array([0.1, 0.1])
    );
    expect(outliner.defaultSVGProperties).toEqual({
      root: { viewBox: "0 0 10000 10000" },
      rootClass: { draw: true },
      bbox: [0, 0, 1, 1],
    });
  });

  it("normalizes the starting point for every supported rotation", () => {
    const cases = [
      [0, [0.1, 0.1]],
      [90, [0.8, 0.05]],
      [180, [0.9, 0.9]],
      [270, [0.1, 0.95]],
    ];

    for (const [rotation, expected] of cases) {
      const outliner = new InkDrawOutliner(10, 20, 100, 200, rotation, 2);
      expectCloseArray(outliner.getLastElement().points, expected);
    }
  });

  it("ignores input within two canvas pixels but still exposes the input tip", () => {
    const outliner = new InkDrawOutliner(0, 0, 100, 100, 0, 2);

    const rejected = outliner.add(2, 0);
    expect(rejected.path.d).toBe(" M 0 0 L 200 0");
    expect(outliner.getLastElement().points).toEqual(new Float32Array([0, 0]));
    expect(outliner.isCancellable()).toBe(true);

    const accepted = outliner.add(2.5, 0);
    expect(accepted.path.d).toBe(" M 0 0 L 200 0 L 250 0");
    expect(outliner.getLastElement().points).toEqual(
      new Float32Array([0, 0, 0.025, 0])
    );
  });

  it("adds a point, renders a transient tip, and removes the tip when ending", () => {
    const outliner = new InkDrawOutliner(10, 10, 100, 100, 0, 4);

    expect(outliner.add(20, 10).path.d).toBe(
      " M 1000 1000 L 2000 1000 L 2000 1000"
    );
    expect(outliner.end().path.d).toBe(" M 1000 1000 L 2000 1000");
  });

  it("ends a single-point drawing with a closed dot path", () => {
    const outliner = new InkDrawOutliner(10, 10, 100, 100, 0, 4);
    expect(outliner.end().path.d).toBe(" M 1000 1000 Z");
  });

  it("adds a final accepted point on end without retaining the transient tip", () => {
    const outliner = new InkDrawOutliner(0, 0, 100, 100, 0, 2);
    outliner.add(10, 0);

    expect(outliner.end(20, 0).path.d).toBe(
      "  M 0 0C833 0 1167 0 1500 0"
    );
  });

  it("does not extend an existing path when end receives a rejected point", () => {
    const outliner = new InkDrawOutliner(0, 0, 100, 100, 0, 2);
    outliner.add(10, 0);

    expect(outliner.end(11, 0).path.d).toBe(" M 0 0 L 1000 0");
  });

  it("accepts batched points and maintains all generated curve segments", () => {
    const outliner = new InkDrawOutliner(0, 0, 100, 100, 0, 4);

    const result = outliner.addPoints([10, 0, 20, 0, 30, 0, 40, 0]);

    expect(result.path.d.match(/C/g)).toHaveLength(3);
    expect(result.path.d).toContain("C833 0 1167 0 1500 0");
    expect(result.path.d.endsWith("L 4000 0")).toBe(true);
    expect(outliner.getLastElement().points).toHaveLength(8);

    const ended = outliner.end();
    expect(ended.path.d.endsWith("3500 0")).toBe(true);
    expect(ended.path.d.endsWith("L 4000 0")).toBe(false);
  });

  it("does not grow when a batched point duplicates the last accepted point", () => {
    const outliner = new InkDrawOutliner(0, 0, 100, 100, 0, 4);
    outliner.addPoints([10, 0, 20, 0]);

    const before = [...outliner.getLastElement().points];
    const result = outliner.addPoints([20, 0, 20.5, 0]);

    expect(outliner.getLastElement().points).toEqual(
      new Float32Array(before)
    );
    expect(result.path.d).not.toContain("2050");
  });

  it("is cancellable up to ten stored coordinates and not beyond", () => {
    const outliner = new InkDrawOutliner(0, 0, 100, 100, 0, 2);

    for (let i = 1; i <= 4; i++) {
      outliner.add(i * 10, 0);
    }
    expect(outliner.getLastElement().points).toHaveLength(10);
    expect(outliner.isCancellable()).toBe(true);

    outliner.add(50, 0);
    expect(outliner.isCancellable()).toBe(false);
  });

  it("starts a new subpath, snapshots the previous one, and uses new dimensions", () => {
    const outliner = new InkDrawOutliner(10, 10, 100, 100, 0, 4);
    outliner.add(20, 10);
    const first = outliner.getLastElement();

    expect(outliner.startNew(30, 30, 200, 100, 90)).toBeNull();

    expect(first.line).toBeInstanceOf(Float32Array);
    expect(first.points).toBeInstanceOf(Float32Array);
    expectCloseArray(first.points, [0.1, 0.1, 0.2, 0.1]);
    expectCloseArray(outliner.getLastElement().points, [0.85, 0.3]);

    outliner.add(40, 30);
    expect(outliner.toSVGPath()).toBe(
      " M 8500 3000 L 8500 4000 M 8500 3000 L 8500 4000"
    );
  });

  it("appends a replacement element and switches drawing to it", () => {
    const outliner = new InkDrawOutliner(10, 10, 100, 100, 0, 4);
    expect(outliner.toSVGPath()).toBe(" M 1000 1000 Z");

    const replacement = segmentElement(0.2, 0.3, 0.4, 0.5);
    const result = outliner.setLastElement(replacement);

    expect(result.path.d).toBe(
      " M 1000 1000 Z M 2000 3000 L 4000 5000"
    );
    expect(outliner.getLastElement()).toBe(replacement);
    expect(outliner.toSVGPath()).toBe(result.path.d);
  });

  it("removes subpaths and replays the remaining path", () => {
    const outliner = new InkDrawOutliner(10, 10, 100, 100, 0, 2);
    outliner.add(20, 10);
    outliner.startNew(30, 30, 100, 100, 0);
    outliner.add(40, 30);

    expect(outliner.removeLastElement().path.d).toBe(
      " M 1000 1000 L 2000 1000"
    );
    expect(outliner.removeLastElement().path.d).toBe("");
    expect(outliner.isEmpty()).toBe(true);
  });

  it("builds a completed outline with the selected stroke width and resets itself", () => {
    const outliner = new InkDrawOutliner(10, 10, 100, 100, 0, 2);
    expect(outliner.updateProperty("color", "red")).toBeUndefined();
    outliner.updateProperty("stroke-width", 10);

    const outline = outliner.getOutlines(100, 100, 1, 0);

    expect(outline).toBeInstanceOf(InkDrawOutline);
    expect(outline.thickness).toBe(10);
    expect(outline.toSVGPath()).toBe("M1000 1000Z");
    expectCloseArray(outline.box, [0.05, 0.05, 0.1, 0.1]);
    expect(outliner.isEmpty()).toBe(true);
  });

  it("delegates post-completion element changes to the built outline", () => {
    const outliner = new InkDrawOutliner(10, 10, 100, 100, 0, 4);
    outliner.add(40, 40);
    outliner.end();
    const outline = outliner.getOutlines(100, 100, 1, 0);

    const inserted = outliner.setLastElement(
      segmentElement(0.6, 0.6, 0.8, 0.8)
    );
    expect(inserted.path.d).toBe(
      "M1000 1000L4000 4000M6000 6000L8000 8000"
    );
    expect(outline.toSVGPath()).toBe(inserted.path.d);

    expect(outliner.removeLastElement().path.d).toBe(
      "M1000 1000L4000 4000"
    );
    expect(outline.toSVGPath()).toBe("M1000 1000L4000 4000");
  });
});

describe("InkDrawOutline", () => {
  it("computes a bounding box, viewBox, and path for a segment", () => {
    const outline = buildOutline([segmentElement(0.2, 0.1, 0.4, 0.5)]);

    expectCloseArray(outline.box, [0.2, 0.1, 0.2, 0.4]);
    expect(outline.viewBox).toBe("2000 1000 2000 4000");
    expect(outline.toSVGPath()).toBe("M2000 1000L4000 5000");
    expect(outline.defaultProperties).toEqual({
      root: { viewBox: "2000 1000 2000 4000" },
      path: { "transform-origin": "2000 1000" },
    });
  });

  it("formats one-point and cubic-curve geometry", () => {
    const dot = buildOutline([dotElement(0.5, 0.5)]);
    expect(dot.toSVGPath()).toBe("M5000 5000Z");
    expectCloseArray(dot.box, [0.5, 0.5, 0, 0]);

    const curve = buildOutline([
      curveElement(0.2, 0.2, 0.2, 0.2, 0.8, 0.2, 0.4, 0.2),
    ]);
    expect(curve.toSVGPath()).toBe("M2000 2000C2000 2000 8000 2000 4000 2000");
    expectCloseArray(curve.box, [0.2, 0.2, 0.2, 0]);
  });

  it("expands and clamps the bounding box by the stroke margin", () => {
    const outline = buildOutline([segmentElement(0.2, 0.1, 0.4, 0.5)], {
      thickness: 20,
    });

    expect(outline.thickness).toBe(20);
    expectCloseArray(outline.box, [0.1, 0, 0.4, 0.6]);
  });

  it("swaps margin axes for rotated drawings", () => {
    const outline = buildOutline([segmentElement(0.2, 0.1, 0.4, 0.5)], {
      parentWidth: 200,
      parentHeight: 100,
      rotation: 90,
      thickness: 20,
