    expect(result.path.d).toBe("M1000 2000L3000 6000");
    expect(result.path["transform-origin"]).toBe("1000 2000");
    expectCloseArray(outline.box, [0.1, 0.2, 0.2, 0.4]);
  });

  it("rescales geometry when moving to differently sized parents", () => {
    const outline = buildOutline([segmentElement(0.2, 0.1, 0.4, 0.5)]);

    const result = outline.getPathTranslatedSVGProperties(
      [0.1, 0.2],
      [200, 100]
    );

    expect(result.root.viewBox).toBe("1000 2000 1000 4000");
    expect(result.path.d).toBe("M0 2000L1000 6000");
    expectCloseArray(outline.box, [0.1, 0.2, 0.1, 0.4]);
  });

  it("exposes the complete default SVG properties", () => {
    const outline = buildOutline([segmentElement(0.2, 0.1, 0.4, 0.5)]);

    const properties = outline.defaultSVGProperties;

    expect(properties.root).toEqual({ viewBox: "2000 1000 2000 4000" });
    expect(properties.rootClass).toEqual({ draw: true });
    expect(properties.path).toEqual({
      d: "M2000 1000L4000 5000",
      "transform-origin": "2000 1000",
      transform: null,
    });
    expect(properties.bbox).toBe(outline.box);
  });
});
