    if (args.length === 1) {
      const { a, b, c, d, e, f } = args[0];
      ctx._transform = createMatrix(a, b, c, d, e, f);
    } else {
      ctx._transform = createMatrix(...args);
    }
  };
  ctx.transform = (...args) => {
    calls.push({ name: "transform", args });
    ctx._transform.multiplySelf(createMatrix(...args));
  };
  ctx.resetTransform = () => {
    calls.push({ name: "resetTransform", args: [] });
    ctx._transform = createMatrix();
  };
  ctx.scale = (x, y) => {
    calls.push({ name: "scale", args: [x, y] });
    ctx._transform.scale(x, y);
  };
  ctx.translate = (x, y) => {
    calls.push({ name: "translate", args: [x, y] });
    ctx._transform.translate(x, y);
  };
  ctx.rotate = angle => {
    calls.push({ name: "rotate", args: [angle] });
  };
  ctx.save = () => {
    calls.push({ name: "save", args: [] });
    const snapshot = {};
    for (const key of CONTEXT_PROPERTIES) {
      snapshot[key] = ctx[key];
    }
    snapshot.transform = createMatrix(
      ctx._transform.a,
      ctx._transform.b,
      ctx._transform.c,
      ctx._transform.d,
      ctx._transform.e,
      ctx._transform.f
    );
    snapshot.lineDash = lineDash.slice();
    stateStack.push(snapshot);
  };
  ctx.restore = () => {
    calls.push({ name: "restore", args: [] });
    const snapshot = stateStack.pop();
    if (!snapshot) {
      return;
    }
    for (const key of CONTEXT_PROPERTIES) {
      ctx[key] = snapshot[key];
    }
    ctx._transform = createMatrix(
      snapshot.transform.a,
      snapshot.transform.b,
      snapshot.transform.c,
      snapshot.transform.d,
      snapshot.transform.e,
      snapshot.transform.f
    );
    lineDash = snapshot.lineDash.slice();
  };
  ctx.setLineDash = dash => {
    calls.push({ name: "setLineDash", args: [dash] });
    lineDash = dash.slice();
  };
  ctx.getLineDash = () => lineDash.slice();
  ctx.createImageData = (w, h) => ({
    width: w,
    height: h,
    data: new Uint8ClampedArray(w * h * 4),
  });
  ctx.measureText = text => ({
    width: text.length * 10,
    actualBoundingBoxLeft: 0,
    actualBoundingBoxRight: text.length * 10,
    actualBoundingBoxAscent: 10,
    actualBoundingBoxDescent: 2,
  });

  const simple = name => {
    ctx[name] = (...args) => {
      calls.push({ name, args });
    };
  };
  for (const name of [
    "fillRect",
    "clearRect",
    "beginPath",
    "closePath",
    "rect",
    "moveTo",
    "lineTo",
    "bezierCurveTo",
    "quadraticCurveTo",
    "arc",
    "arcTo",
    "ellipse",
    "roundRect",
    "putImageData",
    "fillText",
    "strokeText",
  ]) {
    simple(name);
  }
  ctx.fill = (...args) => {
    calls.push({
      name: "fill",
      args,
      fillStyle: ctx.fillStyle,
      globalAlpha: ctx.globalAlpha,
    });
  };
  ctx.stroke = (...args) => {
    calls.push({
      name: "stroke",
      args,
      lineWidth: ctx.lineWidth,
      lineDash: lineDash.slice(),
      lineDashOffset: ctx.lineDashOffset,
      globalAlpha: ctx.globalAlpha,
    });
  };
  ctx.clip = (...args) => {
    calls.push({ name: "clip", args });
  };
  ctx.drawImage = (...args) => {
    calls.push({ name: "drawImage", args });
  };
  ctx.fillRect = (...args) => {
    calls.push({ name: "fillRect", args, fillStyle: ctx.fillStyle });
  };

  return ctx;
}

function createCanvasFactory() {
  const created = [];
  const destroyed = [];
  return {
    created,
    destroyed,
    create: jest.fn((width, height) => {
      const context = createMockContext(width, height);
      const entry = { canvas: context.canvas, context };
      created.push(entry);
      return entry;
    }),
    destroy: jest.fn(entry => {
      destroyed.push(entry);
    }),
    reset: jest.fn((entry, width, height) => {
      entry.canvas.width = width;
      entry.canvas.height = height;
      entry.context.canvas.width = width;
      entry.context.canvas.height = height;
    }),
  };
}

function createObjectStore(entries = {}) {
  return {
    has: jest.fn(id => Object.prototype.hasOwnProperty.call(entries, id)),
    get: jest.fn(id => entries[id]),
  };
}

function createDependencyTracker() {
  const tracker = {
    clipBox: [0, 0, 100, 100],
  };
  for (const name of [
    "save",
    "restore",
    "recordSimpleData",
    "recordSimpleDataFromNamed",
    "recordDependencies",
    "recordOperation",
    "recordNamedDependency",
    "recordNamedData",
    "recordOpenMarker",
    "resetIncrementalData",
    "recordIncrementalData",
    "beginMarkedContent",
    "endMarkedContent",
    "resetBBox",
    "recordBBox",
    "recordClipBox",
    "recordFutureForcedDependency",
    "recordShowTextOperation",
    "recordCharacterBBox",
    "inheritPendingDependenciesAsFutureForcedDependencies",
    "bboxToClipBoxDropOperation",
    "popBaseTransform",
    "pushBaseTransform",
  ]) {
    tracker[name] = jest.fn(() => tracker);
  }
  tracker.getSimpleIndex = jest.fn(() => 0);
  tracker.getOpenMarker = jest.fn(() => 0);
  return tracker;
}

function createFilterFactory() {
  return {
    addFilter: jest.fn(() => "none"),
    addHCMFilter: jest.fn(() => "none"),
  };
}

function createGraphics(options = {}) {
  const width = options.width ?? 100;
  const height = options.height ?? 100;
  const ctx = options.ctx ?? createMockContext(width, height);
  const canvasFactory = options.canvasFactory ?? createCanvasFactory();
  const commonObjs =
    options.commonObjs?.get && options.commonObjs?.has
      ? options.commonObjs
      : createObjectStore(options.commonObjs);
  const objs =
    options.objs?.get && options.objs?.has
      ? options.objs
      : createObjectStore(options.objs);
  const filterFactory = options.filterFactory ?? createFilterFactory();
  const optionalContentConfig = options.optionalContentConfig ?? {
    isVisible: jest.fn(() => true),
  };
  const graphics = new CanvasGraphics(
    ctx,
    commonObjs,
    objs,
    canvasFactory,
    filterFactory,
    {
      optionalContentConfig,
      markedContentStack: options.markedContentStack ?? [],
      pixelRatio: options.pixelRatio ?? 1,
    },
    options.annotationCanvasMap,
    options.pageColors ?? null,
    options.dependencyTracker ?? null,
    options.imagesTracker ?? null
  );
  return {
    graphics,
    ctx,
    canvasFactory,
    commonObjs,
    objs,
    filterFactory,
    optionalContentConfig,
  };
}

function callsOf(ctx, name) {
  return ctx.calls.filter(call => call.name === name);
}

function makeFont(overrides = {}) {
  return {
    fontMatrix: [0.001, 0, 0, 0.001, 0, 0],
    loadedName: "F1",
    fallbackName: "sans-serif",
    vertical: false,
    disableFontFace: false,
    missingFile: false,
    isType3Font: false,
    ...overrides,
  };
}

function setFont(graphics, font = makeFont(), size = 10) {
  graphics.commonObjs.get.mockReturnValue(font);
  graphics.setFont(0, "F1", size);
  return font;
}

let originalMapGetOrInsertComputed;
let originalWeakMapGetOrInsertComputed;
let originalPath2D;
let originalDOMMatrix;

beforeAll(() => {
  originalMapGetOrInsertComputed = Map.prototype.getOrInsertComputed;
  originalWeakMapGetOrInsertComputed = WeakMap.prototype.getOrInsertComputed;
  originalPath2D = globalThis.Path2D;
  originalDOMMatrix = globalThis.DOMMatrix;

  const install = proto => {
    if (typeof proto.getOrInsertComputed !== "function") {
      Object.defineProperty(proto, "getOrInsertComputed", {
        configurable: true,
        writable: true,
        value(key, callback) {
          if (!this.has(key)) {
            this.set(key, callback(key));
          }
          return this.get(key);
        },
      });
    }
  };
  install(Map.prototype);
  install(WeakMap.prototype);
  globalThis.Path2D = FakePath2D;
  globalThis.DOMMatrix = FakeDOMMatrix;
});

afterAll(() => {
  if (originalMapGetOrInsertComputed === undefined) {
    delete Map.prototype.getOrInsertComputed;
  } else {
    Map.prototype.getOrInsertComputed = originalMapGetOrInsertComputed;
  }
  if (originalWeakMapGetOrInsertComputed === undefined) {
    delete WeakMap.prototype.getOrInsertComputed;
  } else {
    WeakMap.prototype.getOrInsertComputed = originalWeakMapGetOrInsertComputed;
  }
  if (originalPath2D === undefined) {
    delete globalThis.Path2D;
  } else {
    globalThis.Path2D = originalPath2D;
  }
  if (originalDOMMatrix === undefined) {
    delete globalThis.DOMMatrix;
  } else {
    globalThis.DOMMatrix = originalDOMMatrix;
  }
});

