describe("getObject", () => {
  test("resolves common and page object references", () => {
    const commonObject = { kind: "common" };
    const pageObject = { kind: "page" };
    const commonObjs = createObjectStore({ g_font: commonObject });
    const objs = createObjectStore({ img_1: pageObject });
    const tracker = createDependencyTracker();
    const { graphics } = createGraphics({
      commonObjs,
      objs,
      dependencyTracker: tracker,
    });

    expect(graphics.getObject(3, "g_font")).toBe(commonObject);
    expect(commonObjs.get).toHaveBeenCalledWith("g_font");
    expect(objs.get).not.toHaveBeenCalled();

    expect(graphics.getObject(4, "img_1")).toBe(pageObject);
    expect(objs.get).toHaveBeenCalledWith("img_1");
    expect(tracker.recordNamedDependency).toHaveBeenCalledWith(4, "img_1");
  });

  test("returns the supplied fallback for non-string data", () => {
    const { graphics } = createGraphics();
    const fallback = { fallback: true };

    expect(graphics.getObject(0, { data: true }, fallback)).toBe(fallback);
    expect(graphics.getObject(0, null)).toBeNull();
  });
});

describe("executeOperatorList", () => {
  test("returns immediately for an empty operator list", () => {
    const { graphics } = createGraphics();
    expect(
      graphics.executeOperatorList(
        { argsArray: [], fnArray: [], pathCache: new Map() },
        0
      )
    ).toBe(0);
  });

  test("dispatches operators and returns the next execution index", () => {
    const { graphics, ctx } = createGraphics();
    const operatorList = {
      argsArray: [[4], [2, 0, 0, 2, 10, 20], ["#ff0000"]],
      fnArray: [OPS.setLineWidth, OPS.transform, OPS.setFillRGBColor],
      pathCache: new Map(),
    };

    expect(graphics.executeOperatorList(operatorList, 0)).toBe(3);
    expect(ctx.lineWidth).toBe(4);
    expect(ctx.getTransform()).toMatchObject({ a: 2, b: 0, c: 0, d: 2, e: 10, f: 20 });
    expect(graphics.current.fillColor).toBe("#ff0000");
    expect(ctx.fillStyle).toBe("#ff0000");
  });

  test("honors the execution start index", () => {
    const { graphics, ctx } = createGraphics();
    const operatorList = {
      argsArray: [[9], [2]],
      fnArray: [OPS.setLineWidth, OPS.setLineWidth],
      pathCache: new Map(),
    };

    expect(graphics.executeOperatorList(operatorList, 1)).toBe(2);
    expect(ctx.lineWidth).toBe(2);
  });

  test("defers unresolved dependencies and forwards the continuation callbacks", () => {
    const continueCallback = jest.fn();
    const errorCallback = jest.fn();
    const objs = createObjectStore({});
    const { graphics, ctx } = createGraphics({ objs });
    const operatorList = {
      argsArray: [["img_5"], [3]],
      fnArray: [OPS.dependency, OPS.setLineWidth],
      pathCache: new Map(),
    };

    expect(
      graphics.executeOperatorList(
        operatorList,
        0,
        continueCallback,
        errorCallback
      )
    ).toBe(0);
    expect(objs.has).toHaveBeenCalledWith("img_5");
    expect(objs.get).toHaveBeenCalledWith(
      "img_5",
      continueCallback,
      errorCallback
    );
    expect(ctx.lineWidth).toBe(1);
  });

  test("routes global dependencies to the common object store", () => {
    const commonObjs = createObjectStore({ g_font: {} });
    const objs = createObjectStore({});
    const { graphics } = createGraphics({ commonObjs, objs });
    const operatorList = {
      argsArray: [["g_font"]],
      fnArray: [OPS.dependency],
      pathCache: new Map(),
    };

    expect(graphics.executeOperatorList(operatorList, 0)).toBe(1);
    expect(commonObjs.has).toHaveBeenCalledWith("g_font");
    expect(objs.has).not.toHaveBeenCalled();
  });

  test("supports a stepper break point", () => {
    const continueCallback = jest.fn();
    const stepper = {
      nextBreakPoint: 1,
      breakIt: jest.fn(),
      shouldSkip: jest.fn(() => false),
    };
    const { graphics, ctx } = createGraphics();
    const operatorList = {
      argsArray: [[5], [7]],
      fnArray: [OPS.setLineWidth, OPS.setLineWidth],
      pathCache: new Map(),
    };

    expect(
      graphics.executeOperatorList(
        operatorList,
        0,
        continueCallback,
        undefined,
        stepper
      )
    ).toBe(1);
    expect(stepper.breakIt).toHaveBeenCalledWith(1, continueCallback);
    expect(ctx.lineWidth).toBe(5);
    expect(ctx.lineWidth).not.toBe(7);
  });

  test("supports stepper skipping and operation filtering", () => {
    const skipStepper = {
      nextBreakPoint: 99,
      breakIt: jest.fn(),
      shouldSkip: jest.fn(index => index === 0),
    };
    const { graphics, ctx } = createGraphics();
    const skipList = {
      argsArray: [[5]],
      fnArray: [OPS.setLineWidth],
      pathCache: new Map(),
    };

    expect(
      graphics.executeOperatorList(skipList, 0, undefined, undefined, skipStepper)
    ).toBe(1);
    expect(ctx.lineWidth).toBe(1);

    const filter = jest.fn(index => index === 0);
    const filteredList = {
      argsArray: [[5], ["#00ff00"]],
      fnArray: [OPS.setLineWidth, OPS.setFillRGBColor],
      pathCache: new Map(),
    };
    graphics.executeOperatorList(
      filteredList,
      0,
      undefined,
      undefined,
      undefined,
      filter
    );
    expect(ctx.lineWidth).toBe(5);
    expect(graphics.current.fillColor).toBe("#000000");
  });
});

describe("graphics state save/restore", () => {
  test("save and restore preserve the PDF graphics state", () => {
    const tracker = createDependencyTracker();
    const { graphics, ctx } = createGraphics({ dependencyTracker: tracker });
    graphics.current.clipBox.set([1, 2, 30, 40]);
    graphics.current.minMax.set([5, 6, 7, 8]);

    graphics.save(10);
    graphics.setLineWidth(11, 5);
    graphics.current.clipBox[0] = 99;
    graphics.current.minMax[0] = 99;

    expect(graphics.stateStack).toHaveLength(1);
    expect(ctx.lineWidth).toBe(5);

    graphics.restore(12);
    expect(graphics.stateStack).toHaveLength(0);
    expect(graphics.current.lineWidth).toBe(1);
    expect(ctx.lineWidth).toBe(1);
    expect(graphics.current.clipBox).toEqual(new Float32Array([1, 2, 30, 40]));
    expect(graphics.current.minMax).toEqual(new Float32Array([5, 6, 7, 8]));
    expect(tracker.save).toHaveBeenCalledWith(10);
    expect(tracker.restore).toHaveBeenCalledWith(12);
  });

  test("restore clears pending clips and invalidates the stroke scale cache", () => {
    const { graphics } = createGraphics();
    graphics.save(0);
    graphics.pendingClip = {};
    graphics._cachedScaleForStroking = [4, 5];

    graphics.restore(1);

    expect(graphics.pendingClip).toBeNull();
    expect(graphics._cachedScaleForStroking[0]).toBe(-1);
  });

  test("transform applies the matrix and invalidates cached stroke scaling", () => {
    const { graphics, ctx } = createGraphics();
    graphics._cachedScaleForStroking = [3, 4];

    graphics.transform(2, 2, 0, 0, 2, 5, 6);

    expect(ctx.getTransform()).toMatchObject({ a: 2, b: 0, c: 0, d: 2, e: 5, f: 6 });
    expect(graphics._cachedScaleForStroking[0]).toBe(-1);
  });

  test("restore without a matching save is a no-op", () => {
    const { graphics } = createGraphics();
    expect(() => graphics.restore(0)).not.toThrow();
    expect(graphics.stateStack).toHaveLength(0);
  });
});

describe("graphics state setters", () => {
  test("line setters update both state and context", () => {
    const { graphics, ctx } = createGraphics();

    graphics.setLineWidth(0, 2.5);
    expect(graphics.current.lineWidth).toBe(2.5);
    expect(ctx.lineWidth).toBe(2.5);

    graphics.setLineCap(1, 1);
    expect(ctx.lineCap).toBe("round");
    graphics.setLineJoin(2, 2);
    expect(ctx.lineJoin).toBe("bevel");
    graphics.setMiterLimit(3, 7);
    expect(ctx.miterLimit).toBe(7);
    graphics.setDash(4, [2, 3], 4);
    expect(ctx.getLineDash()).toEqual([2, 3]);
    expect(ctx.lineDashOffset).toBe(4);
  });

  test("setLineWidth only invalidates the stroke scale when the width changes", () => {
    const { graphics } = createGraphics();
    graphics._cachedScaleForStroking[0] = 2;

    graphics.setLineWidth(0, 1);
    expect(graphics._cachedScaleForStroking[0]).toBe(2);

    graphics.setLineWidth(1, 3);
    expect(graphics._cachedScaleForStroking[0]).toBe(-1);
  });

  test("color setters update solid colors and clear pattern flags", () => {
    const { graphics, ctx } = createGraphics();
    graphics.current.patternStroke = true;
    graphics.current.patternFill = true;
    graphics.current.tilingPatternDims = [1, 2, 3, 4];

    graphics.setStrokeRGBColor(0, "#112233");
    expect(graphics.current.strokeColor).toBe("#112233");
    expect(graphics.current.patternStroke).toBe(false);
    expect(ctx.strokeStyle).toBe("#112233");

    graphics.setFillRGBColor(1, "#445566");
    expect(graphics.current.fillColor).toBe("#445566");
    expect(graphics.current.patternFill).toBe(false);
    expect(graphics.current.tilingPatternDims).toBeNull();
    expect(ctx.fillStyle).toBe("#445566");

    graphics.setStrokeTransparent(2);
    expect(graphics.current.strokeColor).toBe("transparent");
    expect(ctx.strokeStyle).toBe("transparent");

    graphics.setFillTransparent(3);
    expect(graphics.current.fillColor).toBe("transparent");
    expect(ctx.fillStyle).toBe("transparent");
  });

  test("setGState applies a batch of graphics state parameters", () => {
    const tracker = createDependencyTracker();
    const { graphics, ctx } = createGraphics({ dependencyTracker: tracker });

    graphics.setGState(9, [
      ["LW", 3],
      ["LC", 2],
      ["LJ", 1],
      ["ML", 8],
      ["D", [[4, 2], 3]],
      ["CA", 0.4],
      ["ca", 0.6],
      ["BM", "multiply"],
    ]);

    expect(ctx.lineWidth).toBe(3);
    expect(ctx.lineCap).toBe("square");
    expect(ctx.lineJoin).toBe("round");
    expect(ctx.miterLimit).toBe(8);
    expect(ctx.getLineDash()).toEqual([4, 2]);
    expect(ctx.lineDashOffset).toBe(3);
    expect(graphics.current.strokeAlpha).toBe(0.4);
    expect(graphics.current.fillAlpha).toBe(0.6);
    expect(ctx.globalAlpha).toBe(0.6);
    expect(ctx.globalCompositeOperation).toBe("multiply");
    expect(tracker.recordSimpleData).toHaveBeenCalledWith("lineWidth", 9);
    expect(tracker.recordSimpleData).toHaveBeenCalledWith("strokeAlpha", 9);
    expect(tracker.recordSimpleData).toHaveBeenCalledWith("fillAlpha", 9);
  });

  test("transfer map state falls back to pixel remapping when canvas filters are unavailable", () => {
    const filterFactory = createFilterFactory();
    filterFactory.addFilter.mockReturnValue("url(#transfer)");
    const { graphics, ctx } = createGraphics({ filterFactory });
    const invert = Uint8Array.from({ length: 256 }, (_, index) => 255 - index);

    graphics.setFillRGBColor(0, "#000000");
    graphics.setStrokeRGBColor(1, "#ffffff");
    graphics.setGState(2, [["TR", [invert]]]);

    expect(graphics.current.transferMaps).toBe("none");
    expect(graphics.current.transferMapsFallback).not.toBeNull();
    expect(ctx.filter).toBe("none");
    expect(ctx.fillStyle).toBe("#ffffff");
    expect(ctx.strokeStyle).toBe("#000000");
  });
});

describe("text state", () => {
  test("text spacing setters update the current state", () => {
    const { graphics } = createGraphics();

    graphics.setCharSpacing(0, 25);
    expect(graphics.current.charSpacing).toBe(25);

    graphics.setWordSpacing(0, 10);
    expect(graphics.current.wordSpacing).toBe(10);

    graphics.setHScale(0, 150);
    expect(graphics.current.textHScale).toBeCloseTo(1.5);

    graphics.setLeading(0, 12);
    expect(graphics.current.leading).toBe(-12);

    graphics.setTextRenderingMode(0, TextRenderingMode.STROKE);
    expect(graphics.current.textRenderingMode).toBe(TextRenderingMode.STROKE);

    graphics.setTextRise(0, 3);
    expect(graphics.current.textRise).toBe(3);
  });

  test("text positioning operations update line and text coordinates", () => {
    const { graphics } = createGraphics();

    graphics.beginText(0);
    graphics.moveText(1, 3, 4);
    expect(graphics.current).toMatchObject({ x: 3, y: 4, lineX: 3, lineY: 4 });

    graphics.moveText(2, 2, -1);
    expect(graphics.current).toMatchObject({ x: 5, y: 3, lineX: 5, lineY: 3 });

    graphics.setLeadingMoveText(3, 2, 3);
    expect(graphics.current.leading).toBe(3);
    expect(graphics.current).toMatchObject({ x: 7, y: 6, lineX: 7, lineY: 6 });

    graphics.nextLine(4);
    expect(graphics.current).toMatchObject({ x: 7, y: 9, lineX: 7, lineY: 9 });

    graphics.setTextMatrix(5, [2, 3, 0, 4, 5, 6]);
    expect(graphics.current.textMatrix).toEqual([2, 3, 0, 4, 5, 6]);
    expect(graphics.current.textMatrixScale).toBeCloseTo(Math.hypot(2, 3));
    expect(graphics.current).toMatchObject({ x: 0, y: 0, lineX: 0, lineY: 0 });
  });

  test("beginText resets text state", () => {
    const { graphics } = createGraphics();
    graphics.current.textMatrix = [1, 0, 0, 1, 2, 3];
    graphics.current.textMatrixScale = 7;
    graphics.current.x = 10;
    graphics.current.y = 20;
    graphics.current.lineX = 30;
    graphics.current.lineY = 40;

    graphics.beginText(0);

    expect(graphics.current.textMatrix).toBeNull();
    expect(graphics.current.textMatrixScale).toBe(1);
