      this.a = a1 * o.a + c1 * o.b;
      this.b = b1 * o.a + d1 * o.b;
      this.c = a1 * o.c + c1 * o.d;
      this.d = b1 * o.c + d1 * o.d;
      this.e = a1 * o.e + c1 * o.f + e1;
      this.f = b1 * o.e + d1 * o.f + f1;
      return this;
    },
    preMultiplySelf(o) {
