      this.f = o.b * e1 + o.d * f1 + o.f;
      return this;
    },
    translate(x, y) {
      return this.multiplySelf(matrix(1, 0, 0, 1, x, y));
    },
    scale(x, y) {
      return this.multiplySelf(matrix(x, 0, 0, y, 0, 0));
    },
  };
