const STATE_PROPERTIES = [
  "strokeStyle",
  "fillStyle",
  "fillRule",
  "globalAlpha",
  "lineWidth",
  "lineCap",
  "lineJoin",
  "miterLimit",
  "globalCompositeOperation",
  "font",
  "filter",
  "imageSmoothingEnabled",
];

function createMockContext(width = 100, height = 80) {
  const canvas = { width, height };
  const ctx = {
    canvas,
    calls: [],
    _transform: matrix(),
    _stateStack: [],
    _lineDash: [],
    lineDashOffset: 0,
  };

  const defaults = {
    strokeStyle: "#000000",
    fillStyle: "#000000",
    fillRule: "nonzero",
    globalAlpha: 1,
    lineWidth: 1,
    lineCap: "butt",
    lineJoin: "miter",
    miterLimit: 10,
    globalCompositeOperation: "source-over",
    font: "10px sans-serif",
    filter: "none",
    imageSmoothingEnabled: true,
  };
  Object.assign(ctx, defaults);

  const log = (name, args) => ctx.calls.push({ name, args });
  for (const name of [
    "fillRect",
    "clearRect",
    "fill",
    "stroke",
    "clip",
    "drawImage",
    "fillText",
    "strokeText",
    "closePath",
    "beginPath",
    "moveTo",
    "lineTo",
    "rect",
    "putImageData",
  ]) {
    ctx[name] = (...args) => log(name, args);
  }

  ctx.save = () => {
    const state = {};
    for (const p of STATE_PROPERTIES) {
      state[p] = ctx[p];
    }
    ctx._stateStack.push({
      state,
      transform: matrix(
        ctx._transform.a,
        ctx._transform.b,
        ctx._transform.c,
        ctx._transform.d,
        ctx._transform.e,
        ctx._transform.f
      ),
      lineDash: ctx._lineDash.slice(),
      lineDashOffset: ctx.lineDashOffset,
    });
    log("save", []);
  };

  ctx.restore = () => {
    log("restore", []);
    const saved = ctx._stateStack.pop();
    if (!saved) {
      return;
    }
    Object.assign(ctx, saved.state);
    ctx._transform = saved.transform;
    ctx._lineDash = saved.lineDash;
    ctx.lineDashOffset = saved.lineDashOffset;
  };

  ctx.getTransform = () =>
    matrix(
      ctx._transform.a,
      ctx._transform.b,
      ctx._transform.c,
      ctx._transform.d,
      ctx._transform.e,
      ctx._transform.f
    );

  ctx.setTransform = (...args) => {
    if (args.length === 1) {
      const o = args[0];
      ctx._transform = matrix(o.a, o.b, o.c, o.d, o.e, o.f);
    } else {
      ctx._transform = matrix(...args);
    }
    log("setTransform", args);
  };

  ctx.transform = (...args) => {
    ctx._transform.multiplySelf(matrix(...args));
    log("transform", args);
  };
  ctx.resetTransform = () => {
    ctx._transform = matrix();
    log("resetTransform", []);
  };
  ctx.scale = (x, y) => {
    ctx._transform.multiplySelf(matrix(x, 0, 0, y, 0, 0));
    log("scale", [x, y]);
  };
  ctx.translate = (x, y) => {
    ctx._transform.multiplySelf(matrix(1, 0, 0, 1, x, y));
    log("translate", [x, y]);
  };
  ctx.rotate = angle => {
    const cos = Math.cos(angle);
    const sin = Math.sin(angle);
    ctx._transform.multiplySelf(matrix(cos, sin, -sin, cos, 0, 0));
    log("rotate", [angle]);
  };

  ctx.setLineDash = dash => {
    ctx._lineDash = dash.slice();
    log("setLineDash", [dash]);
  };
  ctx.getLineDash = () => ctx._lineDash.slice();

  ctx.createImageData = (w, h) => ({
    width: w,
    height: h,
    data: new Uint8ClampedArray(w * h * 4),
  });

  ctx.measureText = text => ({
    width: text.length * 10,
    actualBoundingBoxLeft: 0,
    actualBoundingBoxRight: text.length * 10,
    actualBoundingBoxAscent: 8,
    actualBoundingBoxDescent: 2,
  });

  return ctx;
}

function createCanvasFactory() {
  const created = [];
