beforeAll(() => {
  originalPath2D = globalThis.Path2D;
  originalDOMMatrix = globalThis.DOMMatrix;
  globalThis.Path2D = FakePath2D;
  globalThis.DOMMatrix = FakeDOMMatrix;

  originalMapGetOrInsert = Map.prototype.getOrInsertComputed;
  originalWeakMapGetOrInsert = WeakMap.prototype.getOrInsertComputed;
  const install = proto => {
    if (!proto.getOrInsertComputed) {
      Object.defineProperty(proto, "getOrInsertComputed", {
        configurable: true,
        writable: true,
        value(key, callback) {
          if (!this.has(key)) {
            this.set(key, callback(key));
          }
          return this.get(key);
        },
      });
    }
  };
  install(Map.prototype);
  install(WeakMap.prototype);
});

afterAll(() => {
  if (originalPath2D === undefined) {
    delete globalThis.Path2D;
  } else {
    globalThis.Path2D = originalPath2D;
  }
