const IDENTITY = [1, 0, 0, 1, 0, 0];

function matrix(a = 1, b = 0, c = 0, d = 1, e = 0, f = 0) {
  const m = {
    a,
    b,
    c,
    d,
    e,
    f,
    invertSelf() {
      const det = this.a * this.d - this.b * this.c;
      const { a: a1, b: b1, c: c1, d: d1, e: e1, f: f1 } = this;
      this.a = d1 / det;
      this.b = -b1 / det;
      this.c = -c1 / det;
      this.d = a1 / det;
      this.e = (c1 * f1 - d1 * e1) / det;
      this.f = (b1 * e1 - a1 * f1) / det;
      return this;
    },
    multiplySelf(o) {
      const { a: a1, b: b1, c: c1, d: d1, e: e1, f: f1 } = this;
      this.a = a1 * o.a + c1 * o.b;
      this.b = b1 * o.a + d1 * o.b;
      this.c = a1 * o.c + c1 * o.d;
      this.d = b1 * o.c + d1 * o.d;
      this.e = a1 * o.e + c1 * o.f + e1;
      this.f = b1 * o.e + d1 * o.f + f1;
      return this;
    },
    preMultiplySelf(o) {
      const { a: a1, b: b1, c: c1, d: d1, e: e1, f: f1 } = this;
      this.a = o.a * a1 + o.c * b1;
      this.b = o.b * a1 + o.d * b1;
      this.c = o.a * c1 + o.c * d1;
      this.d = o.b * c1 + o.d * d1;
      this.e = o.a * e1 + o.c * f1 + o.e;
      this.f = o.b * e1 + o.d * f1 + o.f;
      return this;
    },
    translate(x, y) {
      return this.multiplySelf(matrix(1, 0, 0, 1, x, y));
    },
    scale(x, y) {
      return this.multiplySelf(matrix(x, 0, 0, y, 0, 0));
    },
  };
  return m;
