        configurable: true,
        writable: true,
        value(key, callback) {
          if (!this.has(key)) {
            this.set(key, callback(key));
          }
          return this.get(key);
        },
      });
    }
  };
  install(Map.prototype);
  install(WeakMap.prototype);
});

afterAll(() => {
  if (originalPath2D === undefined) {
    delete globalThis.Path2D;
  } else {
    globalThis.Path2D = originalPath2D;
  }
  if (originalDOMMatrix === undefined) {
    delete globalThis.DOMMatrix;
  } else {
    globalThis.DOMMatrix = originalDOMMatrix;
  }
  if (originalMapGetOrInsert === undefined) {
    delete Map.prototype.getOrInsertComputed;
  } else {
    Map.prototype.getOrInsertComputed = originalMapGetOrInsert;
  }
  if (originalWeakMapGetOrInsert === undefined) {
    delete WeakMap.prototype.getOrInsertComputed;
  } else {
    WeakMap.prototype.getOrInsertComputed = originalWeakMapGetOrInsert;
  }
});

