describe("text painting", () => {
  function prepareText(graphics, overrides = {}) {
    graphics.current.font = fontObject(overrides.font);
    graphics.current.fontSize = overrides.fontSize ?? 10;
    graphics.current.fontSizeScale = overrides.fontSizeScale ?? 1;
    graphics.current.fontMatrix = FONT_IDENTITY_MATRIX;
    graphics.current.textMatrix = overrides.textMatrix ?? null;
    graphics.current.textMatrixScale = overrides.textMatrixScale ?? 1;
    graphics.current.textRenderingMode =
      overrides.textRenderingMode ?? TextRenderingMode.FILL;
  }

  test("draws ordinary glyphs with fillText and advances the text position", () => {
    const { graphics, ctx } = createGraphics();
    prepareText(graphics);

    graphics.showText(0, [
      { fontChar: "A", width: 500, isSpace: false, isInFont: true },
    ]);

    const fillTextCalls = callsOf(ctx, "fillText");
    expect(fillTextCalls).toHaveLength(1);
    expect(fillTextCalls[0].args).toEqual(["A", 0, 0]);
    expect(graphics.current.x).toBeCloseTo(5);
    expect(callsOf(ctx, "save")).toHaveLength(1);
    expect(callsOf(ctx, "restore")).toHaveLength(1);
  });

  test("accounts for word and character spacing", () => {
    const { graphics } = createGraphics();
    prepareText(graphics);
    graphics.current.wordSpacing = 20;
    graphics.current.charSpacing = 10;

    graphics.showText(0, [
      { fontChar: "A", width: 500, isSpace: true, isInFont: true },
    ]);

    expect(graphics.current.x).toBeCloseTo(35);
  });

  test("does not draw when the font size is zero", () => {
    const dependencyTracker = createDependencyTracker();
    const { graphics, ctx } = createGraphics({ dependencyTracker });
    prepareText(graphics, { fontSize: 0 });

    graphics.showText(7, [
      { fontChar: "A", width: 500, isInFont: true },
    ]);

    expect(callsOf(ctx, "fillText")).toHaveLength(0);
    expect(dependencyTracker.recordOperation).toHaveBeenCalledWith(7);
  });

  test("uses strokeText in stroke rendering mode", () => {
    const { graphics, ctx } = createGraphics();
    prepareText(graphics, {
      textRenderingMode: TextRenderingMode.STROKE,
    });

    graphics.showText(0, [
      { fontChar: "A", width: 500, isInFont: true, isSpace: false },
    ]);

    expect(callsOf(ctx, "strokeText")).toHaveLength(1);
    expect(callsOf(ctx, "fillText")).toHaveLength(0);
  });

  test("skips painting glyphs that are not in the font", () => {
    const { graphics, ctx } = createGraphics();
    prepareText(graphics);
    graphics.current.font.missingFile = false;

    graphics.showText(0, [
      { fontChar: "X", width: 500, isInFont: false, isSpace: false },
    ]);

    expect(callsOf(ctx, "fillText")).toHaveLength(0);
    expect(graphics.current.x).toBeCloseTo(5);
  });

  test("endText clips pending text paths and clears them", () => {
    const { graphics, ctx } = createGraphics();
    const textPath = new FakePath2D();
    graphics.pendingTextPaths = [
      { transform: IDENTITY, x: 1, y: 2, fontSize: 3, path: textPath },
      { transform: IDENTITY, x: 0, y: 0, fontSize: 1, path: null },
    ];

    graphics.endText(0);

    const clipCalls = callsOf(ctx, "clip");
    expect(clipCalls).toHaveLength(1);
    expect(clipCalls[0].args[0]).toBeInstanceOf(FakePath2D);
    expect(clipCalls[0].args[0].ops[0]).toMatchObject({
      type: "addPath",
      path: textPath,
    });
    expect(graphics.pendingTextPaths).toBeUndefined();
  });
});

