    return this;
  }

  preMultiplySelf(o) {
    const m = matrix(this.a, this.b, this.c, this.d, this.e, this.f);
    Object.assign(this, m.preMultiplySelf(o));
    return this;
  }

  multiplySelf(o) {
    const m = matrix(this.a, this.b, this.c, this.d, this.e, this.f);
    Object.assign(this, m.multiplySelf(o));
    return this;
  }

  translate(x, y) {
    const m = matrix(this.a, this.b, this.c, this.d, this.e, this.f);
    Object.assign(this, m.translate(x, y));
    return this;
  }

  scale(x, y) {
    const m = matrix(this.a, this.b, this.c, this.d, this.e, this.f);
    Object.assign(this, m.scale(x, y));
    return this;
  }
}

const STATE_PROPERTIES = [
  "strokeStyle",
  "fillStyle",
  "fillRule",
  "globalAlpha",
  "lineWidth",
  "lineCap",
  "lineJoin",
  "miterLimit",
  "globalCompositeOperation",
  "font",
  "filter",
  "imageSmoothingEnabled",
];

function createMockContext(width = 100, height = 80) {
  const canvas = { width, height };
  const ctx = {
    canvas,
    calls: [],
    _transform: matrix(),
    _stateStack: [],
    _lineDash: [],
    lineDashOffset: 0,
  };

  const defaults = {
    strokeStyle: "#000000",
    fillStyle: "#000000",
    fillRule: "nonzero",
    globalAlpha: 1,
    lineWidth: 1,
    lineCap: "butt",
    lineJoin: "miter",
    miterLimit: 10,
    globalCompositeOperation: "source-over",
    font: "10px sans-serif",
    filter: "none",
    imageSmoothingEnabled: true,
  };
  Object.assign(ctx, defaults);

  const log = (name, args) => ctx.calls.push({ name, args });
  for (const name of [
    "fillRect",
    "clearRect",
    "fill",
    "stroke",
    "clip",
    "drawImage",
    "fillText",
    "strokeText",
    "closePath",
    "beginPath",
    "moveTo",
    "lineTo",
    "rect",
    "putImageData",
  ]) {
    ctx[name] = (...args) => log(name, args);
  }

  ctx.save = () => {
    const state = {};
    for (const p of STATE_PROPERTIES) {
      state[p] = ctx[p];
    }
    ctx._stateStack.push({
      state,
      transform: matrix(
        ctx._transform.a,
        ctx._transform.b,
        ctx._transform.c,
        ctx._transform.d,
        ctx._transform.e,
        ctx._transform.f
      ),
      lineDash: ctx._lineDash.slice(),
      lineDashOffset: ctx.lineDashOffset,
    });
    log("save", []);
  };

  ctx.restore = () => {
    log("restore", []);
    const saved = ctx._stateStack.pop();
    if (!saved) {
      return;
    }
    Object.assign(ctx, saved.state);
    ctx._transform = saved.transform;
    ctx._lineDash = saved.lineDash;
    ctx.lineDashOffset = saved.lineDashOffset;
  };

  ctx.getTransform = () =>
    matrix(
      ctx._transform.a,
      ctx._transform.b,
      ctx._transform.c,
      ctx._transform.d,
      ctx._transform.e,
      ctx._transform.f
    );

  ctx.setTransform = (...args) => {
    if (args.length === 1) {
      const o = args[0];
      ctx._transform = matrix(o.a, o.b, o.c, o.d, o.e, o.f);
    } else {
      ctx._transform = matrix(...args);
    }
    log("setTransform", args);
  };

  ctx.transform = (...args) => {
    ctx._transform.multiplySelf(matrix(...args));
    log("transform", args);
  };
  ctx.resetTransform = () => {
    ctx._transform = matrix();
    log("resetTransform", []);
  };
  ctx.scale = (x, y) => {
    ctx._transform.multiplySelf(matrix(x, 0, 0, y, 0, 0));
    log("scale", [x, y]);
  };
  ctx.translate = (x, y) => {
    ctx._transform.multiplySelf(matrix(1, 0, 0, 1, x, y));
    log("translate", [x, y]);
  };
  ctx.rotate = angle => {
    const cos = Math.cos(angle);
    const sin = Math.sin(angle);
    ctx._transform.multiplySelf(matrix(cos, sin, -sin, cos, 0, 0));
    log("rotate", [angle]);
  };

  ctx.setLineDash = dash => {
    ctx._lineDash = dash.slice();
    log("setLineDash", [dash]);
  };
  ctx.getLineDash = () => ctx._lineDash.slice();

  ctx.createImageData = (w, h) => ({
    width: w,
    height: h,
    data: new Uint8ClampedArray(w * h * 4),
  });

  ctx.measureText = text => ({
    width: text.length * 10,
    actualBoundingBoxLeft: 0,
    actualBoundingBoxRight: text.length * 10,
    actualBoundingBoxAscent: 8,
    actualBoundingBoxDescent: 2,
  });

  return ctx;
}

function createCanvasFactory() {
  const created = [];
  const destroyed = [];
  return {
    created,
    destroyed,
    create: jest.fn((width, height) => {
      const context = createMockContext(width, height);
      const entry = { canvas: context.canvas, context };
      created.push(entry);
      return entry;
    }),
    destroy: jest.fn(entry => {
      destroyed.push(entry);
    }),
    reset: jest.fn((entry, width, height) => {
      entry.canvas.width = width;
      entry.canvas.height = height;
      entry.context.canvas.width = width;
      entry.context.canvas.height = height;
    }),
  };
}

function createObjectStore(entries = {}) {
  return {
    has: jest.fn(id => Object.prototype.hasOwnProperty.call(entries, id)),
    get: jest.fn(id => entries[id]),
  };
}

function createDependencyTracker() {
  const tracker = { clipBox: [0, 0, 100, 80] };
  for (const name of [
    "save",
    "restore",
    "recordSimpleData",
    "recordSimpleDataFromNamed",
    "recordDependencies",
    "recordOperation",
    "recordNamedDependency",
    "recordNamedData",
    "recordOpenMarker",
    "recordCloseMarker",
    "resetIncrementalData",
    "recordIncrementalData",
    "beginMarkedContent",
    "endMarkedContent",
    "resetBBox",
    "recordBBox",
    "recordClipBox",
    "recordFutureForcedDependency",
    "recordCharacterBBox",
    "recordShowTextOperation",
    "inheritPendingDependenciesAsFutureForcedDependencies",
    "bboxToClipBoxDropOperation",
    "popBaseTransform",
    "pushBaseTransform",
  ]) {
    tracker[name] = jest.fn(() => tracker);
  }
  tracker.getSimpleIndex = jest.fn(() => 0);
  return tracker;
}

function createGraphics({
  width = 100,
  height = 80,
  commonObjs,
  objs,
  factory = createCanvasFactory(),
  filterFactory,
  optionalContentConfig,
  annotationCanvasMap,
  dependencyTracker = null,
  pixelRatio = 1,
  pageColors = null,
  ctx,
} = {}) {
  const context = ctx ?? createMockContext(width, height);
  const common = commonObjs ?? createObjectStore();
  const object = objs ?? createObjectStore();
  const ff = filterFactory ?? {
    addFilter: jest.fn(() => "none"),
    addHCMFilter: jest.fn(() => "none"),
  };
  const oc = optionalContentConfig ?? { isVisible: jest.fn(() => true) };
  const graphics = new CanvasGraphics(
    context,
    common,
    object,
    factory,
    ff,
    { optionalContentConfig: oc, pixelRatio },
    annotationCanvasMap,
    pageColors,
    dependencyTracker
  );
  return {
    graphics,
    ctx: context,
    factory,
    filterFactory: ff,
    optionalContentConfig: oc,
    commonObjs: common,
    objs: object,
  };
}

function callsOf(ctx, name) {
  return ctx.calls.filter(call => call.name === name);
}

function fontObject(overrides = {}) {
  return {
    fontMatrix: FONT_IDENTITY_MATRIX,
    loadedName: "F1",
    fallbackName: "sans-serif",
    vertical: false,
    disableFontFace: false,
    missingFile: false,
    isType3Font: false,
    ...overrides,
  };
}

let originalPath2D;
let originalDOMMatrix;
let originalMapGetOrInsert;
let originalWeakMapGetOrInsert;

beforeAll(() => {
  originalPath2D = globalThis.Path2D;
  originalDOMMatrix = globalThis.DOMMatrix;
  globalThis.Path2D = FakePath2D;
  globalThis.DOMMatrix = FakeDOMMatrix;

  originalMapGetOrInsert = Map.prototype.getOrInsertComputed;
  originalWeakMapGetOrInsert = WeakMap.prototype.getOrInsertComputed;
  const install = proto => {
    if (!proto.getOrInsertComputed) {
      Object.defineProperty(proto, "getOrInsertComputed", {
        configurable: true,
        writable: true,
        value(key, callback) {
          if (!this.has(key)) {
            this.set(key, callback(key));
          }
          return this.get(key);
        },
      });
    }
  };
  install(Map.prototype);
  install(WeakMap.prototype);
});

afterAll(() => {
  if (originalPath2D === undefined) {
    delete globalThis.Path2D;
  } else {
    globalThis.Path2D = originalPath2D;
  }
  if (originalDOMMatrix === undefined) {
    delete globalThis.DOMMatrix;
  } else {
    globalThis.DOMMatrix = originalDOMMatrix;
  }
  if (originalMapGetOrInsert === undefined) {
    delete Map.prototype.getOrInsertComputed;
  } else {
    Map.prototype.getOrInsertComputed = originalMapGetOrInsert;
  }
  if (originalWeakMapGetOrInsert === undefined) {
    delete WeakMap.prototype.getOrInsertComputed;
  } else {
    WeakMap.prototype.getOrInsertComputed = originalWeakMapGetOrInsert;
  }
});

