describe("executeOperatorList", () => {
  test("returns the start index for an empty operator list", () => {
    const { graphics } = createGraphics();
    expect(
      graphics.executeOperatorList({ fnArray: [], argsArray: [] }, 0)
    ).toBe(0);
    expect(
      graphics.executeOperatorList({ fnArray: [], argsArray: [] }, 3)
    ).toBe(3);
  });

  test("dispatches numeric operators and returns the final index", () => {
    const { graphics, ctx } = createGraphics();
    const operatorList = {
      fnArray: [OPS.setLineWidth, OPS.transform, OPS.setFillRGBColor],
      argsArray: [[4], [2, 0, 0, 2, 10, 20], ["#ff0000"]],
      pathCache: new Map(),
    };

    const result = graphics.executeOperatorList(operatorList, 0);

    expect(result).toBe(3);
    expect(ctx.lineWidth).toBe(4);
    expect(ctx.getTransform()).toMatchObject({
      a: 2,
      b: 0,
      c: 0,
      d: 2,
      e: 10,
      f: 20,
    });
    expect(graphics.current.fillColor).toBe("#ff0000");
    expect(ctx.fillStyle).toBe("#ff0000");
  });

  test("starts at the requested execution index", () => {
    const { graphics, ctx } = createGraphics();
    const operatorList = {
      fnArray: [OPS.setLineWidth, OPS.setMiterLimit],
      argsArray: [[2], [9]],
      pathCache: new Map(),
    };
    expect(graphics.executeOperatorList(operatorList, 1)).toBe(2);
    expect(ctx.lineWidth).toBe(1);
    expect(ctx.miterLimit).toBe(9);
  });

  test("defers execution when a dependency is not resolved", () => {
    const continueCallback = jest.fn();
    const errorCallback = jest.fn();
    const objs = createObjectStore();
    const { graphics, ctx } = createGraphics({ objs });
    const operatorList = {
      fnArray: [OPS.dependency, OPS.setLineWidth],
      argsArray: [["img_pending"], [7]],
      pathCache: new Map(),
    };

    expect(
      graphics.executeOperatorList(
        operatorList,
        0,
        continueCallback,
        errorCallback
      )
    ).toBe(0);
    expect(objs.has).toHaveBeenCalledWith("img_pending");
    expect(objs.get).toHaveBeenCalledWith(
      "img_pending",
      continueCallback,
      errorCallback
    );
    expect(ctx.lineWidth).toBe(1);
  });

  test("continues after resolved dependencies, including common objs", () => {
    const commonObjs = createObjectStore({ g_font: {} });
    const objs = createObjectStore({ img_ready: {} });
    const { graphics, ctx } = createGraphics({ commonObjs, objs });
    const operatorList = {
      fnArray: [OPS.dependency, OPS.dependency, OPS.setLineWidth],
      argsArray: [["g_font"], ["img_ready"], [5]],
      pathCache: new Map(),
    };

    expect(graphics.executeOperatorList(operatorList, 0)).toBe(3);
    expect(commonObjs.has).toHaveBeenCalledWith("g_font");
    expect(objs.has).toHaveBeenCalledWith("img_ready");
    expect(ctx.lineWidth).toBe(5);
  });

  test("honors an operations filter", () => {
    const { graphics, ctx } = createGraphics();
    const operatorList = {
      fnArray: [OPS.setLineWidth, OPS.setFillRGBColor],
      argsArray: [[3], ["#00ff00"]],
      pathCache: new Map(),
    };
    const operationsFilter = jest.fn((idx, list) => {
      expect(list).toBe(operatorList);
      return idx === 0;
    });

    expect(
      graphics.executeOperatorList(
        operatorList,
        0,
        undefined,
        undefined,
        undefined,
        operationsFilter
      )
    ).toBe(2);
    expect(operationsFilter).toHaveBeenCalledTimes(2);
    expect(ctx.lineWidth).toBe(3);
    expect(graphics.current.fillColor).toBe("#000000");
  });

  test("honors stepper break points", () => {
    const continueCallback = jest.fn();
    const stepper = {
      nextBreakPoint: 1,
      breakIt: jest.fn(),
      shouldSkip: jest.fn(() => false),
    };
    const { graphics, ctx } = createGraphics();
    const operatorList = {
      fnArray: [OPS.setLineWidth, OPS.setMiterLimit],
      argsArray: [[2], [9]],
      pathCache: new Map(),
    };

    expect(
      graphics.executeOperatorList(
        operatorList,
        0,
        continueCallback,
        undefined,
        stepper
      )
    ).toBe(1);
    expect(stepper.breakIt).toHaveBeenCalledWith(1, continueCallback);
    expect(ctx.lineWidth).toBe(2);
    expect(ctx.miterLimit).toBe(10);
  });

  test("skips operators requested by the stepper", () => {
    const stepper = {
      nextBreakPoint: 99,
      breakIt: jest.fn(),
      shouldSkip: jest.fn(idx => idx === 0),
    };
    const { graphics, ctx } = createGraphics();
    const operatorList = {
      fnArray: [OPS.setLineWidth, OPS.setMiterLimit],
      argsArray: [[2], [9]],
      pathCache: new Map(),
    };

    expect(
      graphics.executeOperatorList(operatorList, 0, undefined, undefined, stepper)
    ).toBe(2);
    expect(ctx.lineWidth).toBe(1);
    expect(ctx.miterLimit).toBe(9);
  });
});

describe("graphics state stack", () => {
  test("save snapshots state and restore returns to it", () => {
    const dependencyTracker = createDependencyTracker();
    const { graphics, ctx } = createGraphics({ dependencyTracker });
    graphics.current.lineWidth = 1;
    graphics.current.clipBox.set([1, 2, 30, 40]);
    graphics.current.minMax.set([5, 6, 7, 8]);

    graphics.save(10);
    graphics.setLineWidth(11, 5);
    graphics.current.clipBox[0] = 99;
    graphics.current.minMax[0] = 99;
    expect(ctx.lineWidth).toBe(5);

    graphics.restore(12);

    expect(graphics.current.lineWidth).toBe(1);
    expect(graphics.current.clipBox).toEqual(new Float32Array([1, 2, 30, 40]));
    expect(graphics.current.minMax).toEqual(new Float32Array([5, 6, 7, 8]));
    expect(ctx.lineWidth).toBe(1);
    expect(graphics.stateStack).toHaveLength(0);
    expect(dependencyTracker.save).toHaveBeenCalledWith(10);
    expect(dependencyTracker.restore).toHaveBeenCalledWith(12);
  });

  test("restore clears pending clip and invalidates the stroke scale cache", () => {
    const { graphics } = createGraphics();
    graphics.save(0);
    graphics.pendingClip = { some: "clip" };
    graphics._cachedScaleForStroking = [3, 4];

    graphics.restore(1);

    expect(graphics.pendingClip).toBeNull();
    expect(graphics._cachedScaleForStroking[0]).toBe(-1);
  });

  test("restore without a matching save is a no-op", () => {
    const { graphics } = createGraphics();
    const before = graphics.current;
    expect(() => graphics.restore(0)).not.toThrow();
    expect(graphics.current).toBe(before);
    expect(graphics.stateStack).toHaveLength(0);
  });

  test("transform updates the context and invalidates cached stroking scale", () => {
    const dependencyTracker = createDependencyTracker();
    const { graphics, ctx } = createGraphics({ dependencyTracker });
    graphics._cachedScaleForStroking = [2, 2];

    graphics.transform(4, 2, 0, 0, 3, 5, 6);

    expect(ctx.getTransform()).toMatchObject({
      a: 2,
      b: 0,
      c: 0,
      d: 3,
      e: 5,
      f: 6,
    });
    expect(graphics._cachedScaleForStroking[0]).toBe(-1);
    expect(dependencyTracker.recordIncrementalData).toHaveBeenCalledWith(
      "transform",
      4
    );
  });
});

