describe("text state", () => {
  test("updates spacing, leading, rendering mode and text rise", () => {
    const { graphics } = createGraphics();
    graphics.setCharSpacing(0, 25);
    graphics.setWordSpacing(0, 10);
    graphics.setHScale(0, 150);
    graphics.setLeading(0, 12);
