describe("text painting", () => {
  function prepareText(graphics, overrides = {}) {
    graphics.current.font = fontObject(overrides.font);
    graphics.current.fontSize = overrides.fontSize ?? 10;
    graphics.current.fontSizeScale = overrides.fontSizeScale ?? 1;
    graphics.current.fontMatrix = FONT_IDENTITY_MATRIX;
    graphics.current.textMatrix = overrides.textMatrix ?? null;
    graphics.current.textMatrixScale = overrides.textMatrixScale ?? 1;
    graphics.current.textRenderingMode =
      overrides.textRenderingMode ?? TextRenderingMode.FILL;
  }

  test("draws ordinary glyphs with fillText and advances the text position", () => {
    const { graphics, ctx } = createGraphics();
    prepareText(graphics);

    graphics.showText(0, [
      { fontChar: "A", width: 500, isSpace: false, isInFont: true },
    ]);

    const fillTextCalls = callsOf(ctx, "fillText");
    expect(fillTextCalls).toHaveLength(1);
    expect(fillTextCalls[0].args).toEqual(["A", 0, 0]);
    expect(graphics.current.x).toBeCloseTo(5);
    expect(callsOf(ctx, "save")).toHaveLength(1);
    expect(callsOf(ctx, "restore")).toHaveLength(1);
  });

  test("accounts for word and character spacing", () => {
    const { graphics } = createGraphics();
    prepareText(graphics);
    graphics.current.wordSpacing = 20;
    graphics.current.charSpacing = 10;

    graphics.showText(0, [
      { fontChar: "A", width: 500, isSpace: true, isInFont: true },
    ]);

    expect(graphics.current.x).toBeCloseTo(35);
  });

  test("does not draw when the font size is zero", () => {
    const dependencyTracker = createDependencyTracker();
    const { graphics, ctx } = createGraphics({ dependencyTracker });
    prepareText(graphics, { fontSize: 0 });

    graphics.showText(7, [
      { fontChar: "A", width: 500, isInFont: true },
    ]);

    expect(callsOf(ctx, "fillText")).toHaveLength(0);
    expect(dependencyTracker.recordOperation).toHaveBeenCalledWith(7);
  });

  test("uses strokeText in stroke rendering mode", () => {
    const { graphics, ctx } = createGraphics();
    prepareText(graphics, {
      textRenderingMode: TextRenderingMode.STROKE,
    });

    graphics.showText(0, [
      { fontChar: "A", width: 500, isInFont: true, isSpace: false },
    ]);

    expect(callsOf(ctx, "strokeText")).toHaveLength(1);
    expect(callsOf(ctx, "fillText")).toHaveLength(0);
  });

  test("skips painting glyphs that are not in the font", () => {
    const { graphics, ctx } = createGraphics();
    prepareText(graphics);
    graphics.current.font.missingFile = false;

    graphics.showText(0, [
      { fontChar: "X", width: 500, isInFont: false, isSpace: false },
    ]);

    expect(callsOf(ctx, "fillText")).toHaveLength(0);
    expect(graphics.current.x).toBeCloseTo(5);
  });

  test("endText clips pending text paths and clears them", () => {
    const { graphics, ctx } = createGraphics();
    const textPath = new FakePath2D();
    graphics.pendingTextPaths = [
      { transform: IDENTITY, x: 1, y: 2, fontSize: 3, path: textPath },
      { transform: IDENTITY, x: 0, y: 0, fontSize: 1, path: null },
    ];

    graphics.endText(0);

    const clipCalls = callsOf(ctx, "clip");
    expect(clipCalls).toHaveLength(1);
    expect(clipCalls[0].args[0]).toBeInstanceOf(FakePath2D);
    expect(clipCalls[0].args[0].ops[0]).toMatchObject({
      type: "addPath",
      path: textPath,
    });
    expect(graphics.pendingTextPaths).toBeUndefined();
  });
});

describe("path painting and clipping", () => {
  test("fill paints a visible path and resets the path bounding box", () => {
    const { graphics, ctx } = createGraphics();
    const path = { kind: "path" };
    graphics.current.minMax.set([1, 2, 9, 10]);

    graphics.fill(0, path);

    const fillCalls = callsOf(ctx, "fill");
    expect(fillCalls).toHaveLength(1);
    expect(fillCalls[0].args).toEqual([path]);
    expect(graphics.current.minMax).toEqual(F32_BBOX_INIT);
  });

  test("eoFill uses the even-odd fill rule", () => {
    const { graphics, ctx } = createGraphics();
    const path = { kind: "path" };
    graphics.current.minMax.set([1, 2, 9, 10]);

    graphics.eoFill(0, path);

    expect(callsOf(ctx, "fill")[0].args).toEqual([path, "evenodd"]);
    expect(graphics.pendingEOFill).toBe(false);
  });

  test("fill skips the context when the path is outside the clip box", () => {
    const { graphics, ctx } = createGraphics();
    const path = { kind: "path" };
    graphics.current.clipBox.set([0, 0, 10, 10]);
    graphics.current.minMax.set([20, 20, 30, 30]);

    graphics.fill(0, path);

    expect(callsOf(ctx, "fill")).toHaveLength(0);
    expect(graphics.current.minMax).toEqual(F32_BBOX_INIT);
  });

  test("fill does not paint hidden content", () => {
    const optionalContentConfig = { isVisible: jest.fn(() => false) };
    const { graphics, ctx } = createGraphics({ optionalContentConfig });
    graphics.beginMarkedContentProps(0, "OC", { id: "hidden" });
    graphics.current.minMax.set([1, 2, 9, 10]);

    graphics.fill(1, { kind: "path" });

    expect(callsOf(ctx, "fill")).toHaveLength(0);
    expect(graphics.contentVisible).toBe(false);
  });

  test("stroke paints with the current line width", () => {
    const { graphics, ctx } = createGraphics();
    const path = { kind: "path" };
    graphics.current.lineWidth = 1;
    graphics.current.minMax.set([1, 2, 9, 10]);

    graphics.stroke(0, path);

    const strokeCalls = callsOf(ctx, "stroke");
    expect(strokeCalls).toHaveLength(1);
    expect(strokeCalls[0].args[0]).toBe(path);
    expect(ctx.lineWidth).toBe(1);
    expect(ctx.globalAlpha).toBe(graphics.current.fillAlpha);
  });

  test("stroke does not paint hidden content", () => {
    const optionalContentConfig = { isVisible: jest.fn(() => false) };
    const { graphics, ctx } = createGraphics({ optionalContentConfig });
    graphics.beginMarkedContentProps(0, "OC", {});
    graphics.current.minMax.set([1, 2, 9, 10]);

    graphics.stroke(1, { kind: "path" });

    expect(callsOf(ctx, "stroke")).toHaveLength(0);
  });

  test("fillStroke fills and strokes once, then consumes the path", () => {
    const { graphics, ctx } = createGraphics();
    const path = { kind: "path" };
    graphics.current.minMax.set([1, 2, 9, 10]);

    graphics.fillStroke(0, path);

    expect(callsOf(ctx, "fill")).toHaveLength(1);
    expect(callsOf(ctx, "stroke")).toHaveLength(1);
    expect(graphics.current.minMax).toEqual(F32_BBOX_INIT);
  });

  test("clip intersects the path box with the current clip box", () => {
    const { graphics, ctx } = createGraphics();
    const path = { kind: "path" };
    graphics.current.clipBox.set([0, 0, 10, 10]);
    graphics.current.minMax.set([2, 3, 8, 12]);

    graphics.clip(0);
    expect(graphics.pendingClip).toBeTruthy();
    graphics.consumePath(0, path);

    const clipCalls = callsOf(ctx, "clip");
    expect(clipCalls).toHaveLength(1);
    expect(clipCalls[0].args).toEqual([path]);
    expect(graphics.pendingClip).toBeNull();
    expect(Array.from(graphics.current.clipBox)).toEqual([2, 3, 8, 10]);
    expect(graphics.current.minMax).toEqual(F32_BBOX_INIT);
  });

  test("eoClip uses the even-odd clip rule", () => {
    const { graphics, ctx } = createGraphics();
    const path = { kind: "path" };
    graphics.current.minMax.set([1, 1, 5, 5]);

    graphics.eoClip(0);
    graphics.consumePath(0, path);

    expect(callsOf(ctx, "clip")[0].args).toEqual([path, "evenodd"]);
  });

  test("an empty clip path is not applied to the context", () => {
    const { graphics, ctx } = createGraphics();
    graphics.clip(0);

    graphics.consumePath(0, { kind: "path" });

    expect(callsOf(ctx, "clip")).toHaveLength(0);
    expect(Array.from(graphics.current.clipBox)).toEqual([0, 0, 0, 0]);
  });

  test("closePath and endPath reach the context and reset the path box", () => {
    const { graphics, ctx } = createGraphics();
    graphics.closePath(0);
    expect(callsOf(ctx, "closePath")).toHaveLength(1);

    graphics.current.minMax.set([1, 2, 3, 4]);
    graphics.endPath(1, { kind: "path" });
    expect(graphics.current.minMax).toEqual(F32_BBOX_INIT);
  });

  test("rawFillPath always fills the supplied path", () => {
    const { graphics, ctx } = createGraphics();
    const path = { kind: "path" };
    graphics.contentVisible = false;
    graphics.rawFillPath(0, path);
    expect(callsOf(ctx, "fill")[0].args).toEqual([path]);
  });

  test("setCharWidthAndBounds clips the glyph box", () => {
    const { graphics, ctx } = createGraphics();
    graphics.setCharWidthAndBounds(0, 1, 1, 2, 3, 10, 12);

    const clipCalls = callsOf(ctx, "clip");
    expect(clipCalls).toHaveLength(1);
    expect(clipCalls[0].args[0]).toBeInstanceOf(FakePath2D);
    expect(clipCalls[0].args[0].ops[0]).toEqual({
      type: "rect",
      args: [2, 3, 8, 9],
    });
    expect(graphics.current.minMax).toEqual(F32_BBOX_INIT);
  });

  test("beginInlineImage and beginImageData are unsupported", () => {
    const { graphics } = createGraphics();
    expect(() => graphics.beginInlineImage()).toThrow(
      "Should not call beginInlineImage"
    );
    expect(() => graphics.beginImageData()).toThrow(
      "Should not call beginImageData"
    );
  });
});

describe("stroke scaling", () => {
  test("getSinglePixelWidth fast path with axis-aligned transforms", () => {
    const { graphics, ctx } = createGraphics();
    expect(graphics.getSinglePixelWidth()).toBe(1);

    ctx._transform = matrix(2, 0, 0, 4, 10, 20);
    expect(graphics.getSinglePixelWidth()).toBe(0.5);
  });

  test("getSinglePixelWidth handles sheared transforms", () => {
    const { graphics, ctx } = createGraphics();
    ctx._transform = matrix(2, 1, -1, 2, 0, 0);
    expect(graphics.getSinglePixelWidth()).toBeCloseTo(Math.sqrt(5) / 5, 10);
  });

  test("getScaleForStroking handles uniform transforms", () => {
    const { graphics, ctx } = createGraphics();
    graphics.current.lineWidth = 1;
    expect(Array.from(graphics.getScaleForStroking())).toEqual([1, 1]);

    graphics.current.lineWidth = 0.25;
    graphics._cachedScaleForStroking = [-1, 0];
    ctx._transform = matrix(2, 0, 0, 2, 0, 0);
    expect(Array.from(graphics.getScaleForStroking())).toEqual([2, 2]);
  });

  test("getScaleForStroking handles non-uniform transforms", () => {
    const { graphics, ctx } = createGraphics();
    ctx._transform = matrix(2, 0, 0, 4, 0, 0);
    graphics.current.lineWidth = 0.1;
    let scale = graphics.getScaleForStroking();
    expect(scale[0]).toBeCloseTo(5);
    expect(scale[1]).toBeCloseTo(2.5);

    graphics.current.lineWidth = 0;
    graphics._cachedScaleForStroking = [-1, 0];
    scale = graphics.getScaleForStroking();
    expect(scale[0]).toBeCloseTo(0.5);
    expect(scale[1]).toBeCloseTo(0.25);
  });

  test("getScaleForStroking handles sheared transforms", () => {
    const { graphics, ctx } = createGraphics();
    ctx._transform = matrix(1, 1, -1, 1, 0, 0);
    graphics.current.lineWidth = 0.1;
    const scale = graphics.getScaleForStroking();
    expect(scale[0]).toBeCloseTo(Math.SQRT2 / 0.2);
    expect(scale[1]).toBeCloseTo(Math.SQRT2 / 0.2);
  });

  test("caches the stroking scale until a state change invalidates it", () => {
    const { graphics, ctx } = createGraphics();
    graphics.current.lineWidth = 0.1;
    ctx._transform = matrix(2, 0, 0, 4, 0, 0);
    expect(graphics.getScaleForStroking()).toEqual([5, 2.5]);

    ctx._transform = matrix(10, 0, 0, 10, 0, 0);
    expect(graphics.getScaleForStroking()).toEqual([5, 2.5]);

    graphics.setLineWidth(0, 0.2);
    const updated = graphics.getScaleForStroking();
    expect(updated[0]).toBeCloseTo(0.5);
    expect(updated[1]).toBeCloseTo(0.5);
  });

  test("rescaleAndStroke uses a simple line width for uniform scaling", () => {
    const { graphics, ctx } = createGraphics();
    const path = { kind: "path" };
    ctx._transform = matrix(2, 0, 0, 2, 0, 0);
    graphics.current.lineWidth = 0.25;

    graphics.rescaleAndStroke(path, true);

    expect(ctx.lineWidth).toBeCloseTo(0.5);
    expect(callsOf(ctx, "stroke")[0].args).toEqual([path]);
    expect(callsOf(ctx, "save")).toHaveLength(0);
  });

  test("rescaleAndStroke rescales non-uniform paths and dashes", () => {
    const { graphics, ctx } = createGraphics();
    const path = new FakePath2D();
    ctx._transform = matrix(2, 0, 0, 1, 0, 0);
    graphics.current.lineWidth = 0.25;
    ctx._lineDash = [8, 4];
    ctx.lineDashOffset = 8;

    graphics.rescaleAndStroke(path, false);

    const scaledPath = callsOf(ctx, "stroke")[0].args[0];
    expect(scaledPath).toBeInstanceOf(FakePath2D);
    expect(scaledPath.ops[0]).toMatchObject({ type: "addPath", path });
    expect(ctx.getLineDash()).toEqual([2, 1]);
    expect(ctx.lineDashOffset).toBe(2);
    expect(ctx.lineWidth).toBe(0.25);
    expect(callsOf(ctx, "scale")[0].args).toEqual([2, 4]);
  });

  test("rescaleAndStroke restores state when saveRestore is requested", () => {
    const { graphics, ctx } = createGraphics();
    const path = new FakePath2D();
    ctx._transform = matrix(2, 0, 0, 1, 0, 0);
    graphics.current.lineWidth = 0.25;
    ctx._lineDash = [8, 4];
    ctx.lineDashOffset = 8;

    graphics.rescaleAndStroke(path, true);

    expect(callsOf(ctx, "save")).toHaveLength(1);
    expect(callsOf(ctx, "restore")).toHaveLength(1);
    expect(ctx.getLineDash()).toEqual([8, 4]);
    expect(ctx.lineDashOffset).toBe(8);
  });
});

describe("marked content visibility", () => {
  test("OC marked content hides nested content until it is ended", () => {
    const optionalContentConfig = { isVisible: jest.fn(() => false) };
    const { graphics } = createGraphics({ optionalContentConfig });

    graphics.beginMarkedContent(0, "Span");
    expect(graphics.contentVisible).toBe(true);

    graphics.beginMarkedContentProps(1, "OC", { id: "layer-1" });
    expect(optionalContentConfig.isVisible).toHaveBeenCalledWith({
      id: "layer-1",
    });
    expect(graphics.contentVisible).toBe(false);
    expect(graphics.isContentVisible()).toBe(false);

    graphics.endMarkedContent(2);
    expect(graphics.contentVisible).toBe(true);
    expect(graphics.isContentVisible()).toBe(true);
  });

  test("non-OC marked content stays visible", () => {
    const { graphics } = createGraphics();
    graphics.beginMarkedContentProps(0, "P", {});
    expect(graphics.contentVisible).toBe(true);
    expect(graphics.markedContentStack).toHaveLength(1);
    graphics.endMarkedContent(1);
    expect(graphics.markedContentStack).toHaveLength(0);
  });

  test("isContentVisible requires every stack entry to be visible", () => {
    const { graphics } = createGraphics();
    graphics.markedContentStack.push({ visible: true });
    graphics.markedContentStack.push({ visible: false });
    graphics.markedContentStack.push({ visible: true });
    expect(graphics.isContentVisible()).toBe(false);

    graphics.markedContentStack.pop();
    expect(graphics.isContentVisible()).toBe(false);
    graphics.markedContentStack.pop();
    expect(graphics.isContentVisible()).toBe(true);
  });
});

describe("beginDrawing and endDrawing", () => {
  test("clears the canvas, resets state and composes page transforms", () => {
    const { graphics, ctx } = createGraphics({ width: 100, height: 50 });
    ctx.fillStyle = "#123456";

    graphics.beginDrawing({
      transform: [2, 0, 0, 3, 0, 0],
      viewport: { transform: [1, 0, 0, 1, 10, 20], scale: 2 },
    });

    const fillRect = callsOf(ctx, "fillRect");
    expect(fillRect).toHaveLength(1);
    expect(fillRect[0].args).toEqual([0, 0, 100, 50]);
    expect(ctx.fillStyle).toBe("#000000");
    expect(ctx.lineWidth).toBe(1);
    expect(ctx.globalAlpha).toBe(1);
    expect(graphics.outputScaleX).toBe(2);
    expect(graphics.outputScaleY).toBe(3);
    expect(graphics.viewportScale).toBe(2);
    expect(graphics.baseTransform).toEqual([2, 0, 0, 3, 20, 60]);
  });

  test("uses a requested background color while clearing", () => {
    const { graphics, ctx } = createGraphics({ width: 10, height: 10 });
    graphics.beginDrawing({
      transform: null,
      viewport: { transform: IDENTITY, scale: 1 },
      background: "#abcdef",
    });

    expect(ctx.calls.find(c => c.name === "fillRect")).toBeDefined();
    expect(ctx.fillStyle).toBe("#000000");
  });

  test("transparency renders into a separate canvas and composites on end", () => {
    const { graphics, ctx, factory } = createGraphics({
      width: 20,
      height: 10,
    });

    graphics.beginDrawing({
      transform: null,
      viewport: { transform: IDENTITY, scale: 1 },
      transparency: true,
    });

    expect(factory.create).toHaveBeenCalledWith(20, 10);
    const entry = factory.created[0];
    expect(graphics.transparentCanvas).toBe(entry.canvas);
    expect(graphics.compositeCtx).toBe(ctx);
    expect(graphics.ctx).toBe(entry.context);

    graphics.endDrawing();

    expect(graphics.ctx).toBe(ctx);
    expect(graphics.transparentCanvas).toBeNull();
    expect(factory.destroy).toHaveBeenCalledWith(entry);
    expect(callsOf(ctx, "drawImage")[0].args[0]).toBe(entry.canvas);
  });

  test("endDrawing is safe when drawing never started", () => {
    const { graphics } = createGraphics();
    expect(() => graphics.endDrawing()).not.toThrow();
  });
});

describe("annotations and form XObjects", () => {
  function beginAnnotation(graphics, id, canvasName, map) {
