    graphics.beginAnnotation(
      0,
      id,
      [5, 6, 25, 16],
      [1, 0, 0, 1, 10, 20],
      IDENTITY,
      true,
      canvasName
    );
    return map.get(id);
  }

  test("beginAnnotation creates a named annotation canvas and restores on end", () => {
    const factory = createCanvasFactory();
    const map = new Map();
    const { graphics, ctx } = createGraphics({
      factory,
      annotationCanvasMap: map,
    });

    const canvases = beginAnnotation(graphics, 7, "annotation-A", map);

    expect(factory.create).toHaveBeenCalledWith(40, 20);
    expect(Array.isArray(canvases)).toBe(true);
    expect(canvases).toHaveLength(1);
    expect(getAnnotationCanvasName(canvases[0])).toBe("annotation-A");
    expect(graphics.ctx).toBe(factory.created[0].context);
    expect(graphics.current.clipBox).toEqual(new Float32Array([0, 0, 40, 20]));

    graphics.endAnnotation(1);

    expect(graphics.ctx).toBe(ctx);
    expect(graphics.baseTransform).toBeNull();
  });

  test("a same-named annotation canvas is replaced rather than appended", () => {
