    const map = new Map();
    const { graphics } = createGraphics({
      factory,
      annotationCanvasMap: map,
    });

    beginAnnotation(graphics, 7, "annotation-A", map);
    graphics.endAnnotation(1);
    beginAnnotation(graphics, 7, "annotation-A", map);

    const canvases = map.get(7);
    expect(canvases).toHaveLength(1);
    expect(canvases[0]).toBe(factory.created[1].canvas);
  });

  test("annotations without a canvas name are stored directly in the map", () => {
    const factory = createCanvasFactory();
    const map = new Map();
    const { graphics } = createGraphics({
      factory,
      annotationCanvasMap: map,
    });

    beginAnnotation(graphics, 11, undefined, map);

    expect(Array.isArray(map.get(11))).toBe(false);
    expect(map.get(11)).toBe(factory.created[0].canvas);
    graphics.endAnnotation(1);
