  test("annotations without their own canvas are clipped to their rect", () => {
    const { graphics, ctx } = createGraphics();
    graphics.outputScaleX = 2;
    graphics.outputScaleY = 2;
    graphics.beginAnnotation(
      0,
      1,
      [0, 0, 10, 10],
      IDENTITY,
      IDENTITY,
      false
    );

    const clipCalls = callsOf(ctx, "clip");
    expect(clipCalls).toHaveLength(1);
    expect(clipCalls[0].args[0]).toBeInstanceOf(FakePath2D);
    expect(clipCalls[0].args[0].ops[0]).toEqual({
      type: "rect",
      args: [0, 0, 10, 10],
    });
    graphics.endAnnotation(1);
  });

  test("paintFormXObjectBegin applies the matrix and paintFormXObjectEnd restores it", () => {
    const { graphics, ctx } = createGraphics();
    graphics.baseTransform = IDENTITY;

    graphics.paintFormXObjectBegin(0, [2, 0, 0, 2, 5, 6], [0, 0, 10, 10]);

