    } else {
      this.a = this.d = 1;
      this.b = this.c = this.e = this.f = 0;
    }
  }

  translate(tx, ty = 0) {
    this.e += this.a * tx + this.c * ty;
    this.f += this.b * tx + this.d * ty;
    return this;
  }

  scale(sx, sy = sx) {
    this.a *= sx;
    this.b *= sx;
    this.c *= sy;
    this.d *= sy;
    return this;
  }

  toArray() {
    return [this.a, this.b, this.c, this.d, this.e, this.f];
  }
}

function createRecordingGradient(kind, args) {
  return {
    kind,
    args,
    stops: [],
    addColorStop(offset, color) {
      this.stops.push([offset, color]);
    },
  };
}

function createRecordingContext({
  transform = IDENTITY,
  canvas = { width: 600, height: 400 },
} = {}) {
  const calls = {};
  const push = (name, args) => {
    (calls[name] ||= []).push(args);
  };

  const ctx = {
    canvas,
    calls,
    fillStyle: null,
    strokeStyle: null,
    globalAlpha: 1,
    globalCompositeOperation: "source-over",
    _matrix: transform.slice(),

    getTransform() {
      const [a, b, c, d, e, f] = ctx._matrix;
      return { a, b, c, d, e, f };
    },
    setTransform(...args) {
      push("setTransform", args);
      ctx._matrix = args.slice();
    },
    transform(...args) {
      push("transform", args);
    },
    translate(...args) {
      push("translate", args);
    },
    scale(...args) {
      push("scale", args);
    },
    rotate(...args) {
      push("rotate", args);
    },
    save() {
      push("save", []);
    },
    restore() {
      push("restore", []);
    },
    beginPath() {
      push("beginPath", []);
    },
    rect(...args) {
      push("rect", args);
    },
    clip(...args) {
      push("clip", args);
    },
    fill(...args) {
      push("fill", args);
    },
    fillRect(...args) {
      push("fillRect", args);
    },
    clearRect(...args) {
      push("clearRect", args);
    },
    drawImage(...args) {
      push("drawImage", args);
    },
    putImageData(...args) {
      push("putImageData", args);
    },
    createImageData(width, height) {
      const data = {
        width,
        height,
        data: new Uint8ClampedArray(width * height * 4),
      };
      push("createImageData", [width, height, data]);
      return data;
    },
    createLinearGradient(...args) {
      const gradient = createRecordingGradient("linear", args);
      (calls.createLinearGradient ||= []).push(gradient);
      return gradient;
    },
    createRadialGradient(...args) {
      const gradient = createRecordingGradient("radial", args);
      (calls.createRadialGradient ||= []).push(gradient);
      return gradient;
    },
    createPattern(source, repetition) {
      const pattern = {
        source,
        repetition,
        transform: null,
        setTransform(matrix) {
          this.transform = matrix;
        },
      };
      push("createPattern", [source, repetition, pattern]);
      return pattern;
    },
  };

  return ctx;
}

function createCanvasFactory() {
  const created = [];
  const destroyed = [];

  return {
    created,
    destroyed,
    create(width, height) {
      const context = createRecordingContext({ canvas: { width, height } });
      const entry = { canvas: { width, height }, context };
      created.push({ width, height, entry });
      return entry;
    },
    destroy(entry) {
      destroyed.push(entry);
    },
  };
}

function createGraphics(ctx) {
  const calls = {
    transform: [],
    executeOperatorList: [],
    endDrawing: 0,
    dependencySave: 0,
    dependencyRestore: 0,
    updateClipFromPath: 0,
  };

  return {
    ctx,
    calls,
    groupLevel: 0,
    baseTransform: null,
    current: {
      minMax: [Infinity, Infinity, -Infinity, -Infinity],
      transferMapsFallback: null,
      patternFill: true,
      patternStroke: true,
      fillColor: null,
      strokeColor: null,
      updateClipFromPath() {
        calls.updateClipFromPath++;
      },
    },
    dependencyTracker: {
      save() {
        calls.dependencySave++;
        return this;
      },
      restore() {
        calls.dependencyRestore++;
        return this;
      },
    },
    transform(...args) {
      calls.transform.push(args);
    },
    executeOperatorList(operatorList) {
      calls.executeOperatorList.push(operatorList);
    },
    endDrawing() {
      calls.endDrawing++;
    },
  };
}

function createGraphicsFactory(graphics) {
  const calls = [];
  return {
    calls,
    createCanvasGraphics(ctx, opIdx) {
      calls.push([ctx, opIdx]);
      return graphics;
    },
  };
}

function makeRadialAxial({
  type = "axial",
  bbox = [0, 0, 10, 10],
  colorStops = [
    [0, "red"],
    [1, "blue"],
  ],
  p0 = [0, 0],
  p1 = [10, 0],
  r0 = 0,
  r1 = 10,
} = {}) {
  return getShadingPattern([
    "RadialAxial",
    type,
    bbox,
    colorStops,
    p0,
    p1,
    r0,
    r1,
  ]);
}

function makeMesh({
  posData = new Float32Array(0),
  colData = new Uint8Array(0),
  vertexCount = 0,
  bounds = [0, 0, 10, 10],
  bbox = [0, 0, 10, 10],
  background = null,
} = {}) {
  return getShadingPattern([
    "Mesh",
    0,
    posData,
    colData,
    vertexCount,
    bounds,
    bbox,
    background,
  ]);
}

function makeTiling({
  color = "#000000",
  operatorList = ["op"],
  matrix = IDENTITY,
  bbox = [0, 0, 10, 10],
  xstep = 10,
  ystep = 10,
  paintType = 2,
  tilingType = 1,
  needsIsolation,
  ctx = createRecordingContext(),
  canvasGraphicsFactory,
  baseTransform = IDENTITY,
} = {}) {
  const IR = [
    null,
    color,
    operatorList,
    matrix,
    bbox,
    xstep,
    ystep,
    paintType,
    tilingType,
    needsIsolation,
  ];
  return new TilingPattern(IR, ctx, canvasGraphicsFactory, baseTransform);
}

function makeOwner({ canvasFactory, graphicsFactory, ctx } = {}) {
  return {
    canvasFactory: canvasFactory ?? createCanvasFactory(),
    canvasGraphicsFactory: graphicsFactory,
    ctx: ctx ?? createRecordingContext(),
    groupLevel: 5,
    baseTransform: IDENTITY.slice(),
    current: {
      transferMapsFallback: null,
    },
  };
}

