describe("PathType and getShadingPattern", () => {
  test("exposes the three PDF path types", () => {
    expect(PathType).toEqual({
      FILL: "Fill",
      STROKE: "Stroke",
      SHADING: "Shading",
    });
  });

  test.each([
    ["axial", false],
    ["radial", true],
  ])("creates a %s RadialAxial shading pattern", (type, isRadial) => {
    const pattern = makeRadialAxial({ type });

    expect(pattern).toBeInstanceOf(Object);
    expect(pattern.isRadial()).toBe(isRadial);
    expect(pattern.isModifyingCurrentTransform()).toBe(false);
    expect(pattern.matrix).toBeNull();
  });

  test("creates a Mesh shading pattern", () => {
    const pattern = makeMesh();

    expect(pattern.isModifyingCurrentTransform()).toBe(true);
    expect(pattern.matrix).toBeNull();
  });

  test("creates a Dummy shading pattern returning the fallback color", () => {
    const pattern = getShadingPattern(["Dummy"]);

    expect(pattern.getPattern()).toBe("hotpink");
    expect(pattern.isModifyingCurrentTransform()).toBe(false);
  });

  test("throws for an unknown shading IR type", () => {
    expect(() => getShadingPattern(["Unknown"])).toThrow(
      "Unknown IR type: Unknown"
    );
  });
});

describe("RadialAxialShadingPattern geometry predicates", () => {
  test("isOriginBased is true for an axial gradient starting at the origin", () => {
    expect(makeRadialAxial({ type: "axial", p0: [0, 0], p1: [50, 5] }).isOriginBased()).toBe(
      true
    );
  });

  test("isOriginBased is false when an axial gradient starts away from the origin", () => {
    expect(makeRadialAxial({ type: "axial", p0: [1, 0] }).isOriginBased()).toBe(
      false
    );
  });

  test("isOriginBased for radial gradients requires both circle centres at the origin", () => {
    expect(
      makeRadialAxial({ type: "radial", p0: [0, 0], p1: [0, 0] }).isOriginBased()
    ).toBe(true);
    expect(
      makeRadialAxial({ type: "radial", p0: [0, 0], p1: [1, 0] }).isOriginBased()
    ).toBe(false);
  });

  test("areConic is always false for axial gradients", () => {
    expect(makeRadialAxial({ type: "axial", p0: [0, 0], p1: [1, 0] }).areConic()).toBe(
      false
    );
  });

  test("areConic is true when the radial circles overlap", () => {
    const pattern = makeRadialAxial({
      type: "radial",
      p0: [0, 0],
      p1: [1, 0],
      r0: 10,
      r1: 10,
    });

    expect(pattern.areConic()).toBe(true);
  });

  test("areConic is false when one radial circle fully contains the other", () => {
    const pattern = makeRadialAxial({
      type: "radial",
      p0: [0, 0],
      p1: [1, 0],
      r0: 10,
      r1: 2,
    });

    expect(pattern.areConic()).toBe(false);
  });
});

describe("RadialAxialShadingPattern.getPattern for shading paths", () => {
  test("clips to the bbox and returns a plain gradient", () => {
    const pattern = makeRadialAxial({
      type: "axial",
      bbox: [1, 2, 21, 12],
      colorStops: [
        [0, "#ff0000"],
        [0.5, "#00ff00"],
        [1, "#0000ff"],
      ],
      p0: [10, 20],
      p1: [70, 20],
    });
    const ctx = createRecordingContext();
    const owner = {
      current: { transferMapsFallback: null },
    };

    const result = pattern.getPattern(ctx, owner, IDENTITY, PathType.SHADING);

    expect(ctx.calls.clip).toHaveLength(1);
    expect(ctx.calls.clip[0][0]).toBeInstanceOf(FakePath2D);
    expect(ctx.calls.clip[0][0].ops).toEqual([["rect", 1, 2, 20, 10]]);
    expect(ctx.calls.save).toBeUndefined();
    expect(ctx.calls.createLinearGradient).toHaveLength(1);
    expect(ctx.calls.createLinearGradient[0].args).toEqual([10, 20, 70, 20]);
    expect(ctx.calls.createLinearGradient[0].stops).toEqual([
      [0, "#ff0000"],
      [0.5, "#00ff00"],
      [1, "#0000ff"],
    ]);
    expect(result).toBe(ctx.calls.createLinearGradient[0]);
  });

  test("draws the reversed conic gradient before filling the normal gradient", () => {
    const pattern = makeRadialAxial({
      type: "radial",
      bbox: [0, 0, 50, 50],
      colorStops: [
        [0, "red"],
        [1, "blue"],
      ],
      p0: [0, 0],
      p1: [1, 0],
      r0: 10,
      r1: 10,
    });
    const ctx = createRecordingContext();
    const owner = {
      current: { transferMapsFallback: null },
    };

    const result = pattern.getPattern(ctx, owner, IDENTITY, PathType.SHADING);

    expect(ctx.calls.save).toHaveLength(1);
    expect(ctx.calls.restore).toHaveLength(1);
    expect(ctx.calls.fillRect).toEqual([[-1e10, -1e10, 2e10, 2e10]]);
    expect(ctx.calls.createRadialGradient).toHaveLength(2);

    const [reversed, normal] = ctx.calls.createRadialGradient;
    expect(reversed.args).toEqual([1, 0, 10, 0, 0, 10]);
    expect(reversed.stops).toEqual([
      [0, "blue"],
      [1, "red"],
    ]);
    expect(normal.args).toEqual([0, 0, 10, 1, 0, 10]);
    expect(normal.stops).toEqual([
      [0, "red"],
      [1, "blue"],
    ]);
    expect(result).toBe(normal);
    // One clip for the reversed fill and one for the returned gradient.
    expect(ctx.calls.clip).toHaveLength(2);
  });

  test("rasterizes shading paths when transfer maps are active", () => {
    const transferMaps = { applyToCanvas: jest.fn() };
    const pattern = makeRadialAxial({
      type: "axial",
      bbox: [0, 0, 10, 20],
      p0: [1, 1],
      p1: [5, 5],
    });
    const ctx = createRecordingContext({ transform: [2, 0, 0, 2, 3, 4] });
    const factory = createCanvasFactory();
    const owner = {
      canvasFactory: factory,
      baseTransform: IDENTITY,
      current: {
        transferMapsFallback: transferMaps,
        clipBox: [-5, -5, 45, 25],
      },
    };

    const result = pattern.getPattern(
      ctx,
      owner,
      [0.5, 0, 0, 0.5, 0, 0],
      PathType.SHADING
    );

    expect(factory.created).toHaveLength(1);
    expect(factory.created[0]).toMatchObject({ width: 50, height: 30 });
    const tmpCtx = factory.created[0].entry.context;
    expect(tmpCtx.calls.clearRect).toEqual([[0, 0, 50, 30]]);
    expect(tmpCtx.calls.rect).toEqual([[0, 0, 50, 30]]);
    expect(tmpCtx.calls.translate).toEqual([[5, 5]]);
    expect(tmpCtx.calls.transform).toEqual([[2, 0, 0, 2, 3, 4]]);
    expect(tmpCtx.calls.clip[0][0].ops).toEqual([["rect", 0, 0, 10, 20]]);
    expect(tmpCtx.calls.fill).toHaveLength(1);
    expect(transferMaps.applyToCanvas).toHaveBeenCalledWith(tmpCtx);

    expect(ctx.calls.createPattern).toHaveLength(1);
    expect(ctx.calls.createPattern[0][0]).toBe(factory.created[0].entry.canvas);
    expect(ctx.calls.createPattern[0][1]).toBe("no-repeat");
    expect(factory.destroyed).toEqual([factory.created[0].entry]);

    const patternMatrix = ctx.calls.createPattern[0][2].transform;
    expect(patternMatrix.toArray()).toEqual([0.5, 0, 0, 0.5, -2.5, -2.5]);
    expect(result).toBe(ctx.calls.createPattern[0][2]);
  });

  test("creates a radial gradient directly when a square transform is applied", () => {
    const pattern = makeRadialAxial({
      type: "radial",
      bbox: [0, 0, 10, 10],
      colorStops: [
        [0, "white"],
        [1, "black"],
      ],
      p0: [0, 0],
      p1: [0, 0],
      r0: 1,
      r1: 2,
    });
    const ctx = createRecordingContext();
    const getClippedPathBoundingBox = jest.fn();
    const owner = {
      baseTransform: [2, 0, 0, 2, 10, 20],
      canvasFactory: createCanvasFactory(),
      current: {
        transferMapsFallback: null,
        getClippedPathBoundingBox,
      },
    };

    const result = pattern.getPattern(ctx, owner, IDENTITY, PathType.FILL);

    expect(getClippedPathBoundingBox).not.toHaveBeenCalled();
    expect(ctx.calls.createRadialGradient).toHaveLength(1);
    expect(ctx.calls.createRadialGradient[0].args).toEqual([
      10, 20, 2, 10, 20, 4,
    ]);
    expect(ctx.calls.createRadialGradient[0].stops).toEqual([
      [0, "white"],
      [1, "black"],
    ]);
    expect(result).toBe(ctx.calls.createRadialGradient[0]);
  });
});

