describe("MeshShadingPattern.getPattern", () => {
  function triangleMesh(overrides = {}) {
    return makeMesh({
      posData: new Float32Array([0, 0, 10, 0, 0, 10]),
      colData: new Uint8Array([
        255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255,
      ]),
      vertexCount: 3,
      ...overrides,
    });
  }

  test("rasterizes triangles with the CPU path and creates a no-repeat pattern", () => {
    const pattern = triangleMesh();
    const ctx = createRecordingContext();
    const factory = createCanvasFactory();
    const owner = {
      canvasFactory: factory,
      baseTransform: IDENTITY,
      current: { transferMapsFallback: null },
    };

    const result = pattern.getPattern(
      ctx,
      owner,
      IDENTITY,
      PathType.SHADING
    );

    expect(ctx.calls.clip[0][0].ops).toEqual([["rect", 0, 0, 10, 10]]);
    expect(factory.created).toHaveLength(1);
    // 10 * sqrt(1.1) style padding: ceil(10 * 1.1) + 2 * border.
    expect(factory.created[0]).toMatchObject({ width: 15, height: 15 });

    const tmpCtx = factory.created[0].entry.context;
    expect(tmpCtx.calls.createImageData).toHaveLength(1);
    expect(tmpCtx.calls.createImageData[0].slice(0, 2)).toEqual([11, 11]);

    const imageData = tmpCtx.calls.createImageData[0][2];
    expect(tmpCtx.calls.putImageData).toHaveLength(1);
    expect(tmpCtx.calls.putImageData[0][0]).toBe(imageData);
    expect(tmpCtx.calls.putImageData[0].slice(1)).toEqual([2, 2]);
    // At least one pixel must have been rasterized.
    expect(Array.from(imageData.data).some(value => value !== 0)).toBe(true);

    expect(ctx.calls.setTransform).toBeUndefined();
    expect(ctx.calls.translate).toHaveLength(1);
    expect(ctx.calls.translate[0][0]).toBeCloseTo(-2 * (10 / 11));
    expect(ctx.calls.translate[0][1]).toBeCloseTo(-2 * (10 / 11));
    expect(ctx.calls.scale).toEqual([[10 / 11, 10 / 11]]);

    expect(ctx.calls.createPattern).toHaveLength(1);
    expect(ctx.calls.createPattern[0][1]).toBe("no-repeat");
    expect(factory.destroyed).toHaveLength(1);
    expect(result).toBe(ctx.calls.createPattern[0][2]);
  });

  test("pre-fills the mesh image with the background and applies owner transforms", () => {
    const transferMaps = { applyToCanvas: jest.fn() };
    const pattern = makeMesh({
      vertexCount: 0,
      bounds: [0, 0, 4, 4],
      bbox: [0, 0, 4, 4],
      background: [10, 20, 30],
    });
    pattern.matrix = [2, 0, 0, 2, 0, 0];

    const ctx = createRecordingContext();
    const factory = createCanvasFactory();
    const owner = {
      canvasFactory: factory,
      baseTransform: [1, 0, 0, 1, 5, 6],
      current: { transferMapsFallback: transferMaps },
    };

    pattern.getPattern(ctx, owner, IDENTITY, PathType.FILL);

    expect(factory.created).toHaveLength(1);
    expect(factory.created[0]).toMatchObject({ width: 13, height: 13 });
    const tmpCtx = factory.created[0].entry.context;
    expect(tmpCtx.calls.createImageData[0].slice(0, 2)).toEqual([9, 9]);

    const imageData = tmpCtx.calls.createImageData[0][2];
    expect(Array.from(imageData.data.slice(0, 4))).toEqual([10, 20, 30, 255]);
    expect(
      Array.from(imageData.data.slice(imageData.data.length - 4))
    ).toEqual([10, 20, 30, 255]);
    expect(transferMaps.applyToCanvas).toHaveBeenCalledWith(tmpCtx);

    expect(ctx.calls.setTransform).toEqual([[1, 0, 0, 1, 5, 6]]);
    expect(ctx.calls.transform).toEqual([[2, 0, 0, 2, 0, 0]]);
    expect(ctx.calls.translate[0][0]).toBeCloseTo(-2 * (4 / 9));
    expect(ctx.calls.scale).toEqual([[4 / 9, 4 / 9]]);
  });

  test("falls back to one-pixel dimensions for an empty bounding box", () => {
    const pattern = makeMesh({
      vertexCount: 0,
