    };
  }

  test("renders the tile through the graphics factory and positions the pattern", () => {
    const { ctx, factory, graphics, graphicsFactory, owner, result } = setup();

    expect(graphicsFactory.calls).toHaveLength(1);
    expect(graphicsFactory.calls[0][1]).toBe(7);
    expect(graphics.groupLevel).toBe(9);
    expect(graphics.current.transferMapsFallback).toBeNull();
    expect(graphics.ctx.fillStyle).toBe("#ff0000");
    expect(graphics.ctx.strokeStyle).toBe("#ff0000");
    expect(graphics.current.fillColor).toBe("#ff0000");
    expect(graphics.calls.transform).toEqual([[0, 1, 0, 0, 1, 0, 0]]);
    expect(graphics.calls.executeOperatorList).toEqual([["op-a", "op-b"]]);
    expect(graphics.calls.endDrawing).toBe(1);
    expect(graphics.calls.dependencySave).toBe(1);
    expect(graphics.calls.dependencyRestore).toBe(1);
    expect(graphics.calls.updateClipFromPath).toBe(1);

    expect(factory.created).toHaveLength(1);
    expect(factory.created[0]).toMatchObject({ width: 10, height: 10 });
    const tmpCtx = factory.created[0].entry.context;
    expect(tmpCtx.calls.translate).toEqual([[-2, -3]]);
    expect(tmpCtx.calls.clip[0][0].ops).toEqual([["rect", 2, 3, 10, 10]]);
