    const { result } = setup({
      inverse: [1, 0, 0, 1, 5, 6],
      pathType: PathType.SHADING,
    });

    expect(result.transform.toArray()).toEqual([1, 0, 0, 1, 7, 9]);
  });

  test("redraws overlapping tiles into an xstep by ystep canvas", () => {
    const { factory, result } = setup({
      bbox: [2, 3, 12, 13],
      xstep: 5,
      ystep: 5,
    });

    expect(factory.created.map(({ width, height }) => [width, height])).toEqual([
      [10, 10],
      [10, 5],
      [5, 5],
    ]);

    const bandCtx = factory.created[1].entry.context;
    expect(bandCtx.calls.drawImage).toHaveLength(3);

    const finalCtx = factory.created[2].entry.context;
    expect(finalCtx.calls.drawImage).toHaveLength(3);

    expect(factory.destroyed).toHaveLength(3);
    expect(factory.destroyed[0]).toBe(factory.created[1].entry);
    expect(factory.destroyed[1]).toBe(factory.created[0].entry);
    expect(factory.destroyed[2]).toBe(factory.created[2].entry);

    expect(result.source).toBe(factory.created[2].entry.canvas);
    expect(result.source).toMatchObject({ width: 5, height: 5 });
  });

  test("redraws only horizontally when the y step already covers the bbox", () => {
    const { factory, result } = setup({
      bbox: [2, 3, 12, 13],
      xstep: 5,
      ystep: 10,
    });

    expect(factory.created.map(({ width, height }) => [width, height])).toEqual([
      [10, 10],
      [5, 10],
    ]);
    expect(factory.created[1].entry.context.calls.drawImage).toHaveLength(3);
    expect(factory.destroyed).toHaveLength(2);
    expect(result.source).toMatchObject({ width: 5, height: 10 });
  });
});

