      transferMapsFallback: null,
      patternFill: true,
      patternStroke: true,
      fillColor: null,
      strokeColor: null,
      updateClipFromPath() {
        calls.updateClipFromPath++;
      },
    },
    dependencyTracker: {
      save() {
        calls.save++;
