}

function makeDrawOwner() {
  const ctx = createRecordingContext();
  const canvasFactory = createCanvasFactory();
  const current = {
    minMax: [Infinity, Infinity, -Infinity, -Infinity],
    transferMapsFallback: null,
    patternFill: true,
    patternStroke: true,
    fillColor: null,
    strokeColor: null,
    updateCount: 0,
    updateClipFromPath() {
      current.updateCount++;
    },
  };
  const owner = {
    ctx,
    canvasFactory,
    groupLevel: 2,
    current,
    baseTransform: [2, 0, 0, 2, 0, 0],
    baseTransformStack: [],
    inSMaskMode: false,
    dependencyTracker: null,
    saveCount: 0,
    restoreCount: 0,
    executed: [],
    save() {
      owner.saveCount++;
    },
    restore() {
      owner.restoreCount++;
    },
    executeOperatorList(list) {
      owner.executed.push(list);
    },
  };
  return { owner, ctx, canvasFactory };
}

function radialAxialIR(overrides = {}) {
  const {
    type = "axial",
    bbox = [0, 0, 100, 100],
    colorStops = [
      [0, "#ff0000"],
      [1, "#0000ff"],
    ],
    p0 = [0, 0],
    p1 = [100, 0],
    r0 = 0,
    r1 = 50,
  } = overrides;
  return ["RadialAxial", type, bbox, colorStops, p0, p1, r0, r1];
}

function meshIR(overrides = {}) {
  const {
    posData = new Float32Array([0, 0, 10, 0, 0, 10]),
    colData = new Uint8Array([255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255]),
    vertexCount = 3,
    bounds = [0, 0, 10, 10],
    bbox = [0, 0, 10, 10],
    background = null,
  } = overrides;
  return ["Mesh", 0, posData, colData, vertexCount, bounds, bbox, background];
}

function tilingPattern(overrides = {}) {
  const {
    ctx = createRecordingContext(),
    canvasGraphicsFactory = createGraphicsFactory(createFakeGraphics(ctx)),
    baseTransform = IDENTITY.slice(),
    color = "#336699",
    operatorList = ["operator-list"],
    matrix = IDENTITY.slice(),
    bbox = [0, 0, 10, 10],
    xstep = 10,
    ystep = 10,
    paintType = 2,
    tilingType = 1,
    needsIsolation = undefined,
  } = overrides;
  const pattern = new TilingPattern(
    [
      null,
      color,
      operatorList,
      matrix,
      bbox,
      xstep,
      ystep,
      paintType,
      tilingType,
      needsIsolation,
    ],
    ctx,
    canvasGraphicsFactory,
    baseTransform
  );
  return { pattern, ctx, canvasGraphicsFactory };
}

