describe("RadialAxialShadingPattern predicates", () => {
  test("isRadial distinguishes axial from radial", () => {
    expect(getShadingPattern(radialAxialIR({ type: "axial" })).isRadial()).toBe(
      false
    );
    expect(
      getShadingPattern(radialAxialIR({ type: "radial" })).isRadial()
    ).toBe(true);
  });

  test("isOriginBased only requires p1 at origin for radial gradients", () => {
    const axial = getShadingPattern(
      radialAxialIR({ type: "axial", p0: [0, 0], p1: [10, 20] })
    );
    expect(axial.isOriginBased()).toBe(true);

    const radialAtOrigin = getShadingPattern(
      radialAxialIR({ type: "radial", p0: [0, 0], p1: [0, 0] })
    );
    expect(radialAtOrigin.isOriginBased()).toBe(true);

    const radialOffOrigin = getShadingPattern(
      radialAxialIR({ type: "radial", p0: [0, 0], p1: [1, 0] })
    );
    expect(radialOffOrigin.isOriginBased()).toBe(false);

    const nonZeroStart = getShadingPattern(
      radialAxialIR({ type: "axial", p0: [0, 1], p1: [10, 20] })
    );
    expect(nonZeroStart.isOriginBased()).toBe(false);
  });

  test("areConic is false for axial and for nested circles", () => {
    expect(
      getShadingPattern(radialAxialIR({ type: "axial" })).areConic()
    ).toBe(false);
    expect(
      getShadingPattern(
        radialAxialIR({
          type: "radial",
          p0: [0, 0],
          p1: [0, 0],
          r0: 10,
          r1: 5,
        })
      ).areConic()
    ).toBe(false);
  });

  test("areConic is true when neither circle contains the other", () => {
    expect(
      getShadingPattern(
        radialAxialIR({
          type: "radial",
          p0: [0, 0],
          p1: [1, 0],
          r0: 10,
          r1: 10,
        })
      ).areConic()
    ).toBe(true);
    expect(
      getShadingPattern(
        radialAxialIR({
          type: "radial",
          p0: [0, 0],
          p1: [100, 0],
          r0: 1,
          r1: 1,
        })
      ).areConic()
    ).toBe(true);
  });
});

