describe("TilingPattern.canSkipPatternCanvas", () => {
  test("returns tile indices for areas within a single tile", () => {
    const { pattern } = tilingPattern({
      bbox: [0, 0, 10, 10],
      xstep: 10,
      ystep: 10,
    });
    expect(pattern.canSkipPatternCanvas([5, 5, 0, 0])).toEqual([0, 0]);
    expect(pattern.canSkipPatternCanvas([5, 5, 10, 10])).toEqual([1, 1]);
  });

  test("returns null when any dimension exceeds the step", () => {
    const { pattern } = tilingPattern({
      bbox: [0, 0, 10, 10],
      xstep: 10,
      ystep: 10,
    });
    expect(pattern.canSkipPatternCanvas([11, 5, 0, 0])).toBeNull();
    expect(pattern.canSkipPatternCanvas([5, 11, 0, 0])).toBeNull();
  });

  test("returns null when the area spans multiple tiles", () => {
    const { pattern } = tilingPattern({
      bbox: [0, 0, 10, 10],
      xstep: 10,
      ystep: 10,
    });
    expect(pattern.canSkipPatternCanvas([5, 5, 6, 6])).toBeNull();
  });

  test("compares against the absolute step for negative steps", () => {
    const { pattern } = tilingPattern({
      bbox: [0, 0, 10, 10],
      xstep: -10,
      ystep: -10,
    });
    expect(pattern.canSkipPatternCanvas([5, 5, 0, 0])).toEqual([0, 0]);
  });
});

describe("TilingPattern.updatePatternDims", () => {
