    });
    const dims = [0, 0, 0, 0];
    pattern.updatePatternDims([0, 0, 10, 20], dims);
    expect(dims).toEqual([20, 10, 0, -10]);
  });
});

describe("TilingPattern.clipBbox", () => {
  test("clips to the bbox and records the device-space minMax", () => {
    const { pattern } = tilingPattern();
    const ctx = createRecordingContext();
    const graphics = createFakeGraphics(ctx);

    pattern.clipBbox(graphics, 2, 3, 12, 13);

    expect(ctx.calls.clip).toHaveLength(1);
    expect(ctx.calls.clip[0][0]).toBeInstanceOf(FakePath2D);
    expect(ctx.calls.clip[0][0].ops).toEqual([["rect", 2, 3, 10, 10]]);
    expect(graphics.current.minMax).toEqual([2, 3, 12, 13]);
    expect(graphics.calls.updateClipFromPath).toBe(1);
  });

  test("transforms the bbox through the current transform", () => {
    const { pattern } = tilingPattern();
    const ctx = createRecordingContext({ transform: [2, 0, 0, 2, 1, 1] });
    const graphics = createFakeGraphics(ctx);

    pattern.clipBbox(graphics, 0, 0, 10, 10);

    expect(graphics.current.minMax).toEqual([1, 1, 21, 21]);
  });
});

describe("TilingPattern.setFillAndStrokeStyleToContext", () => {
  function makeGraphics() {
    const ctx = createRecordingContext();
    const graphics = createFakeGraphics(ctx);
    return { ctx, graphics };
  }

  test("COLORED always paints black and clears pattern flags", () => {
    const { pattern } = tilingPattern();
    const { ctx, graphics } = makeGraphics();

    pattern.setFillAndStrokeStyleToContext(graphics, 1, "#ff0000");

    expect(ctx.fillStyle).toBe("#000000");
    expect(ctx.strokeStyle).toBe("#000000");
    expect(graphics.current.fillColor).toBe("#000000");
    expect(graphics.current.strokeColor).toBe("#000000");
    expect(graphics.current.patternFill).toBe(false);
    expect(graphics.current.patternStroke).toBe(false);
  });

  test("UNCOLORED keeps the supplied colour", () => {
    const { pattern } = tilingPattern();
    const { ctx, graphics } = makeGraphics();

    pattern.setFillAndStrokeStyleToContext(graphics, 2, "#ff8800");

    expect(ctx.fillStyle).toBe("#ff8800");
    expect(ctx.strokeStyle).toBe("#ff8800");
    expect(graphics.current.fillColor).toBe("#ff8800");
  });

  test("mapped colours are used for the canvas but raw colours for state", () => {
    const { pattern } = tilingPattern();
    const { ctx, graphics } = makeGraphics();
    const transferMaps = { applyToColor: jest.fn(() => "#010203") };
    graphics.current.transferMapsFallback = transferMaps;

    pattern.setFillAndStrokeStyleToContext(graphics, 2, "#ff8800");

    expect(transferMaps.applyToColor).toHaveBeenCalledWith("#ff8800");
    expect(ctx.fillStyle).toBe("#010203");
    expect(graphics.current.fillColor).toBe("#ff8800");
  });

  test("rejects unsupported paint types", () => {
    const { pattern } = tilingPattern();
    const { graphics } = makeGraphics();

    let error;
    try {
      pattern.setFillAndStrokeStyleToContext(graphics, 7, "#000000");
    } catch (e) {
      error = e;
    }
    expect(error).toBeDefined();
    expect(error.name).toBe("FormatError");
    expect(error.message).toBe("Unsupported paint type: 7");
  });
});

// ---------------------------------------------------------------------------
// TilingPattern.createPatternCanvas / getPattern.
// ---------------------------------------------------------------------------

describe("TilingPattern.getPattern", () => {
  test("renders one tile and returns a repeating pattern", () => {
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const tmpCtx = createRecordingContext({ canvas: { width: 10, height: 10 } });
    const graphics = createFakeGraphics(tmpCtx);
    const graphicsFactory = createGraphicsFactory(graphics);
    const { pattern } = tilingPattern({
      ctx,
      canvasGraphicsFactory: graphicsFactory,
      bbox: [0, 0, 10, 10],
      xstep: 10,
      ystep: 10,
      color: "#123456",
      operatorList: ["tile-ops"],
    });
    const owner = makeOwner({ canvasFactory, baseTransform: IDENTITY });

    const result = pattern.getPattern(
      ctx,
      owner,
      IDENTITY,
      PathType.FILL,
      7
    );

    expect(graphicsFactory.calls).toEqual([[tmpCtx, 7]]);
    expect(graphics.groupLevel).toBe(4);
    expect(graphics.current.transferMapsFallback).toBe(null);
    expect(graphics.current.fillColor).toBe("#123456");
    expect(tmpCtx.fillStyle).toBe("#123456");
    expect(tmpCtx.calls.translate).toEqual([[0, 0]]);
    expect(graphics.calls.transform).toEqual([[0, 1, 0, 0, 1, 0, 0]]);
    expect(tmpCtx.calls.save).toHaveLength(1);
    expect(tmpCtx.calls.restore).toHaveLength(1);
    expect(graphics.calls.save).toBe(1);
    expect(graphics.calls.restore).toBe(1);
    expect(graphics.calls.executeOperatorList).toEqual([["tile-ops"]]);
    expect(graphics.calls.endDrawing).toBe(1);
    expect(tmpCtx.calls.clip[0][0].ops).toEqual([["rect", 0, 0, 10, 10]]);

    expect(ctx.calls.createPattern).toHaveLength(1);
    expect(ctx.calls.createPattern[0][1]).toBe("repeat");
    expect(result).toBe(ctx.calls.createPattern[0][2]);
    expect(matrixValues(result.transform)).toEqual(IDENTITY);
    expect(canvasFactory.destroyed).toEqual([canvasFactory.created[0].entry]);
  });

  test("SHADING positions the pattern with the inverse transform", () => {
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const graphics = createFakeGraphics(
      createRecordingContext({ canvas: { width: 10, height: 10 } })
    );
    const { pattern } = tilingPattern({
      ctx,
      canvasGraphicsFactory: createGraphicsFactory(graphics),
      matrix: [1, 0, 0, 1, 99, 99],
      baseTransform: IDENTITY,
      bbox: [0, 0, 10, 10],
    });
    const owner = makeOwner({ canvasFactory });

    const result = pattern.getPattern(
      ctx,
      owner,
      [1, 0, 0, 1, 5, 6],
      PathType.SHADING
    );

    expect(matrixValues(result.transform)).toEqual([1, 0, 0, 1, 5, 6]);
  });

  test("uses bbox offsets for the pattern transform", () => {
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const graphics = createFakeGraphics(
      createRecordingContext({ canvas: { width: 10, height: 20 } })
    );
    const { pattern } = tilingPattern({
      ctx,
      canvasGraphicsFactory: createGraphicsFactory(graphics),
      bbox: [5, 7, 15, 27],
      xstep: 10,
      ystep: 20,
    });
    const owner = makeOwner({ canvasFactory });

    const result = pattern.getPattern(
      ctx,
      owner,
      IDENTITY,
      PathType.FILL
    );

    expect(canvasFactory.created[0].width).toBe(10);
    expect(canvasFactory.created[0].height).toBe(20);
    expect(matrixValues(result.transform)).toEqual([1, 0, 0, 1, 5, 7]);
  });

  test("redraws overlapping tiles horizontally and vertically", () => {
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const graphics = createFakeGraphics(
      createRecordingContext({ canvas: { width: 10, height: 10 } })
    );
    const { pattern } = tilingPattern({
      ctx,
      canvasGraphicsFactory: createGraphicsFactory(graphics),
      bbox: [0, 0, 10, 10],
      xstep: 5,
      ystep: 5,
    });
    const owner = makeOwner({ canvasFactory });

    const result = pattern.getPattern(
      ctx,
      owner,
      IDENTITY,
      PathType.FILL
    );

    expect(canvasFactory.created.map(({ width, height }) => [width, height])).toEqual([
      [10, 10],
      [10, 5],
      [5, 5],
    ]);
    const bandEntry = canvasFactory.created[1].entry;
    const finalEntry = canvasFactory.created[2].entry;
    expect(bandEntry.context.calls.drawImage).toHaveLength(3);
    expect(finalEntry.context.calls.drawImage).toHaveLength(3);
    expect(canvasFactory.destroyed).toContain(bandEntry);
    expect(canvasFactory.destroyed).toContain(canvasFactory.created[0].entry);
    expect(canvasFactory.destroyed).toContain(finalEntry);
    expect(result.source).toBe(finalEntry.canvas);
    expect(result.repetition).toBe("repeat");
  });

  test("redraws only horizontally when the vertical tile is large enough", () => {
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const graphics = createFakeGraphics(
      createRecordingContext({ canvas: { width: 10, height: 10 } })
    );
    const { pattern } = tilingPattern({
      ctx,
      canvasGraphicsFactory: createGraphicsFactory(graphics),
      bbox: [0, 0, 10, 10],
      xstep: 5,
      ystep: 10,
    });
    const owner = makeOwner({ canvasFactory });

    const result = pattern.getPattern(
      ctx,
      owner,
      IDENTITY,
      PathType.FILL
    );

    expect(canvasFactory.created.map(({ width, height }) => [width, height])).toEqual([
      [10, 10],
      [5, 10],
    ]);
    const finalEntry = canvasFactory.created[1].entry;
    expect(finalEntry.context.calls.drawImage).toHaveLength(3);
    expect(canvasFactory.destroyed).not.toContain(finalEntry);
    expect(result.source).toBe(finalEntry.canvas);
  });
});

// ---------------------------------------------------------------------------
// TilingPattern.drawPattern.
// ---------------------------------------------------------------------------

describe("TilingPattern.drawPattern", () => {
  test("isolates the tile via a temporary canvas by default", () => {
    const { owner, ctx, canvasFactory } = makeDrawOwner();
    const graphics = createFakeGraphics(
      createRecordingContext({ canvas: { width: 10, height: 10 } })
    );
    const graphicsFactory = createGraphicsFactory(graphics);
    const { pattern } = tilingPattern({
      canvasGraphicsFactory: graphicsFactory,
      bbox: [0, 0, 10, 10],
      xstep: 10,
      ystep: 10,
      needsIsolation: true,
    });
    const path = new FakePath2D();
    const originalTracker = { id: "tracker" };
    owner.dependencyTracker = originalTracker;

    pattern.drawPattern(owner, path, false, [1, 1], 9);

    expect(owner.saveCount).toBe(1);
    expect(owner.restoreCount).toBe(1);
    expect(owner.dependencyTracker).toBe(originalTracker);
    expect(ctx.calls.clip[0][0]).toBe(path);
    expect(ctx.calls.setTransform).toEqual([IDENTITY]);
    expect(ctx.calls.translate).toEqual([[10, 10]]);
    expect(ctx.calls.drawImage).toHaveLength(1);
    expect(ctx.calls.drawImage[0][1]).toBe(0);
    expect(ctx.calls.drawImage[0][2]).toBe(0);
    expect(ctx.calls.drawImage[0][3]).toBe(10);
    expect(ctx.calls.drawImage[0][4]).toBe(10);
    expect(canvasFactory.created).toHaveLength(1);
    expect(canvasFactory.destroyed).toHaveLength(1);
    expect(owner.executed).toHaveLength(0);
  });

  test("honours the even-odd fill rule", () => {
    const { owner, ctx } = makeDrawOwner();
    const { pattern } = tilingPattern({
      bbox: [0, 0, 10, 10],
      needsIsolation: true,
    });
    const path = new FakePath2D();

    pattern.drawPattern(owner, path, true, [0, 0], 1);

    expect(ctx.calls.clip[0][0]).toBe(path);
    expect(ctx.calls.clip[0][1]).toBe("evenodd");
  });

  test("executes operators directly when isolation is unnecessary", () => {
    const { owner, ctx, canvasFactory } = makeDrawOwner();
    const { pattern } = tilingPattern({
      bbox: [0, 0, 10, 10],
      xstep: 10,
      ystep: 10,
      needsIsolation: false,
      operatorList: ["direct-ops"],
    });
    const path = new FakePath2D();

    pattern.drawPattern(owner, path, false, [0, 0], 3);

    expect(canvasFactory.created).toHaveLength(0);
    expect(owner.executed).toEqual([["direct-ops"]]);
    expect(owner.baseTransformStack).toHaveLength(0);
    // baseTransform is restored after the direct render.
    expect(owner.baseTransform).toEqual([2, 0, 0, 2, 0, 0]);
    expect(ctx.calls.clip).toHaveLength(2);
    expect(owner.current.fillColor).toBe("#336699");
    expect(owner.current.updateCount).toBe(1);
  });

  test("falls back to isolated rendering for non-trivial global alpha", () => {
    const { owner, ctx, canvasFactory } = makeDrawOwner();
    owner.ctx.globalAlpha = 0.5;
    const graphics = createFakeGraphics(
      createRecordingContext({ canvas: { width: 10, height: 10 } })
    );
    const { pattern } = tilingPattern({
      canvasGraphicsFactory: createGraphicsFactory(graphics),
      bbox: [0, 0, 10, 10],
      needsIsolation: false,
    });
    const path = new FakePath2D();

    pattern.drawPattern(owner, path, false, [0, 0], 2);

    expect(canvasFactory.created).toHaveLength(1);
    expect(ctx.calls.drawImage).toHaveLength(1);
    expect(owner.executed).toHaveLength(0);
  });
});
