import { jest } from "@jest/globals";

import {
  getShadingPattern,
  PathType,
  TilingPattern,
} from "../../src/display/pattern_helper.js";

// ---------------------------------------------------------------------------
// Lightweight browser API substitutes.
// ---------------------------------------------------------------------------

class FakePath2D {
  constructor() {
    this.ops = [];
  }
  rect(...args) {
    this.ops.push(["rect", ...args]);
    return this;
  }
  moveTo(...args) {
    this.ops.push(["moveTo", ...args]);
    return this;
  }
  lineTo(...args) {
    this.ops.push(["lineTo", ...args]);
    return this;
  }
  closePath() {
    this.ops.push(["closePath"]);
    return this;
  }
}

// Faithful enough 2D subset of the DOMMatrix API for the code under test.
class FakeDOMMatrix {
  constructor(init) {
    if (Array.isArray(init)) {
      [this.a, this.b, this.c, this.d, this.e, this.f] = init;
    } else if (init && typeof init === "object") {
      this.a = init.a ?? 1;
      this.b = init.b ?? 0;
      this.c = init.c ?? 0;
      this.d = init.d ?? 1;
      this.e = init.e ?? 0;
      this.f = init.f ?? 0;
    } else {
      this.a = 1;
      this.b = 0;
      this.c = 0;
      this.d = 1;
      this.e = 0;
      this.f = 0;
    }
  }
  translate(tx, ty = 0) {
    this.e += this.a * tx + this.c * ty;
    this.f += this.b * tx + this.d * ty;
    return this;
  }
  scale(sx, sy = sx) {
    this.a *= sx;
    this.b *= sx;
    this.c *= sy;
    this.d *= sy;
    return this;
  }
  toArray() {
    return [this.a, this.b, this.c, this.d, this.e, this.f];
  }
}

const IDENTITY = [1, 0, 0, 1, 0, 0];

function matrixValues(matrix) {
  return [matrix.a, matrix.b, matrix.c, matrix.d, matrix.e, matrix.f];
}

function createGradient(kind, args) {
  return {
    kind,
    args,
    stops: [],
    addColorStop(offset, color) {
      this.stops.push([offset, color]);
    },
  };
}

function createRecordingContext({
  transform = IDENTITY,
  canvas = { width: 800, height: 600 },
} = {}) {
  const calls = {};
  const push = (name, args) => {
    (calls[name] ||= []).push(args);
  };
  const ctx = {
    canvas,
    calls,
    fillStyle: null,
    strokeStyle: null,
    globalAlpha: 1,
    globalCompositeOperation: "source-over",
    _matrix: transform.slice(),

    getTransform() {
      const [a, b, c, d, e, f] = ctx._matrix;
      return { a, b, c, d, e, f };
    },
    setTransform(...args) {
      push("setTransform", args);
      ctx._matrix = args.slice(0, 6);
    },
    transform(...args) {
      push("transform", args);
    },
    translate(...args) {
      push("translate", args);
    },
    scale(...args) {
      push("scale", args);
    },
    rotate(...args) {
      push("rotate", args);
    },
    save() {
      push("save", []);
    },
    restore() {
      push("restore", []);
    },
    beginPath() {
      push("beginPath", []);
    },
    rect(...args) {
      push("rect", args);
    },
    clip(...args) {
      push("clip", args);
    },
    fill(...args) {
      push("fill", args);
    },
    fillRect(...args) {
      push("fillRect", args);
    },
    clearRect(...args) {
      push("clearRect", args);
    },
    drawImage(...args) {
      push("drawImage", args);
    },
    putImageData(...args) {
      push("putImageData", args);
    },
    createImageData(width, height) {
      const imageData = {
        width,
        height,
        data: new Uint8ClampedArray(width * height * 4),
      };
      push("createImageData", [width, height, imageData]);
      return imageData;
    },
    createLinearGradient(...args) {
      const gradient = createGradient("linear", args);
      (calls.createLinearGradient ||= []).push(gradient);
      return gradient;
    },
    createRadialGradient(...args) {
      const gradient = createGradient("radial", args);
      (calls.createRadialGradient ||= []).push(gradient);
      return gradient;
    },
    createPattern(source, repetition) {
      const pattern = {
        source,
        repetition,
        transform: null,
        setTransform(matrix) {
          this.transform = matrix;
        },
      };
      push("createPattern", [source, repetition, pattern]);
      return pattern;
    },
  };
  return ctx;
}

function createCanvasFactory() {
  const created = [];
  const destroyed = [];
  return {
    created,
    destroyed,
    create(width, height) {
      const context = createRecordingContext({ canvas: { width, height } });
      const entry = { canvas: { width, height }, context };
      created.push({ width, height, entry });
      return entry;
    },
    destroy(entry) {
      destroyed.push(entry);
    },
  };
}

function createFakeGraphics(ctx) {
  const calls = {
    transform: [],
    executeOperatorList: [],
    endDrawing: 0,
    save: 0,
    restore: 0,
    updateClipFromPath: 0,
  };
  return {
    ctx,
    calls,
    groupLevel: 0,
    baseTransform: null,
    current: {
      minMax: [Infinity, Infinity, -Infinity, -Infinity],
      transferMapsFallback: null,
      patternFill: true,
      patternStroke: true,
      fillColor: null,
      strokeColor: null,
      updateClipFromPath() {
        calls.updateClipFromPath++;
      },
    },
    dependencyTracker: {
      save() {
        calls.save++;
        return this;
      },
      restore() {
        calls.restore++;
        return this;
      },
    },
    transform(...args) {
      calls.transform.push(args);
    },
    executeOperatorList(list) {
      calls.executeOperatorList.push(list);
    },
    endDrawing() {
      calls.endDrawing++;
    },
  };
}

function createGraphicsFactory(graphics) {
  const calls = [];
  return {
    calls,
    createCanvasGraphics(ctx, opIdx) {
      calls.push([ctx, opIdx]);
      return graphics;
    },
  };
}

function makeOwner({
  canvasFactory = createCanvasFactory(),
  baseTransform = IDENTITY.slice(),
  current = {},
} = {}) {
  return {
    canvasFactory,
    baseTransform,
    groupLevel: 4,
    current: { transferMapsFallback: null, ...current },
  };
}

function makeDrawOwner() {
  const ctx = createRecordingContext();
  const canvasFactory = createCanvasFactory();
  const current = {
    minMax: [Infinity, Infinity, -Infinity, -Infinity],
    transferMapsFallback: null,
    patternFill: true,
    patternStroke: true,
    fillColor: null,
    strokeColor: null,
    updateCount: 0,
    updateClipFromPath() {
      current.updateCount++;
    },
  };
  const owner = {
    ctx,
    canvasFactory,
    groupLevel: 2,
    current,
    baseTransform: [2, 0, 0, 2, 0, 0],
    baseTransformStack: [],
    inSMaskMode: false,
    dependencyTracker: null,
    saveCount: 0,
    restoreCount: 0,
    executed: [],
    save() {
      owner.saveCount++;
    },
    restore() {
      owner.restoreCount++;
    },
    executeOperatorList(list) {
      owner.executed.push(list);
    },
  };
  return { owner, ctx, canvasFactory };
}

function radialAxialIR(overrides = {}) {
  const {
    type = "axial",
    bbox = [0, 0, 100, 100],
    colorStops = [
      [0, "#ff0000"],
      [1, "#0000ff"],
    ],
    p0 = [0, 0],
    p1 = [100, 0],
    r0 = 0,
    r1 = 50,
  } = overrides;
  return ["RadialAxial", type, bbox, colorStops, p0, p1, r0, r1];
}

function meshIR(overrides = {}) {
  const {
    posData = new Float32Array([0, 0, 10, 0, 0, 10]),
    colData = new Uint8Array([255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255]),
    vertexCount = 3,
    bounds = [0, 0, 10, 10],
    bbox = [0, 0, 10, 10],
    background = null,
  } = overrides;
  return ["Mesh", 0, posData, colData, vertexCount, bounds, bbox, background];
}

function tilingPattern(overrides = {}) {
  const {
    ctx = createRecordingContext(),
    canvasGraphicsFactory = createGraphicsFactory(createFakeGraphics(ctx)),
    baseTransform = IDENTITY.slice(),
    color = "#336699",
    operatorList = ["operator-list"],
    matrix = IDENTITY.slice(),
    bbox = [0, 0, 10, 10],
    xstep = 10,
    ystep = 10,
    paintType = 2,
    tilingType = 1,
    needsIsolation = undefined,
  } = overrides;
  const pattern = new TilingPattern(
    [
      null,
      color,
      operatorList,
      matrix,
      bbox,
      xstep,
      ystep,
      paintType,
      tilingType,
      needsIsolation,
    ],
    ctx,
    canvasGraphicsFactory,
    baseTransform
  );
  return { pattern, ctx, canvasGraphicsFactory };
}

beforeAll(() => {
  globalThis.Path2D = FakePath2D;
  globalThis.DOMMatrix = FakeDOMMatrix;
});

afterAll(() => {
  delete globalThis.Path2D;
  delete globalThis.DOMMatrix;
});

// ---------------------------------------------------------------------------
// Public exports and factory.
// ---------------------------------------------------------------------------

describe("pattern_helper public API", () => {
  test("PathType exposes the three path kinds", () => {
    expect(PathType).toEqual({
      FILL: "Fill",
      STROKE: "Stroke",
      SHADING: "Shading",
    });
  });

  test("getShadingPattern builds a radial/axial pattern", () => {
    const pattern = getShadingPattern(radialAxialIR({ type: "radial" }));
    expect(pattern.isRadial()).toBe(true);
    expect(pattern.isModifyingCurrentTransform()).toBe(false);
  });

  test("getShadingPattern builds a mesh pattern", () => {
    const pattern = getShadingPattern(meshIR());
    expect(pattern.isModifyingCurrentTransform()).toBe(true);
  });

  test("getShadingPattern builds a dummy pattern", () => {
    const pattern = getShadingPattern(["Dummy"]);
    expect(pattern.getPattern()).toBe("hotpink");
    expect(pattern.isModifyingCurrentTransform()).toBe(false);
  });

  test("getShadingPattern rejects unknown IR types", () => {
    expect(() => getShadingPattern(["Unknown"])).toThrow(
      "Unknown IR type: Unknown"
    );
  });
});

// ---------------------------------------------------------------------------
// RadialAxialShadingPattern geometry predicates.
// ---------------------------------------------------------------------------

describe("RadialAxialShadingPattern predicates", () => {
  test("isRadial distinguishes axial from radial", () => {
    expect(getShadingPattern(radialAxialIR({ type: "axial" })).isRadial()).toBe(
      false
    );
    expect(
      getShadingPattern(radialAxialIR({ type: "radial" })).isRadial()
    ).toBe(true);
  });

  test("isOriginBased only requires p1 at origin for radial gradients", () => {
    const axial = getShadingPattern(
      radialAxialIR({ type: "axial", p0: [0, 0], p1: [10, 20] })
    );
    expect(axial.isOriginBased()).toBe(true);

    const radialAtOrigin = getShadingPattern(
      radialAxialIR({ type: "radial", p0: [0, 0], p1: [0, 0] })
    );
    expect(radialAtOrigin.isOriginBased()).toBe(true);

    const radialOffOrigin = getShadingPattern(
      radialAxialIR({ type: "radial", p0: [0, 0], p1: [1, 0] })
    );
    expect(radialOffOrigin.isOriginBased()).toBe(false);

    const nonZeroStart = getShadingPattern(
      radialAxialIR({ type: "axial", p0: [0, 1], p1: [10, 20] })
    );
    expect(nonZeroStart.isOriginBased()).toBe(false);
  });

  test("areConic is false for axial and for nested circles", () => {
    expect(
      getShadingPattern(radialAxialIR({ type: "axial" })).areConic()
    ).toBe(false);
    expect(
      getShadingPattern(
        radialAxialIR({
          type: "radial",
          p0: [0, 0],
          p1: [0, 0],
          r0: 10,
          r1: 5,
        })
      ).areConic()
    ).toBe(false);
  });

  test("areConic is true when neither circle contains the other", () => {
    expect(
      getShadingPattern(
        radialAxialIR({
          type: "radial",
          p0: [0, 0],
          p1: [1, 0],
          r0: 10,
