describe("MeshShadingPattern rendering", () => {
  test("SHADING rasterizes the mesh with a transparent border", () => {
    const pattern = getShadingPattern(
      meshIR({ bounds: [0, 0, 10, 10], bbox: [0, 0, 10, 10] })
    );
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const owner = makeOwner({ canvasFactory });

    const result = pattern.getPattern(
      ctx,
      owner,
      IDENTITY,
      PathType.SHADING
    );

    expect(ctx.calls.clip[0][0].ops).toEqual([["rect", 0, 0, 10, 10]]);
    expect(canvasFactory.created).toHaveLength(1);
    expect(canvasFactory.created[0].width).toBe(15);
    expect(canvasFactory.created[0].height).toBe(15);

    const tmpCtx = canvasFactory.created[0].entry.context;
    expect(tmpCtx.calls.createImageData).toHaveLength(1);
    expect(tmpCtx.calls.createImageData[0][0]).toBe(11);
    expect(tmpCtx.calls.createImageData[0][1]).toBe(11);
    const imageData = tmpCtx.calls.createImageData[0][2];
    // Gouraud shading must have written opaque pixels.
    expect(imageData.data.some((value, index) => index % 4 === 3 && value === 255)).toBe(true);
    expect(tmpCtx.calls.putImageData[0][1]).toBe(2);
    expect(tmpCtx.calls.putImageData[0][2]).toBe(2);

    expect(ctx.calls.createPattern).toHaveLength(1);
    expect(ctx.calls.createPattern[0][1]).toBe("no-repeat");
    expect(result).toBe(ctx.calls.createPattern[0][2]);
    expect(canvasFactory.destroyed).toHaveLength(1);
  });

  test("FILL fills the background and applies owner and pattern transforms", () => {
    const pattern = getShadingPattern(
      meshIR({
        vertexCount: 0,
        bounds: [0, 0, 4, 4],
        bbox: [0, 0, 4, 4],
        background: [10, 20, 30],
      })
    );
    pattern.matrix = [2, 0, 0, 2, 0, 0];
    const transferMaps = { applyToCanvas: jest.fn() };
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const owner = makeOwner({
      canvasFactory,
      baseTransform: [1, 0, 0, 1, 5, 6],
      current: { transferMapsFallback: transferMaps },
    });

    pattern.getPattern(ctx, owner, IDENTITY, PathType.FILL);

    expect(ctx.calls.setTransform).toEqual([[1, 0, 0, 1, 5, 6]]);
    expect(ctx.calls.transform).toEqual([[2, 0, 0, 2, 0, 0]]);

    const tmpCtx = canvasFactory.created[0].entry.context;
    expect(tmpCtx.calls.createImageData[0][0]).toBe(9);
    expect(tmpCtx.calls.createImageData[0][1]).toBe(9);
    const { data } = tmpCtx.calls.createImageData[0][2];
    expect(Array.from(data.slice(0, 4))).toEqual([10, 20, 30, 255]);
    expect(transferMaps.applyToCanvas).toHaveBeenCalledWith(tmpCtx);
    expect(canvasFactory.created[0].width).toBe(13);
    expect(canvasFactory.created[0].height).toBe(13);
  });

  test("zero-sized bounds still produce a valid one-pixel canvas", () => {
    const pattern = getShadingPattern(
      meshIR({
        vertexCount: 0,
        bounds: [0, 0, 0, 0],
        bbox: [0, 0, 0, 0],
        background: null,
      })
    );
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const owner = makeOwner({ canvasFactory });

    expect(() =>
      pattern.getPattern(ctx, owner, IDENTITY, PathType.SHADING)
    ).not.toThrow();
    expect(canvasFactory.created[0].width).toBe(5);
    expect(canvasFactory.created[0].height).toBe(5);
    const tmpCtx = canvasFactory.created[0].entry.context;
    expect(tmpCtx.calls.createImageData[0][0]).toBe(1);
    expect(tmpCtx.calls.createImageData[0][1]).toBe(1);
  });

  test("large meshes stay on the CPU fallback when the GPU is unavailable", () => {
    const vertexCount = 51;
    const posData = new Float32Array(vertexCount * 2);
    const colData = new Uint8Array(vertexCount * 4);
    const pattern = getShadingPattern(
      meshIR({ posData, colData, vertexCount })
    );
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const owner = makeOwner({ canvasFactory });

    pattern.getPattern(ctx, owner, IDENTITY, PathType.SHADING);

    const tmpCtx = canvasFactory.created[0].entry.context;
    expect(tmpCtx.calls.putImageData).toHaveLength(1);
    // The GPU path would blit via drawImage onto the temporary canvas.
    expect(tmpCtx.calls.drawImage).toBeUndefined();
  });
});

