describe("TilingPattern.getPattern", () => {
  test("renders one tile and returns a repeating pattern", () => {
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const tmpCtx = createRecordingContext({ canvas: { width: 10, height: 10 } });
    const graphics = createFakeGraphics(tmpCtx);
    const graphicsFactory = createGraphicsFactory(graphics);
    const { pattern } = tilingPattern({
      ctx,
      canvasGraphicsFactory: graphicsFactory,
      bbox: [0, 0, 10, 10],
      xstep: 10,
      ystep: 10,
      color: "#123456",
      operatorList: ["tile-ops"],
    });
    const owner = makeOwner({ canvasFactory, baseTransform: IDENTITY });

    const result = pattern.getPattern(
      ctx,
      owner,
      IDENTITY,
      PathType.FILL,
      7
    );

    expect(graphicsFactory.calls).toEqual([[tmpCtx, 7]]);
    expect(graphics.groupLevel).toBe(4);
    expect(graphics.current.transferMapsFallback).toBe(null);
    expect(graphics.current.fillColor).toBe("#123456");
    expect(tmpCtx.fillStyle).toBe("#123456");
    expect(tmpCtx.calls.translate).toEqual([[0, 0]]);
    expect(graphics.calls.transform).toEqual([[0, 1, 0, 0, 1, 0, 0]]);
    expect(tmpCtx.calls.save).toHaveLength(1);
    expect(tmpCtx.calls.restore).toHaveLength(1);
    expect(graphics.calls.save).toBe(1);
    expect(graphics.calls.restore).toBe(1);
    expect(graphics.calls.executeOperatorList).toEqual([["tile-ops"]]);
    expect(graphics.calls.endDrawing).toBe(1);
    expect(tmpCtx.calls.clip[0][0].ops).toEqual([["rect", 0, 0, 10, 10]]);

    expect(ctx.calls.createPattern).toHaveLength(1);
    expect(ctx.calls.createPattern[0][1]).toBe("repeat");
    expect(result).toBe(ctx.calls.createPattern[0][2]);
    expect(matrixValues(result.transform)).toEqual(IDENTITY);
    expect(canvasFactory.destroyed).toEqual([canvasFactory.created[0].entry]);
