class FakePath2D {
  constructor() {
    this.ops = [];
  }
  rect(...args) {
    this.ops.push(["rect", ...args]);
    return this;
  }
  moveTo(...args) {
    this.ops.push(["moveTo", ...args]);
    return this;
  }
  lineTo(...args) {
    this.ops.push(["lineTo", ...args]);
    return this;
  }
  closePath() {
    this.ops.push(["closePath"]);
    return this;
  }
}

// Faithful enough 2D subset of the DOMMatrix API for the code under test.
class FakeDOMMatrix {
  constructor(init) {
    if (Array.isArray(init)) {
      [this.a, this.b, this.c, this.d, this.e, this.f] = init;
    } else if (init && typeof init === "object") {
      this.a = init.a ?? 1;
      this.b = init.b ?? 0;
      this.c = init.c ?? 0;
      this.d = init.d ?? 1;
      this.e = init.e ?? 0;
      this.f = init.f ?? 0;
    } else {
      this.a = 1;
      this.b = 0;
      this.c = 0;
      this.d = 1;
      this.e = 0;
      this.f = 0;
    }
  }
  translate(tx, ty = 0) {
    this.e += this.a * tx + this.c * ty;
    this.f += this.b * tx + this.d * ty;
    return this;
  }
  scale(sx, sy = sx) {
    this.a *= sx;
    this.b *= sx;
    this.c *= sy;
    this.d *= sy;
    return this;
  }
  toArray() {
    return [this.a, this.b, this.c, this.d, this.e, this.f];
  }
}

const IDENTITY = [1, 0, 0, 1, 0, 0];

function matrixValues(matrix) {
  return [matrix.a, matrix.b, matrix.c, matrix.d, matrix.e, matrix.f];
}

function createGradient(kind, args) {
  return {
    kind,
    args,
    stops: [],
    addColorStop(offset, color) {
      this.stops.push([offset, color]);
    },
  };
}

function createRecordingContext({
  transform = IDENTITY,
  canvas = { width: 800, height: 600 },
} = {}) {
  const calls = {};
  const push = (name, args) => {
    (calls[name] ||= []).push(args);
  };
  const ctx = {
    canvas,
    calls,
    fillStyle: null,
    strokeStyle: null,
    globalAlpha: 1,
    globalCompositeOperation: "source-over",
    _matrix: transform.slice(),

    getTransform() {
      const [a, b, c, d, e, f] = ctx._matrix;
      return { a, b, c, d, e, f };
    },
    setTransform(...args) {
      push("setTransform", args);
      ctx._matrix = args.slice(0, 6);
    },
    transform(...args) {
      push("transform", args);
    },
    translate(...args) {
      push("translate", args);
    },
    scale(...args) {
      push("scale", args);
    },
    rotate(...args) {
      push("rotate", args);
    },
    save() {
      push("save", []);
    },
    restore() {
      push("restore", []);
    },
    beginPath() {
      push("beginPath", []);
    },
    rect(...args) {
      push("rect", args);
    },
    clip(...args) {
      push("clip", args);
    },
    fill(...args) {
      push("fill", args);
    },
    fillRect(...args) {
      push("fillRect", args);
    },
    clearRect(...args) {
      push("clearRect", args);
    },
