  return {
    ctx,
    calls,
    groupLevel: 0,
    baseTransform: null,
    current: {
      minMax: [Infinity, Infinity, -Infinity, -Infinity],
      transferMapsFallback: null,
      patternFill: true,
      patternStroke: true,
      fillColor: null,
      strokeColor: null,
      updateClipFromPath() {
        calls.updateClipFromPath++;
