    },
    dependencyTracker: {
      save() {
        calls.save++;
        return this;
      },
      restore() {
        calls.restore++;
        return this;
      },
    },
    transform(...args) {
      calls.transform.push(args);
    },
    executeOperatorList(list) {
      calls.executeOperatorList.push(list);
    },
    endDrawing() {
      calls.endDrawing++;
    },
  };
}

function createGraphicsFactory(graphics) {
  const calls = [];
  return {
    calls,
    createCanvasGraphics(ctx, opIdx) {
      calls.push([ctx, opIdx]);
      return graphics;
    },
  };
