    expect(transferMaps.applyToCanvas).toHaveBeenCalledWith(tmpCtx);

    expect(ctx.calls.createPattern).toHaveLength(1);
    expect(ctx.calls.createPattern[0][1]).toBe("no-repeat");
    expect(result.transform).not.toBeNull();
    expect(matrixValues(result.transform)).toEqual([
      0.5, 0, 0, 0.5, -2.5, -2.5,
    ]);
    expect(canvasFactory.destroyed).toEqual([canvasFactory.created[0].entry]);
  });

  test("origin-based axial FILL uses a direct gradient with the base transform", () => {
    const pattern = getShadingPattern(
      radialAxialIR({
        type: "axial",
        p0: [0, 0],
        p1: [4, 0],
        colorStops: [
          [0, "#111111"],
          [1, "#eeeeee"],
        ],
      })
    );
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const getBBox = jest.fn();
    const owner = makeOwner({
      canvasFactory,
      baseTransform: [2, 0, 0, 2, 10, 20],
      current: { getClippedPathBoundingBox: getBBox },
    });

    const result = pattern.getPattern(ctx, owner, IDENTITY, PathType.FILL);

    expect(getBBox).not.toHaveBeenCalled();
    expect(canvasFactory.created).toHaveLength(0);
    expect(result.kind).toBe("linear");
    expect(result.args).toEqual([10, 20, 18, 20]);
    expect(result.stops).toEqual([
      [0, "#111111"],
      [1, "#eeeeee"],
    ]);
  });

  test("origin-based radial FILL uses direct gradient only for a square transform", () => {
    const pattern = getShadingPattern(
      radialAxialIR({
        type: "radial",
        p0: [0, 0],
        p1: [0, 0],
        r0: 1,
        r1: 2,
      })
    );
    const ctx = createRecordingContext();
    const owner = makeOwner({ baseTransform: [2, 0, 0, 2, 10, 20] });

    const result = pattern.getPattern(ctx, owner, IDENTITY, PathType.FILL);

    expect(result.kind).toBe("radial");
    expect(result.args).toEqual([10, 20, 2, 10, 20, 4]);
  });

  test("non-square radial FILL falls back to rasterization", () => {
    const pattern = getShadingPattern(
      radialAxialIR({
        type: "radial",
        p0: [0, 0],
        p1: [0, 0],
        r0: 1,
        r1: 2,
      })
    );
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const getBBox = jest.fn(() => [0, 0, 10, 10]);
    const owner = makeOwner({
      canvasFactory,
      baseTransform: [2, 0, 0, 3, 0, 0],
      current: { getClippedPathBoundingBox: getBBox },
    });

    const result = pattern.getPattern(ctx, owner, IDENTITY, PathType.STROKE);

    expect(getBBox).toHaveBeenCalledWith(PathType.STROKE, IDENTITY);
    expect(canvasFactory.created).toHaveLength(1);
    expect(canvasFactory.created[0].width).toBe(10);
    expect(canvasFactory.created[0].height).toBe(10);
    const tmpCtx = canvasFactory.created[0].entry.context;
    expect(tmpCtx.calls.transform).toEqual([[2, 0, 0, 3, 0, 0]]);
    expect(result.repetition).toBe("no-repeat");
  });

  test("non-origin FILL rasterizes using the clipped path bbox", () => {
    const pattern = getShadingPattern(
      radialAxialIR({
        type: "axial",
        p0: [1, 0],
        p1: [10, 0],
      })
    );
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const getBBox = jest.fn(() => [10, 20, 60, 80]);
    const owner = makeOwner({
      canvasFactory,
      current: { getClippedPathBoundingBox: getBBox },
    });

    pattern.getPattern(ctx, owner, IDENTITY, PathType.FILL);

    expect(getBBox).toHaveBeenCalledWith(PathType.FILL, IDENTITY);
    expect(canvasFactory.created[0].width).toBe(50);
    expect(canvasFactory.created[0].height).toBe(60);
  });

  test("FILL with transfer maps rasterizes and combines matrix with baseTransform", () => {
    const transferMaps = { applyToCanvas: jest.fn() };
    const pattern = getShadingPattern(
      radialAxialIR({ type: "axial", p0: [0, 0], p1: [5, 5] })
    );
    pattern.matrix = [3, 0, 0, 3, 0, 0];
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const owner = makeOwner({
      canvasFactory,
      baseTransform: [2, 0, 0, 2, 0, 0],
      current: {
        transferMapsFallback: transferMaps,
        getClippedPathBoundingBox: jest.fn(() => [0, 0, 10, 10]),
      },
    });

    pattern.getPattern(ctx, owner, IDENTITY, PathType.FILL);

    const tmpCtx = canvasFactory.created[0].entry.context;
    expect(tmpCtx.calls.transform).toEqual([[6, 0, 0, 6, 0, 0]]);
    expect(transferMaps.applyToCanvas).toHaveBeenCalledWith(tmpCtx);
  });
});

