describe("TilingPattern.setFillAndStrokeStyleToContext", () => {
  function makeGraphics() {
    const ctx = createRecordingContext();
    const graphics = createFakeGraphics(ctx);
    return { ctx, graphics };
  }

  test("COLORED always paints black and clears pattern flags", () => {
    const { pattern } = tilingPattern();
    const { ctx, graphics } = makeGraphics();

    pattern.setFillAndStrokeStyleToContext(graphics, 1, "#ff0000");

    expect(ctx.fillStyle).toBe("#000000");
    expect(ctx.strokeStyle).toBe("#000000");
    expect(graphics.current.fillColor).toBe("#000000");
    expect(graphics.current.strokeColor).toBe("#000000");
    expect(graphics.current.patternFill).toBe(false);
    expect(graphics.current.patternStroke).toBe(false);
  });

  test("UNCOLORED keeps the supplied colour", () => {
    const { pattern } = tilingPattern();
    const { ctx, graphics } = makeGraphics();

    pattern.setFillAndStrokeStyleToContext(graphics, 2, "#ff8800");

    expect(ctx.fillStyle).toBe("#ff8800");
    expect(ctx.strokeStyle).toBe("#ff8800");
    expect(graphics.current.fillColor).toBe("#ff8800");
  });

  test("mapped colours are used for the canvas but raw colours for state", () => {
    const { pattern } = tilingPattern();
    const { ctx, graphics } = makeGraphics();
    const transferMaps = { applyToColor: jest.fn(() => "#010203") };
    graphics.current.transferMapsFallback = transferMaps;

    pattern.setFillAndStrokeStyleToContext(graphics, 2, "#ff8800");

    expect(transferMaps.applyToColor).toHaveBeenCalledWith("#ff8800");
    expect(ctx.fillStyle).toBe("#010203");
    expect(graphics.current.fillColor).toBe("#ff8800");
