describe("TilingPattern.getPattern", () => {
  test("renders one tile and returns a repeating pattern", () => {
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const tmpCtx = createRecordingContext({ canvas: { width: 10, height: 10 } });
    const graphics = createFakeGraphics(tmpCtx);
    const graphicsFactory = createGraphicsFactory(graphics);
    const { pattern } = tilingPattern({
      ctx,
      canvasGraphicsFactory: graphicsFactory,
      bbox: [0, 0, 10, 10],
      xstep: 10,
      ystep: 10,
      color: "#123456",
      operatorList: ["tile-ops"],
    });
    const owner = makeOwner({ canvasFactory, baseTransform: IDENTITY });

    const result = pattern.getPattern(
      ctx,
      owner,
      IDENTITY,
      PathType.FILL,
      7
    );

    expect(graphicsFactory.calls).toEqual([[tmpCtx, 7]]);
    expect(graphics.groupLevel).toBe(4);
    expect(graphics.current.transferMapsFallback).toBe(null);
    expect(graphics.current.fillColor).toBe("#123456");
    expect(tmpCtx.fillStyle).toBe("#123456");
    expect(tmpCtx.calls.translate).toEqual([[0, 0]]);
    expect(graphics.calls.transform).toEqual([[0, 1, 0, 0, 1, 0, 0]]);
    expect(tmpCtx.calls.save).toHaveLength(1);
    expect(tmpCtx.calls.restore).toHaveLength(1);
    expect(graphics.calls.save).toBe(1);
    expect(graphics.calls.restore).toBe(1);
    expect(graphics.calls.executeOperatorList).toEqual([["tile-ops"]]);
    expect(graphics.calls.endDrawing).toBe(1);
    expect(tmpCtx.calls.clip[0][0].ops).toEqual([["rect", 0, 0, 10, 10]]);

    expect(ctx.calls.createPattern).toHaveLength(1);
    expect(ctx.calls.createPattern[0][1]).toBe("repeat");
    expect(result).toBe(ctx.calls.createPattern[0][2]);
    expect(matrixValues(result.transform)).toEqual(IDENTITY);
    expect(canvasFactory.destroyed).toEqual([canvasFactory.created[0].entry]);
  });

  test("SHADING positions the pattern with the inverse transform", () => {
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const graphics = createFakeGraphics(
      createRecordingContext({ canvas: { width: 10, height: 10 } })
    );
    const { pattern } = tilingPattern({
      ctx,
      canvasGraphicsFactory: createGraphicsFactory(graphics),
      matrix: [1, 0, 0, 1, 99, 99],
      baseTransform: IDENTITY,
      bbox: [0, 0, 10, 10],
    });
    const owner = makeOwner({ canvasFactory });

    const result = pattern.getPattern(
      ctx,
      owner,
      [1, 0, 0, 1, 5, 6],
      PathType.SHADING
    );

    expect(matrixValues(result.transform)).toEqual([1, 0, 0, 1, 5, 6]);
  });

  test("uses bbox offsets for the pattern transform", () => {
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const graphics = createFakeGraphics(
      createRecordingContext({ canvas: { width: 10, height: 20 } })
    );
    const { pattern } = tilingPattern({
      ctx,
      canvasGraphicsFactory: createGraphicsFactory(graphics),
      bbox: [5, 7, 15, 27],
      xstep: 10,
      ystep: 20,
    });
    const owner = makeOwner({ canvasFactory });

    const result = pattern.getPattern(
      ctx,
      owner,
      IDENTITY,
      PathType.FILL
    );

    expect(canvasFactory.created[0].width).toBe(10);
    expect(canvasFactory.created[0].height).toBe(20);
    expect(matrixValues(result.transform)).toEqual([1, 0, 0, 1, 5, 7]);
  });

  test("redraws overlapping tiles horizontally and vertically", () => {
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const graphics = createFakeGraphics(
      createRecordingContext({ canvas: { width: 10, height: 10 } })
    );
    const { pattern } = tilingPattern({
      ctx,
      canvasGraphicsFactory: createGraphicsFactory(graphics),
      bbox: [0, 0, 10, 10],
      xstep: 5,
      ystep: 5,
    });
    const owner = makeOwner({ canvasFactory });

    const result = pattern.getPattern(
      ctx,
      owner,
      IDENTITY,
      PathType.FILL
    );

    expect(canvasFactory.created.map(({ width, height }) => [width, height])).toEqual([
      [10, 10],
      [10, 5],
      [5, 5],
    ]);
    const bandEntry = canvasFactory.created[1].entry;
    const finalEntry = canvasFactory.created[2].entry;
    expect(bandEntry.context.calls.drawImage).toHaveLength(3);
    expect(finalEntry.context.calls.drawImage).toHaveLength(3);
    expect(canvasFactory.destroyed).toContain(bandEntry);
    expect(canvasFactory.destroyed).toContain(canvasFactory.created[0].entry);
    expect(canvasFactory.destroyed).toContain(finalEntry);
    expect(result.source).toBe(finalEntry.canvas);
    expect(result.repetition).toBe("repeat");
  });

  test("redraws only horizontally when the vertical tile is large enough", () => {
    const ctx = createRecordingContext();
    const canvasFactory = createCanvasFactory();
    const graphics = createFakeGraphics(
      createRecordingContext({ canvas: { width: 10, height: 10 } })
    );
    const { pattern } = tilingPattern({
      ctx,
      canvasGraphicsFactory: createGraphicsFactory(graphics),
      bbox: [0, 0, 10, 10],
      xstep: 5,
      ystep: 10,
    });
    const owner = makeOwner({ canvasFactory });

    const result = pattern.getPattern(
      ctx,
      owner,
      IDENTITY,
      PathType.FILL
    );

    expect(canvasFactory.created.map(({ width, height }) => [width, height])).toEqual([
      [10, 10],
      [5, 10],
    ]);
    const finalEntry = canvasFactory.created[1].entry;
    expect(finalEntry.context.calls.drawImage).toHaveLength(3);
    expect(canvasFactory.destroyed).not.toContain(finalEntry);
    expect(result.source).toBe(finalEntry.canvas);
  });
});

