describe("TilingPattern.drawPattern", () => {
  test("isolates the tile via a temporary canvas by default", () => {
    const { owner, ctx, canvasFactory } = makeDrawOwner();
    const graphics = createFakeGraphics(
      createRecordingContext({ canvas: { width: 10, height: 10 } })
    );
    const graphicsFactory = createGraphicsFactory(graphics);
    const { pattern } = tilingPattern({
      canvasGraphicsFactory: graphicsFactory,
      bbox: [0, 0, 10, 10],
      xstep: 10,
      ystep: 10,
      needsIsolation: true,
    });
    const path = new FakePath2D();
    const originalTracker = { id: "tracker" };
    owner.dependencyTracker = originalTracker;

    pattern.drawPattern(owner, path, false, [1, 1], 9);

    expect(owner.saveCount).toBe(1);
    expect(owner.restoreCount).toBe(1);
    expect(owner.dependencyTracker).toBe(originalTracker);
    expect(ctx.calls.clip[0][0]).toBe(path);
    expect(ctx.calls.setTransform).toEqual([IDENTITY]);
    expect(ctx.calls.translate).toEqual([[10, 10]]);
    expect(ctx.calls.drawImage).toHaveLength(1);
    expect(ctx.calls.drawImage[0][1]).toBe(0);
    expect(ctx.calls.drawImage[0][2]).toBe(0);
    expect(ctx.calls.drawImage[0][3]).toBe(10);
    expect(ctx.calls.drawImage[0][4]).toBe(10);
    expect(canvasFactory.created).toHaveLength(1);
    expect(canvasFactory.destroyed).toHaveLength(1);
    expect(owner.executed).toHaveLength(0);
  });

  test("honours the even-odd fill rule", () => {
    const { owner, ctx } = makeDrawOwner();
    const { pattern } = tilingPattern({
      bbox: [0, 0, 10, 10],
      needsIsolation: true,
    });
    const path = new FakePath2D();

    pattern.drawPattern(owner, path, true, [0, 0], 1);

    expect(ctx.calls.clip[0][0]).toBe(path);
    expect(ctx.calls.clip[0][1]).toBe("evenodd");
  });

  test("executes operators directly when isolation is unnecessary", () => {
    const { owner, ctx, canvasFactory } = makeDrawOwner();
    const { pattern } = tilingPattern({
      bbox: [0, 0, 10, 10],
      xstep: 10,
      ystep: 10,
      needsIsolation: false,
      operatorList: ["direct-ops"],
    });
    const path = new FakePath2D();

    pattern.drawPattern(owner, path, false, [0, 0], 3);

    expect(canvasFactory.created).toHaveLength(0);
    expect(owner.executed).toEqual([["direct-ops"]]);
    expect(owner.baseTransformStack).toHaveLength(0);
    // baseTransform is restored after the direct render.
    expect(owner.baseTransform).toEqual([2, 0, 0, 2, 0, 0]);
    expect(ctx.calls.clip).toHaveLength(2);
    expect(owner.current.fillColor).toBe("#336699");
    expect(owner.current.updateCount).toBe(1);
  });

  test("falls back to isolated rendering for non-trivial global alpha", () => {
    const { owner, ctx, canvasFactory } = makeDrawOwner();
    owner.ctx.globalAlpha = 0.5;
    const graphics = createFakeGraphics(
      createRecordingContext({ canvas: { width: 10, height: 10 } })
    );
    const { pattern } = tilingPattern({
      canvasGraphicsFactory: createGraphicsFactory(graphics),
      bbox: [0, 0, 10, 10],
      needsIsolation: false,
    });
    const path = new FakePath2D();

    pattern.drawPattern(owner, path, false, [0, 0], 2);

    expect(canvasFactory.created).toHaveLength(1);
    expect(ctx.calls.drawImage).toHaveLength(1);
    expect(owner.executed).toHaveLength(0);
  });
});
